window.MV_DATA=window.MV_DATA||{};window.MV_DATA[5]={"id":5,"topics":[{"id":41,"words":[{"en":"CNC machine","pos":"noun phrase","ipa":"/ˌsiː en ˈsiː məˌʃiːn/","ja":"NC工作機械","kana":"エヌシーこうさくきかい","romaji":"enushiikousakukikai","vi":"máy CNC (máy công cụ điều khiển số)","level":1,"def_vi":"Máy công cụ có chuyển động của dao và phôi được máy tính điều khiển theo chương trình số.","def_en":"A machine tool whose tool and workpiece motions are controlled by a computer running a numerical program.","def_ja":"工具や工作物の動きを数値プログラムによりコンピュータで制御する工作機械。","usage_en":"Danh từ đếm được. Hay đi với: run / set up / program a CNC machine; 'CNC' luôn viết hoa, đọc từng chữ cái.","usage_ja":"Trong xưởng Nhật thường gọi tắt là NC hoặc NC機; văn bản kỹ thuật dùng NC工作機械. Động từ đi kèm: 操作する, 段取りする.","context_vi":"Dùng khắp các xưởng cơ khí chính xác, sản xuất khuôn, linh kiện ô tô, hàng không.","ex_en":"We bought a second CNC machine to handle the aluminium bracket orders.","ex_ja":"アルミブラケットの受注に対応するため、2台目のNC工作機械を導入した。","ex_vi":"Chúng tôi mua thêm một máy CNC thứ hai để đáp ứng các đơn hàng giá đỡ nhôm.","syn_en":["CNC machine tool","NC machine (cách gọi cũ)"],"syn_ja":["NC機","CNC工作機械"]},{"en":"machining center","pos":"noun phrase","ipa":"/məˈʃiːnɪŋ ˌsentə/","ja":"マシニングセンタ","kana":"マシニングセンタ","romaji":"mashiningusenta","vi":"trung tâm gia công","level":1,"def_vi":"Máy CNC đa năng có bộ thay dao tự động, thực hiện phay, khoan, taro, doa trên một lần gá phôi.","def_en":"A multi-purpose CNC machine with an automatic tool changer that mills, drills, taps and bores in one setup.","def_ja":"自動工具交換装置を備え、フライス削り・穴あけ・タップ立てなどを一度の段取りで行うNC工作機械。","usage_en":"Danh từ đếm được; Anh-Anh viết 'machining centre'. Hay đi với: vertical / horizontal machining center, 5-axis machining center.","usage_ja":"Hay gọi tắt là MC; ghép loại phía trước: 立形マシニングセンタ, 横形マシニングセンタ. Lưu ý JIS viết センタ (không có dấu ー cuối).","context_vi":"Dùng để gia công vỏ hộp số, khuôn, chi tiết lăng trụ nhiều mặt trong sản xuất hàng loạt hoặc đơn chiếc.","ex_en":"The gearbox housing is finished on a horizontal machining center in two setups.","ex_ja":"ギヤボックスハウジングは横形マシニングセンタで2工程に分けて仕上げる。","ex_vi":"Vỏ hộp số được gia công tinh trên trung tâm gia công ngang qua hai lần gá.","syn_en":["MC (viết tắt)","VMC / HMC (loại đứng / ngang)"],"syn_ja":["MC","マシニング (khẩu ngữ)"]},{"en":"CNC lathe","pos":"noun phrase","ipa":"/ˌsiː en ˌsiː ˈleɪð/","ja":"NC旋盤","kana":"エヌシーせんばん","romaji":"enushiisenban","vi":"máy tiện CNC","level":1,"def_vi":"Máy tiện có các trục chạy dao X, Z được điều khiển số, dùng gia công chi tiết tròn xoay.","def_en":"A lathe whose X and Z feed axes are numerically controlled, used to machine rotational parts.","def_ja":"X軸とZ軸の送りを数値制御し、回転体の部品を加工する旋盤。","usage_en":"Danh từ đếm được. Hay đi với: on a CNC lathe, CNC lathe with live tooling; đừng nhầm với 'turning center' (có thêm dao quay, trục C).","usage_ja":"Văn bản dùng NC旋盤; loại có dao quay và trục C gọi là 複合加工機 hoặc ターニングセンタ. Động từ: NC旋盤で加工する / 挽く (khẩu ngữ).","context_vi":"Dùng sản xuất trục, bạc, mặt bích, chi tiết ren trong xưởng tiện và dây chuyền ô tô.","ex_en":"All the pump shafts are turned on the CNC lathe before grinding.","ex_ja":"ポンプ軸はすべて研削前にNC旋盤で旋削する。","ex_vi":"Tất cả các trục bơm được tiện trên máy tiện CNC trước khi mài.","syn_en":["turning center (nghĩa rộng hơn)","CNC turning machine"],"syn_ja":["CNC旋盤","ターニングセンタ (gần nghĩa)"]},{"en":"spindle","pos":"noun","ipa":"/ˈspɪndl/","ja":"主軸","kana":"しゅじく","romaji":"shujiku","vi":"trục chính","level":1,"def_vi":"Trục quay chính của máy công cụ, kẹp dao (máy phay) hoặc phôi (máy tiện) và truyền chuyển động cắt.","def_en":"The main rotating shaft of a machine tool that holds the tool or workpiece and provides the cutting motion.","def_ja":"工具または工作物を保持し、切削運動を与える工作機械の主要な回転軸。","usage_en":"Danh từ đếm được. Collocations: spindle speed, spindle load, spindle taper; động từ: start / stop / orient the spindle.","usage_ja":"Đi với 主軸回転数, 主軸負荷, 主軸オリエンテーション. Ngoài xưởng hay nói katakana スピンドル.","context_vi":"Xuất hiện trên màn hình điều khiển (tốc độ, tải trục chính) và khi bảo dưỡng ổ bi trục chính.","ex_en":"Check the spindle load before increasing the feed on this roughing pass.","ex_ja":"この荒加工で送りを上げる前に主軸の負荷を確認してください。","ex_vi":"Hãy kiểm tra tải trục chính trước khi tăng lượng chạy dao ở lượt gia công thô này.","syn_en":["main spindle","work spindle"],"syn_ja":["スピンドル"]},{"en":"operator panel","pos":"noun phrase","ipa":"/ˈɒpəreɪtə ˌpænl/","ja":"操作盤","kana":"そうさばん","romaji":"sousaban","vi":"bảng điều khiển (bảng vận hành)","level":1,"def_vi":"Bảng gồm màn hình, phím và công tắc để người vận hành điều khiển máy CNC.","def_en":"The panel with screen, keys and switches that the operator uses to control a CNC machine.","def_ja":"画面・キー・スイッチを備え、作業者がNC工作機械を操作するための盤。","usage_en":"Danh từ đếm được. Hay đi với: on the operator panel, machine operator panel (MOP); động từ: press a key on the operator panel.","usage_ja":"Đi với 操作盤のスイッチ, 操作盤で切り替える. Cũng gọi 操作パネル; phân biệt với 制御盤 (tủ điện).","context_vi":"Dùng khi hướng dẫn vận hành, viết quy trình thao tác và đào tạo công nhân đứng máy.","ex_en":"Select MEMORY mode on the operator panel before pressing cycle start.","ex_ja":"サイクルスタートを押す前に、操作盤でメモリモードを選択する。","ex_vi":"Chọn chế độ MEMORY trên bảng điều khiển trước khi nhấn khởi động chu trình.","syn_en":["control panel","MOP (machine operator panel)"],"syn_ja":["操作パネル","機械操作盤"]},{"en":"part program","pos":"noun phrase","ipa":"/ˈpɑːt ˌprəʊɡræm/","ja":"加工プログラム","kana":"かこうプログラム","romaji":"kakoupuroguramu","vi":"chương trình gia công","level":1,"def_vi":"Tập hợp các câu lệnh NC mô tả đường chạy dao, tốc độ và chức năng phụ để gia công một chi tiết.","def_en":"The set of NC instructions describing tool motions, speeds and auxiliary functions to machine one part.","def_ja":"一つの部品を加工するための工具経路・速度・補助機能を記述したNC指令の集まり。","usage_en":"Danh từ đếm được. Động từ: write / edit / load / prove out a part program; thường gọi ngắn là 'the program'.","usage_ja":"Hay nói NCプログラム hoặc プログラム. Động từ: 作成する, 編集する, 転送する, プログラムチェックする.","context_vi":"Dùng khi lập trình CNC, truyền chương trình xuống máy và kiểm tra trước khi chạy hàng loạt.","ex_en":"The part program was generated in CAM and checked in simulation before transfer.","ex_ja":"加工プログラムはCAMで作成し、転送前にシミュレーションで確認した。","ex_vi":"Chương trình gia công được tạo bằng CAM và kiểm tra mô phỏng trước khi truyền xuống máy.","syn_en":["NC program","CNC program"],"syn_ja":["NCプログラム","プログラム"]},{"en":"G-code","pos":"noun","ipa":"/ˈdʒiː kəʊd/","ja":"Gコード","kana":"ジーコード","romaji":"jiikoodo","vi":"mã G","level":1,"def_vi":"Mã lệnh chuẩn bị bắt đầu bằng chữ G, quy định kiểu chuyển động hoặc chế độ của máy CNC (ví dụ G01, G02).","def_en":"A preparatory command beginning with G that sets the motion type or mode of a CNC machine, e.g. G01, G02.","def_ja":"Gで始まる準備機能の指令で、G01やG02のように移動の種類やモードを指定する。","usage_en":"Danh từ đếm được và không đếm được: 'a G-code' (một mã), 'G-code' (ngôn ngữ). Hay đi với: modal G-code, write G-code, G-code program.","usage_ja":"Văn bản JIS gọi là 準備機能; thực tế nói Gコード. Đi với Gコードを指令する, モーダルなGコード.","context_vi":"Dùng hằng ngày khi lập trình tay, đọc chương trình và sửa lỗi trên máy CNC.","ex_en":"G-code G02 commands clockwise circular motion in the selected plane.","ex_ja":"GコードのG02は、選択した平面での時計回りの円弧移動を指令する。","ex_vi":"Mã G G02 ra lệnh chuyển động cung tròn theo chiều kim đồng hồ trên mặt phẳng đã chọn.","syn_en":["preparatory function","G-word"],"syn_ja":["準備機能","Gコマンド"]},{"en":"M-code","pos":"noun","ipa":"/ˈem kəʊd/","ja":"Mコード","kana":"エムコード","romaji":"emukoodo","vi":"mã M","level":1,"def_vi":"Mã chức năng phụ bắt đầu bằng chữ M, điều khiển các thao tác như bật trục chính, tưới nguội, dừng chương trình.","def_en":"A miscellaneous function code beginning with M that switches machine functions such as spindle, coolant or program stop.","def_ja":"Mで始まる補助機能の指令で、主軸回転・クーラント・プログラム停止などを切り替える。","usage_en":"Danh từ đếm được. Ví dụ: M03 spindle on, M08 coolant on, M30 program end; nhiều mã M phụ thuộc nhà sản xuất máy.","usage_ja":"Văn bản JIS gọi 補助機能; ngoài xưởng nói Mコード. Ví dụ M08でクーラントON.","context_vi":"Dùng khi lập trình và khi đọc tài liệu của nhà sản xuất máy về các mã M riêng.","ex_en":"Add the M-code M08 after the tool change to turn on coolant.","ex_ja":"工具交換の後にMコードのM08を入れてクーラントをONにする。","ex_vi":"Thêm mã M M08 sau lệnh thay dao để bật dung dịch tưới nguội.","syn_en":["miscellaneous function","auxiliary function"],"syn_ja":["補助機能","M機能"]},{"en":"cycle start","pos":"noun phrase","ipa":"/ˈsaɪkl stɑːt/","ja":"サイクルスタート","kana":"サイクルスタート","romaji":"saikurusutaato","vi":"nút khởi động chu trình (Cycle Start)","level":1,"def_vi":"Nút hoặc lệnh bắt đầu chạy chương trình ở chế độ tự động trên máy CNC.","def_en":"The button or command that starts execution of the program in automatic mode on a CNC machine.","def_ja":"NC工作機械で自動運転のプログラム実行を開始させるボタンまたは指令。","usage_en":"Thường dùng như danh từ chỉ nút: press / hit cycle start; cũng dùng làm tính từ: cycle start button.","usage_ja":"Đi với サイクルスタートを押す, サイクルスタートボタン. Trong tài liệu có thể gọi 自動運転起動.","context_vi":"Dùng trong hướng dẫn vận hành máy và quy trình chạy thử chương trình mới.","ex_en":"Close the door and press cycle start to run the first part.","ex_ja":"扉を閉めてサイクルスタートを押し、初品を加工する。","ex_vi":"Đóng cửa máy và nhấn nút khởi động chu trình để chạy chi tiết đầu tiên.","syn_en":["cycle start button","program start"],"syn_ja":["起動ボタン","自動運転起動"]},{"en":"feed hold","pos":"noun phrase","ipa":"/ˈfiːd həʊld/","ja":"フィードホールド","kana":"フィードホールド","romaji":"fiidohoorudo","vi":"tạm dừng chạy dao (Feed Hold)","level":1,"def_vi":"Chức năng tạm dừng chuyển động chạy dao các trục trong khi chạy tự động, có thể tiếp tục bằng Cycle Start.","def_en":"A function that temporarily stops axis motion during automatic operation; cycle start resumes it.","def_ja":"自動運転中に軸の移動を一時停止させる機能で、サイクルスタートで再開できる。","usage_en":"Danh từ chỉ nút/chức năng: press feed hold, in feed hold. Khác với emergency stop (dừng khẩn cấp, ngắt toàn bộ).","usage_ja":"Đi với フィードホールドを押す, フィードホールド状態. Không giống 非常停止 (dừng khẩn cấp).","context_vi":"Dùng khi người vận hành cần dừng tạm để quan sát phoi, kiểm tra dao hoặc xử lý tình huống.","ex_en":"Hit feed hold if the chips start wrapping around the tool.","ex_ja":"切りくずが工具に巻き付き始めたらフィードホールドを押すこと。","ex_vi":"Hãy nhấn tạm dừng chạy dao nếu phoi bắt đầu quấn quanh dao.","syn_en":["feed stop","pause (khẩu ngữ)"],"syn_ja":["送り一時停止","一時停止"]},{"en":"jog feed","pos":"noun phrase","ipa":"/ˈdʒɒɡ fiːd/","ja":"ジョグ送り","kana":"ジョグおくり","romaji":"joguokuri","vi":"chạy dao tay (jog)","level":1,"def_vi":"Di chuyển một trục bằng tay với tốc độ đặt trước khi giữ nút hướng trên bảng điều khiển.","def_en":"Manual movement of an axis at a preset rate while a direction button on the operator panel is held.","def_ja":"操作盤の方向ボタンを押している間、設定した速度で軸を手動移動させること。","usage_en":"Danh từ; động từ 'jog' rất phổ biến: jog the X axis, jog the table away. Hay đi với: jog mode, jog rate.","usage_ja":"Đi với ジョグ送りで移動する, ジョグモード. Khẩu ngữ: ジョグで逃がす (lùi dao bằng jog).","context_vi":"Dùng khi gá đặt, so dao, lùi dao ra khỏi phôi trong thao tác thủ công.","ex_en":"Use jog feed to move the table clear of the vise before measuring.","ex_ja":"測定の前に、ジョグ送りでテーブルをバイスから離す。","ex_vi":"Dùng chạy dao tay để đưa bàn máy ra xa ê-tô trước khi đo.","syn_en":["jogging","manual continuous feed"],"syn_ja":["手動連続送り","ジョグ"]},{"en":"manual pulse generator","pos":"noun phrase","ipa":"/ˌmænjuəl ˈpʌls ˌdʒenəreɪtə/","ja":"手動パルス発生器","kana":"しゅどうパルスはっせいき","romaji":"shudouparusuhasseiki","vi":"tay quay xung (MPG)","level":2,"def_vi":"Tay quay điện tử phát xung, mỗi nấc quay làm trục di chuyển một lượng nhỏ (0,001; 0,01; 0,1 mm).","def_en":"An electronic handwheel that sends pulses so each click moves an axis a small fixed increment.","def_ja":"回すとパルスを出し、1目盛りごとに軸を一定量だけ移動させる電子式ハンドル。","usage_en":"Danh từ đếm được; ngoài xưởng gọi là 'handwheel' hoặc 'MPG'. Động từ: turn the handwheel, select x10 on the MPG.","usage_ja":"Ngoài xưởng gần như luôn gọi ハンドル hoặc 手動ハンドル; đi với ハンドル送り, 倍率を×10にする.","context_vi":"Dùng khi so dao, chạm phôi, căn tâm và các thao tác cần dịch chuyển chính xác bằng tay.","ex_en":"Touch off the edge with the manual pulse generator set to 0.001 mm per click.","ex_ja":"手動パルス発生器を1目盛り0.001mmに設定して端面に当てる。","ex_vi":"Chạm cạnh phôi bằng tay quay xung đặt ở 0,001 mm mỗi nấc.","syn_en":["handwheel","MPG"],"syn_ja":["手動ハンドル","ハンドル"]},{"en":"controlled axis","pos":"noun phrase","ipa":"/kənˌtrəʊld ˈæksɪs/","ja":"制御軸","kana":"せいぎょじく","romaji":"seigyojiku","vi":"trục điều khiển","level":2,"def_vi":"Mỗi hướng chuyển động thẳng (X, Y, Z) hoặc quay (A, B, C) mà bộ điều khiển CNC điều khiển được vị trí.","def_en":"Each linear (X, Y, Z) or rotary (A, B, C) direction of motion whose position the CNC controls.","def_ja":"NC装置が位置を制御する直線軸（X・Y・Z）または回転軸（A・B・C）の各運動方向。","usage_en":"Danh từ đếm được, số nhiều 'axes' /ˈæksiːz/. Hay nói: number of controlled axes, simultaneous controlled axes.","usage_ja":"Đi với 制御軸数, 同時制御軸数 (số trục điều khiển đồng thời). Trong giao tiếp thường chỉ nói X軸, B軸.","context_vi":"Xuất hiện trong thông số kỹ thuật máy, catalogue và khi chọn máy 3, 4 hay 5 trục.","ex_en":"The B axis is a controlled axis, so it can be indexed or moved simultaneously with X, Y and Z.","ex_ja":"B軸は制御軸なので、割り出しもX・Y・Zとの同時移動もできる。","ex_vi":"Trục B là một trục điều khiển nên có thể phân độ hoặc chuyển động đồng thời với X, Y và Z.","syn_en":["NC axis","machine axis"],"syn_ja":["NC軸","軸 (khẩu ngữ)"]},{"en":"machine zero","pos":"noun phrase","ipa":"/məˌʃiːn ˈzɪərəʊ/","ja":"機械原点","kana":"きかいげんてん","romaji":"kikaigenten","vi":"điểm gốc máy","level":2,"def_vi":"Điểm tham chiếu cố định do nhà sản xuất đặt trên máy, làm gốc cho hệ tọa độ máy.","def_en":"A fixed reference point set by the machine builder that is the origin of the machine coordinate system.","def_ja":"機械メーカが定めた固定の基準点で、機械座標系の原点となる点。","usage_en":"Danh từ không đếm được trong cụm cố định; cũng nói 'machine home', 'machine reference point'. Đi với: return to machine zero.","usage_ja":"Đi với 機械原点に戻す, 機械座標. Phân biệt với ワーク原点 (gốc phôi) do người lập trình chọn.","context_vi":"Dùng khi khởi động máy, thiết lập hệ tọa độ và khi xử lý sự cố mất vị trí gốc.","ex_en":"All work offsets are measured from machine zero.","ex_ja":"すべてのワーク座標系のオフセットは機械原点から測られる。","ex_vi":"Mọi giá trị bù gốc phôi đều được đo tính từ điểm gốc máy.","syn_en":["machine home","machine reference point"],"syn_ja":["リファレンス点","機械原点位置"]},{"en":"zero return","pos":"noun phrase","ipa":"/ˈzɪərəʊ rɪˌtɜːn/","ja":"原点復帰","kana":"げんてんふっき","romaji":"gentenfukki","vi":"về điểm gốc (về home)","level":2,"def_vi":"Thao tác đưa các trục về điểm gốc máy để bộ điều khiển xác lập lại vị trí tuyệt đối.","def_en":"The operation of sending the axes back to machine zero so the control re-establishes absolute position.","def_ja":"各軸を機械原点へ戻し、NC装置に絶対位置を確立させる操作。","usage_en":"Danh từ; ngoài xưởng hay nói 'homing' hoặc động từ 'home the machine'. Đi với: perform a zero return, zero return mode.","usage_ja":"Đi với 原点復帰する, 原点復帰を行う, 原点復帰未完了アラーム. Là việc đầu tiên sau khi bật máy (với encoder tương đối).","context_vi":"Dùng mỗi khi bật máy, sau dừng khẩn cấp hoặc khi máy báo lỗi chưa về gốc.","ex_en":"After the power failure, perform a zero return on all axes before restarting.","ex_ja":"停電の後は、再開前に全軸の原点復帰を行うこと。","ex_vi":"Sau sự cố mất điện, hãy cho tất cả các trục về điểm gốc trước khi chạy lại.","syn_en":["homing","reference point return"],"syn_ja":["リファレンス点復帰","ゼロリターン"]},{"en":"work coordinate system","pos":"noun phrase","ipa":"/ˌwɜːk kəʊˈɔːdɪnət ˌsɪstəm/","ja":"ワーク座標系","kana":"ワークざひょうけい","romaji":"waakuzahyoukei","vi":"hệ tọa độ phôi","level":2,"def_vi":"Hệ tọa độ có gốc đặt trên phôi do người lập trình chọn, khai báo bằng G54–G59.","def_en":"A coordinate system with its origin on the workpiece chosen by the programmer, selected with G54 to G59.","def_ja":"プログラマが工作物上に原点を定める座標系で、G54〜G59で選択する。","usage_en":"Danh từ đếm được; thực tế hay gọi 'work offset' hoặc 'G54'. Động từ: set / select / shift the work coordinate system.","usage_ja":"Đi với ワーク座標系を設定する, G54を呼ぶ. Gốc của nó gọi là ワーク原点 hoặc プログラム原点.","context_vi":"Dùng khi gá phôi, so gốc phôi và khi gia công nhiều phôi trên cùng bàn máy.","ex_en":"Each vise uses its own work coordinate system, G54 and G55.","ex_ja":"各バイスにはそれぞれのワーク座標系としてG54とG55を割り当てる。","ex_vi":"Mỗi ê-tô dùng một hệ tọa độ phôi riêng là G54 và G55.","syn_en":["work offset","part zero (gốc của hệ)"],"syn_ja":["ワーク原点 (gốc của hệ)","プログラム座標系"]},{"en":"rapid traverse","pos":"noun phrase","ipa":"/ˌræpɪd ˈtrævɜːs/","ja":"早送り","kana":"はやおくり","romaji":"hayaokuri","vi":"chạy dao nhanh","level":2,"def_vi":"Chuyển động không cắt với tốc độ tối đa của máy để định vị dao nhanh (lệnh G00).","def_en":"Non-cutting motion at the machine's maximum rate used to position the tool quickly (G00).","def_ja":"切削を伴わず、機械の最高速度で工具を位置決めする移動（G00）。","usage_en":"Danh từ không đếm được; cũng nói 'rapid' hoặc 'rapids'. Đi với: rapid traverse rate, move in rapid traverse, rapid override.","usage_ja":"Đi với 早送り速度, 早送りオーバライド, 早送りで位置決めする. Cẩn thận va chạm khi dùng 早送り gần phôi.","context_vi":"Dùng trong lập trình (G00), thông số máy (m/min) và khi chạy thử giảm tốc độ để tránh va chạm.","ex_en":"Reduce rapid traverse to 25 % when proving out a new program.","ex_ja":"新しいプログラムを確認するときは、早送りを25%に下げる。","ex_vi":"Giảm tốc độ chạy dao nhanh xuống 25 % khi chạy thử chương trình mới.","syn_en":["rapid","positioning move"],"syn_ja":["位置決め (G00)","ラピッド"]},{"en":"linear interpolation","pos":"noun phrase","ipa":"/ˌlɪniər ɪnˌtɜːpəˈleɪʃn/","ja":"直線補間","kana":"ちょくせんほかん","romaji":"chokusenhokan","vi":"nội suy đường thẳng","level":2,"def_vi":"Chuyển động cắt theo đường thẳng với lượng chạy dao lập trình, các trục phối hợp đồng thời (lệnh G01).","def_en":"Cutting motion along a straight line at the programmed feed, with axes coordinated simultaneously (G01).","def_ja":"指令した送り速度で、複数軸を同時に制御して直線上を切削移動させること（G01）。","usage_en":"Danh từ không đếm được. Đi với: in linear interpolation, linear interpolation mode; trong xưởng hay nói gọn 'G01 move'.","usage_ja":"Đi với 直線補間で切削する, 直線補間指令. Khác 早送り ở chỗ có tốc độ chạy dao F và đường đi đúng thẳng.","context_vi":"Dùng khi lập trình biên dạng, mặt phẳng, vát mép và khi đọc tài liệu điều khiển.","ex_en":"The chamfer is cut using linear interpolation at F200.","ex_ja":"面取りはF200の直線補間で加工する。","ex_vi":"Mép vát được cắt bằng nội suy đường thẳng với F200.","syn_en":["G01 move","straight-line cutting move"],"syn_ja":["G01","直線切削"]},{"en":"circular interpolation","pos":"noun phrase","ipa":"/ˌsɜːkjələr ɪnˌtɜːpəˈleɪʃn/","ja":"円弧補間","kana":"えんこほかん","romaji":"enkohokan","vi":"nội suy cung tròn","level":2,"def_vi":"Chuyển động cắt theo cung tròn trên một mặt phẳng, theo chiều kim đồng hồ (G02) hoặc ngược chiều (G03).","def_en":"Cutting motion along a circular arc in a plane, clockwise (G02) or counterclockwise (G03).","def_ja":"平面上で円弧に沿って切削移動させること。時計回りG02、反時計回りG03。","usage_en":"Danh từ không đếm được. Đi với: circular interpolation with I, J, K or R; helical interpolation (nội suy xoắn) là dạng mở rộng.","usage_ja":"Đi với 円弧補間指令, 半径Rで指令する, I・J・Kで中心を指定する.","context_vi":"Dùng khi lập trình bo góc, lỗ tròn phay nội suy, rãnh cung.","ex_en":"The 40 mm bore is finished by circular interpolation with an end mill.","ex_ja":"直径40mmの穴はエンドミルによる円弧補間で仕上げる。","ex_vi":"Lỗ 40 mm được gia công tinh bằng nội suy cung tròn với dao phay ngón.","syn_en":["G02/G03 move","arc interpolation"],"syn_ja":["G02/G03","円弧切削"]},{"en":"absolute programming","pos":"noun phrase","ipa":"/ˌæbsəluːt ˈprəʊɡræmɪŋ/","ja":"絶対値指令","kana":"ぜったいちしれい","romaji":"zettaichishirei","vi":"lập trình tuyệt đối","level":2,"def_vi":"Cách lập trình trong đó mọi tọa độ được tính từ gốc phôi (G90 trên máy phay).","def_en":"Programming in which every coordinate is given relative to the work origin (G90 on milling controls).","def_ja":"すべての座標値をワーク原点からの位置で指令する方式（フライス系ではG90）。","usage_en":"Danh từ không đếm được. Đi với: in absolute (mode), switch to absolute programming; đối lập với incremental programming.","usage_ja":"Khẩu ngữ: アブソリュート, アブソ. Đi với 絶対値指令で書く, G90で絶対値指令にする.","context_vi":"Dùng khi lập trình và khi đọc chương trình để hiểu tọa độ đang tính theo gốc nào.","ex_en":"We use absolute programming so that one wrong value does not shift all later moves.","ex_ja":"一つの誤った値が後の移動すべてをずらさないよう、絶対値指令を使う。","ex_vi":"Chúng tôi dùng lập trình tuyệt đối để một giá trị sai không làm lệch tất cả các bước di chuyển sau đó.","syn_en":["absolute mode","absolute positioning"],"syn_ja":["アブソリュート指令","絶対指令"]},{"en":"incremental programming","pos":"noun phrase","ipa":"/ˌɪŋkrəˌmentl ˈprəʊɡræmɪŋ/","ja":"増分値指令","kana":"ぞうぶんちしれい","romaji":"zoubunchishirei","vi":"lập trình tương đối (gia số)","level":2,"def_vi":"Cách lập trình trong đó mỗi tọa độ là khoảng dịch chuyển tính từ vị trí hiện tại (G91 trên máy phay).","def_en":"Programming in which each coordinate is the distance moved from the current position (G91 on milling controls).","def_ja":"各座標値を現在位置からの移動量で指令する方式（フライス系ではG91）。","usage_en":"Danh từ không đếm được. Đi với: in incremental (mode), incremental moves; trên máy tiện thường dùng địa chỉ U, W thay cho X, Z.","usage_ja":"Khẩu ngữ: インクリ, インクリメンタル. Đi với 増分値指令で書く, G91.","context_vi":"Dùng cho chương trình con lặp lại nhiều lỗ cách đều, hoặc khi dịch chuyển tương đối.","ex_en":"The hole pattern subprogram uses incremental programming so it can be called at any position.","ex_ja":"穴パターンのサブプログラムは増分値指令で書かれているので、どの位置からでも呼び出せる。","ex_vi":"Chương trình con cho cụm lỗ dùng lập trình tương đối nên có thể gọi tại bất kỳ vị trí nào.","syn_en":["incremental mode","relative programming"],"syn_ja":["インクリメンタル指令","相対値指令"]},{"en":"tool length offset","pos":"noun phrase","ipa":"/ˌtuːl ˈleŋθ ˌɒfset/","ja":"工具長補正","kana":"こうぐちょうほせい","romaji":"kouguchouhosei","vi":"bù chiều dài dao","level":2,"def_vi":"Chức năng cộng chiều dài thực của từng dao vào trục Z để mọi dao cắt đúng độ sâu lập trình (G43).","def_en":"A function that applies each tool's measured length along Z so all tools cut to the programmed depth (G43).","def_ja":"工具ごとに測定した長さをZ方向に補正し、指令どおりの深さで切削させる機能（G43）。","usage_en":"Danh từ đếm được. Động từ: measure / set / enter the tool length offset; đi với H-number (H01).","usage_ja":"Đi với 工具長補正量, 工具長を測定する, G43 H01. Thường đo bằng ツールプリセッタ hoặc タッチセンサ.","context_vi":"Dùng khi so dao, thay dao mới, và là nguyên nhân phổ biến của va chạm nếu nhập sai.","ex_en":"A wrong tool length offset caused the drill to crash into the fixture.","ex_ja":"工具長補正の入力ミスで、ドリルが治具に衝突した。","ex_vi":"Nhập sai bù chiều dài dao đã khiến mũi khoan đâm vào đồ gá.","syn_en":["tool length compensation","H offset"],"syn_ja":["工具長オフセット","長さ補正"]},{"en":"automatic tool changer","pos":"noun phrase","ipa":"/ˌɔːtəˌmætɪk ˈtuːl ˌtʃeɪndʒə/","ja":"自動工具交換装置","kana":"じどうこうぐこうかんそうち","romaji":"jidoukougukoukansouchi","vi":"bộ thay dao tự động (ATC)","level":2,"def_vi":"Cơ cấu tự động lấy dao từ ổ chứa dao và lắp vào trục chính theo lệnh chương trình (M06).","def_en":"A mechanism that automatically takes tools from the magazine and loads them into the spindle on command (M06).","def_ja":"プログラム指令により工具マガジンから工具を取り出し、主軸に自動で装着する装置。","usage_en":"Danh từ đếm được, thường viết tắt ATC. Đi với: ATC arm, tool-to-tool time, ATC alarm.","usage_ja":"Gần như luôn nói ATC (エーティーシー). Đi với ATCアーム, 工具交換時間, ATCが止まる.","context_vi":"Dùng trên trung tâm gia công; quan trọng trong thông số thời gian thay dao và bảo dưỡng.","ex_en":"The automatic tool changer swaps tools in 1.5 seconds.","ex_ja":"この自動工具交換装置は1.5秒で工具を交換する。","ex_vi":"Bộ thay dao tự động này đổi dao trong 1,5 giây.","syn_en":["ATC","tool changer"],"syn_ja":["ATC","工具交換装置"]},{"en":"single block","pos":"noun phrase","ipa":"/ˌsɪŋɡl ˈblɒk/","ja":"シングルブロック","kana":"シングルブロック","romaji":"shinguruburokku","vi":"chạy từng câu lệnh (Single Block)","level":2,"def_vi":"Chế độ máy chỉ thực hiện một câu lệnh (block) rồi dừng, chờ nhấn Cycle Start để chạy câu tiếp theo.","def_en":"A mode in which the machine executes one program block and stops until cycle start is pressed again.","def_ja":"プログラムを1ブロック実行するごとに停止し、再びサイクルスタートを押すまで待つモード。","usage_en":"Danh từ, hay dùng như tính từ: single block mode, run in single block, turn single block on/off.","usage_ja":"Đi với シングルブロックで確認する, シングルブロックON. Thường dùng cùng 早送りオーバライド thấp khi chạy thử.","context_vi":"Dùng khi chạy thử chương trình mới hoặc gia công chi tiết đầu tiên để kiểm tra từng bước.","ex_en":"Run the first part in single block with the rapid override at 25 %.","ex_ja":"初品は早送りオーバライド25%、シングルブロックで加工する。","ex_vi":"Chạy chi tiết đầu tiên ở chế độ từng câu lệnh với tốc độ chạy nhanh 25 %.","syn_en":["single-block mode","block-by-block execution"],"syn_ja":["シングルブロック運転","1ブロック運転"]},{"en":"cutter radius compensation","pos":"noun phrase","ipa":"/ˌkʌtə ˈreɪdiəs ˌkɒmpenˈseɪʃn/","ja":"工具径補正","kana":"こうぐけいほせい","romaji":"kougukeihosei","vi":"bù bán kính dao","level":3,"def_vi":"Chức năng tự dịch đường dao lệch sang trái (G41) hoặc phải (G42) biên dạng một lượng bằng bán kính dao.","def_en":"A function that offsets the toolpath left (G41) or right (G42) of the contour by the tool radius.","def_ja":"輪郭に対して工具経路を工具半径分だけ左（G41）または右（G42）にずらす機能。","usage_en":"Danh từ không đếm được. Đi với: apply / cancel cutter compensation (G40), D-offset; cũng gọi 'cutter comp', 'tool nose radius compensation' trên máy tiện.","usage_ja":"Đi với 工具径補正をかける / キャンセルする, G41/G42/G40. Trên máy tiện gọi 刃先R補正.","context_vi":"Dùng khi phay biên dạng chính xác, cho phép điều chỉnh kích thước bằng giá trị bù mà không sửa chương trình.","ex_en":"Increase the D value slightly in cutter radius compensation to leave 0.02 mm for finishing.","ex_ja":"工具径補正のD値を少し大きくして、仕上げ代を0.02mm残す。","ex_vi":"Tăng nhẹ giá trị D trong bù bán kính dao để để lại 0,02 mm lượng dư gia công tinh.","syn_en":["cutter compensation","tool radius compensation"],"syn_ja":["工具径オフセット","刃先R補正 (máy tiện)"]},{"en":"canned cycle","pos":"noun phrase","ipa":"/ˌkænd ˈsaɪkl/","ja":"固定サイクル","kana":"こていサイクル","romaji":"koteisaikuru","vi":"chu trình gia công cố định","level":3,"def_vi":"Lệnh gộp sẵn một chuỗi chuyển động lặp lại như khoan, khoan bẻ phoi, taro trong một câu lệnh (G81–G89).","def_en":"A single command that packages a repeated motion sequence such as drilling, peck drilling or tapping (G81–G89).","def_ja":"穴あけ・ペック・タップなどの一連の動作を1つの指令にまとめたもの（G81〜G89など）。","usage_en":"Danh từ đếm được. Đi với: drilling canned cycle, peck drilling cycle (G83), cancel the canned cycle with G80.","usage_ja":"Đi với 穴あけ固定サイクル, 固定サイクルをキャンセルする (G80). Máy tiện có 複合形固定サイクル (G71).","context_vi":"Dùng khi lập trình nhiều lỗ, taro, tiện thô để rút ngắn chương trình.","ex_en":"A G83 canned cycle is used for the deep 6 mm holes to break chips.","ex_ja":"深いφ6の穴には切りくず分断のためG83の固定サイクルを使う。","ex_vi":"Chu trình gia công cố định G83 được dùng cho các lỗ sâu 6 mm để bẻ phoi.","syn_en":["fixed cycle","drilling cycle (nghĩa hẹp hơn)"],"syn_ja":["穴あけサイクル (nghĩa hẹp hơn)","固定サイクル指令"]},{"en":"custom macro","pos":"noun phrase","ipa":"/ˌkʌstəm ˈmækrəʊ/","ja":"カスタムマクロ","kana":"カスタムマクロ","romaji":"kasutamumakuro","vi":"chương trình macro","level":3,"def_vi":"Chương trình NC dùng biến, phép tính và lệnh rẽ nhánh để tạo chu trình linh hoạt hoặc tự động hóa đo đạc.","def_en":"An NC program that uses variables, arithmetic and branching to create flexible cycles or automate measurement.","def_ja":"変数・演算・分岐を用いて、汎用的なサイクルや計測の自動化を行うNCプログラム。","usage_en":"Danh từ đếm được. Đi với: macro variable (#100), call a custom macro (G65), Macro B (tên trên máy Fanuc).","usage_ja":"Đi với マクロ変数, G65で呼び出す, マクロを組む. Khẩu ngữ: マクロ.","context_vi":"Dùng cho họ chi tiết có kích thước thay đổi, chu trình đo bằng đầu dò, và đếm chi tiết.","ex_en":"One custom macro handles all twelve flange sizes by reading the diameter from a variable.","ex_ja":"一つのカスタムマクロで、変数から直径を読み込み12種類のフランジすべてに対応している。","ex_vi":"Một chương trình macro xử lý cả mười hai cỡ mặt bích bằng cách đọc đường kính từ biến.","syn_en":["macro program","parametric program"],"syn_ja":["マクロプログラム","ユーザマクロ"]},{"en":"post-processor","pos":"noun","ipa":"/ˌpəʊst ˈprəʊsesə/","ja":"ポストプロセッサ","kana":"ポストプロセッサ","romaji":"posutopurosessa","vi":"bộ hậu xử lý","level":3,"def_vi":"Phần mềm chuyển đường chạy dao từ CAM thành mã G phù hợp với bộ điều khiển và cấu hình của từng máy.","def_en":"Software that converts CAM toolpaths into G-code matching a specific machine's control and kinematics.","def_ja":"CAMの工具経路を、特定の機械の制御装置と構成に合ったNCコードへ変換するソフトウェア。","usage_en":"Danh từ đếm được; khẩu ngữ 'post'. Động từ: edit / customise the post-processor, post (out) a program.","usage_ja":"Khẩu ngữ ポスト. Đi với ポストプロセッサを作成する / 修正する, ポスト処理.","context_vi":"Dùng khi đưa máy mới vào sản xuất, đặc biệt máy 5 trục, hoặc khi chương trình CAM chạy sai trên máy.","ex_en":"The post-processor was modified to output M08 after every tool change.","ex_ja":"工具交換ごとにM08を出力するよう、ポストプロセッサを修正した。","ex_vi":"Bộ hậu xử lý đã được sửa để xuất M08 sau mỗi lần thay dao.","syn_en":["post","postprocessor"],"syn_ja":["ポスト","ポストプロセサ"]},{"en":"five-axis machining","pos":"noun phrase","ipa":"/ˌfaɪv ˈæksɪs məˌʃiːnɪŋ/","ja":"5軸加工","kana":"ごじくかこう","romaji":"gojikukakou","vi":"gia công 5 trục","level":3,"def_vi":"Gia công dùng ba trục thẳng và hai trục quay để định hướng dao, cắt được mặt cong phức tạp trong một lần gá.","def_en":"Machining using three linear and two rotary axes to orient the tool, reaching complex surfaces in one setup.","def_ja":"直線3軸と回転2軸で工具の姿勢を変え、複雑な曲面を一度の段取りで加工すること。","usage_en":"Danh từ không đếm được. Phân biệt 'simultaneous five-axis machining' (5 trục đồng thời) và '3+2 machining' (định vị).","usage_ja":"Phân biệt 同時5軸加工 và 割出し5軸加工 (3+2). Đi với 5軸加工機, 5軸マシニングセンタ.","context_vi":"Dùng trong hàng không (cánh quạt, blisk), khuôn mẫu, cấy ghép y tế.","ex_en":"Five-axis machining let us finish the impeller blades without re-clamping.","ex_ja":"5軸加工により、インペラの羽根を段取り替えなしで仕上げることができた。","ex_vi":"Gia công 5 trục giúp chúng tôi hoàn thiện cánh bánh công tác mà không cần gá lại.","syn_en":["5-axis machining","simultaneous five-axis machining (nghĩa hẹp hơn)"],"syn_ja":["同時5軸加工 (nghĩa hẹp hơn)","5軸制御加工"]},{"en":"look-ahead control","pos":"noun phrase","ipa":"/ˈlʊk əˌhed kənˌtrəʊl/","ja":"先読み制御","kana":"さきよみせいぎょ","romaji":"sakiyomiseigyo","vi":"điều khiển đọc trước (look-ahead)","level":3,"def_vi":"Chức năng bộ điều khiển đọc trước nhiều câu lệnh để tính tăng giảm tốc, giữ biên dạng chính xác khi chạy nhanh.","def_en":"A control function that reads many blocks ahead to plan acceleration, keeping contours accurate at high feed.","def_ja":"多数のブロックを先に読み込んで加減速を計画し、高速送りでも形状精度を保つ制御機能。","usage_en":"Danh từ không đếm được. Đi với: look-ahead blocks (số câu đọc trước), high-speed look-ahead, AI contour control (tên thương mại Fanuc).","usage_ja":"Đi với 先読みブロック数, 高精度輪郭制御 (tên chức năng Fanuc), 先読み制御をONにする.","context_vi":"Dùng trong phay tốc độ cao khuôn mẫu với chương trình CAM có hàng nghìn đoạn thẳng ngắn.","ex_en":"Without look-ahead control, the machine slowed down at every short segment of the mold surface.","ex_ja":"先読み制御なしでは、金型曲面の短い線分ごとに機械が減速していた。","ex_vi":"Không có điều khiển đọc trước, máy giảm tốc ở mỗi đoạn ngắn trên bề mặt khuôn.","syn_en":["look-ahead","advanced preview control"],"syn_ja":["先読み","AI輪郭制御 (tên thương mại)"]}]},{"id":42,"words":[{"en":"cutting tool","pos":"noun phrase","ipa":"/ˈkʌtɪŋ ˌtuːl/","ja":"切削工具","kana":"せっさくこうぐ","romaji":"sessakukougu","vi":"dụng cụ cắt","level":1,"def_vi":"Dụng cụ có một hay nhiều lưỡi cắt dùng để bóc vật liệu khỏi phôi dưới dạng phoi khi gia công cắt gọt.","def_en":"A tool with one or more cutting edges that removes material from a workpiece in the form of chips.","def_ja":"一つ以上の切れ刃をもち、工作物から切りくずとして材料を除去する工具。","usage_en":"Danh từ đếm được. Hay đi với: single-point / multi-point cutting tool, carbide cutting tool; động từ: select / change / set a cutting tool.","usage_ja":"Văn bản kỹ thuật dùng 切削工具; ngoài xưởng hay nói gọn 工具 hoặc 刃物 (はもの). Động từ đi kèm: 選定する, 交換する, 取り付ける.","context_vi":"Dùng trong mọi nguyên công tiện, phay, khoan, doa và trong catalog dao của các hãng như Sandvik, Mitsubishi, Kyocera.","ex_en":"Cutting tool costs account for about 5% of the machining cost per part.","ex_ja":"部品一個あたりの加工費のうち、切削工具の費用は約5%を占める。","ex_vi":"Chi phí dụng cụ cắt chiếm khoảng 5% chi phí gia công mỗi chi tiết.","syn_en":["cutter (thường chỉ dao phay)","tool (khẩu ngữ)"],"syn_ja":["刃物 (khẩu ngữ)","工具"]},{"en":"cutting edge","pos":"noun phrase","ipa":"/ˈkʌtɪŋ ˌedʒ/","ja":"切れ刃","kana":"きれは","romaji":"kireha","vi":"lưỡi cắt","level":1,"def_vi":"Đường giao giữa mặt trước và mặt sau của dao, là phần trực tiếp tách vật liệu thành phoi.","def_en":"The edge where the rake face meets the flank, which actually separates the chip from the workpiece.","def_ja":"すくい面と逃げ面が交わる稜線で、工作物から切りくずを分離する部分。","usage_en":"Danh từ đếm được. Hay đi với: main / minor cutting edge, sharp / worn / chipped cutting edge.","usage_ja":"Hay ghép: 主切れ刃, 副切れ刃; nói 切れ刃が欠ける / 摩耗する. Ngoài xưởng gọi 刃先 (はさき) khi chỉ phần mũi của lưỡi cắt.","context_vi":"Dùng khi kiểm tra tình trạng dao, mô tả hình học dao trong catalog và trong báo cáo hư hỏng dao.","ex_en":"Inspect the cutting edge under a magnifier before reusing the insert.","ex_ja":"チップを再使用する前に、ルーペで切れ刃を点検すること。","ex_vi":"Hãy kiểm tra lưỡi cắt bằng kính lúp trước khi dùng lại mảnh dao.","syn_en":["edge","tool edge"],"syn_ja":["刃先 (gần nghĩa)","エッジ"]},{"en":"high-speed steel","pos":"noun phrase","ipa":"/ˌhaɪ spiːd ˈstiːl/","ja":"高速度工具鋼","kana":"こうそくどこうぐこう","romaji":"kousokudokougukou","vi":"thép gió","level":1,"def_vi":"Thép dụng cụ hợp kim cao chứa W, Mo, Cr, V, giữ được độ cứng đến khoảng 600 °C, dùng làm mũi khoan, ta rô, dao phay.","def_en":"A highly alloyed tool steel containing W, Mo, Cr and V that keeps its hardness up to about 600 °C.","def_ja":"W・Mo・Cr・Vを多く含み、約600 °Cまで硬さを保つ工具鋼。","usage_en":"Danh từ không đếm được, thường viết tắt HSS và dùng như tính từ: HSS drill, HSS tap. Có gạch nối giữa high và speed.","usage_ja":"Ngoài xưởng gần như luôn gọi ハイス; ký hiệu JIS là SKH (SKH51…). Ví dụ: ハイスドリル, 粉末ハイス.","context_vi":"Dùng cho mũi khoan, ta rô, dao chuốt, dao phay ngón cỡ nhỏ, khi cần độ dai cao và giá rẻ.","ex_en":"Taps are still mostly made of high-speed steel because of its toughness.","ex_ja":"タップは靭性が高いため、今でも高速度工具鋼製が主流である。","ex_vi":"Ta rô hiện vẫn chủ yếu được làm bằng thép gió vì có độ dai cao.","syn_en":["HSS"],"syn_ja":["ハイス","SKH (ký hiệu JIS)"]},{"en":"cemented carbide","pos":"noun phrase","ipa":"/sɪˌmentɪd ˈkɑːbaɪd/","ja":"超硬合金","kana":"ちょうこうごうきん","romaji":"choukougoukin","vi":"hợp kim cứng","level":1,"def_vi":"Vật liệu thiêu kết từ hạt cacbua vonfram (WC) với chất kết dính coban, rất cứng và chịu nhiệt, dùng làm dao cắt.","def_en":"A sintered material of tungsten carbide grains bonded with cobalt, very hard and heat-resistant, used for cutting tools.","def_ja":"炭化タングステン粒子をコバルトで結合した焼結材料で、硬く耐熱性に優れる。","usage_en":"Danh từ không đếm được; trong xưởng gọi ngắn là carbide: carbide insert, solid carbide end mill. Đừng nhầm carbide với carbon.","usage_ja":"Ngoài xưởng gọi tắt 超硬: 超硬チップ, 超硬ドリル, ソリッド超硬. Văn bản chuẩn dùng 超硬合金.","context_vi":"Vật liệu dao phổ biến nhất trong gia công CNC: mảnh dao, mũi khoan, dao phay ngón nguyên khối.","ex_en":"Most indexable inserts are made of coated cemented carbide.","ex_ja":"ほとんどのスローアウェイチップは、コーティングされた超硬合金でできている。","ex_vi":"Hầu hết mảnh dao thay thế được làm bằng hợp kim cứng có phủ.","syn_en":["carbide (khẩu ngữ)","tungsten carbide"],"syn_ja":["超硬 (khẩu ngữ)","WC-Co合金"]},{"en":"indexable insert","pos":"noun phrase","ipa":"/ɪnˌdeksəbl ˈɪnsɜːt/","ja":"スローアウェイチップ","kana":"スローアウェイチップ","romaji":"surooaweichippu","vi":"mảnh dao thay thế (insert)","level":1,"def_vi":"Mảnh dao nhỏ có nhiều lưỡi cắt, được kẹp cơ khí trên cán dao; khi mòn chỉ cần xoay sang góc khác hoặc thay mảnh mới.","def_en":"A small replaceable tool tip with several cutting edges, clamped in a holder and rotated or replaced when worn.","def_ja":"ホルダに機械的に固定する複数の切れ刃をもつ刃先で、摩耗したら回転または交換する。","usage_en":"Danh từ đếm được, thường nói gọn insert. Động từ: index / rotate / change an insert; hay đi với insert grade, insert geometry.","usage_ja":"Ngoài xưởng gọi チップ hoặc インサート; JIS mới dùng 刃先交換チップ. Động từ: コーナチェンジする, 交換する.","context_vi":"Dùng trên dao tiện, dao phay mặt, dao khoan gắn mảnh trong sản xuất hàng loạt.","ex_en":"Rotate the indexable insert to a fresh corner every 200 parts.","ex_ja":"200個ごとにスローアウェイチップを新しいコーナに回すこと。","ex_vi":"Cứ 200 chi tiết thì xoay mảnh dao thay thế sang góc mới.","syn_en":["insert","throwaway insert"],"syn_ja":["刃先交換チップ","インサート","チップ (khẩu ngữ)"]},{"en":"tool holder","pos":"noun phrase","ipa":"/ˈtuːl ˌhəʊldə/","ja":"ツールホルダ","kana":"ツールホルダ","romaji":"tsuuruhoruda","vi":"cán dao / đầu kẹp dao","level":1,"def_vi":"Bộ phận giữ dao hoặc mảnh dao và lắp nó lên đài dao hay trục chính của máy.","def_en":"The body that holds a cutting tool or insert and mounts it on the turret or spindle.","def_ja":"切削工具やチップを保持し、刃物台や主軸に取り付けるための部品。","usage_en":"Danh từ đếm được; viết toolholder hay tool holder đều gặp. Hay đi với: turning tool holder, shrink-fit tool holder, BT40 tool holder.","usage_ja":"Dao tiện thường gọi バイトホルダ; trên trung tâm gia công gọi ツールホルダ hoặc ホルダ. Động từ: ホルダに取り付ける, ホルダを交換する.","context_vi":"Dùng khi chọn dao trong catalog, chuẩn bị dao cho máy CNC và tính chiều dài nhô của dao.","ex_en":"A rigid tool holder reduces vibration in heavy roughing.","ex_ja":"剛性の高いツールホルダを使うと、重切削での振動が減る。","ex_vi":"Cán dao cứng vững giúp giảm rung khi gia công thô nặng.","syn_en":["toolholder","shank (cán dao tiện)"],"syn_ja":["ホルダ","バイトホルダ (dao tiện)"]},{"en":"tool wear","pos":"noun phrase","ipa":"/ˈtuːl ˌweə/","ja":"工具摩耗","kana":"こうぐまもう","romaji":"kougumamou","vi":"mòn dao","level":1,"def_vi":"Sự mất dần vật liệu và thay đổi hình dạng của lưỡi cắt trong quá trình cắt do ma sát, nhiệt và tác dụng hóa học.","def_en":"The gradual loss of material and change of shape at the cutting edge caused by friction, heat and chemical action.","def_ja":"摩擦・熱・化学作用により、切れ刃の材料が徐々に失われ形状が変化すること。","usage_en":"Danh từ không đếm được. Động từ: reduce / monitor / measure tool wear; hay nói excessive tool wear, rapid tool wear.","usage_ja":"Hay nói 工具摩耗が進む / 大きい; ngoài xưởng nói 刃物の摩耗 hoặc 刃が減る. Thường kèm 工具摩耗量 (lượng mòn).","context_vi":"Dùng khi phân tích bề mặt xấu, sai kích thước theo thời gian và khi lên lịch thay dao.","ex_en":"Tool wear caused the bore diameter to drift by 15 µm.","ex_ja":"工具摩耗により、穴径が15 µmずれた。","ex_vi":"Mòn dao làm đường kính lỗ bị trôi 15 µm.","syn_en":["cutting tool wear","edge wear"],"syn_ja":["刃物の摩耗 (khẩu ngữ)","工具損耗"]},{"en":"chipping","pos":"noun","ipa":"/ˈtʃɪpɪŋ/","ja":"チッピング","kana":"チッピング","romaji":"chippingu","vi":"mẻ lưỡi cắt","level":1,"def_vi":"Hiện tượng các mảnh nhỏ bị vỡ bong ra khỏi lưỡi cắt, thường do va đập, rung hoặc lưỡi cắt quá giòn.","def_en":"Small fragments breaking away from the cutting edge, usually caused by impact, vibration or a too-brittle edge.","def_ja":"衝撃・振動や刃先のもろさにより、切れ刃が小さく欠けること。","usage_en":"Danh từ không đếm được (edge chipping); động từ dạng the edge chipped. Đừng nhầm với chips (phoi).","usage_ja":"Dùng như danh từ: チッピングが発生する. Ngoài xưởng nói 刃が欠ける / 微小欠損. Phân biệt với 欠損 (vỡ lớn).","context_vi":"Hay gặp khi phay hoặc tiện cắt gián đoạn, gia công gang, hoặc khi máy và đồ gá rung.","ex_en":"Chipping appeared on the edge after only ten interrupted cuts.","ex_ja":"断続切削わずか10回で、切れ刃にチッピングが発生した。","ex_vi":"Lưỡi cắt bị mẻ chỉ sau mười lần cắt gián đoạn.","syn_en":["edge chipping","microchipping (mẻ rất nhỏ)"],"syn_ja":["微小欠損","刃欠け (khẩu ngữ)"]},{"en":"tool life","pos":"noun phrase","ipa":"/ˈtuːl ˌlaɪf/","ja":"工具寿命","kana":"こうぐじゅみょう","romaji":"kougujumyou","vi":"tuổi bền dao","level":1,"def_vi":"Thời gian cắt hoặc số chi tiết mà dao gia công được cho đến khi đạt tiêu chuẩn mòn quy định.","def_en":"The cutting time, or number of parts, a tool can produce before reaching a specified wear criterion.","def_ja":"規定の摩耗基準に達するまでに、工具が切削できる時間または加工個数。","usage_en":"Danh từ không đếm được. Động từ: extend / improve / shorten tool life; đơn vị thường là minutes hoặc parts per edge.","usage_ja":"Hay nói 工具寿命を延ばす / 工具寿命が短い; ngoài xưởng nói 寿命 hoặc 刃持ち (はもち).","context_vi":"Dùng khi so sánh dao, tính chi phí gia công và cài đặt quản lý tuổi bền dao trên máy CNC.","ex_en":"Lowering the cutting speed by 10% doubled the tool life.","ex_ja":"切削速度を10%下げたところ、工具寿命が2倍になった。","ex_vi":"Giảm tốc độ cắt 10% đã làm tuổi bền dao tăng gấp đôi.","syn_en":["edge life","tool durability (ít dùng)"],"syn_ja":["刃持ち (khẩu ngữ)","寿命"]},{"en":"cutting fluid","pos":"noun phrase","ipa":"/ˈkʌtɪŋ ˌfluːɪd/","ja":"切削油剤","kana":"せっさくゆざい","romaji":"sessakuyuzai","vi":"dung dịch trơn nguội","level":1,"def_vi":"Chất lỏng tưới vào vùng cắt để làm mát, bôi trơn, giảm mòn dao và cuốn phoi đi.","def_en":"A liquid applied to the cutting zone to cool, lubricate, reduce tool wear and flush away chips.","def_ja":"切削点に供給し、冷却・潤滑・工具摩耗の低減・切りくず排出を行う液体。","usage_en":"Danh từ không đếm được. Hay đi với: water-soluble / neat cutting fluid; động từ: apply / supply cutting fluid. Ngoài xưởng hay nói coolant.","usage_ja":"Chia ra 水溶性切削油剤 và 不水溶性切削油剤; ngoài xưởng gọi クーラント hoặc 切削油. Động từ: かける, 供給する.","context_vi":"Dùng ở hầu hết máy tiện, phay, khoan; liên quan đến quản lý nồng độ, vi khuẩn và an toàn môi trường.","ex_en":"Check the concentration of the cutting fluid every morning.","ex_ja":"毎朝、切削油剤の濃度を確認すること。","ex_vi":"Kiểm tra nồng độ dung dịch trơn nguội mỗi sáng.","syn_en":["coolant","cutting oil (dạng dầu)"],"syn_ja":["クーラント","切削油"]},{"en":"rake face","pos":"noun phrase","ipa":"/ˈreɪk ˌfeɪs/","ja":"すくい面","kana":"すくいめん","romaji":"sukuimen","vi":"mặt trước (của dao)","level":2,"def_vi":"Mặt của dao mà phoi trượt lên khi được tách ra khỏi phôi.","def_en":"The tool surface over which the chip flows as it is cut from the workpiece.","def_ja":"切削時に切りくずが流れ出て接触する工具の面。","usage_en":"Danh từ đếm được. Hay đi với: on the rake face, rake face wear; liên quan chặt với rake angle.","usage_ja":"Hay ghép: すくい面摩耗, すくい面のクレータ. Chữ すくい thường viết bằng hiragana.","context_vi":"Dùng khi mô tả hình học dao, rãnh bẻ phoi và cơ chế mòn lõm.","ex_en":"A crater formed on the rake face near the cutting edge.","ex_ja":"切れ刃近くのすくい面にクレータが生じた。","ex_vi":"Một vết lõm đã hình thành trên mặt trước gần lưỡi cắt.","syn_en":["tool face","face (ngắn gọn)"],"syn_ja":["すくい角 (liên quan)"]},{"en":"flank face","pos":"noun phrase","ipa":"/ˈflæŋk ˌfeɪs/","ja":"逃げ面","kana":"にげめん","romaji":"nigemen","vi":"mặt sau (của dao)","level":2,"def_vi":"Mặt của dao đối diện với bề mặt vừa gia công trên phôi, được làm vát đi để không cọ xát vào phôi.","def_en":"The tool surface facing the newly machined surface, relieved so that it does not rub the workpiece.","def_ja":"加工面に向き合い、工作物とこすれないよう逃がした工具の面。","usage_en":"Danh từ đếm được; thường nói gọn flank. Hay đi với: main flank, minor flank, flank wear.","usage_ja":"Hay ghép: 主逃げ面, 副逃げ面, 逃げ面摩耗. Đọc là にげめん.","context_vi":"Dùng khi đo mòn dao và mô tả hình học dao trong tài liệu nguyên lý cắt.","ex_en":"Measure the wear land on the flank face with a toolmaker's microscope.","ex_ja":"工具顕微鏡で逃げ面の摩耗幅を測定する。","ex_vi":"Đo vùng mòn trên mặt sau bằng kính hiển vi dụng cụ.","syn_en":["flank","clearance face"],"syn_ja":["逃げ角 (liên quan)"]},{"en":"rake angle","pos":"noun phrase","ipa":"/ˈreɪk ˌæŋɡl/","ja":"すくい角","kana":"すくいかく","romaji":"sukuikaku","vi":"góc trước","level":2,"def_vi":"Góc giữa mặt trước của dao và mặt phẳng vuông góc với hướng cắt; góc dương giúp cắt nhẹ hơn.","def_en":"The angle between the rake face and a plane perpendicular to the cutting direction; positive values give lighter cutting.","def_ja":"すくい面と切削方向に垂直な面とのなす角。正にすると切れ味が良くなる。","usage_en":"Danh từ đếm được. Hay nói positive / negative / neutral rake angle, a 6° rake angle.","usage_ja":"Hay nói 正のすくい角, 負のすくい角; ngoài xưởng gọi tắt mảnh dao là ポジ hoặc ネガ.","context_vi":"Dùng khi chọn mảnh dao theo vật liệu: nhôm cần góc trước dương lớn, thép cứng dùng góc âm.","ex_en":"A larger rake angle reduces cutting force but weakens the edge.","ex_ja":"すくい角を大きくすると切削抵抗は減るが、刃先は弱くなる。","ex_vi":"Góc trước lớn hơn làm giảm lực cắt nhưng lưỡi cắt yếu hơn.","syn_en":["rake","top rake (dao tiện)"],"syn_ja":["ポジ / ネガ (khẩu ngữ, chỉ dấu của góc)","逃げ角 (liên quan)"]},{"en":"clearance angle","pos":"noun phrase","ipa":"/ˈklɪərəns ˌæŋɡl/","ja":"逃げ角","kana":"にげかく","romaji":"nigekaku","vi":"góc sau","level":2,"def_vi":"Góc giữa mặt sau của dao và bề mặt đã gia công, giúp dao không cọ xát vào phôi.","def_en":"The angle between the flank face and the machined surface, which prevents the tool rubbing the workpiece.","def_ja":"逃げ面と加工面とのなす角で、工具と工作物のこすれを防ぐ。","usage_en":"Danh từ đếm được. Hay đi với: primary / secondary clearance angle; còn gọi relief angle. Góc sau quá nhỏ gây rubbing.","usage_ja":"Dùng trong bản vẽ dao và catalog: 逃げ角7°. Mảnh dao có góc sau gọi ポジチップ, không có gọi ネガチップ.","context_vi":"Dùng khi mài dao, chọn mảnh dao và giải thích hiện tượng mòn mặt sau.","ex_en":"The clearance angle was ground to 8° to avoid rubbing.","ex_ja":"こすれを防ぐため、逃げ角を8°に研削した。","ex_vi":"Góc sau được mài thành 8° để tránh cọ xát.","syn_en":["relief angle"],"syn_ja":["二番 (khẩu ngữ, phần vát sau lưỡi cắt)"]},{"en":"nose radius","pos":"noun phrase","ipa":"/ˈnəʊz ˌreɪdiəs/","ja":"コーナ半径","kana":"コーナはんけい","romaji":"koonahankei","vi":"bán kính mũi dao","level":2,"def_vi":"Bán kính cung tròn ở mũi dao nối hai lưỡi cắt, ảnh hưởng đến độ nhám bề mặt và độ bền mũi dao.","def_en":"The radius of the rounded tool corner joining two cutting edges, affecting surface finish and corner strength.","def_ja":"二つの切れ刃をつなぐコーナの丸みの半径で、仕上げ面粗さと刃先強度に影響する。","usage_en":"Danh từ đếm được; số nhiều nose radii. Thường ghi nose radius 0.8 mm; hay đi với large / small nose radius.","usage_ja":"Catalog dùng コーナ半径 hoặc コーナR (コーナアール); ngoài xưởng gọi ノーズR. Ví dụ: コーナ半径0.8のチップ.","context_vi":"Dùng khi chọn mảnh dao tiện và tính độ nhám lý thuyết theo lượng chạy dao.","ex_en":"A larger nose radius gives a better finish at the same feed.","ex_ja":"同じ送りなら、コーナ半径が大きいほど仕上げ面が良くなる。","ex_vi":"Với cùng lượng chạy dao, bán kính mũi dao lớn hơn cho bề mặt tốt hơn.","syn_en":["corner radius","tool nose radius"],"syn_ja":["コーナR","ノーズR (khẩu ngữ)"]},{"en":"chip breaker","pos":"noun phrase","ipa":"/ˈtʃɪp ˌbreɪkə/","ja":"チップブレーカ","kana":"チップブレーカ","romaji":"chippubureeka","vi":"rãnh bẻ phoi","level":2,"def_vi":"Rãnh hoặc gờ trên mặt trước của dao làm phoi cuộn lại và gãy thành đoạn ngắn.","def_en":"A groove or step on the rake face that curls the chip and breaks it into short pieces.","def_ja":"すくい面に設けた溝や段で、切りくずをカールさせて短く分断するもの。","usage_en":"Danh từ đếm được, viết rời chip breaker hoặc liền chipbreaker. Hay đi với: chip breaker geometry, finishing / roughing chip breaker.","usage_ja":"Catalog gọi tắt ブレーカ: 仕上げ用ブレーカ, 荒加工用ブレーカ. Động từ: ブレーカを選定する.","context_vi":"Dùng khi chọn mảnh dao để tránh phoi dây quấn vào dao và phôi trên máy tiện CNC.","ex_en":"Switching to a finishing chip breaker stopped the long stringy chips.","ex_ja":"仕上げ用のチップブレーカに変えたら、長く伸びる切りくずがなくなった。","ex_vi":"Đổi sang rãnh bẻ phoi dùng cho tiện tinh thì không còn phoi dây dài.","syn_en":["chipbreaker","chip former"],"syn_ja":["ブレーカ (khẩu ngữ)"]},{"en":"flank wear","pos":"noun phrase","ipa":"/ˈflæŋk ˌweə/","ja":"逃げ面摩耗","kana":"にげめんまもう","romaji":"nigemenmamou","vi":"mòn mặt sau","level":2,"def_vi":"Dạng mòn tạo vùng mòn phẳng trên mặt sau ngay dưới lưỡi cắt do cọ xát với bề mặt gia công.","def_en":"Wear forming a flat land on the flank just below the cutting edge, caused by rubbing against the machined surface.","def_ja":"加工面とのこすれにより、切れ刃直下の逃げ面に平らな摩耗帯ができる摩耗。","usage_en":"Danh từ không đếm được. Hay đi với: flank wear width (VB), uniform flank wear; ví dụ flank wear reached 0.3 mm.","usage_ja":"Thường đo bằng 逃げ面摩耗幅 VB; nói 逃げ面摩耗が進行する. Là dạng mòn chuẩn để đánh giá tuổi bền.","context_vi":"Dạng mòn bình thường nhất, dùng làm tiêu chuẩn tuổi bền dao trong thí nghiệm và trong sản xuất.","ex_en":"Flank wear grows quickly once the coating is worn through.","ex_ja":"コーティングがはがれると、逃げ面摩耗は急速に進む。","ex_vi":"Khi lớp phủ bị mòn thủng, mòn mặt sau tăng rất nhanh.","syn_en":["wear land (liên quan)","VB wear"],"syn_ja":["フランク摩耗"]},{"en":"crater wear","pos":"noun phrase","ipa":"/ˈkreɪtə ˌweə/","ja":"クレータ摩耗","kana":"クレータまもう","romaji":"kureetamamou","vi":"mòn lõm mặt trước","level":2,"def_vi":"Dạng mòn tạo hố lõm trên mặt trước, cách lưỡi cắt một đoạn, do nhiệt và khuếch tán khi phoi nóng trượt qua.","def_en":"A crater-shaped hollow worn into the rake face behind the edge by hot chips, mainly through diffusion.","def_ja":"高温の切りくずにより、すくい面の刃先後方にくぼみができる摩耗。","usage_en":"Danh từ không đếm được. Hay đi với: crater depth (KT), severe crater wear; thường gặp khi cắt thép ở tốc độ cao.","usage_ja":"Tên chuẩn là すくい面摩耗; ngoài xưởng hay gọi クレータ摩耗 hoặc クレータ. Nói クレータが深くなる.","context_vi":"Hay gặp khi tiện thép ở tốc độ cắt cao; dùng để chọn mác dao có lớp phủ Al2O3.","ex_en":"Crater wear weakened the edge until it finally broke.","ex_ja":"クレータ摩耗で刃先が弱くなり、最終的に欠損した。","ex_vi":"Mòn lõm mặt trước làm lưỡi cắt yếu dần cho đến khi gãy.","syn_en":["cratering","rake face wear"],"syn_ja":["すくい面摩耗"]},{"en":"built-up edge","pos":"noun phrase","ipa":"/ˌbɪlt ʌp ˈedʒ/","ja":"構成刃先","kana":"こうせいはさき","romaji":"kouseihasaki","vi":"lẹo dao","level":2,"def_vi":"Lớp vật liệu phôi bám dính và tích tụ trên mũi dao khi cắt ở tốc độ thấp, làm xấu bề mặt và sai kích thước.","def_en":"Workpiece material that welds and builds up on the tool tip at low speeds, spoiling surface finish and size.","def_ja":"低速切削時に工作物材料が刃先に溶着・堆積したもので、仕上げ面や寸法を悪化させる。","usage_en":"Danh từ không đếm được, viết tắt BUE, luôn có gạch nối built-up. Động từ: prevent / suppress built-up edge; built-up edge forms.","usage_ja":"Nói 構成刃先が発生する / 抑える; ngoài xưởng hay nói 溶着 (bám dính). Đọc はさき, không đọc じんさき.","context_vi":"Hay gặp khi gia công nhôm, thép cacbon thấp, thép không gỉ ở tốc độ cắt thấp.","ex_en":"Raising the cutting speed eliminated the built-up edge.","ex_ja":"切削速度を上げたら、構成刃先がなくなった。","ex_vi":"Tăng tốc độ cắt đã loại bỏ hiện tượng lẹo dao.","syn_en":["BUE"],"syn_ja":["溶着 (gần nghĩa, khẩu ngữ)"]},{"en":"notch wear","pos":"noun phrase","ipa":"/ˈnɒtʃ ˌweə/","ja":"境界摩耗","kana":"きょうかいまもう","romaji":"kyoukaimamou","vi":"mòn rãnh (mòn ở biên chiều sâu cắt)","level":2,"def_vi":"Vết mòn khía cục bộ trên lưỡi cắt tại vị trí ứng với chiều sâu cắt, nơi lưỡi cắt gặp bề mặt phôi.","def_en":"Localized notch-shaped wear on the edge at the depth-of-cut line, where the edge meets the workpiece surface.","def_ja":"切込み深さの境界部で、切れ刃が局部的に切欠き状に摩耗する現象。","usage_en":"Danh từ không đếm được. Hay nói notch wear at the depth-of-cut line; giảm bằng cách vary the depth of cut.","usage_ja":"Còn gọi ノッチ摩耗. Nói 境界摩耗が出る; hay gặp khi gia công 耐熱合金, ステンレス.","context_vi":"Hay gặp khi gia công thép không gỉ, hợp kim chịu nhiệt (Inconel) và phôi có lớp vỏ cứng.","ex_en":"Notch wear on the Inconel job was reduced by using a round insert.","ex_ja":"インコネル加工の境界摩耗は、丸駒チップを使うことで減少した。","ex_vi":"Mòn rãnh khi gia công Inconel đã giảm nhờ dùng mảnh dao tròn.","syn_en":["depth-of-cut notching","DOC notch wear"],"syn_ja":["ノッチ摩耗"]},{"en":"cermet","pos":"noun","ipa":"/ˈsɜːmet/","ja":"サーメット","kana":"サーメット","romaji":"saametto","vi":"cermet (gốm kim loại)","level":2,"def_vi":"Vật liệu dao thiêu kết trên cơ sở TiC/TiCN với chất kết dính Ni-Co, cho bề mặt bóng khi gia công tinh thép.","def_en":"A sintered tool material based on TiC/TiCN with a nickel-cobalt binder, used for fine finishing of steel.","def_ja":"TiC・TiCNを主成分としNi・Coで結合した焼結工具材料で、鋼の仕上げ加工に用いる。","usage_en":"Danh từ không đếm được khi chỉ vật liệu, đếm được khi chỉ mác: a cermet grade. Hay đi với: cermet insert, cermet finishing.","usage_ja":"Dùng trong danh từ ghép: サーメットチップ, サーメット材種. Ngoài xưởng hiểu ngay là vật liệu dành cho 仕上げ.","context_vi":"Dùng cho tiện tinh, phay tinh thép khi cần độ bóng cao và ít lẹo dao.","ex_en":"For the final pass we use a cermet insert to get a mirror-like finish.","ex_ja":"仕上げ加工では、鏡面に近い面を得るためにサーメットチップを使う。","ex_vi":"Ở lần cắt tinh cuối, chúng tôi dùng mảnh dao cermet để có bề mặt gần như gương.","syn_en":["TiCN-based cermet","ceramic-metal composite (nghĩa rộng hơn)"],"syn_ja":["TiC系サーメット","超硬合金 (liên quan)"]},{"en":"tool coating","pos":"noun phrase","ipa":"/ˈtuːl ˌkəʊtɪŋ/","ja":"工具コーティング","kana":"こうぐコーティング","romaji":"kougukootingu","vi":"lớp phủ dụng cụ","level":2,"def_vi":"Lớp màng mỏng cứng (TiN, TiAlN, Al2O3…) phủ lên dao bằng CVD hoặc PVD để tăng khả năng chịu mòn và chịu nhiệt.","def_en":"A thin hard film such as TiN, TiAlN or Al2O3 deposited by CVD or PVD to improve wear and heat resistance.","def_ja":"CVDやPVDで工具表面に付けるTiN・TiAlN・Al2O3などの硬質薄膜。","usage_en":"Danh từ đếm được hoặc không đếm được. Hay đi với: PVD / CVD tool coating, multilayer coating; động từ: apply / strip / recoat.","usage_ja":"Ngoài xưởng gọi コーティング hoặc コート: コーティング超硬, 再コーティング. Động từ: コーティングする, (膜が) はがれる.","context_vi":"Dùng khi chọn mác mảnh dao, mũi khoan, dao phay và khi mài lại rồi phủ lại dao.","ex_en":"The TiAlN tool coating allows dry machining of hardened steel.","ex_ja":"TiAlNの工具コーティングにより、焼入れ鋼のドライ加工が可能になる。","ex_vi":"Lớp phủ dụng cụ TiAlN cho phép gia công khô thép đã tôi.","syn_en":["coating","hard coating"],"syn_ja":["コーティング","硬質皮膜"]},{"en":"regrinding","pos":"noun","ipa":"/ˌriːˈɡraɪndɪŋ/","ja":"再研削","kana":"さいけんさく","romaji":"saikensaku","vi":"mài lại dao","level":2,"def_vi":"Việc mài lại lưỡi cắt đã mòn của dao nguyên khối như mũi khoan, dao phay ngón để dùng tiếp.","def_en":"Grinding the worn edges of solid tools such as drills and end mills again so they can be reused.","def_ja":"摩耗したドリルやエンドミルなどの切れ刃を研ぎ直し、再使用できるようにすること。","usage_en":"Danh từ không đếm được; động từ là regrind (quá khứ reground). Hay đi với: send tools for regrinding, regrinding service, number of regrinds.","usage_ja":"Ngoài xưởng gọi 再研磨 hoặc 刃研ぎ (はとぎ). Động từ: 再研削する, 再研磨に出す.","context_vi":"Dùng trong quản lý chi phí dao: mũi khoan, dao phay hợp kim cứng đắt tiền thường được mài lại vài lần.","ex_en":"Each drill can go through three regrinding cycles before it is scrapped.","ex_ja":"各ドリルは、廃棄までに3回の再研削が可能である。","ex_vi":"Mỗi mũi khoan có thể mài lại ba lần trước khi bị loại bỏ.","syn_en":["resharpening","regrind"],"syn_ja":["再研磨","刃研ぎ (khẩu ngữ)"]},{"en":"insert grade","pos":"noun phrase","ipa":"/ˈɪnsɜːt ˌɡreɪd/","ja":"材種","kana":"ざいしゅ","romaji":"zaishu","vi":"mác vật liệu mảnh dao","level":2,"def_vi":"Mã của nhà sản xuất chỉ vật liệu nền và lớp phủ của mảnh dao, được chọn theo vật liệu phôi và điều kiện cắt.","def_en":"The maker's designation for an insert's substrate and coating, chosen to suit the work material and cutting conditions.","def_ja":"チップの母材とコーティングの種類を示す区分で、被削材と切削条件に合わせて選ぶ。","usage_en":"Danh từ đếm được. Hay đi với: choose / switch insert grade, a tougher / harder grade; thường gọi gọn grade (P25, M15…).","usage_ja":"Hay nói 材種を選定する / 変更する, kèm nhóm ISO P・M・K・N・S・H. Ngoài xưởng cũng nói グレード.","context_vi":"Dùng khi tra catalog dao và khi xử lý sự cố mòn nhanh hoặc vỡ dao.","ex_en":"We changed the insert grade from P25 to P15 to cut faster.","ex_ja":"より高速で切削するため、材種をP25からP15に変更した。","ex_vi":"Chúng tôi đổi mác vật liệu mảnh dao từ P25 sang P15 để cắt nhanh hơn.","syn_en":["grade","carbide grade"],"syn_ja":["グレード","工具材種"]},{"en":"cubic boron nitride","pos":"noun phrase","ipa":"/ˌkjuːbɪk ˌbɔːrɒn ˈnaɪtraɪd/","ja":"立方晶窒化ほう素","kana":"りっぽうしょうちっかほうそ","romaji":"rippoushouchikkahouso","vi":"nitrua bo lập phương (CBN)","level":3,"def_vi":"Vật liệu siêu cứng chỉ kém kim cương, dùng làm dao cắt thép đã tôi và gang ở tốc độ cao.","def_en":"A superhard material second only to diamond, used to cut hardened steel and cast iron at high speed.","def_ja":"ダイヤモンドに次ぐ硬さの超硬質材料で、焼入れ鋼や鋳鉄の高速切削に用いる。","usage_en":"Danh từ không đếm được, thường viết tắt CBN hoặc cBN; dùng như tính từ: CBN insert, PCBN tool.","usage_ja":"Ngoài xưởng gọi CBN (シービーエヌ): CBNチップ, CBN焼結体. Theo JIS chữ ほう viết bằng hiragana (窒化ほう素).","context_vi":"Dùng trong tiện cứng bánh răng, trục đã tôi thay cho mài, và gia công gang xám tốc độ cao.","ex_en":"Cubic boron nitride inserts allow hard turning of gears at 60 HRC.","ex_ja":"立方晶窒化ほう素のチップを使えば、60 HRCの歯車を旋削できる。","ex_vi":"Mảnh dao nitrua bo lập phương cho phép tiện cứng bánh răng 60 HRC.","syn_en":["CBN","PCBN (dạng thiêu kết)"],"syn_ja":["CBN","cBN焼結体"]},{"en":"polycrystalline diamond","pos":"noun phrase","ipa":"/ˌpɒlikrɪstəlaɪn ˈdaɪəmənd/","ja":"焼結ダイヤモンド","kana":"しょうけつダイヤモンド","romaji":"shouketsudaiyamondo","vi":"kim cương đa tinh thể (PCD)","level":3,"def_vi":"Vật liệu dao gồm các hạt kim cương thiêu kết với nhau, dùng gia công nhôm, đồng, composite; không dùng cho thép.","def_en":"A tool material of diamond grains sintered together, used for aluminium, copper and composites but not for steel.","def_ja":"ダイヤモンド粒子を焼結した工具材料で、アルミや複合材に使うが鉄系には使わない。","usage_en":"Danh từ không đếm được, viết tắt PCD; hay dùng: PCD insert, PCD-tipped tool. Lưu ý PCD bị mòn hóa học khi cắt thép.","usage_ja":"Ngoài xưởng gọi PCD hoặc 焼結ダイヤ: PCD工具, ダイヤチップ. Phân biệt với 単結晶ダイヤモンド.","context_vi":"Dùng khi gia công nắp xi lanh, piston, mâm xe nhôm trong ô tô và vật liệu CFRP với tuổi bền rất cao.","ex_en":"Polycrystalline diamond tools last fifty times longer than carbide on aluminium wheels.","ex_ja":"アルミホイールの加工では、焼結ダイヤモンド工具は超硬の50倍長持ちする。","ex_vi":"Khi gia công mâm xe nhôm, dao kim cương đa tinh thể bền gấp 50 lần dao hợp kim cứng.","syn_en":["PCD"],"syn_ja":["PCD","焼結ダイヤ (khẩu ngữ)"]},{"en":"Taylor's tool life equation","pos":"noun phrase","ipa":"/ˌteɪləz ˈtuːl laɪf ɪˌkweɪʒn/","ja":"テイラーの寿命方程式","kana":"テイラーのじゅみょうほうていしき","romaji":"teiraanojumyouhouteishiki","vi":"phương trình tuổi bền Taylor","level":3,"def_vi":"Quan hệ thực nghiệm VT^n = C giữa tốc độ cắt V và tuổi bền T, dùng để dự đoán tuổi bền dao.","def_en":"The empirical relation VT^n = C linking cutting speed V and tool life T, used to predict tool life.","def_ja":"切削速度Vと工具寿命Tの関係を表す実験式VT^n = C。","usage_en":"Danh từ đếm được, thường có the: the Taylor tool life equation. Hay đi với: Taylor exponent n, Taylor constant C; apply / fit the equation.","usage_ja":"Thường gọi テイラーの寿命式, biểu diễn bằng V-T線図. Hay nói 指数nを求める.","context_vi":"Dùng trong thí nghiệm cắt, tối ưu tốc độ cắt kinh tế và tài liệu giảng dạy nguyên lý cắt.","ex_en":"Using Taylor's tool life equation, we estimated the speed for a 30-minute life.","ex_ja":"テイラーの寿命方程式を用いて、寿命30分となる切削速度を求めた。","ex_vi":"Dùng phương trình tuổi bền Taylor, chúng tôi ước tính tốc độ cắt cho tuổi bền 30 phút.","syn_en":["Taylor equation","V-T relationship (liên quan)"],"syn_ja":["テイラーの寿命式","V-T線図 (liên quan)"]},{"en":"diffusion wear","pos":"noun phrase","ipa":"/dɪˈfjuːʒn ˌweə/","ja":"拡散摩耗","kana":"かくさんまもう","romaji":"kakusanmamou","vi":"mòn khuếch tán","level":3,"def_vi":"Cơ chế mòn ở nhiệt độ cao, khi nguyên tử của vật liệu dao khuếch tán sang phoi làm lưỡi cắt yếu và mòn nhanh.","def_en":"Wear at high temperature in which tool atoms diffuse into the chip, weakening and removing tool material.","def_ja":"高温で工具の原子が切りくず側へ拡散し、工具材料が失われる摩耗。","usage_en":"Danh từ không đếm được. Hay nói diffusion wear dominates at high cutting speeds; liên quan đến crater wear.","usage_ja":"Dùng trong báo cáo phân tích, ít dùng ngoài xưởng. Hay nói 拡散摩耗が支配的になる.","context_vi":"Dùng khi giải thích mòn lõm, chọn lớp phủ chắn nhiệt và giới hạn tốc độ cắt cho từng vật liệu dao.","ex_en":"Above 900 °C, diffusion wear becomes the main mechanism on the rake face.","ex_ja":"900 °Cを超えると、すくい面では拡散摩耗が主な機構となる。","ex_vi":"Trên 900 °C, mòn khuếch tán trở thành cơ chế chính trên mặt trước.","syn_en":["chemical wear (nghĩa rộng hơn)","dissolution wear"],"syn_ja":["化学的摩耗 (nghĩa rộng hơn)"]},{"en":"thermal cracking","pos":"noun phrase","ipa":"/ˌθɜːml ˈkrækɪŋ/","ja":"熱亀裂","kana":"ねつきれつ","romaji":"netsukiretsu","vi":"nứt nhiệt (nứt răng lược)","level":3,"def_vi":"Các vết nứt nhỏ vuông góc với lưỡi cắt do chu kỳ nóng–nguội lặp lại, thường gặp khi phay.","def_en":"Fine cracks perpendicular to the cutting edge caused by repeated heating and cooling, typical in milling.","def_ja":"加熱と冷却の繰返しにより切れ刃に直角方向に生じる細かい亀裂。フライス加工に多い。","usage_en":"Danh từ không đếm được; còn gọi comb cracks. Hay nói thermal cracking caused by intermittent coolant.","usage_ja":"Catalog dùng 熱亀裂 hoặc サーマルクラック; nói 熱亀裂が発生する. Hay khuyên phay khô (ドライ加工) để tránh.","context_vi":"Hay gặp khi phay thép có tưới nguội không liên tục; dẫn đến mẻ và vỡ dao.","ex_en":"Thermal cracking stopped after we switched the milling operation to dry cutting.","ex_ja":"フライス加工をドライ切削に変えたところ、熱亀裂が出なくなった。","ex_vi":"Nứt nhiệt hết xuất hiện sau khi chúng tôi chuyển nguyên công phay sang cắt khô.","syn_en":["comb cracks","thermal fatigue cracking"],"syn_ja":["サーマルクラック","くし状亀裂"]},{"en":"edge honing","pos":"noun phrase","ipa":"/ˈedʒ ˌhəʊnɪŋ/","ja":"刃先ホーニング","kana":"はさきホーニング","romaji":"hasakihooningu","vi":"vê tròn lưỡi cắt","level":3,"def_vi":"Việc vê tròn hoặc vát rất nhỏ lưỡi cắt sắc để tăng độ bền và chống mẻ dao.","def_en":"Slightly rounding or chamfering a sharp cutting edge to strengthen it against chipping.","def_ja":"鋭い切れ刃にわずかな丸みや面取りを付け、欠けにくくする刃先処理。","usage_en":"Danh từ không đếm được; nghĩa rộng hơn là edge preparation. Hay đi với: light / heavy edge honing, honed edge. Lưu ý: honing đứng riêng là mài khôn lỗ.","usage_ja":"Catalog dùng ホーニング: 丸ホーニング, チャンファホーニング, ホーニングなし (シャープエッジ).","context_vi":"Dùng khi chọn mảnh dao cho gia công thô, cắt gián đoạn và khi thiết kế dao đặc biệt.","ex_en":"Heavy edge honing is recommended for interrupted cuts in cast iron.","ex_ja":"鋳鉄の断続切削には、大きめの刃先ホーニングが推奨される。","ex_vi":"Nên dùng lưỡi cắt được vê tròn lớn khi cắt gián đoạn gang.","syn_en":["edge preparation","edge rounding"],"syn_ja":["ホーニング","刃先処理"]}]},{"id":43,"words":[{"en":"jig","pos":"noun","ipa":"/dʒɪɡ/","ja":"治具","kana":"じぐ","romaji":"jigu","vi":"đồ gá (dẫn hướng dụng cụ)","level":1,"def_vi":"Thiết bị giữ phôi đúng vị trí và dẫn hướng dụng cụ cắt, ví dụ dẫn mũi khoan qua bạc dẫn để khoan lỗ chính xác.","def_en":"A device that holds the workpiece and guides the cutting tool, for example leading a drill through a bushing.","def_ja":"工作物を保持し、ブシュなどで工具を案内して正確に加工するための装置。","usage_en":"Danh từ đếm được. Hay đi với: drill jig, welding jig, assembly jig; động từ: design / build / load a jig. Kỹ thuật phân biệt jig (dẫn dao) với fixture (chỉ giữ phôi).","usage_ja":"Trong tiếng Nhật 治具 dùng rất rộng cho mọi đồ gá, kể cả đồ gá kẹp, đồ gá hàn, đồ gá kiểm tra. Ghép: 溶接治具, 検査治具; động từ: 治具を製作する.","context_vi":"Dùng trong gia công lỗ hàng loạt, hàn, lắp ráp và kiểm tra, khi cần lặp lại vị trí chính xác mà không cần lấy dấu.","ex_en":"A drill jig guides the bit so that all four holes line up.","ex_ja":"ドリル治具でドリルを案内し、4つの穴位置をそろえる。","ex_vi":"Đồ gá khoan dẫn hướng mũi khoan để cả bốn lỗ thẳng hàng.","syn_en":["fixture (gần nghĩa)","drill jig (nghĩa hẹp hơn)"],"syn_ja":["ジグ","冶具 (viết sai thường gặp)"]},{"en":"fixture","pos":"noun","ipa":"/ˈfɪkstʃə/","ja":"取付具","kana":"とりつけぐ","romaji":"toritsukegu","vi":"đồ gá kẹp (fixture)","level":1,"def_vi":"Thiết bị định vị và kẹp chặt phôi trên bàn máy trong khi gia công, nhưng không dẫn hướng dụng cụ cắt.","def_en":"A device that locates and clamps the workpiece on the machine table during machining, without guiding the tool.","def_ja":"加工中に工作物を機械テーブル上で位置決め・固定する装置で、工具の案内は行わない。","usage_en":"Danh từ đếm được. Hay đi với: milling fixture, welding fixture, fixture plate; động từ: load / unload / mount a fixture.","usage_ja":"Văn bản chuẩn dùng 取付具; ngoài xưởng Nhật gần như luôn gọi 治具. Cũng gặp katakana フィクスチャ trong tài liệu dịch.","context_vi":"Dùng trên máy phay, trung tâm gia công, máy hàn tự động để gá phôi nhanh và lặp lại chính xác.","ex_en":"The fixture holds two housings so both can be machined in one cycle.","ex_ja":"この取付具は2個のハウジングを保持し、1サイクルで両方を加工できる。","ex_vi":"Đồ gá kẹp giữ hai vỏ hộp nên có thể gia công cả hai trong một chu kỳ.","syn_en":["work fixture","jig (khẩu ngữ, nghĩa rộng)"],"syn_ja":["治具","フィクスチャ"]},{"en":"vise","pos":"noun","ipa":"/vaɪs/","ja":"バイス","kana":"バイス","romaji":"baisu","vi":"ê tô","level":1,"def_vi":"Dụng cụ kẹp gồm một má cố định và một má di động điều chỉnh bằng vít, dùng giữ phôi trên bàn máy hoặc bàn nguội.","def_en":"A clamping device with a fixed jaw and a screw-driven movable jaw, used to hold work on a machine table or bench.","def_ja":"固定口金とねじで動く移動口金からなり、工作物を機械テーブルや作業台上に固定する器具。","usage_en":"Danh từ đếm được; Anh-Anh viết vice, Anh-Mỹ viết vise. Hay đi với: machine vise, bench vise, vise jaws; động từ: clamp / hold a part in the vise.","usage_ja":"Trên máy phay gọi マシンバイス; ở bàn nguội gọi 万力 (まんりき). Má kẹp gọi 口金 (くちがね).","context_vi":"Dùng trên máy phay, máy khoan, trung tâm gia công và bàn nguội để kẹp phôi dạng khối.","ex_en":"Clamp the block in the vise with parallels underneath.","ex_ja":"ブロックの下にパラレルを敷いて、バイスに固定する。","ex_vi":"Kẹp khối phôi vào ê tô, bên dưới kê căn song song.","syn_en":["vice (Anh)","machine vise"],"syn_ja":["マシンバイス","万力"]},{"en":"clamp","pos":"noun","ipa":"/klæmp/","ja":"クランプ","kana":"クランプ","romaji":"kuranpu","vi":"cơ cấu kẹp (vấu kẹp)","level":1,"def_vi":"Chi tiết hoặc cơ cấu tạo lực ép giữ chặt phôi vào các điểm định vị trong khi gia công.","def_en":"A device that applies force to hold the workpiece firmly against its locators during machining.","def_ja":"工作物を位置決め部に押し付け、加工中に固定する力を与える器具。","usage_en":"Danh từ đếm được, cũng dùng làm động từ (clamp the part). Hay đi với: strap clamp, step clamp, clamp bolt; tighten / release a clamp.","usage_ja":"Dùng cả danh từ và động từ クランプする. Ngoài xưởng nói クランプを締める / 緩める; văn bản cũ dùng 締付け具.","context_vi":"Dùng ở mọi đồ gá phay, khoan, hàn; khi viết hướng dẫn gá đặt cần ghi vị trí và thứ tự kẹp.","ex_en":"Tighten the clamp only after the part sits on all three rest buttons.","ex_ja":"部品が3つの受けに着座してから、クランプを締めること。","ex_vi":"Chỉ siết cơ cấu kẹp sau khi chi tiết đã tỳ đủ lên ba chốt tỳ.","syn_en":["hold-down","strap clamp (một loại cụ thể)"],"syn_ja":["締付け具","押え金 (khẩu ngữ)"]},{"en":"chuck","pos":"noun","ipa":"/tʃʌk/","ja":"チャック","kana":"チャック","romaji":"chakku","vi":"mâm cặp","level":1,"def_vi":"Cơ cấu lắp trên trục chính máy tiện hoặc máy mài, dùng các chấu để kẹp và quay phôi tròn.","def_en":"A device mounted on a lathe or grinder spindle that grips and rotates the workpiece with its jaws.","def_ja":"旋盤や研削盤の主軸に取り付け、爪で工作物をつかんで回転させる装置。","usage_en":"Danh từ đếm được, cũng dùng làm động từ chuck a part. Hay đi với: power chuck, hydraulic chuck, chuck jaws, chuck key.","usage_ja":"Ghép: パワーチャック, 油圧チャック, チャック圧 (áp lực kẹp). Động từ: チャッキングする, チャックでつかむ.","context_vi":"Dùng trên máy tiện thường và máy tiện CNC; liên quan an toàn như không để quên chìa vặn mâm cặp.","ex_en":"Remove all chips from the chuck before loading each part.","ex_ja":"部品を取り付ける前に、チャックの切りくずをすべて取り除くこと。","ex_vi":"Làm sạch hết phoi trên mâm cặp trước khi gá mỗi chi tiết.","syn_en":["lathe chuck","power chuck (loại tự động)"],"syn_ja":["パワーチャック (loại tự động)","スクロールチャック (loại tay)"]},{"en":"three-jaw chuck","pos":"noun phrase","ipa":"/ˌθriː dʒɔː ˈtʃʌk/","ja":"三つ爪チャック","kana":"みつづめチャック","romaji":"mitsuzumechakku","vi":"mâm cặp ba chấu","level":1,"def_vi":"Mâm cặp có ba chấu dịch chuyển đồng thời, tự định tâm phôi tròn hoặc lục giác.","def_en":"A chuck whose three jaws move together, automatically centring round or hexagonal work.","def_ja":"3つの爪が同時に動き、丸物や六角物を自動的に芯出しするチャック。","usage_en":"Danh từ đếm được; có gạch nối three-jaw. Đối lập với four-jaw independent chuck; còn gọi self-centring chuck.","usage_ja":"Đọc みつづめ, không đọc さんつめ. Đối lập: 四つ爪チャック (単動チャック). Hay nói 三つ爪でつかむ.","context_vi":"Dùng phổ biến nhất trên máy tiện để kẹp phôi thanh tròn, phôi rèn, phôi đúc tròn xoay.","ex_en":"A three-jaw chuck centres round bar automatically within about 0.05 mm.","ex_ja":"三つ爪チャックは、丸棒を約0.05 mm以内で自動的に芯出しする。","ex_vi":"Mâm cặp ba chấu tự định tâm phôi thanh tròn với sai lệch khoảng 0,05 mm.","syn_en":["self-centring chuck","scroll chuck"],"syn_ja":["連動チャック","スクロールチャック"]},{"en":"collet","pos":"noun","ipa":"/ˈkɒlɪt/","ja":"コレット","kana":"コレット","romaji":"koretto","vi":"ống kẹp đàn hồi (collet)","level":1,"def_vi":"Ống kẹp có xẻ rãnh, co lại đều khi bị kéo hoặc ép vào lỗ côn, dùng kẹp phôi thanh hoặc chuôi dao với độ đồng tâm cao.","def_en":"A slotted sleeve that closes evenly when drawn into a taper, gripping bar stock or tool shanks with high concentricity.","def_ja":"すり割りのあるスリーブで、テーパに引き込むと均一に縮み、棒材や工具シャンクを高精度に把持する。","usage_en":"Danh từ đếm được. Hay đi với: collet chuck, ER collet, spring collet; động từ: open / close / change the collet.","usage_ja":"Ghép: コレットチャック, ERコレット. Trên máy tiện tự động gọi チャッキングコレット. Động từ: コレットでつかむ.","context_vi":"Dùng trên máy tiện tự động kiểu Thụy Sĩ, máy tiện thanh và đầu kẹp dao phay, khi cần đồng tâm tốt.","ex_en":"Small pins are held in a collet for better concentricity.","ex_ja":"小径ピンは、同心度を高めるためにコレットでつかむ。","ex_vi":"Chốt cỡ nhỏ được kẹp bằng ống kẹp đàn hồi để có độ đồng tâm tốt hơn.","syn_en":["collet chuck (nghĩa rộng hơn)","spring collet"],"syn_ja":["コレットチャック (nghĩa rộng hơn)"]},{"en":"locating pin","pos":"noun phrase","ipa":"/ləʊˈkeɪtɪŋ ˌpɪn/","ja":"位置決めピン","kana":"いちぎめピン","romaji":"ichigimepin","vi":"chốt định vị","level":1,"def_vi":"Chốt cứng, mài chính xác, lắp vào lỗ chuẩn của phôi để xác định vị trí phôi trên đồ gá.","def_en":"A hardened, precision-ground pin that fits a datum hole in the workpiece to fix its position on the fixture.","def_ja":"工作物の基準穴にはめ込み、治具上での位置を決める焼入れ研削されたピン。","usage_en":"Danh từ đếm được. Hay đi với: round locating pin, diamond locating pin; động từ: fit / press in / replace a locating pin.","usage_ja":"Hay nói 位置決めピンに入れる / 差し込む. Catalog MISUMI phân loại 丸ピン và ダイヤピン.","context_vi":"Dùng trong đồ gá phay, khoan, hàn, kiểm tra khi phôi có hai lỗ chuẩn đã gia công tinh.","ex_en":"Two locating pins fit into reamed holes in the casting.","ex_ja":"鋳物のリーマ穴に、2本の位置決めピンをはめ込む。","ex_vi":"Hai chốt định vị lắp vào hai lỗ đã doa trên phôi đúc.","syn_en":["locator pin","dowel pin (gần nghĩa)"],"syn_ja":["ロケートピン","ノックピン (gần nghĩa)"]},{"en":"V-block","pos":"noun","ipa":"/ˈviː ˌblɒk/","ja":"Vブロック","kana":"ブイブロック","romaji":"buiburokku","vi":"khối V","level":1,"def_vi":"Khối thép có rãnh hình chữ V dùng để đặt và định tâm phôi trụ tròn khi lấy dấu, gia công hoặc kiểm tra.","def_en":"A steel block with a V-shaped groove used to support and centre cylindrical work for marking, machining or inspection.","def_ja":"V字形の溝をもつ鋼製ブロックで、円筒工作物を支持・芯出しする。","usage_en":"Danh từ đếm được, viết hoa chữ V và có gạch nối. Thường dùng theo cặp: a pair of V-blocks; đi với rest / clamp a shaft on a V-block.","usage_ja":"Đọc là ブイブロック. Hay dùng theo cặp, kèm Vブロッククランプ để kẹp trục.","context_vi":"Dùng khi khoan lỗ ngang trên trục, lấy dấu và đo độ đảo trên bàn máp.","ex_en":"Place the shaft on a V-block before drilling the cross hole.","ex_ja":"横穴をあける前に、シャフトをVブロックに載せる。","ex_vi":"Đặt trục lên khối V trước khi khoan lỗ ngang.","syn_en":["vee block"],"syn_ja":["V溝ブロック"]},{"en":"setup","pos":"noun","ipa":"/ˈsetʌp/","ja":"段取り","kana":"だんどり","romaji":"dandori","vi":"gá đặt, chuẩn bị máy (setup)","level":1,"def_vi":"Toàn bộ công việc gá đồ gá, kẹp phôi, lắp dao và cài gốc tọa độ trước khi bắt đầu gia công một loại chi tiết.","def_en":"All the work of mounting fixtures, clamping the part, loading tools and setting offsets before machining a job.","def_ja":"加工前に治具の取付け、工作物の固定、工具の準備、原点設定などを行うこと。","usage_en":"Danh từ đếm được (số lần gá: two setups). Danh từ viết liền setup, động từ viết rời set up. Hay đi với: setup time, setup sheet.","usage_ja":"Ghép: 段取り時間, 段取り替え (đổi mã hàng), 外段取り / 内段取り. Từ dùng hằng ngày ở mọi xưởng Nhật.","context_vi":"Dùng hằng ngày trong xưởng gia công; giảm số lần gá và thời gian gá là mục tiêu chính của thiết kế đồ gá.","ex_en":"The setup for the new bracket took 45 minutes.","ex_ja":"新しいブラケットの段取りに45分かかった。","ex_vi":"Việc gá đặt cho giá đỡ mới mất 45 phút.","syn_en":["set-up","job setup"],"syn_ja":["セットアップ","段取り替え (liên quan)"]},{"en":"workholding","pos":"noun","ipa":"/ˈwɜːkˌhəʊldɪŋ/","ja":"工作物保持","kana":"こうさくぶつほじ","romaji":"kousakubutsuhoji","vi":"kẹp giữ phôi","level":2,"def_vi":"Tên chung cho các phương pháp và thiết bị định vị, kẹp giữ phôi trên máy như mâm cặp, ê tô, đồ gá.","def_en":"The general term for methods and devices that locate and hold the workpiece on a machine, such as chucks, vises and fixtures.","def_ja":"チャック・バイス・治具など、機械上で工作物を位置決め・保持する方法や装置の総称。","usage_en":"Danh từ không đếm được, viết liền workholding (đôi khi work holding). Hay dùng như tính từ: workholding device, workholding solution.","usage_ja":"Văn bản dùng 工作物保持; ngoài xưởng nói ワーク保持 hoặc ワーククランプ. Ghép: 工作物保持具.","context_vi":"Dùng trong catalog đồ gá, hội chợ máy công cụ và khi bàn phương án gá cho chi tiết mới.","ex_en":"Good workholding is the key to holding tight tolerances on thin parts.","ex_ja":"薄物部品で厳しい公差を守るには、適切な工作物保持が鍵となる。","ex_vi":"Kẹp giữ phôi tốt là chìa khóa để đạt dung sai hẹp trên chi tiết mỏng.","syn_en":["work holding","fixturing"],"syn_ja":["ワーク保持","ワーククランプ"]},{"en":"soft jaw","pos":"noun phrase","ipa":"/ˌsɒft ˈdʒɔː/","ja":"生爪","kana":"なまづめ","romaji":"namazume","vi":"chấu mềm","level":2,"def_vi":"Chấu mâm cặp bằng thép hoặc nhôm chưa tôi, được tiện theo đúng biên dạng phôi để kẹp chính xác và không làm hỏng bề mặt.","def_en":"An unhardened chuck jaw machined to match the part shape, giving accurate gripping without marking the surface.","def_ja":"焼入れしていない爪で、工作物形状に合わせて成形し、高精度かつ傷を付けずにつかむ。","usage_en":"Danh từ đếm được, thường số nhiều soft jaws. Động từ: bore / machine soft jaws; đối lập với hard jaws.","usage_ja":"Đọc なまづめ. Đối lập 硬爪 (かたづめ). Hay nói 生爪を成形する / 生爪を削る.","context_vi":"Dùng trên máy tiện CNC khi tiện mặt thứ hai, phôi thành mỏng hoặc yêu cầu độ đồng tâm cao.","ex_en":"We bore a new set of soft jaws for every part number.","ex_ja":"品番ごとに、新しい生爪を成形している。","ex_vi":"Mỗi mã chi tiết chúng tôi tiện một bộ chấu mềm mới.","syn_en":["machinable jaw","hard jaw (liên quan, đối nghĩa)"],"syn_ja":["ソフトジョー","硬爪 (liên quan, đối nghĩa)"]},{"en":"clamping force","pos":"noun phrase","ipa":"/ˈklæmpɪŋ ˌfɔːs/","ja":"クランプ力","kana":"クランプりょく","romaji":"kuranpuryoku","vi":"lực kẹp","level":2,"def_vi":"Lực mà cơ cấu kẹp tác dụng lên phôi để giữ phôi không dịch chuyển dưới tác dụng của lực cắt.","def_en":"The force a clamp exerts on the workpiece so that it does not move under the cutting forces.","def_ja":"切削力で工作物が動かないよう、クランプが工作物に加える力。","usage_en":"Danh từ không đếm được. Hay đi với: apply / increase / reduce clamping force, sufficient clamping force, clamping force of 10 kN.","usage_ja":"Hay nói クランプ力が足りない / 強すぎる; với mâm cặp gọi 把握力 (はあくりょく). Văn bản cũ dùng 締付け力.","context_vi":"Dùng khi tính toán đồ gá, chọn xi lanh kẹp thủy lực và khi xử lý phôi bị trượt hoặc biến dạng.","ex_en":"The clamping force was reduced to stop the thin wall from distorting.","ex_ja":"薄肉部の変形を防ぐため、クランプ力を下げた。","ex_vi":"Lực kẹp đã được giảm để thành mỏng không bị biến dạng.","syn_en":["holding force","gripping force (mâm cặp)"],"syn_ja":["締付け力","把握力 (mâm cặp)"]},{"en":"toggle clamp","pos":"noun phrase","ipa":"/ˈtɒɡl ˌklæmp/","ja":"トグルクランプ","kana":"トグルクランプ","romaji":"togurukuranpu","vi":"kẹp nhanh (toggle clamp)","level":2,"def_vi":"Cơ cấu kẹp nhanh dùng tay gạt và khớp đòn khuỷu, khi qua điểm chết thì tự khóa với lực lớn.","def_en":"A quick-acting clamp with a hand lever and toggle linkage that locks past dead centre with high force.","def_ja":"レバーとトグル機構で素早く締め付け、死点を越えると自己保持するクランプ。","usage_en":"Danh từ đếm được. Hay đi với: horizontal / vertical / push-pull toggle clamp; động từ: close / open / lock the toggle clamp.","usage_ja":"Catalog chia 横型, 縦型, プッシュプル型 トグルクランプ. Ngoài xưởng nói トグルで押さえる.","context_vi":"Dùng nhiều trong đồ gá hàn, đồ gá lắp ráp, đồ gá khoan nhẹ cần thao tác kẹp nhanh bằng tay.","ex_en":"Each welding jig uses four toggle clamps to hold the frame.","ex_ja":"各溶接治具は、4個のトグルクランプでフレームを押さえる。","ex_vi":"Mỗi đồ gá hàn dùng bốn kẹp nhanh để giữ khung.","syn_en":["quick-release clamp","over-centre clamp"],"syn_ja":["クイッククランプ"]},{"en":"swing clamp","pos":"noun phrase","ipa":"/ˈswɪŋ ˌklæmp/","ja":"スイングクランプ","kana":"スイングクランプ","romaji":"suingukuranpu","vi":"xi lanh kẹp xoay (swing clamp)","level":2,"def_vi":"Xi lanh kẹp thủy lực hoặc khí nén có cần kẹp vừa xoay 90° vừa hạ xuống ép phôi, nhường chỗ khi nạp phôi.","def_en":"A hydraulic or pneumatic cylinder whose arm rotates about 90° and then pulls down onto the part, clearing the loading area.","def_ja":"アームが約90°旋回してから下降し工作物を押さえる油圧・空圧シリンダ。","usage_en":"Danh từ đếm được. Hay đi với: hydraulic swing clamp, swing clamp arm, swing direction (left / right).","usage_ja":"Tên sản phẩm của các hãng Kosmek, Pascal. Ghép: 油圧スイングクランプ, 旋回方向 (右旋回 / 左旋回).","context_vi":"Dùng trong đồ gá thủy lực trên trung tâm gia công sản xuất hàng loạt chi tiết ô tô.","ex_en":"The swing clamp rotates clear so the robot can load the casting.","ex_ja":"スイングクランプが旋回して退避し、ロボットが鋳物を搬入する。","ex_vi":"Xi lanh kẹp xoay quay ra ngoài để robot nạp phôi đúc vào.","syn_en":["rotary clamp cylinder"],"syn_ja":["旋回クランプ"]},{"en":"magnetic chuck","pos":"noun phrase","ipa":"/mæɡˌnetɪk ˈtʃʌk/","ja":"マグネットチャック","kana":"マグネットチャック","romaji":"magunettochakku","vi":"bàn từ","level":2,"def_vi":"Bàn kẹp dùng lực từ của nam châm vĩnh cửu hoặc nam châm điện để hút giữ phôi thép, phổ biến trên máy mài phẳng.","def_en":"A workholding plate that holds ferrous parts by permanent or electromagnetic force, common on surface grinders.","def_ja":"永久磁石または電磁石の吸着力で鉄系工作物を保持する装置で、平面研削盤に多い。","usage_en":"Danh từ đếm được. Hay đi với: permanent / electro-magnetic chuck; động từ: energize / demagnetize; phôi cần demagnetizing sau khi mài.","usage_ja":"Còn gọi 電磁チャック (loại điện từ) hay 永磁チャック. Hay nói マグネットをかける / 脱磁する.","context_vi":"Dùng trên máy mài phẳng, máy phay và EDM để kẹp phôi thép mỏng, phẳng mà không cần vấu kẹp.","ex_en":"Thin plates are held on a magnetic chuck for surface grinding.","ex_ja":"薄板は、平面研削のためにマグネットチャックで保持する。","ex_vi":"Tấm mỏng được giữ trên bàn từ để mài phẳng.","syn_en":["electromagnetic chuck","magnetic table"],"syn_ja":["電磁チャック","永磁チャック"]},{"en":"vacuum chuck","pos":"noun phrase","ipa":"/ˈvækjuːm ˌtʃʌk/","ja":"真空チャック","kana":"しんくうチャック","romaji":"shinkuuchakku","vi":"bàn hút chân không","level":2,"def_vi":"Bàn kẹp dùng áp suất chân không hút giữ phôi phẳng, dùng cho vật liệu không nhiễm từ hoặc chi tiết mỏng dễ biến dạng.","def_en":"A workholding plate that holds flat parts by vacuum, used for non-magnetic materials and thin, easily distorted parts.","def_ja":"真空圧で平らな工作物を吸着保持する装置で、非磁性材や薄物に用いる。","usage_en":"Danh từ đếm được. Hay đi với: vacuum chuck plate, vacuum pump, seal / O-ring groove; động từ: hold / release by vacuum.","usage_ja":"Ngoài xưởng gọi バキュームチャック hoặc 真空吸着. Hay nói 真空で吸着する / 真空圧が下がる.","context_vi":"Dùng khi phay tấm nhôm, nhựa, gỗ, tấm bán dẫn và chi tiết mỏng mà kẹp cơ khí sẽ làm biến dạng.","ex_en":"The aluminium panel is held on a vacuum chuck during face milling.","ex_ja":"アルミパネルは、正面フライス加工中に真空チャックで保持される。","ex_vi":"Tấm nhôm được giữ trên bàn hút chân không khi phay mặt.","syn_en":["vacuum fixture","vacuum table"],"syn_ja":["バキュームチャック","真空吸着治具"]},{"en":"drill bushing","pos":"noun phrase","ipa":"/ˈdrɪl ˌbʊʃɪŋ/","ja":"ドリルブシュ","kana":"ドリルブシュ","romaji":"dorirubushu","vi":"bạc dẫn khoan","level":2,"def_vi":"Ống lót thép tôi cứng lắp trong tấm dẫn của đồ gá khoan để dẫn hướng mũi khoan đúng vị trí.","def_en":"A hardened steel sleeve fitted in the jig plate that guides the drill to the correct hole position.","def_ja":"治具板に取り付け、ドリルを正しい穴位置に案内する焼入れ鋼製のブシュ。","usage_en":"Danh từ đếm được; Anh-Anh hay viết drill bush. Hay đi với: press-fit / slip-renewable / fixed drill bushing.","usage_ja":"JIS gọi ジグ用ブシュ; chia 固定ブシュ, 差込みブシュ. Ngoài xưởng gọi ブシュ hoặc ブッシュ.","context_vi":"Dùng trong đồ gá khoan trên máy khoan đứng, máy khoan cần khi không có CNC để định vị lỗ.","ex_en":"The drill bushing must be replaced when its bore wears 0.02 mm oversize.","ex_ja":"内径が0.02 mm摩耗したら、ドリルブシュを交換すること。","ex_vi":"Phải thay bạc dẫn khoan khi lỗ bạc mòn rộng thêm 0,02 mm.","syn_en":["drill bush (Anh)","jig bushing"],"syn_ja":["ジグ用ブシュ","ブッシュ (khẩu ngữ)"]},{"en":"T-slot","pos":"noun","ipa":"/ˈtiː ˌslɒt/","ja":"T溝","kana":"ティーみぞ","romaji":"tiimizo","vi":"rãnh chữ T","level":2,"def_vi":"Rãnh có tiết diện hình chữ T trên bàn máy, dùng lắp bu lông chữ T để kẹp ê tô, đồ gá hoặc phôi.","def_en":"A T-shaped groove in a machine table that takes T-bolts or T-nuts for clamping vises, fixtures or parts.","def_ja":"機械テーブルに設けたT字形の溝で、Tボルトでバイスや治具を固定する。","usage_en":"Danh từ đếm được, viết hoa T và có gạch nối. Hay đi với: T-slot bolt, T-slot nut, T-slot table; T-slot width 18 mm.","usage_ja":"Đọc ティーみぞ. Ghép: T溝ボルト, T溝ナット, T溝幅 (chiều rộng rãnh).","context_vi":"Dùng trên bàn máy phay, máy khoan, máy bào, trung tâm gia công để cố định đồ gá.","ex_en":"Clean the T-slot before sliding in the T-nuts.","ex_ja":"Tナットを差し込む前に、T溝を清掃すること。","ex_vi":"Làm sạch rãnh chữ T trước khi luồn đai ốc chữ T vào.","syn_en":["tee slot"],"syn_ja":["ティースロット (ít dùng)"]},{"en":"angle plate","pos":"noun phrase","ipa":"/ˈæŋɡl ˌpleɪt/","ja":"アングルプレート","kana":"アングルプレート","romaji":"angurupureeto","vi":"ke gá vuông (bàn gá góc)","level":2,"def_vi":"Khối gang hoặc thép có hai mặt vuông góc chính xác, dùng gá phôi lên mặt đứng khi gia công hoặc kiểm tra.","def_en":"A cast-iron or steel block with two accurately square faces, used to mount work on a vertical face.","def_ja":"正確に直角な2面をもつ鋳鉄・鋼製の取付具で、工作物を垂直面に固定する。","usage_en":"Danh từ đếm được. Hay đi với: bolt / clamp the part to an angle plate, adjustable angle plate.","usage_ja":"Ngoài xưởng Nhật hay gọi イケール (gốc tiếng Pháp). Hay nói イケールに当てる / 固定する.","context_vi":"Dùng trên máy phay, máy mài và bàn máp để gá phôi vuông góc hoặc kiểm tra độ vuông góc.","ex_en":"The bracket was bolted to an angle plate to machine its side face.","ex_ja":"側面を加工するため、ブラケットをアングルプレートにボルトで固定した。","ex_vi":"Giá đỡ được bắt bu lông lên ke gá vuông để gia công mặt bên.","syn_en":["knee","angle bracket (khẩu ngữ)"],"syn_ja":["イケール (khẩu ngữ)","直角定盤"]},{"en":"locating surface","pos":"noun phrase","ipa":"/ləʊˈkeɪtɪŋ ˌsɜːfɪs/","ja":"基準面","kana":"きじゅんめん","romaji":"kijunmen","vi":"mặt chuẩn định vị","level":2,"def_vi":"Bề mặt của phôi được chọn để tỳ lên các chi tiết định vị của đồ gá, quyết định vị trí phôi khi gia công.","def_en":"The workpiece surface chosen to rest against the fixture's locators, which fixes its position for machining.","def_ja":"治具の位置決め部に当てる工作物の面で、加工時の位置を決める。","usage_en":"Danh từ đếm được. Hay đi với: primary / secondary locating surface, machined locating surface; động từ: rest on / seat against.","usage_ja":"Hay nói 基準面に当てる, 基準面を先に加工する. Khi nói về đồ gá còn dùng 位置決め面.","context_vi":"Dùng khi lập quy trình công nghệ, chọn chuẩn gia công cho từng nguyên công và thiết kế đồ gá.","ex_en":"The first operation machines the locating surface for all later operations.","ex_ja":"第1工程で、以降の全工程に使う基準面を加工する。","ex_vi":"Nguyên công đầu tiên gia công mặt chuẩn định vị cho tất cả các nguyên công sau.","syn_en":["datum surface","locating face"],"syn_ja":["位置決め面","基準 (khẩu ngữ)"]},{"en":"hydraulic fixture","pos":"noun phrase","ipa":"/haɪˌdrɒlɪk ˈfɪkstʃə/","ja":"油圧治具","kana":"ゆあつじぐ","romaji":"yuatsujigu","vi":"đồ gá thủy lực","level":2,"def_vi":"Đồ gá dùng xi lanh thủy lực để kẹp phôi, cho lực kẹp lớn, ổn định và có thể tự động hóa.","def_en":"A fixture that uses hydraulic cylinders to clamp the part, giving high, consistent force suitable for automation.","def_ja":"油圧シリンダで工作物をクランプする治具で、大きく安定したクランプ力が得られ自動化に向く。","usage_en":"Danh từ đếm được. Hay đi với: hydraulic fixture with rotary joint, clamping pressure; động từ: pressurize / release the fixture.","usage_ja":"Ghép: 油圧クランプ, 油圧ユニット, ロータリジョイント. Đối lập với 手締め治具 (kẹp tay) hay 空圧治具.","context_vi":"Dùng trên trung tâm gia công ngang trong dây chuyền sản xuất hàng loạt như vỏ hộp số, thân van.","ex_en":"The hydraulic fixture clamps eight parts in under two seconds.","ex_ja":"この油圧治具は、8個の部品を2秒以内でクランプする。","ex_vi":"Đồ gá thủy lực kẹp tám chi tiết trong chưa đến hai giây.","syn_en":["hydraulic workholding","power fixture"],"syn_ja":["油圧クランプ治具","空圧治具 (liên quan)"]},{"en":"diamond pin","pos":"noun phrase","ipa":"/ˈdaɪəmənd ˌpɪn/","ja":"菱形ピン","kana":"ひしがたピン","romaji":"hishigatapin","vi":"chốt trám","level":2,"def_vi":"Chốt định vị được vát hai bên còn lại hai cung hẹp, dùng cùng chốt trụ để định vị phôi bằng hai lỗ mà không bị kẹt.","def_en":"A relieved locating pin with two narrow lands, used with a round pin to locate a part on two holes without binding.","def_ja":"両側を削り落とした位置決めピンで、丸ピンと組み合わせ二つの穴で拘束過多なく位置決めする。","usage_en":"Danh từ đếm được. Thường đi theo cặp: one round pin and one diamond pin; còn gọi relieved pin. Hướng phần cung phải vuông góc với đường nối hai lỗ.","usage_ja":"Catalog gọi ダイヤピン hoặc ダイヤ形ピン; dùng cặp 丸ピン + 菱形ピン.","context_vi":"Dùng trong đồ gá định vị bằng mặt phẳng và hai lỗ, rất phổ biến khi gia công vỏ hộp, nắp máy.","ex_en":"The diamond pin is oriented at 90° to the line between the two holes.","ex_ja":"菱形ピンは、2穴を結ぶ線に対して90°の向きに取り付ける。","ex_vi":"Chốt trám được lắp vuông góc với đường nối hai lỗ.","syn_en":["relieved pin","diamond locator"],"syn_ja":["ダイヤピン","削りピン"]},{"en":"dedicated fixture","pos":"noun phrase","ipa":"/ˌdedɪkeɪtɪd ˈfɪkstʃə/","ja":"専用治具","kana":"せんようじぐ","romaji":"senyoujigu","vi":"đồ gá chuyên dùng","level":2,"def_vi":"Đồ gá được thiết kế riêng cho một chi tiết hoặc một nguyên công, gá nhanh và chính xác nhưng không dùng được cho chi tiết khác.","def_en":"A fixture designed for one specific part or operation, fast and accurate but not reusable for other parts.","def_ja":"特定の部品や工程専用に設計した治具で、段取りが速く高精度だが他部品には使えない。","usage_en":"Danh từ đếm được. Đối lập với modular fixture, general-purpose fixture; động từ: design / build a dedicated fixture.","usage_ja":"Đối lập 汎用治具 (đồ gá vạn năng). Hay nói 専用治具を製作する, 専用治具化する.","context_vi":"Dùng trong sản xuất loạt lớn như ô tô, xe máy, nơi chi phí đồ gá được bù bằng sản lượng.","ex_en":"A dedicated fixture paid for itself after 3,000 parts.","ex_ja":"専用治具の費用は、3,000個の生産で回収できた。","ex_vi":"Chi phí đồ gá chuyên dùng đã được thu hồi sau 3.000 chi tiết.","syn_en":["special-purpose fixture","custom fixture"],"syn_ja":["専用取付具","汎用治具 (liên quan, đối nghĩa)"]},{"en":"3-2-1 principle","pos":"noun phrase","ipa":"/ˌθriː tuː ˈwʌn ˌprɪnsəpl/","ja":"3-2-1の原則","kana":"さんにいちのげんそく","romaji":"sanniichinogensoku","vi":"nguyên tắc định vị 3-2-1","level":3,"def_vi":"Định vị phôi lăng trụ bằng 3 điểm ở mặt chính, 2 điểm ở mặt phụ và 1 điểm ở mặt thứ ba để khử 6 bậc tự do.","def_en":"Locating a prismatic part with three points on the primary face, two on the secondary and one on the tertiary, removing six degrees of freedom.","def_ja":"第1面を3点、第2面を2点、第3面を1点で支え、6自由度を拘束する位置決めの考え方。","usage_en":"Danh từ đếm được, thường có the: the 3-2-1 principle. Còn gọi 3-2-1 locating method; đọc three-two-one.","usage_ja":"Gặp trong sách thiết kế đồ gá, còn gọi 3-2-1の法則 hoặc 6点位置決め. Ngoài xưởng ít nói tên, chỉ nói 3点で受ける.","context_vi":"Dùng khi thiết kế đồ gá, phân tích bậc tự do bị khống chế và đào tạo kỹ sư công nghệ.","ex_en":"The fixture follows the 3-2-1 principle with six hardened rest buttons.","ex_ja":"この治具は3-2-1の原則に従い、6個の焼入れ受けで位置決めする。","ex_vi":"Đồ gá này tuân theo nguyên tắc định vị 3-2-1 với sáu chốt tỳ đã tôi cứng.","syn_en":["3-2-1 locating method","six-point locating principle"],"syn_ja":["3-2-1の法則","6点位置決め"]},{"en":"overconstraint","pos":"noun","ipa":"/ˌəʊvəkənˈstreɪnt/","ja":"過拘束","kana":"かこうそく","romaji":"kakousoku","vi":"siêu định vị (định vị thừa)","level":3,"def_vi":"Tình trạng đồ gá khống chế cùng một bậc tự do hai lần trở lên, khiến phôi bị kênh, biến dạng hoặc không gá vào được.","def_en":"A condition where the fixture restrains the same degree of freedom more than once, causing rocking, distortion or misloading.","def_ja":"同じ自由度を二重以上に拘束した状態で、工作物のがたつき・変形・入らない原因になる。","usage_en":"Danh từ không đếm được; tính từ overconstrained. Trong đồ gá còn nói over-locating hoặc redundant locating.","usage_ja":"Hay nói 過拘束になる / 過拘束を避ける. Gặp nhiều trong thiết kế đồ gá và thiết kế cơ cấu.","context_vi":"Dùng khi rà soát thiết kế đồ gá, ví dụ dùng hai chốt trụ cho hai lỗ hoặc bốn điểm tỳ trên một mặt thô.","ex_en":"Using two round pins caused overconstraint, so one was changed to a diamond pin.","ex_ja":"丸ピン2本では過拘束になるため、1本を菱形ピンに変更した。","ex_vi":"Dùng hai chốt trụ gây siêu định vị nên một chốt đã được đổi thành chốt trám.","syn_en":["over-locating","redundant locating"],"syn_ja":["二重拘束","拘束過多"]},{"en":"locating error","pos":"noun phrase","ipa":"/ləʊˈkeɪtɪŋ ˌerə/","ja":"位置決め誤差","kana":"いちぎめごさ","romaji":"ichigimegosa","vi":"sai số chuẩn (sai số định vị)","level":3,"def_vi":"Sai lệch vị trí của phôi so với dụng cụ cắt do chọn chuẩn, khe hở chốt–lỗ và dung sai của mặt định vị gây ra.","def_en":"The positional deviation of the part relative to the tool caused by datum choice, pin clearance and locating-surface tolerances.","def_ja":"基準の選び方、ピンと穴のすきま、基準面の公差などによる工作物位置のずれ。","usage_en":"Danh từ đếm được. Hay đi với: calculate / minimize locating error, locating error due to pin clearance.","usage_ja":"Hay nói 位置決め誤差を見積もる / 小さくする. Trong tài liệu Việt tương đương sai số chuẩn εc.","context_vi":"Dùng khi tính toán độ chính xác đồ gá và kiểm tra khả năng đạt dung sai bản vẽ.","ex_en":"Pin-to-hole clearance accounts for most of the locating error.","ex_ja":"位置決め誤差の大部分は、ピンと穴のすきまによるものだ。","ex_vi":"Khe hở giữa chốt và lỗ chiếm phần lớn sai số chuẩn.","syn_en":["datum error","positioning error"],"syn_ja":["位置ずれ (khẩu ngữ)","基準誤差"]},{"en":"clamping distortion","pos":"noun phrase","ipa":"/ˈklæmpɪŋ dɪˌstɔːʃn/","ja":"クランプひずみ","kana":"クランプひずみ","romaji":"kuranpuhizumi","vi":"biến dạng do kẹp","level":3,"def_vi":"Biến dạng đàn hồi của phôi do lực kẹp; khi tháo kẹp phôi đàn hồi trở lại làm sai hình dạng đã gia công.","def_en":"Elastic deformation of the part caused by clamping, which springs back after unclamping and spoils the machined shape.","def_ja":"クランプ力による工作物の弾性変形で、取り外すと戻り加工形状が狂う。","usage_en":"Danh từ không đếm được. Hay đi với: minimize clamping distortion, distortion-free clamping; nguyên nhân phổ biến của sai độ phẳng, độ tròn.","usage_ja":"Còn gọi クランプ変形 hoặc 締付けひずみ. Hay nói クランプひずみが出る / 逃がす.","context_vi":"Dùng khi gia công vòng thành mỏng, tấm mỏng, chi tiết nhôm yêu cầu độ phẳng hoặc độ tròn cao.","ex_en":"Clamping distortion made the thin ring 30 µm out of round after release.","ex_ja":"クランプひずみにより、薄肉リングは取り外し後に真円度が30 µm悪化した。","ex_vi":"Biến dạng do kẹp làm vòng thành mỏng bị méo 30 µm sau khi tháo ra.","syn_en":["clamping deformation","clamp-induced distortion"],"syn_ja":["クランプ変形","締付けひずみ"]},{"en":"zero-point clamping system","pos":"noun phrase","ipa":"/ˌzɪərəʊ ˈpɔɪnt ˈklæmpɪŋ ˌsɪstəm/","ja":"ゼロポイントクランプ","kana":"ゼロポイントクランプ","romaji":"zeropointokuranpu","vi":"hệ thống kẹp điểm không (zero-point)","level":3,"def_vi":"Hệ thống kẹp nhanh dùng chốt kéo và mô-đun kẹp để thay đồ gá hoặc pallet trong vài giây với độ lặp lại vài micromet.","def_en":"A quick-change system using pull studs and clamping modules to swap fixtures or pallets in seconds with micron repeatability.","def_ja":"プルスタッドとクランプモジュールで、治具やパレットを数秒・ミクロン単位の再現性で交換する仕組み。","usage_en":"Danh từ đếm được. Hay đi với: zero-point clamping module, pull stud, repeatability; gọi ngắn zero-point system.","usage_ja":"Ngoài xưởng gọi ゼロポイント hoặc ゼロクランプ; hay nói 段取り替えを短縮する.","context_vi":"Dùng trên trung tâm gia công 5 trục và hệ thống tự động hóa để giảm thời gian gá đặt.","ex_en":"With the zero-point clamping system, changeover dropped from 40 minutes to 5.","ex_ja":"ゼロポイントクランプを導入して、段取り替えが40分から5分になった。","ex_vi":"Nhờ hệ thống kẹp điểm không, thời gian chuyển đổi giảm từ 40 phút xuống 5 phút.","syn_en":["zero-point system","quick-change pallet system"],"syn_ja":["ゼロクランプ","クイックチェンジ治具 (gần nghĩa)"]},{"en":"work support","pos":"noun phrase","ipa":"/ˈwɜːk səˌpɔːt/","ja":"ワークサポート","kana":"ワークサポート","romaji":"waakusapooto","vi":"chốt tỳ phụ (work support)","level":3,"def_vi":"Chốt đỡ tự điều chỉnh, tiếp xúc phôi sau khi định vị rồi khóa lại, tăng độ cứng vững mà không gây siêu định vị.","def_en":"A self-adjusting support that contacts the part after locating and then locks, adding rigidity without overconstraint.","def_ja":"位置決め後に工作物に接触してロックする補助支持具で、過拘束なく剛性を高める。","usage_en":"Danh từ đếm được. Hay đi với: hydraulic work support, spring-advanced work support; lưu ý nó không phải locator.","usage_ja":"Tên sản phẩm hãng Kosmek, Pascal; ghép: 油圧ワークサポート. Văn bản thiết kế gọi 補助支持.","context_vi":"Dùng dưới vùng thành mỏng hoặc phần nhô của phôi đúc để chống rung và chống võng khi phay.","ex_en":"A hydraulic work support under the flange stopped the chatter.","ex_ja":"フランジの下に油圧ワークサポートを入れたら、びびりが止まった。","ex_vi":"Đặt chốt tỳ phụ thủy lực dưới mặt bích đã hết rung động.","syn_en":["auxiliary support","adjustable support"],"syn_ja":["補助支持","サポートシリンダ"]}]},{"id":44,"words":[{"en":"injection molding machine","pos":"noun phrase","ipa":"/ɪnˈdʒekʃn ˌməʊldɪŋ məˌʃiːn/","ja":"射出成形機","kana":"しゃしゅつせいけいき","romaji":"shashutsuseikeiki","vi":"máy ép phun","level":1,"def_vi":"Máy làm chảy nhựa hạt bằng trục vít gia nhiệt rồi phun nhựa nóng chảy vào khuôn kín để tạo sản phẩm.","def_en":"A machine that melts plastic pellets with a heated screw and injects the melt into a closed mold to form parts.","def_ja":"加熱したスクリュで樹脂を溶かし、閉じた金型に射出して製品を成形する機械。","usage_en":"Danh từ đếm được; Anh-Anh viết injection moulding machine. Thường gọi theo lực kẹp: a 350-ton injection molding machine; động từ: run / set up the machine.","usage_ja":"Ngoài xưởng gọi 成形機 hoặc 射出機; hay ghép tên hãng và tấn: 350トン成形機. Chia 電動式 và 油圧式.","context_vi":"Dùng trong xưởng ép nhựa sản xuất vỏ thiết bị điện tử, chi tiết ô tô, đồ gia dụng.","ex_en":"We added two all-electric injection molding machines for the medical parts line.","ex_ja":"医療部品ライン用に、全電動の射出成形機を2台増設した。","ex_vi":"Chúng tôi đã bổ sung hai máy ép phun điện hoàn toàn cho dây chuyền chi tiết y tế.","syn_en":["injection press","molding machine"],"syn_ja":["成形機 (khẩu ngữ)","射出機"]},{"en":"resin pellet","pos":"noun phrase","ipa":"/ˈrezɪn ˌpelɪt/","ja":"ペレット","kana":"ペレット","romaji":"peretto","vi":"hạt nhựa","level":1,"def_vi":"Hạt nhựa nhỏ hình trụ hoặc tròn, là dạng nguyên liệu cấp vào máy ép phun hoặc máy đùn.","def_en":"A small cylindrical or round granule of plastic, the usual raw-material form fed to molding machines and extruders.","def_ja":"成形機や押出機に供給する、円柱状や球状の小さな樹脂の粒。","usage_en":"Danh từ đếm được, thường số nhiều resin pellets; cũng nói plastic pellets, granules. Động từ: dry / feed / blend pellets.","usage_ja":"Ngoài xưởng gọi ペレット hoặc 材料; tiếng chung là 樹脂. Ghép: 着色ペレット, ナチュラルペレット, マスターバッチ.","context_vi":"Dùng khi nhập nguyên liệu, sấy nhựa, pha màu và quản lý lô nguyên liệu trong xưởng ép.","ex_en":"Store the resin pellets in sealed bags to keep moisture out.","ex_ja":"吸湿を防ぐため、ペレットは密封袋で保管すること。","ex_vi":"Bảo quản hạt nhựa trong bao kín để tránh hút ẩm.","syn_en":["plastic pellets","granules"],"syn_ja":["樹脂ペレット","材料 (khẩu ngữ)"]},{"en":"cavity","pos":"noun","ipa":"/ˈkævəti/","ja":"キャビティ","kana":"キャビティ","romaji":"kyabiti","vi":"lòng khuôn","level":1,"def_vi":"Khoảng trống bên trong khuôn có hình dạng sản phẩm, nơi nhựa nóng chảy được điền vào; cũng chỉ nửa khuôn tạo mặt ngoài.","def_en":"The hollow in the mold shaped like the part, which the melt fills; also the mold half forming the outer surface.","def_ja":"金型内の製品形状の空間で、溶融樹脂が充填される部分。外側を形作る型を指すこともある。","usage_en":"Danh từ đếm được. Hay đi với: four-cavity mold, cavity side, cavity pressure; đối lập với core.","usage_ja":"Gọi tắt キャビ; đối lập コア. Ghép: 4個取り (khuôn 4 lòng), キャビ側, キャビ番号.","context_vi":"Dùng khi thiết kế khuôn, ghi số lòng khuôn trên sản phẩm và truy vết lỗi theo từng lòng khuôn.","ex_en":"Parts from cavity 3 were consistently 0.1 mm short.","ex_ja":"3番キャビティの製品は、いつも0.1 mm寸法が小さかった。","ex_vi":"Sản phẩm từ lòng khuôn số 3 luôn bị hụt 0,1 mm.","syn_en":["mold cavity","impression (Anh)"],"syn_ja":["キャビ (khẩu ngữ)","コア (liên quan, đối nghĩa)"]},{"en":"ejector pin","pos":"noun phrase","ipa":"/ɪˈdʒektə ˌpɪn/","ja":"エジェクタピン","kana":"エジェクタピン","romaji":"ejekutapin","vi":"chốt đẩy","level":1,"def_vi":"Chốt thép trong khuôn đẩy sản phẩm ra khỏi lõi khuôn sau khi khuôn mở.","def_en":"A steel pin in the mold that pushes the part off the core after the mold opens.","def_ja":"型開き後に、製品をコアから押し出す金型内の鋼製ピン。","usage_en":"Danh từ đếm được. Hay đi với: ejector plate, ejector pin mark; động từ: eject / push out the part; ejector pins stick / break.","usage_ja":"JIS gọi 突出しピン; ngoài xưởng gọi エジェクタピン hoặc EP. Vết trên sản phẩm gọi エジェクタピン跡.","context_vi":"Dùng khi thiết kế, bảo trì khuôn và khi xử lý sản phẩm bị biến dạng, trắng vết khi lấy ra.","ex_en":"A bent ejector pin left a white mark on the housing.","ex_ja":"曲がったエジェクタピンが、ハウジングに白い跡を残した。","ex_vi":"Một chốt đẩy bị cong đã để lại vết trắng trên vỏ sản phẩm.","syn_en":["knockout pin","ejector"],"syn_ja":["突出しピン","EP (khẩu ngữ)"]},{"en":"short shot","pos":"noun phrase","ipa":"/ˌʃɔːt ˈʃɒt/","ja":"ショートショット","kana":"ショートショット","romaji":"shootoshotto","vi":"ép thiếu (thiếu liệu)","level":1,"def_vi":"Lỗi sản phẩm không được điền đầy do nhựa đông đặc trước khi lấp kín lòng khuôn.","def_en":"A defect where the part is incomplete because the melt freezes before the cavity is completely filled.","def_ja":"キャビティが充填しきれずに樹脂が固まり、製品の一部が欠ける不良。","usage_en":"Danh từ đếm được. Hay nói the part has a short shot, causes of short shots; cũng dùng làm động từ: the part is shorting.","usage_ja":"Ngoài xưởng nói ショート hoặc 充填不足; nói ショートが出る. Hay đi với 射出圧力を上げる.","context_vi":"Dùng trong báo cáo lỗi, khi chạy thử khuôn và khi điều chỉnh thông số ép.","ex_en":"The short shot at the end of the rib was caused by a blocked vent.","ex_ja":"リブ先端のショートショットは、ガスベントの詰まりが原因だった。","ex_vi":"Lỗi ép thiếu ở đầu gân là do lỗ thoát khí bị tắc.","syn_en":["incomplete fill","non-fill"],"syn_ja":["ショート (khẩu ngữ)","充填不足"]},{"en":"cooling time","pos":"noun phrase","ipa":"/ˈkuːlɪŋ ˌtaɪm/","ja":"冷却時間","kana":"れいきゃくじかん","romaji":"reikyakujikan","vi":"thời gian làm nguội","level":2,"def_vi":"Thời gian sản phẩm nằm trong khuôn kín sau khi phun để nguội đủ cứng trước khi mở khuôn.","def_en":"The time the part stays in the closed mold after injection to become rigid enough for ejection.","def_ja":"射出後、製品が取り出せる硬さになるまで閉じた金型内で冷やす時間。","usage_en":"Danh từ không đếm được. Hay đi với: reduce / extend the cooling time; cooling time accounts for most of the cycle time.","usage_ja":"Là một mục trong 成形条件; hay nói 冷却時間を短縮する. Đi cùng 射出時間, 保圧時間.","context_vi":"Dùng khi cài đặt thông số máy ép và tối ưu thời gian chu kỳ sản xuất.","ex_en":"Better water channels cut the cooling time from 20 s to 12 s.","ex_ja":"冷却回路を改良し、冷却時間を20秒から12秒に短縮した。","ex_vi":"Cải tiến kênh nước làm mát đã giảm thời gian làm nguội từ 20 giây xuống 12 giây.","syn_en":["cooling phase","cycle time (liên quan)"],"syn_ja":["冷却 (khẩu ngữ)","サイクルタイム (liên quan)"]},{"en":"mold clamping force","pos":"noun phrase","ipa":"/ˈməʊld ˌklæmpɪŋ ˌfɔːs/","ja":"型締力","kana":"かたじめりょく","romaji":"katajimeryoku","vi":"lực kẹp khuôn","level":2,"def_vi":"Lực máy ép tác dụng giữ hai nửa khuôn đóng kín, chống lại áp lực nhựa phun vào, thường tính bằng tấn hoặc kN.","def_en":"The force the machine applies to keep the mold halves closed against injection pressure, rated in tons or kN.","def_ja":"射出圧力に対して金型を閉じておくために成形機が加える力で、トンやkNで表す。","usage_en":"Danh từ không đếm được; gọi ngắn clamp force hoặc tonnage. Hay nói a mold clamping force of 1,500 kN; insufficient clamping causes flash.","usage_ja":"Hay nói 型締力不足, 型締力○○トン. Dùng để chọn cỡ máy ép.","context_vi":"Dùng khi chọn máy ép cho khuôn mới và khi xử lý lỗi ba via.","ex_en":"The mold clamping force was calculated from the projected area of the part.","ex_ja":"型締力は、製品の投影面積から計算した。","ex_vi":"Lực kẹp khuôn được tính từ diện tích hình chiếu của sản phẩm.","syn_en":["clamp tonnage","clamp force"],"syn_ja":["型締め力","トン数 (khẩu ngữ)"]},{"en":"injection pressure","pos":"noun phrase","ipa":"/ɪnˈdʒekʃn ˌpreʃə/","ja":"射出圧力","kana":"しゃしゅつあつりょく","romaji":"shashutsuatsuryoku","vi":"áp suất phun","level":2,"def_vi":"Áp suất trục vít đẩy nhựa nóng chảy vào khuôn trong giai đoạn điền đầy.","def_en":"The pressure with which the screw pushes melt into the mold during the filling stage.","def_ja":"充填工程でスクリュが溶融樹脂を金型に押し込む圧力。","usage_en":"Danh từ không đếm được. Hay nói increase / reduce injection pressure, peak injection pressure; phân biệt với holding pressure.","usage_ja":"Ngoài xưởng gọi 射出圧 hoặc 一次圧. Hay nói 射出圧力を上げる / 下げる.","context_vi":"Dùng khi cài đặt và điều chỉnh thông số ép, khi xử lý lỗi ép thiếu hoặc ba via.","ex_en":"Raising the injection pressure filled the thin ribs completely.","ex_ja":"射出圧力を上げたことで、薄いリブまで完全に充填できた。","ex_vi":"Tăng áp suất phun đã giúp điền đầy hoàn toàn các gân mỏng.","syn_en":["first-stage pressure","fill pressure"],"syn_ja":["射出圧","一次圧 (khẩu ngữ)"]},{"en":"holding pressure","pos":"noun phrase","ipa":"/ˈhəʊldɪŋ ˌpreʃə/","ja":"保圧","kana":"ほあつ","romaji":"hoatsu","vi":"áp suất duy trì (giữ áp)","level":2,"def_vi":"Áp suất duy trì sau khi điền đầy để bù co ngót khi nhựa nguội, cho đến khi miệng phun đông đặc.","def_en":"Pressure maintained after filling to pack in more melt and compensate shrinkage until the gate freezes.","def_ja":"充填後、ゲートが固まるまで圧力をかけ続け、収縮分の樹脂を補う圧力。","usage_en":"Danh từ không đếm được; còn gọi packing pressure. Hay đi với: holding pressure time, increase holding pressure to reduce sink.","usage_ja":"Ghép: 保圧時間, 保圧切替. Ngoài xưởng còn gọi 二次圧. Hay nói 保圧をかける / 上げる.","context_vi":"Dùng khi điều chỉnh thông số để chống vết lõm, sai kích thước và cong vênh.","ex_en":"Longer holding pressure time improved the dimensional stability.","ex_ja":"保圧時間を長くしたら、寸法が安定した。","ex_vi":"Kéo dài thời gian giữ áp đã làm kích thước ổn định hơn.","syn_en":["packing pressure","second-stage pressure"],"syn_ja":["保持圧力","二次圧 (khẩu ngữ)"]},{"en":"back pressure","pos":"noun phrase","ipa":"/ˈbæk ˌpreʃə/","ja":"背圧","kana":"はいあつ","romaji":"haiatsu","vi":"áp suất ngược","level":2,"def_vi":"Áp suất cản trục vít lùi lại khi định lượng, giúp nhựa trộn đều, đồng nhất và thoát khí.","def_en":"Resistance applied to the screw as it retracts during dosing, improving melt mixing, uniformity and degassing.","def_ja":"計量時に後退するスクリュに加える抵抗圧で、樹脂の混練・均一化・脱気を良くする。","usage_en":"Danh từ không đếm được. Hay nói set the back pressure to 5 MPa, too much back pressure overheats the melt.","usage_ja":"Là thông số 計量条件; hay nói 背圧を上げる / かける. Đọc はいあつ.","context_vi":"Dùng khi pha màu bằng masterbatch, khi sản phẩm có bọt khí hoặc màu không đều.","ex_en":"We increased the back pressure to stop color streaks.","ex_ja":"色ムラを防ぐため、背圧を上げた。","ex_vi":"Chúng tôi tăng áp suất ngược để hết vệt màu không đều.","syn_en":["screw back pressure"],"syn_ja":["スクリュ背圧"]},{"en":"mold shrinkage","pos":"noun phrase","ipa":"/ˈməʊld ˌʃrɪŋkɪdʒ/","ja":"成形収縮","kana":"せいけいしゅうしゅく","romaji":"seikeishuushuku","vi":"co ngót khi ép","level":2,"def_vi":"Sự giảm kích thước của sản phẩm nhựa so với lòng khuôn khi nguội, thường biểu diễn bằng phần trăm.","def_en":"The reduction of part size compared with the mold cavity as the plastic cools, usually given in percent.","def_ja":"樹脂が冷えて製品寸法が金型寸法より小さくなること。通常%で表す。","usage_en":"Danh từ không đếm được. Hay đi với: mold shrinkage rate, shrinkage allowance; động từ: compensate for / allow for shrinkage.","usage_ja":"Hay dùng 成形収縮率 (tỷ lệ co ngót) ghi trong datasheet nhựa; khuôn được làm lớn hơn theo 収縮率.","context_vi":"Dùng khi thiết kế kích thước lòng khuôn, chọn vật liệu và khi sản phẩm sai kích thước.","ex_en":"Glass-filled nylon has lower mold shrinkage in the flow direction.","ex_ja":"ガラス繊維入りナイロンは、流動方向の成形収縮が小さい。","ex_vi":"Nylon gia cường sợi thủy tinh có độ co ngót khi ép theo hướng dòng chảy nhỏ hơn.","syn_en":["molding shrinkage","shrinkage"],"syn_ja":["成形収縮率","収縮 (khẩu ngữ)"]},{"en":"sink mark","pos":"noun phrase","ipa":"/ˈsɪŋk ˌmɑːk/","ja":"ヒケ","kana":"ヒケ","romaji":"hike","vi":"vết lõm (co rút bề mặt)","level":2,"def_vi":"Vết lõm nông trên bề mặt sản phẩm ở vùng thành dày hoặc phía sau gân, do nhựa bên trong co ngót.","def_en":"A shallow depression on the surface over thick sections or ribs, caused by internal shrinkage.","def_ja":"肉厚部やリブの裏側で、内部の収縮により表面が浅くへこむ不良。","usage_en":"Danh từ đếm được, thường số nhiều sink marks. Hay nói sink marks over the ribs; động từ: reduce / eliminate sink.","usage_ja":"Viết ヒケ hoặc ひけ; nói ヒケが出る. Biện pháp: 保圧を上げる, 肉厚を均一にする.","context_vi":"Dùng trong kiểm tra ngoại quan sản phẩm nhựa và khi rà soát thiết kế độ dày thành.","ex_en":"Sink marks appeared opposite each boss on the cover.","ex_ja":"カバーのボスの裏側すべてにヒケが出た。","ex_vi":"Vết lõm xuất hiện ở mặt đối diện mỗi trụ trên nắp.","syn_en":["sink","shrink mark"],"syn_ja":["ひけ","引け"]},{"en":"weld line","pos":"noun phrase","ipa":"/ˈweld ˌlaɪn/","ja":"ウェルドライン","kana":"ウェルドライン","romaji":"werudorain","vi":"đường hàn (vết nối dòng chảy)","level":2,"def_vi":"Đường mảnh nhìn thấy trên sản phẩm nơi hai dòng nhựa gặp nhau, thường là điểm yếu về độ bền.","def_en":"A visible line where two melt fronts meet, often a weak spot in the part.","def_ja":"2つの樹脂の流れが合流した部分に現れる細い線で、強度上の弱点になりやすい。","usage_en":"Danh từ đếm được; còn gọi knit line. Hay nói weld line near the hole, weld line strength; move / hide the weld line.","usage_ja":"Ngoài xưởng gọi tắt ウェルド: ウェルドが目立つ. Biện pháp: 金型温度を上げる, ゲート位置を変える.","context_vi":"Dùng trong kiểm tra ngoại quan và đánh giá độ bền, đặc biệt quanh lỗ và chi tiết có nhiều miệng phun.","ex_en":"The crack started at the weld line beside the screw boss.","ex_ja":"割れは、ねじボス横のウェルドラインから発生した。","ex_vi":"Vết nứt bắt đầu từ đường hàn cạnh trụ bắt vít.","syn_en":["knit line","meld line (gần nghĩa)"],"syn_ja":["ウェルド (khẩu ngữ)"]},{"en":"warpage","pos":"noun","ipa":"/ˈwɔːpɪdʒ/","ja":"反り","kana":"そり","romaji":"sori","vi":"cong vênh","level":2,"def_vi":"Sự biến dạng cong, xoắn của sản phẩm sau khi lấy ra do co ngót không đều hoặc ứng suất dư.","def_en":"Bending or twisting of a molded part after ejection due to uneven shrinkage or residual stress.","def_ja":"収縮の不均一や残留応力により、取出し後の製品が曲がったりねじれたりすること。","usage_en":"Danh từ không đếm được; động từ là warp (the part warps). Hay nói reduce warpage, warpage of 0.5 mm.","usage_ja":"Hay nói 反りが出る / 大きい; ghép: 反り変形, 反り量. Ngoài xưởng cũng nói ねじれ cho biến dạng xoắn.","context_vi":"Dùng khi kiểm tra độ phẳng sản phẩm nhựa, nhất là vỏ dài mỏng và nhựa gia cường sợi.","ex_en":"Warpage of the long cover was reduced by balancing mold temperatures.","ex_ja":"金型温度のバランスを取ることで、長いカバーの反りを減らした。","ex_vi":"Cong vênh của nắp dài đã giảm nhờ cân bằng nhiệt độ khuôn.","syn_en":["warp","distortion"],"syn_ja":["反り変形","ねじれ (gần nghĩa)"]},{"en":"hopper dryer","pos":"noun phrase","ipa":"/ˈhɒpə ˌdraɪə/","ja":"ホッパドライヤ","kana":"ホッパドライヤ","romaji":"hoppadoraiya","vi":"máy sấy phễu","level":2,"def_vi":"Phễu nạp liệu có thổi khí nóng để sấy hạt nhựa ngay trên máy ép trước khi vào trục vít.","def_en":"A feed hopper that blows hot air through the pellets to dry them on the machine before they enter the screw.","def_ja":"熱風を吹き込んで、成形機上でペレットを乾燥させるホッパ。","usage_en":"Danh từ đếm được. Hay đi với: drying temperature, drying time, dehumidifying dryer; động từ: load / dry in the hopper dryer.","usage_ja":"Còn viết ホッパードライヤー. Với nhựa hút ẩm mạnh (PA, PC) dùng 除湿乾燥機.","context_vi":"Dùng khi sấy nhựa như ABS, PC, PA trước khi ép để tránh vệt bạc và giảm cơ tính.","ex_en":"Set the hopper dryer to 80 °C for four hours before molding ABS.","ex_ja":"ABSを成形する前に、ホッパドライヤを80 °Cで4時間運転すること。","ex_vi":"Đặt máy sấy phễu ở 80 °C trong bốn giờ trước khi ép ABS.","syn_en":["resin dryer","dehumidifying dryer (loại tách ẩm)"],"syn_ja":["ホッパードライヤー","除湿乾燥機 (loại tách ẩm)"]},{"en":"extruder","pos":"noun","ipa":"/ɪkˈstruːdə/","ja":"押出機","kana":"おしだしき","romaji":"oshidashiki","vi":"máy đùn","level":2,"def_vi":"Máy dùng trục vít quay liên tục làm chảy nhựa và đẩy qua đầu khuôn để tạo sản phẩm dài như ống, thanh, màng.","def_en":"A machine whose rotating screw melts plastic continuously and forces it through a die to make pipe, profile or film.","def_ja":"回転するスクリュで樹脂を連続的に溶かし、ダイから押し出して管・異形材・フィルムを作る機械。","usage_en":"Danh từ đếm được. Hay đi với: single-screw / twin-screw extruder, extruder barrel, extrusion die; động từ: run / feed the extruder.","usage_ja":"Còn gọi 押出成形機; ghép: 単軸押出機, 二軸押出機. Quá trình gọi 押出成形.","context_vi":"Dùng trong sản xuất ống nhựa, dây cáp, màng, và trong pha trộn compound nhựa.","ex_en":"The twin-screw extruder compounds glass fiber into the polypropylene.","ex_ja":"二軸押出機で、ポリプロピレンにガラス繊維を混練する。","ex_vi":"Máy đùn trục vít đôi trộn sợi thủy tinh vào polypropylene.","syn_en":["extrusion machine"],"syn_ja":["押出成形機","エクストルーダ"]},{"en":"blow molding","pos":"noun","ipa":"/ˈbləʊ ˌməʊldɪŋ/","ja":"ブロー成形","kana":"ブローせいけい","romaji":"burooseikei","vi":"thổi khuôn (ép thổi)","level":2,"def_vi":"Phương pháp thổi khí nén vào phôi ống nhựa nóng đặt trong khuôn để tạo sản phẩm rỗng như chai, can.","def_en":"A process that inflates a hot plastic tube or preform inside a mold with compressed air to make hollow parts.","def_ja":"金型内の加熱した樹脂チューブやプリフォームに圧縮空気を吹き込み、中空品を作る成形法。","usage_en":"Danh từ không đếm được; Anh-Anh viết blow moulding. Chia extrusion blow molding và stretch blow molding (chai PET).","usage_ja":"Chia ダイレクトブロー và 延伸ブロー (chai PET). Hay nói ブロー成形品, ブロー機.","context_vi":"Dùng trong sản xuất chai nước, can dầu, bình nhiên liệu ô tô, ống gió.","ex_en":"The fuel tank is made by blow molding from HDPE.","ex_ja":"燃料タンクは、HDPEのブロー成形で作られる。","ex_vi":"Bình nhiên liệu được làm bằng phương pháp thổi khuôn từ HDPE.","syn_en":["blow moulding (Anh)","stretch blow molding (nghĩa hẹp hơn)"],"syn_ja":["中空成形","延伸ブロー (nghĩa hẹp hơn)"]},{"en":"hot runner","pos":"noun phrase","ipa":"/ˌhɒt ˈrʌnə/","ja":"ホットランナー","kana":"ホットランナー","romaji":"hottorannaa","vi":"kênh dẫn nóng","level":3,"def_vi":"Hệ thống kênh dẫn được gia nhiệt giữ nhựa luôn nóng chảy trong khuôn, không tạo kênh dẫn phế liệu.","def_en":"A heated runner system that keeps the plastic molten inside the mold, so no runner scrap is produced.","def_ja":"金型内のランナーを加熱して樹脂を溶融状態に保ち、ランナー廃材を出さない方式。","usage_en":"Danh từ đếm được. Hay đi với: hot runner system, hot runner nozzle, manifold, temperature controller; đối lập với cold runner.","usage_ja":"JIS viết ホットランナ. Ghép: ホットランナー金型, マニホールド, バルブゲート. Gọi tắt HR.","context_vi":"Dùng cho khuôn nhiều lòng, sản xuất loạt lớn và nhựa đắt tiền để giảm phế liệu và thời gian chu kỳ.","ex_en":"Switching to a hot runner saved 30 tonnes of resin a year.","ex_ja":"ホットランナーに切り替えて、年間30トンの樹脂を節約した。","ex_vi":"Chuyển sang kênh dẫn nóng đã tiết kiệm 30 tấn nhựa mỗi năm.","syn_en":["hot runner system","runnerless molding"],"syn_ja":["ホットランナ","ランナーレス成形"]},{"en":"insert molding","pos":"noun","ipa":"/ˈɪnsɜːt ˌməʊldɪŋ/","ja":"インサート成形","kana":"インサートせいけい","romaji":"insaatoseikei","vi":"ép phun có chi tiết cài (insert molding)","level":3,"def_vi":"Phương pháp đặt sẵn chi tiết kim loại như đai ốc, chân cắm vào khuôn rồi phun nhựa bao quanh để tạo một khối.","def_en":"Placing metal parts such as nuts or terminals in the mold and molding plastic around them to form one piece.","def_ja":"ナットや端子などの金属部品を金型に入れ、その周りに樹脂を成形して一体化する方法。","usage_en":"Danh từ không đếm được; Anh-Anh viết insert moulding. Hay đi với: insert-molded nut, vertical insert molding machine.","usage_ja":"Ghép: インサート成形品, インサートナット, 縦型成形機. Gần nghĩa: アウトサート成形.","context_vi":"Dùng trong sản xuất đầu nối điện, cảm biến, tay nắm có lõi kim loại, chi tiết ô tô.","ex_en":"Insert molding replaced the separate press-fitting of brass nuts.","ex_ja":"インサート成形により、真鍮ナットの圧入工程が不要になった。","ex_vi":"Ép phun có chi tiết cài đã thay thế bước ép đai ốc đồng riêng lẻ.","syn_en":["insert moulding (Anh)","overmolding (nghĩa rộng hơn)"],"syn_ja":["インサート (khẩu ngữ)","アウトサート成形 (liên quan)"]},{"en":"two-shot molding","pos":"noun","ipa":"/ˌtuː ʃɒt ˈməʊldɪŋ/","ja":"二色成形","kana":"にしょくせいけい","romaji":"nishokuseikei","vi":"ép phun hai màu (hai thành phần)","level":3,"def_vi":"Phương pháp ép hai loại nhựa khác màu hoặc khác vật liệu lần lượt trong cùng một khuôn để tạo sản phẩm liền khối.","def_en":"Molding two different colors or materials in sequence in one mold to produce a single integrated part.","def_ja":"色や材質の異なる2種類の樹脂を、一つの金型で順に成形し一体化する方法。","usage_en":"Danh từ không đếm được; còn gọi 2K molding, multi-shot molding. Hay đi với: rotary platen, hard-soft combination.","usage_ja":"Còn gọi 2色成形, 異材質成形. Máy chuyên dùng gọi 二色成形機. Hay nói 硬質と軟質を二色成形する.","context_vi":"Dùng cho nút bấm có ký tự, tay cầm cứng-mềm, đèn hậu ô tô nhiều màu.","ex_en":"The toothbrush handle is produced by two-shot molding of PP and TPE.","ex_ja":"歯ブラシの柄は、PPとTPEの二色成形で作られている。","ex_vi":"Cán bàn chải được sản xuất bằng ép phun hai thành phần PP và TPE.","syn_en":["2K molding","multi-shot molding"],"syn_ja":["2色成形","異材質成形"]},{"en":"jetting","pos":"noun","ipa":"/ˈdʒetɪŋ/","ja":"ジェッティング","kana":"ジェッティング","romaji":"jettingu","vi":"phun tia (lỗi dòng rắn)","level":3,"def_vi":"Lỗi dòng nhựa phun thành tia rắn từ miệng phun vào lòng khuôn rộng mà không lan đều, để lại vết dạng con rắn.","def_en":"A defect where melt shoots from the gate as a snake-like jet instead of spreading evenly, leaving a wavy mark.","def_ja":"ゲートから樹脂がひも状に噴き出し、製品表面に蛇行した跡が残る不良。","usage_en":"Danh từ không đếm được. Hay nói jetting marks, prevent jetting by gating against a wall or slowing injection speed.","usage_ja":"Hay nói ジェッティングが出る; biện pháp: 射出速度を落とす, ゲートを壁に当てる. Ngoài xưởng gọi 蛇行模様.","context_vi":"Dùng khi phân tích lỗi ngoại quan ở sản phẩm có miệng phun nhỏ mở vào vùng thành dày.","ex_en":"Jetting near the gate was solved by reducing the first-stage speed.","ex_ja":"ゲート付近のジェッティングは、初段の射出速度を下げて解決した。","ex_vi":"Lỗi phun tia gần miệng phun được xử lý bằng cách giảm tốc độ phun giai đoạn đầu.","syn_en":["snake flow","worm tracks (khẩu ngữ)"],"syn_ja":["蛇行模様 (khẩu ngữ)"]},{"en":"mold flow analysis","pos":"noun phrase","ipa":"/ˈməʊld fləʊ əˌnæləsɪs/","ja":"流動解析","kana":"りゅうどうかいせき","romaji":"ryuudoukaiseki","vi":"phân tích dòng chảy khuôn","level":3,"def_vi":"Mô phỏng máy tính quá trình điền đầy, giữ áp, làm nguội và cong vênh để tối ưu miệng phun và thông số ép trước khi làm khuôn.","def_en":"Computer simulation of filling, packing, cooling and warpage to optimize gates and settings before building the mold.","def_ja":"充填・保圧・冷却・反りをコンピュータで予測し、金型製作前にゲートや条件を最適化する解析。","usage_en":"Danh từ đếm được. Hay đi với: run a mold flow analysis, fill analysis, warpage prediction; Moldflow là tên phần mềm, không phải tên chung.","usage_ja":"Còn gọi 樹脂流動解析, CAE解析. Tên phần mềm: Moldflow, 3D TIMON, Moldex3D.","context_vi":"Dùng ở giai đoạn thiết kế sản phẩm và khuôn để dự đoán ép thiếu, đường hàn, bọt khí, cong vênh.","ex_en":"The mold flow analysis predicted a weld line across the logo.","ex_ja":"流動解析で、ロゴを横切るウェルドラインの発生が予測された。","ex_vi":"Phân tích dòng chảy khuôn dự đoán có đường hàn cắt ngang logo.","syn_en":["filling simulation","Moldflow analysis (tên phần mềm)"],"syn_ja":["樹脂流動解析","CAE解析 (nghĩa rộng hơn)"]},{"en":"V/P switchover","pos":"noun phrase","ipa":"/ˌviː ˈpiː ˈswɪtʃəʊvə/","ja":"V-P切替","kana":"ブイピーきりかえ","romaji":"buipiikirikae","vi":"điểm chuyển V/P (từ phun sang giữ áp)","level":3,"def_vi":"Thời điểm máy chuyển từ điều khiển tốc độ phun sang điều khiển áp suất giữ, thường theo vị trí trục vít.","def_en":"The point where the machine changes from velocity-controlled filling to pressure-controlled holding, usually by screw position.","def_ja":"射出の速度制御から保圧の圧力制御に切り替える点で、通常スクリュ位置で設定する。","usage_en":"Danh từ đếm được; đọc V-P switchover. Hay nói set the V/P switchover at 98% fill, switchover position / pressure.","usage_ja":"Còn viết VP切換, 保圧切替位置. Hay nói 切替位置を調整する.","context_vi":"Dùng khi tối ưu thông số ép theo phương pháp khoa học (scientific molding) và ổn định trọng lượng sản phẩm.","ex_en":"Setting the V/P switchover too late caused flash at the parting line.","ex_ja":"V-P切替が遅すぎたため、PLにバリが出た。","ex_vi":"Đặt điểm chuyển V/P quá muộn đã gây ba via ở đường phân khuôn.","syn_en":["transfer position","velocity-to-pressure transfer"],"syn_ja":["保圧切替","VP切換"]},{"en":"gas-assisted injection molding","pos":"noun phrase","ipa":"/ˌɡæs əˈsɪstɪd ɪnˈdʒekʃn ˌməʊldɪŋ/","ja":"ガスアシスト成形","kana":"ガスアシストせいけい","romaji":"gasuashisutoseikei","vi":"ép phun có trợ khí","level":3,"def_vi":"Phương pháp bơm khí nitơ vào nhựa đang nóng chảy để tạo lõi rỗng, giảm vết lõm, khối lượng và cong vênh ở chi tiết dày.","def_en":"Injecting nitrogen into the molten plastic to core out thick sections, reducing sink, weight and warpage.","def_ja":"溶融樹脂に窒素ガスを注入して肉厚部を中空にし、ヒケ・重量・反りを減らす成形法。","usage_en":"Danh từ không đếm được; gọi ngắn GAIM hoặc gas assist. Hay đi với: gas channel, gas injection pin, nitrogen pressure.","usage_ja":"Còn gọi ガスインジェクション成形 hoặc 中空射出成形. Ghép: ガスアシスト金型, ガス注入ピン.","context_vi":"Dùng cho tay nắm cửa ô tô, tay cầm, khung ghế nhựa và chi tiết có thành dày.","ex_en":"Gas-assisted injection molding removed the sink marks on the thick handle.","ex_ja":"ガスアシスト成形により、太いハンドルのヒケがなくなった。","ex_vi":"Ép phun có trợ khí đã loại bỏ vết lõm trên tay cầm dày.","syn_en":["GAIM","gas assist molding"],"syn_ja":["ガスインジェクション成形","中空射出成形"]}]},{"id":45,"words":[{"en":"powder metallurgy","pos":"noun phrase","ipa":"/ˌpaʊdə məˈtælədʒi/","ja":"粉末冶金","kana":"ふんまつやきん","romaji":"funmatsuyakin","vi":"luyện kim bột","level":1,"def_vi":"Công nghệ chế tạo chi tiết từ bột kim loại bằng cách ép thành hình rồi thiêu kết ở nhiệt độ dưới điểm nóng chảy.","def_en":"The technology of making parts from metal powder by pressing it to shape and sintering below the melting point.","def_ja":"金属粉末を成形し、融点以下で焼結して部品を作る技術。","usage_en":"Danh từ không đếm được, viết tắt PM hoặc P/M. Hay dùng như tính từ: powder metallurgy parts, PM gear, PM process.","usage_ja":"Hay ghép: 粉末冶金法, 粉末冶金製品. Ngoài xưởng thường nói 焼結 thay cho cả ngành (焼結メーカー).","context_vi":"Dùng trong sản xuất bánh răng bơm dầu, bạc tự bôi trơn, chi tiết ô tô và dụng cụ hợp kim cứng.","ex_en":"Powder metallurgy produces near-net-shape gears with almost no machining.","ex_ja":"粉末冶金では、ほとんど機械加工なしでニアネットシェイプの歯車を作れる。","ex_vi":"Luyện kim bột tạo ra bánh răng gần đúng hình dạng cuối cùng mà hầu như không cần gia công cắt.","syn_en":["PM","P/M"],"syn_ja":["焼結 (khẩu ngữ)","PM"]},{"en":"metal powder","pos":"noun phrase","ipa":"/ˈmetl ˌpaʊdə/","ja":"金属粉末","kana":"きんぞくふんまつ","romaji":"kinzokufunmatsu","vi":"bột kim loại","level":1,"def_vi":"Kim loại hoặc hợp kim ở dạng hạt rất nhỏ, thường từ vài đến vài trăm micromet, là nguyên liệu của luyện kim bột.","def_en":"Metal or alloy in the form of very fine particles, typically a few to several hundred micrometres, used as PM feedstock.","def_ja":"数µmから数百µmの細かい粒子状の金属・合金で、粉末冶金の原料。","usage_en":"Danh từ không đếm được khi nói chung; đếm được khi chỉ loại: different metal powders. Hay đi với: iron / copper metal powder, powder lot.","usage_ja":"Ngoài xưởng gọi ngắn 粉 (こな) hoặc 原料粉. Ghép: 金属粉末製造, 粉末特性.","context_vi":"Dùng khi mua nguyên liệu, kiểm tra lô bột và trong cả in 3D kim loại, phun phủ.","ex_en":"Each lot of metal powder is checked for particle size and flow.","ex_ja":"金属粉末はロットごとに粒度と流動性を確認する。","ex_vi":"Mỗi lô bột kim loại đều được kiểm tra cỡ hạt và độ chảy.","syn_en":["powder","feedstock powder"],"syn_ja":["金属粉","原料粉"]},{"en":"particle size","pos":"noun phrase","ipa":"/ˈpɑːtɪkl ˌsaɪz/","ja":"粒度","kana":"りゅうど","romaji":"ryuudo","vi":"cỡ hạt","level":1,"def_vi":"Kích thước của các hạt bột, thường biểu diễn bằng phân bố cỡ hạt đo bằng sàng hoặc nhiễu xạ laser.","def_en":"The size of powder particles, usually reported as a distribution measured by sieving or laser diffraction.","def_ja":"粉末粒子の大きさで、ふるい分けやレーザ回折で測った分布で表す。","usage_en":"Danh từ không đếm được. Hay đi với: particle size distribution (PSD), mean particle size, D50; động từ: measure / control particle size.","usage_ja":"Hay ghép: 粒度分布, 平均粒径 (へいきんりゅうけい), メッシュ. Ngoài xưởng nói 粒度が粗い / 細かい.","context_vi":"Dùng trong chứng nhận lô bột, chọn bột cho ép, MIM hoặc in 3D kim loại.","ex_en":"Finer particle size improves sintering but reduces powder flow.","ex_ja":"粒度が細かいほど焼結性は良くなるが、流動性は悪くなる。","ex_vi":"Cỡ hạt mịn hơn giúp thiêu kết tốt hơn nhưng làm giảm độ chảy của bột.","syn_en":["grain size (khẩu ngữ, dễ nhầm)","particle size distribution (liên quan)"],"syn_ja":["粒径","粒度分布 (liên quan)"]},{"en":"compaction","pos":"noun","ipa":"/kəmˈpækʃn/","ja":"圧粉成形","kana":"あっぷんせいけい","romaji":"appunseikei","vi":"ép tạo hình bột","level":1,"def_vi":"Công đoạn ép bột kim loại trong khuôn bằng chày trên và chày dưới để tạo phôi có hình dạng và mật độ yêu cầu.","def_en":"Pressing metal powder in a die between upper and lower punches to form a part of the required shape and density.","def_ja":"金型内で上下パンチにより金属粉末を加圧し、所定の形と密度の成形体を作る工程。","usage_en":"Danh từ không đếm được; động từ là compact (compact the powder). Hay đi với: compaction press, compaction pressure, single- / double-action compaction.","usage_ja":"Ngoài xưởng gọi ngắn 成形; ghép: 成形プレス, 成形圧力. Nói 粉末を成形する.","context_vi":"Là bước chính của luyện kim bột, thực hiện trên máy ép cơ khí hoặc thủy lực tốc độ cao.","ex_en":"Compaction at 600 MPa gives a green density of about 7.0 g/cm³.","ex_ja":"600 MPaで圧粉成形すると、約7.0 g/cm³の圧粉密度になる。","ex_vi":"Ép tạo hình bột ở 600 MPa cho mật độ phôi ép khoảng 7,0 g/cm³.","syn_en":["pressing","powder compaction"],"syn_ja":["成形 (khẩu ngữ)","プレス成形"]},{"en":"compaction die","pos":"noun phrase","ipa":"/kəmˈpækʃn ˌdaɪ/","ja":"粉末成形金型","kana":"ふんまつせいけいかながた","romaji":"funmatsuseikeikanagata","vi":"khuôn ép bột","level":1,"def_vi":"Bộ khuôn gồm cối, chày trên, chày dưới và lõi, thường bằng hợp kim cứng, dùng ép bột thành hình.","def_en":"The tool set of die, upper and lower punches and core rod, often carbide, used to press powder to shape.","def_ja":"ダイ・上下パンチ・コアロッドからなる、粉末を成形する金型。超硬製が多い。","usage_en":"Danh từ đếm được; trong ngành hay nói tooling. Hay đi với: carbide compaction die, die wall, core rod, punch.","usage_ja":"Ngoài xưởng gọi 金型 hoặc ダイ; các bộ phận: 上パンチ, 下パンチ, コアロッド.","context_vi":"Dùng khi thiết kế, chế tạo khuôn ép bột và bảo trì do mòn thành cối.","ex_en":"The compaction die has two lower punches to form the stepped gear.","ex_ja":"この粉末成形金型には、段付き歯車を作るため下パンチが2本ある。","ex_vi":"Khuôn ép bột này có hai chày dưới để tạo bánh răng bậc.","syn_en":["PM tooling","die set"],"syn_ja":["成形金型","ダイ (khẩu ngữ)"]},{"en":"green compact","pos":"noun phrase","ipa":"/ˌɡriːn ˈkɒmpækt/","ja":"圧粉体","kana":"あっぷんたい","romaji":"appuntai","vi":"phôi ép (chưa thiêu kết)","level":1,"def_vi":"Chi tiết bột đã được ép thành hình nhưng chưa thiêu kết, còn giòn và có độ bền thấp.","def_en":"A pressed powder part that has not yet been sintered and is still fragile.","def_ja":"成形後で焼結前の粉末の成形体で、強度が低くもろい。","usage_en":"Danh từ đếm được; green nghĩa là chưa thiêu kết. Hay nói green part, handle green compacts carefully.","usage_ja":"Ngoài xưởng gọi 成形体 hoặc グリーン. Hay nói 圧粉体を割らないよう取り扱う.","context_vi":"Dùng ở khâu giữa ép và thiêu kết, khi kiểm tra khối lượng, chiều cao và nứt phôi ép.","ex_en":"The green compact cracked when it was ejected from the die.","ex_ja":"金型から抜き出す際に、圧粉体に割れが生じた。","ex_vi":"Phôi ép bị nứt khi đẩy ra khỏi khuôn.","syn_en":["green part","compact"],"syn_ja":["成形体","グリーン (khẩu ngữ)"]},{"en":"sintering","pos":"noun","ipa":"/ˈsɪntərɪŋ/","ja":"焼結","kana":"しょうけつ","romaji":"shouketsu","vi":"thiêu kết","level":1,"def_vi":"Quá trình nung phôi ép ở nhiệt độ dưới điểm nóng chảy để các hạt bột liên kết với nhau, tăng độ bền.","def_en":"Heating a compact below its melting point so that the particles bond together and the part gains strength.","def_ja":"成形体を融点以下で加熱し、粒子同士を結合させて強度を与える工程。","usage_en":"Danh từ không đếm được; động từ sinter, tính từ sintered. Hay đi với: sintering temperature, sintering time, sinter at 1,120 °C.","usage_ja":"Động từ: 焼結する. Ghép: 焼結温度, 焼結時間, 焼結体. Cũng dùng cho gốm và hợp kim cứng.","context_vi":"Dùng trong luyện kim bột, sản xuất hợp kim cứng, gốm kỹ thuật và nam châm.","ex_en":"Sintering is done at 1,120 °C for 30 minutes in a protective atmosphere.","ex_ja":"焼結は保護雰囲気中で1,120 °C、30分間行う。","ex_vi":"Thiêu kết được thực hiện ở 1.120 °C trong 30 phút trong môi trường khí bảo vệ.","syn_en":["sinter (động từ)","firing (gốm)"],"syn_ja":["シンタリング"]},{"en":"sintering furnace","pos":"noun phrase","ipa":"/ˈsɪntərɪŋ ˌfɜːnɪs/","ja":"焼結炉","kana":"しょうけつろ","romaji":"shouketsuro","vi":"lò thiêu kết","level":1,"def_vi":"Lò nung có kiểm soát nhiệt độ và khí quyển dùng để thiêu kết phôi ép, thường là lò băng tải liên tục.","def_en":"A furnace with controlled temperature and atmosphere for sintering compacts, often a continuous mesh-belt type.","def_ja":"温度と雰囲気を制御して成形体を焼結する炉で、連続式のメッシュベルト炉が多い。","usage_en":"Danh từ đếm được. Hay đi với: mesh-belt / walking-beam / vacuum sintering furnace; zones: preheat, hot zone, cooling zone.","usage_ja":"Ghép: メッシュベルト炉, 真空焼結炉, プッシャー炉. Hay nói 焼結炉に通す.","context_vi":"Dùng trong nhà máy luyện kim bột, nhà máy hợp kim cứng và khi vận hành, bảo trì lò.","ex_en":"The mesh-belt sintering furnace runs 24 hours a day.","ex_ja":"メッシュベルト式の焼結炉は24時間稼働している。","ex_vi":"Lò thiêu kết băng lưới chạy liên tục 24 giờ mỗi ngày.","syn_en":["sinter furnace","mesh-belt furnace (một loại)"],"syn_ja":["メッシュベルト炉 (một loại)","連続焼結炉"]},{"en":"sintered part","pos":"noun phrase","ipa":"/ˌsɪntəd ˈpɑːt/","ja":"焼結部品","kana":"しょうけつぶひん","romaji":"shouketsubuhin","vi":"chi tiết thiêu kết","level":1,"def_vi":"Chi tiết thành phẩm được chế tạo bằng luyện kim bột, có thể còn một tỷ lệ lỗ xốp nhỏ.","def_en":"A finished component made by powder metallurgy, which usually retains some porosity.","def_ja":"粉末冶金で作られた部品で、通常いくらかの気孔を含む。","usage_en":"Danh từ đếm được. Hay đi với: sintered steel part, sintered gear, sintered bushing; cũng nói PM part.","usage_ja":"Ngoài xưởng gọi 焼結品. Ghép: 焼結機械部品 (thuật ngữ JIS), 鉄系焼結部品.","context_vi":"Dùng trong ô tô, xe máy, máy móc gia dụng: bánh răng bơm dầu, puly, đĩa cam, bạc.","ex_en":"Each car contains about 9 kg of sintered parts.","ex_ja":"自動車1台には、約9 kgの焼結部品が使われている。","ex_vi":"Mỗi chiếc ô tô chứa khoảng 9 kg chi tiết thiêu kết.","syn_en":["PM part","sintered component"],"syn_ja":["焼結品","焼結機械部品"]},{"en":"oil-impregnated bearing","pos":"noun phrase","ipa":"/ˌɔɪl ɪmˈpreɡneɪtɪd ˈbeərɪŋ/","ja":"含油軸受","kana":"がんゆじくうけ","romaji":"gan'yujikuuke","vi":"bạc tự bôi trơn (bạc thấm dầu)","level":1,"def_vi":"Bạc thiêu kết xốp được tẩm dầu vào lỗ xốp, tự cấp dầu khi trục quay nên không cần bôi trơn thêm.","def_en":"A porous sintered bearing filled with oil that feeds lubricant to the shaft as it turns, needing no extra lubrication.","def_ja":"多孔質の焼結体に油を含ませ、軸の回転で給油する軸受で、外部給油が不要。","usage_en":"Danh từ đếm được; còn gọi self-lubricating bearing, sintered bronze bushing. Hay đi với: press-fit an oil-impregnated bearing.","usage_ja":"Tên đầy đủ 焼結含油軸受; ngoài xưởng gọi 含油メタル hoặc オイレス (tên thương hiệu). Đọc がんゆ.","context_vi":"Dùng trong quạt điện, động cơ nhỏ, máy in, thiết bị gia dụng và mô tơ ô tô.","ex_en":"The fan motor uses two oil-impregnated bearings made of sintered bronze.","ex_ja":"このファンモータには、焼結青銅製の含油軸受が2個使われている。","ex_vi":"Động cơ quạt dùng hai bạc tự bôi trơn bằng đồng thiêu kết.","syn_en":["self-lubricating bearing","sintered bushing"],"syn_ja":["焼結含油軸受","含油メタル (khẩu ngữ)"]},{"en":"atomization","pos":"noun","ipa":"/ˌætəmaɪˈzeɪʃn/","ja":"アトマイズ法","kana":"アトマイズほう","romaji":"atomaizuhou","vi":"phương pháp phun nguyên tử hóa (atomization)","level":2,"def_vi":"Phương pháp sản xuất bột bằng cách dùng tia nước hoặc khí áp lực cao đánh tan dòng kim loại nóng chảy thành giọt rồi đông đặc.","def_en":"Making powder by breaking a stream of molten metal into droplets with high-pressure water or gas jets.","def_ja":"溶融金属の流れに高圧の水やガスを吹き付けて液滴にし、凝固させて粉末を作る方法。","usage_en":"Danh từ không đếm được; Anh-Anh viết atomisation. Chia water atomization và gas atomization; tính từ: water-atomized powder.","usage_ja":"Chia 水アトマイズ và ガスアトマイズ. Bột tạo ra gọi アトマイズ粉.","context_vi":"Dùng khi nói về nguồn gốc và hình dạng hạt bột; bột khí phun hạt tròn dùng cho MIM và in 3D.","ex_en":"Gas atomization gives spherical particles suitable for additive manufacturing.","ex_ja":"ガスアトマイズ法では、積層造形に適した球状粒子が得られる。","ex_vi":"Phương pháp phun khí tạo ra hạt hình cầu phù hợp cho in 3D.","syn_en":["water atomization (nghĩa hẹp hơn)","gas atomization (nghĩa hẹp hơn)"],"syn_ja":["水アトマイズ","ガスアトマイズ"]},{"en":"iron powder","pos":"noun phrase","ipa":"/ˈaɪən ˌpaʊdə/","ja":"鉄粉","kana":"てっぷん","romaji":"teppun","vi":"bột sắt","level":2,"def_vi":"Bột sắt nguyên chất hoặc hợp kim thấp, nguyên liệu chính của chi tiết thiêu kết hệ sắt, sản xuất bằng phun nước hoặc hoàn nguyên.","def_en":"Pure or low-alloy iron powder, the main raw material for ferrous PM parts, made by water atomization or reduction.","def_ja":"鉄系焼結部品の主原料となる純鉄または低合金の粉末で、水アトマイズや還元で作る。","usage_en":"Danh từ không đếm được. Hay đi với: atomized / sponge iron powder, prealloyed iron powder; trộn với graphite, copper.","usage_ja":"Chia アトマイズ鉄粉 và 還元鉄粉. Đọc てっぷん. Hay nói 鉄粉に黒鉛と銅粉を混ぜる.","context_vi":"Dùng khi lập công thức hỗn hợp bột cho bánh răng, chi tiết kết cấu thiêu kết.","ex_en":"The mix contains iron powder with 2% copper and 0.8% graphite.","ex_ja":"この混合粉は、鉄粉に銅2%と黒鉛0.8%を加えたものだ。","ex_vi":"Hỗn hợp gồm bột sắt với 2% đồng và 0,8% graphit.","syn_en":["sponge iron powder (bột hoàn nguyên)","ferrous powder"],"syn_ja":["純鉄粉","還元鉄粉 (một loại)"]},{"en":"powder blending","pos":"noun phrase","ipa":"/ˈpaʊdə ˌblendɪŋ/","ja":"混合","kana":"こんごう","romaji":"kongou","vi":"trộn bột","level":2,"def_vi":"Công đoạn trộn đều bột nền với bột hợp kim, graphit và chất bôi trơn trước khi ép.","def_en":"Uniformly mixing the base powder with alloying powders, graphite and lubricant before compaction.","def_ja":"成形前に、基粉に合金粉・黒鉛・潤滑剤を均一に混ぜる工程。","usage_en":"Danh từ không đếm được; động từ blend. Hay đi với: blending time, V-blender, double-cone blender; tránh over-blending gây tách lớp.","usage_ja":"Ghép: 混合粉, 混合機 (V型混合機). Thường đọc 混合 là こんごう, không nhầm với 混練.","context_vi":"Dùng ở đầu dây chuyền luyện kim bột, ảnh hưởng đến sự đồng đều thành phần và kích thước sau thiêu kết.","ex_en":"Powder blending for 30 minutes gave a uniform graphite distribution.","ex_ja":"30分間の混合で、黒鉛が均一に分散した。","ex_vi":"Trộn bột trong 30 phút cho graphit phân bố đều.","syn_en":["mixing","blending"],"syn_ja":["粉末混合","ミキシング"]},{"en":"apparent density","pos":"noun phrase","ipa":"/əˌpærənt ˈdensəti/","ja":"見掛密度","kana":"みかけみつど","romaji":"mikakemitsudo","vi":"khối lượng riêng biểu kiến (tỷ trọng đổ đống)","level":2,"def_vi":"Khối lượng của một đơn vị thể tích bột đổ tự do không nén, đo bằng phễu Hall theo tiêu chuẩn.","def_en":"The mass per unit volume of loose, unpacked powder, measured with a Hall funnel by standard methods.","def_ja":"自然に充填した粉末の単位体積あたりの質量で、ホールフローメータで測る。","usage_en":"Danh từ không đếm được, đơn vị g/cm³. Hay nói apparent density of 3.0 g/cm³; phân biệt với tap density và green density.","usage_ja":"JIS viết 見掛密度 (cũng gặp 見かけ密度); ngoài xưởng gọi AD. Ghép: 見掛密度測定.","context_vi":"Dùng trong phiếu chứng nhận lô bột và khi tính chiều sâu điền bột trong khuôn.","ex_en":"A higher apparent density allows a shorter fill height in the die.","ex_ja":"見掛密度が高いほど、金型の充填深さを浅くできる。","ex_vi":"Khối lượng riêng biểu kiến cao hơn cho phép chiều cao điền bột trong khuôn thấp hơn.","syn_en":["bulk density","AD"],"syn_ja":["かさ密度","見かけ密度"]},{"en":"powder flow rate","pos":"noun phrase","ipa":"/ˈpaʊdə ˈfləʊ ˌreɪt/","ja":"流動度","kana":"りゅうどうど","romaji":"ryuudoudo","vi":"độ chảy của bột","level":2,"def_vi":"Thời gian để 50 g bột chảy qua phễu chuẩn, phản ánh khả năng điền đầy khuôn nhanh và đều.","def_en":"The time for 50 g of powder to flow through a standard funnel, showing how quickly and evenly it fills a die.","def_ja":"50 gの粉末が規定の漏斗を流れ落ちる時間で、金型への充填性を示す。","usage_en":"Danh từ không đếm được, đơn vị s/50 g; giá trị càng nhỏ bột chảy càng tốt. Hay đi với: Hall flow rate, poor flow.","usage_ja":"Ngoài xưởng nói 流動性 (tính chảy) chung chung; số đo cụ thể gọi 流動度 (秒/50g).","context_vi":"Dùng trong kiểm tra đầu vào lô bột và khi xử lý phôi ép bị thiếu khối lượng, lệch mật độ.","ex_en":"The powder flow rate of 28 s/50 g is acceptable for high-speed pressing.","ex_ja":"流動度28秒/50 gなら、高速プレスに使える。","ex_vi":"Độ chảy của bột 28 s/50 g là chấp nhận được cho ép tốc độ cao.","syn_en":["Hall flow","flowability (nghĩa rộng hơn)"],"syn_ja":["流動性 (nghĩa rộng hơn)"]},{"en":"green density","pos":"noun phrase","ipa":"/ˌɡriːn ˈdensəti/","ja":"圧粉密度","kana":"あっぷんみつど","romaji":"appunmitsudo","vi":"mật độ phôi ép","level":2,"def_vi":"Khối lượng riêng của phôi ép trước khi thiêu kết, quyết định phần lớn độ bền và độ co của chi tiết.","def_en":"The density of the compact before sintering, which largely determines final strength and dimensional change.","def_ja":"焼結前の成形体の密度で、最終強度や寸法変化を大きく左右する。","usage_en":"Danh từ không đếm được. Hay nói green density of 6.9 g/cm³, density gradient; đối lập với sintered density.","usage_ja":"Còn gọi 成形密度; hay nói 圧粉密度のばらつき, 密度差 giữa trên và dưới phôi.","context_vi":"Dùng khi cài đặt máy ép, kiểm tra chất lượng phôi ép và thiết kế chi tiết nhiều bậc.","ex_en":"Green density varied between the hub and the teeth of the gear.","ex_ja":"歯車のボス部と歯部で、圧粉密度に差があった。","ex_vi":"Mật độ phôi ép khác nhau giữa phần moay-ơ và phần răng của bánh răng.","syn_en":["compact density","pressed density"],"syn_ja":["成形密度"]},{"en":"green strength","pos":"noun phrase","ipa":"/ˌɡriːn ˈstreŋθ/","ja":"圧粉体強度","kana":"あっぷんたいきょうど","romaji":"appuntaikyoudo","vi":"độ bền phôi ép","level":2,"def_vi":"Độ bền của phôi ép chưa thiêu kết, cần đủ lớn để đẩy ra khỏi khuôn và vận chuyển mà không vỡ, mẻ.","def_en":"The strength of an unsintered compact, which must be enough for ejection and handling without breaking or chipping.","def_ja":"焼結前の成形体の強度で、抜出しや搬送で割れ・欠けが出ない程度に必要。","usage_en":"Danh từ không đếm được. Hay đi với: improve green strength, green strength test (transverse rupture); low green strength causes edge chipping.","usage_ja":"Còn gọi 成形体強度; chỉ số liên quan ラトラ値 (đánh giá mẻ cạnh). Hay nói 圧粉体強度が低い.","context_vi":"Dùng khi chọn chất bôi trơn và loại bột, khi phôi ép bị vỡ góc trong lúc vận chuyển.","ex_en":"The new lubricant raised green strength enough for robot handling.","ex_ja":"新しい潤滑剤で圧粉体強度が上がり、ロボット搬送が可能になった。","ex_vi":"Chất bôi trơn mới làm tăng độ bền phôi ép đủ để robot gắp chuyển.","syn_en":["green compact strength"],"syn_ja":["成形体強度","ラトラ値 (liên quan)"]},{"en":"sintered density","pos":"noun phrase","ipa":"/ˌsɪntəd ˈdensəti/","ja":"焼結密度","kana":"しょうけつみつど","romaji":"shouketsumitsudo","vi":"mật độ sau thiêu kết","level":2,"def_vi":"Khối lượng riêng của chi tiết sau thiêu kết, thường biểu diễn bằng g/cm³ hoặc phần trăm so với mật độ lý thuyết.","def_en":"The density of a part after sintering, given in g/cm³ or as a percentage of theoretical density.","def_ja":"焼結後の部品の密度で、g/cm³または理論密度に対する%で表す。","usage_en":"Danh từ không đếm được. Hay nói sintered density of 7.2 g/cm³, 92% of theoretical density; đo theo nguyên lý Archimedes.","usage_ja":"Hay ghép 相対密度 (mật độ tương đối, %); đo bằng アルキメデス法.","context_vi":"Dùng trong bản vẽ chi tiết thiêu kết, tiêu chuẩn vật liệu (MPIF, JIS) và kiểm tra chất lượng.","ex_en":"The drawing specifies a minimum sintered density of 6.8 g/cm³.","ex_ja":"図面では、焼結密度6.8 g/cm³以上と指定されている。","ex_vi":"Bản vẽ quy định mật độ sau thiêu kết tối thiểu 6,8 g/cm³.","syn_en":["final density","relative density (theo %)"],"syn_ja":["相対密度 (theo %)","焼結体密度"]},{"en":"porosity","pos":"noun","ipa":"/pɔːˈrɒsəti/","ja":"気孔率","kana":"きこうりつ","romaji":"kikouritsu","vi":"độ xốp","level":2,"def_vi":"Tỷ lệ thể tích lỗ rỗng trong chi tiết thiêu kết, ảnh hưởng đến độ bền, độ kín và khả năng chứa dầu.","def_en":"The volume fraction of pores in a sintered part, which affects strength, sealing and oil retention.","def_ja":"焼結体に含まれる気孔の体積割合で、強度・気密性・含油量に影響する。","usage_en":"Danh từ không đếm được; cũng chỉ lỗ xốp nói chung. Hay nói residual porosity, open / closed porosity, 10% porosity.","usage_ja":"Lỗ xốp gọi 気孔 hoặc 空孔; ghép: 開気孔, 閉気孔. Bạc tự bôi trơn cần 気孔率 khoảng 20%.","context_vi":"Dùng khi đánh giá chất lượng chi tiết thiêu kết, khi cần tẩm dầu, tẩm nhựa chống rò hoặc mạ.","ex_en":"The bearing has 20% porosity to hold lubricating oil.","ex_ja":"この軸受は、潤滑油を保持するため気孔率が20%ある。","ex_vi":"Bạc này có độ xốp 20% để chứa dầu bôi trơn.","syn_en":["void fraction","pore volume"],"syn_ja":["空孔率","気孔 (liên quan)"]},{"en":"dewaxing","pos":"noun","ipa":"/ˌdiːˈwæksɪŋ/","ja":"脱ろう","kana":"だつろう","romaji":"datsurou","vi":"khử chất bôi trơn (tách sáp)","level":2,"def_vi":"Giai đoạn nung sơ bộ ở khoảng 400–700 °C để đốt cháy, bay hơi chất bôi trơn trong phôi ép trước khi thiêu kết.","def_en":"The preheating stage, around 400–700 °C, that burns off the pressing lubricant before sintering.","def_ja":"焼結前に約400〜700 °Cで加熱し、成形用潤滑剤を除去する工程。","usage_en":"Danh từ không đếm được; còn gọi delubrication, lube burn-off. Hay đi với: dewaxing zone, incomplete dewaxing causes blisters.","usage_ja":"Viết 脱ろう hoặc 脱蝋; ghép: 脱ろうゾーン, 脱ろう不良. Trong MIM thì dùng 脱脂.","context_vi":"Dùng khi vận hành vùng đầu lò thiêu kết và phân tích lỗi bề mặt bị phồng, đen.","ex_en":"Poor dewaxing left soot on the surface of the parts.","ex_ja":"脱ろうが不十分で、部品表面にすすが残った。","ex_vi":"Khử chất bôi trơn không tốt đã để lại muội trên bề mặt chi tiết.","syn_en":["delubrication","lube burn-off"],"syn_ja":["脱蝋","脱脂 (MIM, liên quan)"]},{"en":"sintering atmosphere","pos":"noun phrase","ipa":"/ˈsɪntərɪŋ ˌætməsfɪə/","ja":"焼結雰囲気","kana":"しょうけつふんいき","romaji":"shouketsufun'iki","vi":"khí quyển thiêu kết","level":2,"def_vi":"Khí bảo vệ trong lò như hỗn hợp N2-H2 hoặc khí phân hủy amoniac, chống oxy hóa và kiểm soát hàm lượng cacbon.","def_en":"The protective furnace gas, such as N2-H2 or endothermic gas, that prevents oxidation and controls carbon content.","def_ja":"N2-H2やRXガスなど、酸化を防ぎ炭素量を制御する炉内の保護ガス。","usage_en":"Danh từ đếm được. Hay đi với: reducing atmosphere, dew point, nitrogen-hydrogen atmosphere; động từ: control the atmosphere.","usage_ja":"Ghép: 還元雰囲気, 露点 (điểm sương), 雰囲気ガス. Ngoài xưởng nói gọn 雰囲気.","context_vi":"Dùng khi vận hành lò thiêu kết, kiểm soát điểm sương và xử lý chi tiết bị oxy hóa hoặc thoát cacbon.","ex_en":"A wet sintering atmosphere caused decarburization of the gears.","ex_ja":"焼結雰囲気の露点が高く、歯車が脱炭した。","ex_vi":"Khí quyển thiêu kết bị ẩm đã làm bánh răng bị thoát cacbon.","syn_en":["furnace atmosphere","protective atmosphere"],"syn_ja":["雰囲気ガス","炉内雰囲気"]},{"en":"sizing","pos":"noun","ipa":"/ˈsaɪzɪŋ/","ja":"サイジング","kana":"サイジング","romaji":"saijingu","vi":"ép định cỡ (ép chỉnh kích thước)","level":2,"def_vi":"Công đoạn ép lại chi tiết sau thiêu kết trong khuôn chính xác để nâng độ chính xác kích thước và độ nhẵn bề mặt.","def_en":"Re-pressing a sintered part in a precision die to improve dimensional accuracy and surface finish.","def_ja":"焼結後の部品を精密金型で再加圧し、寸法精度と表面粗さを向上させる工程。","usage_en":"Danh từ không đếm được; động từ size. Hay đi với: sizing press, sizing die; gần nghĩa với coining (ép lại để tăng mật độ).","usage_ja":"Còn gọi 矯正 (きょうせい); ghép: サイジング金型, サイジングプレス. Phân biệt với コイニング.","context_vi":"Dùng cho bạc tự bôi trơn, bánh răng cần dung sai đường kính hẹp sau thiêu kết.","ex_en":"Sizing brought the bore tolerance down to ±0.01 mm.","ex_ja":"サイジングによって、内径公差を±0.01 mmに収めた。","ex_vi":"Ép định cỡ đã đưa dung sai lỗ về ±0,01 mm.","syn_en":["re-pressing","coining (gần nghĩa)"],"syn_ja":["矯正","再圧縮"]},{"en":"infiltration","pos":"noun","ipa":"/ˌɪnfɪlˈtreɪʃn/","ja":"溶浸","kana":"ようしん","romaji":"youshin","vi":"thấm kim loại (thẩm thấu)","level":2,"def_vi":"Quá trình cho kim loại có điểm nóng chảy thấp hơn, thường là đồng, chảy vào lỗ xốp của khung thiêu kết để tăng mật độ và độ bền.","def_en":"Filling the pores of a sintered skeleton with a lower-melting metal, usually copper, to raise density and strength.","def_ja":"焼結体の気孔に銅など融点の低い金属を溶かし込み、密度と強度を高める方法。","usage_en":"Danh từ không đếm được; động từ infiltrate. Hay đi với: copper infiltration, infiltrated steel, infiltrant.","usage_ja":"Hay ghép: 銅溶浸, 溶浸材. Đọc ようしん. Phân biệt với 含浸 (tẩm dầu hoặc nhựa).","context_vi":"Dùng cho chi tiết chịu tải, ghế van, và vật liệu tiếp điểm điện W-Cu.","ex_en":"Copper infiltration raised the density of the valve seat to 7.6 g/cm³.","ex_ja":"銅の溶浸により、バルブシートの密度が7.6 g/cm³に上がった。","ex_vi":"Thấm đồng đã nâng mật độ của bệ van lên 7,6 g/cm³.","syn_en":["copper infiltration (nghĩa hẹp hơn)"],"syn_ja":["銅溶浸 (nghĩa hẹp hơn)","含浸 (liên quan, khác nghĩa)"]},{"en":"steam treatment","pos":"noun phrase","ipa":"/ˈstiːm ˌtriːtmənt/","ja":"水蒸気処理","kana":"すいじょうきしょり","romaji":"suijoukishori","vi":"xử lý hơi nước","level":2,"def_vi":"Nung chi tiết thiêu kết hệ sắt trong hơi nước khoảng 550 °C để tạo lớp Fe3O4 bịt lỗ xốp, tăng chống mòn và chống gỉ.","def_en":"Heating ferrous PM parts in steam at about 550 °C to form Fe3O4 that seals pores and improves wear and rust resistance.","def_ja":"鉄系焼結部品を約550 °Cの水蒸気中で処理し、Fe3O4皮膜で気孔をふさぎ耐摩耗性を高める。","usage_en":"Danh từ không đếm được; còn gọi steam oxidation, steam blueing. Hay đi với: steam-treated parts.","usage_ja":"Ngoài xưởng gọi スチーム処理 hoặc ホモ処理. Hay nói 水蒸気処理を施す.","context_vi":"Dùng cho chi tiết thiêu kết trong bơm dầu, máy nén, bộ giảm chấn cần kín khí và chống mòn.","ex_en":"Steam treatment sealed the pores so the pump part held pressure.","ex_ja":"水蒸気処理で気孔がふさがれ、ポンプ部品が圧力を保てるようになった。","ex_vi":"Xử lý hơi nước đã bịt lỗ xốp nên chi tiết bơm giữ được áp suất.","syn_en":["steam oxidation","steam blueing"],"syn_ja":["スチーム処理","ホモ処理 (khẩu ngữ)"]},{"en":"metal injection molding","pos":"noun phrase","ipa":"/ˈmetl ɪnˈdʒekʃn ˌməʊldɪŋ/","ja":"金属粉末射出成形","kana":"きんぞくふんまつしゃしゅつせいけい","romaji":"kinzokufunmatsushashutsuseikei","vi":"ép phun bột kim loại (MIM)","level":3,"def_vi":"Công nghệ trộn bột kim loại mịn với chất kết dính, ép phun như nhựa, rồi khử chất kết dính và thiêu kết để tạo chi tiết nhỏ phức tạp.","def_en":"Mixing fine metal powder with binder, injection molding it like plastic, then debinding and sintering to make small complex parts.","def_ja":"微細金属粉末とバインダを混ぜて射出成形し、脱脂・焼結して小型複雑形状部品を作る技術。","usage_en":"Danh từ không đếm được, viết tắt MIM; Anh-Anh viết moulding. Hay đi với: MIM part, MIM feedstock, MIM process.","usage_ja":"Ngoài xưởng gọi MIM (ミム) hoặc メタルインジェクション. Ghép: MIM部品, フィードストック.","context_vi":"Dùng sản xuất chi tiết nhỏ phức tạp: linh kiện điện thoại, dụng cụ y tế, chi tiết súng, đồng hồ.","ex_en":"Metal injection molding is economical for small stainless parts above 10,000 pieces.","ex_ja":"金属粉末射出成形は、1万個以上の小型ステンレス部品で経済的だ。","ex_vi":"Ép phun bột kim loại kinh tế với chi tiết inox nhỏ từ 10.000 chiếc trở lên.","syn_en":["MIM","powder injection molding (nghĩa rộng hơn)"],"syn_ja":["MIM","メタルインジェクション"]},{"en":"debinding","pos":"noun","ipa":"/ˌdiːˈbaɪndɪŋ/","ja":"脱脂","kana":"だっし","romaji":"dasshi","vi":"khử chất kết dính","level":3,"def_vi":"Công đoạn loại bỏ chất kết dính khỏi phôi MIM bằng dung môi, xúc tác hoặc nhiệt trước khi thiêu kết.","def_en":"Removing the binder from a MIM part by solvent, catalytic or thermal methods before sintering.","def_ja":"焼結前に、溶剤・触媒・熱でMIM成形体からバインダを除去する工程。","usage_en":"Danh từ không đếm được. Hay đi với: solvent / catalytic / thermal debinding, brown part (phôi sau khử); debinding furnace.","usage_ja":"Ghép: 溶剤脱脂, 触媒脱脂, 加熱脱脂, 脱脂炉. Trong xử lý bề mặt 脱脂 còn có nghĩa tẩy dầu mỡ.","context_vi":"Dùng trong dây chuyền MIM và in 3D kim loại bằng chất kết dính (binder jetting).","ex_en":"Catalytic debinding removes the polyacetal binder in a few hours.","ex_ja":"触媒脱脂では、ポリアセタール系バインダを数時間で除去できる。","ex_vi":"Khử chất kết dính bằng xúc tác loại bỏ chất kết dính polyacetal trong vài giờ.","syn_en":["binder removal"],"syn_ja":["バインダ除去"]},{"en":"liquid phase sintering","pos":"noun phrase","ipa":"/ˌlɪkwɪd feɪz ˈsɪntərɪŋ/","ja":"液相焼結","kana":"えきそうしょうけつ","romaji":"ekisoushouketsu","vi":"thiêu kết pha lỏng","level":3,"def_vi":"Thiêu kết trong đó một thành phần nóng chảy tạo pha lỏng làm ướt các hạt rắn, giúp đông đặc hóa nhanh và đạt mật độ cao.","def_en":"Sintering in which one constituent melts and wets the solid particles, speeding densification to high density.","def_ja":"一部の成分が溶けて液相となり固体粒子をぬらし、緻密化を促進する焼結。","usage_en":"Danh từ không đếm được. Đối lập với solid-state sintering; ví dụ cobalt forms the liquid phase in cemented carbide.","usage_ja":"Đối lập 固相焼結. Hay nói 液相が出る, 液相焼結で緻密化する.","context_vi":"Dùng khi sản xuất hợp kim cứng WC-Co, hợp kim nặng vonfram và một số thép thiêu kết.","ex_en":"Cemented carbide reaches full density by liquid phase sintering at 1,400 °C.","ex_ja":"超硬合金は、1,400 °Cの液相焼結で真密度近くまで緻密化する。","ex_vi":"Hợp kim cứng đạt mật độ gần tuyệt đối nhờ thiêu kết pha lỏng ở 1.400 °C.","syn_en":["LPS","solid-state sintering (liên quan, đối nghĩa)"],"syn_ja":["固相焼結 (liên quan, đối nghĩa)"]},{"en":"neck growth","pos":"noun phrase","ipa":"/ˈnek ˌɡrəʊθ/","ja":"ネック成長","kana":"ネックせいちょう","romaji":"nekkuseichou","vi":"sự phát triển cổ liên kết","level":3,"def_vi":"Sự lớn dần của vùng tiếp xúc (cổ) giữa các hạt bột do khuếch tán khi thiêu kết, tạo nên độ bền của chi tiết.","def_en":"The growth of the contact region (neck) between particles by diffusion during sintering, which gives the part its strength.","def_ja":"焼結中の拡散により粒子間の接触部(ネック)が大きくなる現象で、強度の源となる。","usage_en":"Danh từ không đếm được. Hay đi với: neck formation, sintering neck, neck growth rate; dùng trong mô hình thiêu kết hai hạt.","usage_ja":"Hay nói ネックが形成される / 成長する; dùng chủ yếu trong tài liệu học thuật, ít dùng ngoài xưởng.","context_vi":"Dùng trong giáo trình luyện kim bột và phân tích ảnh hiển vi tổ chức thiêu kết.","ex_en":"Neck growth between particles is clearly visible in the SEM image.","ex_ja":"SEM像では、粒子間のネック成長がはっきり見える。","ex_vi":"Sự phát triển cổ liên kết giữa các hạt thấy rõ trên ảnh SEM.","syn_en":["neck formation","interparticle bonding"],"syn_ja":["ネック形成"]},{"en":"sinter hardening","pos":"noun phrase","ipa":"/ˈsɪntə ˌhɑːdnɪŋ/","ja":"シンターハードニング","kana":"シンターハードニング","romaji":"shintaahaadoningu","vi":"tôi cứng khi thiêu kết (sinter hardening)","level":3,"def_vi":"Phương pháp làm nguội nhanh chi tiết ngay ở vùng nguội của lò thiêu kết để tạo martensit, bỏ được bước tôi riêng.","def_en":"Rapidly cooling parts in the sintering furnace's cooling zone to form martensite, eliminating a separate hardening step.","def_ja":"焼結炉の冷却帯で急冷してマルテンサイトを生成させ、別工程の焼入れを省く方法。","usage_en":"Danh từ không đếm được; tính từ sinter-hardened. Hay đi với: sinter hardening grade, accelerated cooling, tempering after sinter hardening.","usage_ja":"Còn gọi 焼結焼入れ; ghép: シンターハードニング材, 急冷ゾーン. Vẫn cần 焼戻し sau đó.","context_vi":"Dùng cho bánh răng, chi tiết đồng bộ hộp số thiêu kết cần độ cứng cao mà ít biến dạng.","ex_en":"Sinter hardening gave the sprocket 35 HRC without oil quenching.","ex_ja":"シンターハードニングにより、油焼入れなしでスプロケットが35 HRCになった。","ex_vi":"Tôi cứng khi thiêu kết giúp đĩa xích đạt 35 HRC mà không cần tôi dầu.","syn_en":["sinter-hardening process"],"syn_ja":["焼結焼入れ"]},{"en":"hot isostatic pressing","pos":"noun phrase","ipa":"/ˌhɒt ˌaɪsəʊˈstætɪk ˈpresɪŋ/","ja":"熱間等方圧加圧","kana":"ねっかんとうほうあつかあつ","romaji":"nekkantouhouatsukaatsu","vi":"ép đẳng tĩnh nóng (HIP)","level":3,"def_vi":"Phương pháp nung và ép đồng thời bằng khí argon áp suất cao từ mọi phía để loại bỏ lỗ xốp bên trong, đạt mật độ gần 100%.","def_en":"Applying high temperature and high-pressure argon equally from all directions to close internal pores and reach near-full density.","def_ja":"高温と高圧アルゴンガスを全方向から同時に加え、内部の気孔をなくして真密度に近づける方法。","usage_en":"Danh từ không đếm được, viết tắt HIP (đọc là /hɪp/). Hay dùng như động từ: the parts were HIPed; đi với HIP cycle, HIP unit.","usage_ja":"Ngoài xưởng gọi HIP (ヒップ): HIP処理, HIP装置. Tên đầy đủ hay viết 熱間等方圧加圧法.","context_vi":"Dùng cho chi tiết đúc chính xác và in 3D kim loại hàng không, y tế, và để ép bột thành phôi nguyên khối.","ex_en":"Hot isostatic pressing closed the internal porosity in the printed titanium brackets.","ex_ja":"熱間等方圧加圧によって、造形したチタンブラケット内部の気孔がなくなった。","ex_vi":"Ép đẳng tĩnh nóng đã loại bỏ lỗ xốp bên trong các giá đỡ titan in 3D.","syn_en":["HIP","HIPing"],"syn_ja":["HIP処理","熱間静水圧プレス"]}]},{"id":46,"words":[{"en":"assembly line","pos":"noun phrase","ipa":"/əˈsembli laɪn/","ja":"組立ライン","kana":"くみたてライン","romaji":"kumitaterain","vi":"dây chuyền lắp ráp","level":1,"def_vi":"Chuỗi các trạm làm việc bố trí liên tiếp, sản phẩm di chuyển qua từng trạm và được lắp thêm chi tiết cho đến khi hoàn chỉnh.","def_en":"A sequence of workstations through which a product moves, with parts added at each station until it is complete.","def_ja":"製品が順に流れ、各工程で部品を組み付けて完成させる作業場の連なり。","usage_en":"Danh từ đếm được. Hay đi với: on the assembly line, run / stop / set up an assembly line; 'production line' có nghĩa rộng hơn.","usage_ja":"Hay nói 組立ラインに入る, ラインを止める, ライン停止; ngoài xưởng thường gọi tắt là ライン.","context_vi":"Dùng trong nhà máy ô tô, xe máy, điện tử, thiết bị gia dụng sản xuất hàng loạt.","ex_en":"The assembly line was stopped for 20 minutes because a screw feeder jammed.","ex_ja":"ねじ供給機が詰まったため、組立ラインが20分間停止した。","ex_vi":"Dây chuyền lắp ráp đã dừng 20 phút vì máy cấp vít bị kẹt.","syn_en":["production line (nghĩa rộng hơn)"],"syn_ja":["組立工程","ライン (khẩu ngữ)"]},{"en":"subassembly","pos":"noun","ipa":"/ˈsʌbəˌsembli/","ja":"サブアセンブリ","kana":"サブアセンブリ","romaji":"sabuasenburi","vi":"cụm lắp (cụm chi tiết con)","level":1,"def_vi":"Cụm gồm nhiều chi tiết được lắp sẵn thành một khối, sau đó mới đưa vào lắp ráp tổng thành.","def_en":"A unit of several parts assembled separately and later installed into a larger assembly.","def_ja":"複数の部品をあらかじめ組み立てた単位で、後で上位の組立品に組み込まれるもの。","usage_en":"Danh từ đếm được; cũng viết 'sub-assembly'. Hay đi với: build / install / test a subassembly, subassembly line.","usage_ja":"Ngoài xưởng hay nói サブ組 hoặc サブアッシー; văn bản dùng 部分組立品. Động từ: サブアセンブリを組む, 組み込む.","context_vi":"Dùng khi chia công việc lắp ráp thành các cụm như cụm bơm, cụm hộp số, cụm cửa xe để lắp song song.","ex_en":"The gearbox subassembly is tested for noise before it reaches the main line.","ex_ja":"ギヤボックスのサブアセンブリは、メインラインに送る前に騒音を検査する。","ex_vi":"Cụm hộp số được kiểm tra tiếng ồn trước khi đưa vào dây chuyền chính.","syn_en":["sub-assembly","module (gần nghĩa)"],"syn_ja":["部分組立品","サブアッシー (khẩu ngữ)"]},{"en":"final assembly","pos":"noun phrase","ipa":"/ˌfaɪnl əˈsembli/","ja":"最終組立","kana":"さいしゅうくみたて","romaji":"saishuukumitate","vi":"lắp ráp tổng thành (lắp ráp hoàn thiện)","level":1,"def_vi":"Công đoạn cuối, ghép các cụm và chi tiết lại thành sản phẩm hoàn chỉnh trước khi kiểm tra xuất xưởng.","def_en":"The last stage in which subassemblies and parts are joined into the finished product before final testing.","def_ja":"出荷検査の前に、サブアセンブリや部品を組み合わせて完成品にする最後の工程。","usage_en":"Danh từ không đếm được, hay làm bổ ngữ: final assembly line, final assembly plant, in final assembly.","usage_ja":"Hay dùng 最終組立工程, 最終組立ライン; ngoài xưởng còn gọi 総組 (そうぐみ).","context_vi":"Dùng trong nhà máy ô tô, máy công nghiệp, nơi các cụm từ nhiều xưởng hội về một dây chuyền.","ex_en":"Engines arrive at final assembly as complete subassemblies.","ex_ja":"エンジンは完成したサブアセンブリとして最終組立に届く。","ex_vi":"Động cơ được đưa đến khâu lắp ráp tổng thành dưới dạng cụm hoàn chỉnh.","syn_en":["general assembly (gần nghĩa)"],"syn_ja":["総組立","完成組立"]},{"en":"manual assembly","pos":"noun phrase","ipa":"/ˌmænjuəl əˈsembli/","ja":"手組み","kana":"てぐみ","romaji":"tegumi","vi":"lắp ráp thủ công","level":1,"def_vi":"Lắp ráp do công nhân thực hiện bằng tay và dụng cụ cầm tay, không dùng máy tự động.","def_en":"Assembly carried out by workers using their hands and hand tools rather than automated equipment.","def_ja":"自動機を使わず、作業者が手と手工具で行う組立。","usage_en":"Danh từ không đếm được. Hay đi với: manual assembly station / cell; đối lập với automatic assembly.","usage_ja":"手組み là cách nói ở xưởng; văn bản dùng 手作業組立 hoặc 手組立. Hay gặp 手組みライン, 手組み工程.","context_vi":"Dùng khi sản lượng nhỏ, sản phẩm nhiều biến thể hoặc thao tác khó tự động như đi dây điện.","ex_en":"Wiring harness routing is still done by manual assembly.","ex_ja":"ハーネスの配索は今も手組みで行っている。","ex_vi":"Việc đi bó dây điện vẫn được thực hiện bằng lắp ráp thủ công.","syn_en":["hand assembly"],"syn_ja":["手作業組立","手組立"]},{"en":"component","pos":"noun","ipa":"/kəmˈpəʊnənt/","ja":"部品","kana":"ぶひん","romaji":"buhin","vi":"chi tiết, linh kiện","level":1,"def_vi":"Một bộ phận riêng lẻ được chế tạo hoặc mua về để lắp vào cụm hoặc sản phẩm.","def_en":"An individual part made or purchased to be fitted into an assembly or product.","def_ja":"組立品や製品に組み込むために製作または購入した個々の部材。","usage_en":"Danh từ đếm được. Hay đi với: purchased component, critical component, install / fit a component; 'part' là từ thông dụng hơn.","usage_ja":"部品 là từ chung nhất; ghép: 購入部品, 加工部品, 部品を組み付ける. Katakana コンポーネント thường chỉ cụm lớn hơn.","context_vi":"Dùng hằng ngày trong lắp ráp, kho, danh mục vật tư và bản vẽ.","ex_en":"Each component is checked against the parts list before it goes to the line.","ex_ja":"各部品はラインに出す前に部品リストと照合する。","ex_vi":"Mỗi chi tiết được đối chiếu với danh sách linh kiện trước khi đưa ra dây chuyền.","syn_en":["part"],"syn_ja":["パーツ","構成部品"]},{"en":"workbench","pos":"noun","ipa":"/ˈwɜːkbentʃ/","ja":"作業台","kana":"さぎょうだい","romaji":"sagyoudai","vi":"bàn thao tác (bàn nguội)","level":1,"def_vi":"Bàn chắc chắn để công nhân đặt chi tiết, dụng cụ và thực hiện các thao tác lắp ráp, sửa chữa.","def_en":"A sturdy table on which workers place parts and tools and carry out assembly or repair tasks.","def_ja":"作業者が部品や工具を置き、組立や修理作業を行う丈夫な台。","usage_en":"Danh từ đếm được, viết liền một từ. Hay đi với: at the workbench, assembly workbench, ESD workbench.","usage_ja":"Hay đi với 作業台の高さ, 作業台に置く; loại có ê-tô gọi 万力付き作業台.","context_vi":"Dùng ở trạm lắp tay, phòng bảo trì, xưởng nguội, khu sửa chữa.","ex_en":"The workbench height was raised to reduce operator back strain.","ex_ja":"作業者の腰への負担を減らすため、作業台の高さを上げた。","ex_vi":"Chiều cao bàn thao tác đã được nâng lên để giảm mỏi lưng cho công nhân.","syn_en":["bench","work table"],"syn_ja":["ワークベンチ","作業机"]},{"en":"disassembly","pos":"noun","ipa":"/ˌdɪsəˈsembli/","ja":"分解","kana":"ぶんかい","romaji":"bunkai","vi":"tháo rời (tháo máy)","level":1,"def_vi":"Việc tháo một cụm hoặc máy thành các chi tiết riêng để kiểm tra, sửa chữa hoặc thay thế.","def_en":"Taking an assembly or machine apart into its individual parts for inspection, repair or replacement.","def_ja":"点検・修理・交換のため、組立品や機械を個々の部品にばらすこと。","usage_en":"Danh từ không đếm được; động từ là disassemble. Hay đi với: during disassembly, disassembly and reassembly, ease of disassembly.","usage_ja":"Động từ 分解する; cặp hay gặp 分解・組立, 分解点検. Khẩu ngữ: ばらす.","context_vi":"Dùng trong bảo trì, sửa chữa, phân tích hư hỏng và khi thiết kế sản phẩm dễ tháo để tái chế.","ex_en":"Mark the parts before disassembly so they go back in the same position.","ex_ja":"同じ位置に戻せるよう、分解の前に部品に印を付けておく。","ex_vi":"Hãy đánh dấu các chi tiết trước khi tháo rời để lắp lại đúng vị trí.","syn_en":["teardown","dismantling"],"syn_ja":["ばらし (khẩu ngữ)","解体 (cho kết cấu lớn)"]},{"en":"tighten","pos":"verb","ipa":"/ˈtaɪtn/","ja":"締め付ける","kana":"しめつける","romaji":"shimetsukeru","vi":"siết chặt","level":1,"def_vi":"Vặn bu lông, đai ốc hoặc vít để tạo lực kẹp giữa các chi tiết được ghép.","def_en":"To turn a bolt, nut or screw so that it clamps the joined parts together.","def_ja":"ボルト・ナット・ねじを回して、部品同士を締結力で固定すること。","usage_en":"Ngoại động từ: tighten a bolt to 25 N·m, tighten in a cross pattern; trái nghĩa loosen. Không nói 'tight the bolt'.","usage_ja":"Danh từ 締付け (しめつけ); hay gặp 締付けトルク, 仮締め, 本締め. Khẩu ngữ ngắn gọn: 締める.","context_vi":"Dùng ở mọi trạm lắp ráp mối ghép ren, trong hướng dẫn lắp và bảo trì.","ex_en":"Tighten the cylinder head bolts in three stages to the specified torque.","ex_ja":"シリンダヘッドボルトを3段階で規定トルクまで締め付ける。","ex_vi":"Siết các bu lông nắp quy lát theo ba bước đến mô-men quy định.","syn_en":["fasten","torque up (khẩu ngữ)"],"syn_ja":["締める","締結する"]},{"en":"torque wrench","pos":"noun phrase","ipa":"/ˈtɔːk rentʃ/","ja":"トルクレンチ","kana":"トルクレンチ","romaji":"torukurenchi","vi":"cờ lê lực","level":1,"def_vi":"Cờ lê có cơ cấu đặt hoặc hiển thị mô-men xoắn, dùng để siết bu lông đúng giá trị quy định.","def_en":"A wrench that sets or indicates torque so that fasteners can be tightened to a specified value.","def_ja":"トルク値を設定または表示でき、ねじを規定値で締め付けるためのレンチ。","usage_en":"Danh từ đếm được. Hay đi với: click-type torque wrench, set / calibrate a torque wrench, torque wrench set to 40 N·m.","usage_ja":"Phân loại: プレセット形 (loại click), ダイヤル形, デジタル形. Động từ: トルクレンチで締める, 校正する.","context_vi":"Dùng ở trạm lắp ráp quan trọng (bánh xe, nắp máy), trong bảo trì và khi kiểm tra lại mô-men siết.","ex_en":"Use a click-type torque wrench for the wheel nuts.","ex_ja":"ホイールナットにはプレセット形トルクレンチを使う。","ex_vi":"Dùng cờ lê lực loại có tiếng click cho đai ốc bánh xe.","syn_en":["torque spanner (Anh)"],"syn_ja":["トルクスパナ","トルクドライバ (liên quan)"]},{"en":"electric screwdriver","pos":"noun phrase","ipa":"/ɪˌlektrɪk ˈskruːdraɪvə/","ja":"電動ドライバ","kana":"でんどうドライバ","romaji":"dendoudoraiba","vi":"tua vít điện","level":1,"def_vi":"Dụng cụ cầm tay chạy điện để vặn vít, thường có ly hợp tự ngắt khi đạt mô-men cài đặt.","def_en":"A powered hand tool for driving screws, usually with a clutch that slips at a preset torque.","def_ja":"ねじを締める電動の手工具で、設定トルクで止まるクラッチを備えることが多い。","usage_en":"Danh từ đếm được. Hay đi với: cordless electric screwdriver, torque-controlled electric screwdriver; còn gọi 'power screwdriver'.","usage_ja":"Viết 電動ドライバー hoặc 電動ドライバ đều gặp. Hay đi với トルク設定, バランサで吊る.","context_vi":"Dùng ở dây chuyền lắp điện tử, đồ gia dụng, nơi phải vặn nhiều vít nhỏ.","ex_en":"Each station has an electric screwdriver hung from a spring balancer.","ex_ja":"各工程にはバランサで吊った電動ドライバが備えてある。","ex_vi":"Mỗi trạm có một tua vít điện treo trên bộ cân bằng lò xo.","syn_en":["power screwdriver","electric driver"],"syn_ja":["電動ドライバー","ナットランナ (liên quan)"]},{"en":"shim","pos":"noun","ipa":"/ʃɪm/","ja":"シム","kana":"シム","romaji":"shimu","vi":"căn đệm (miếng chêm)","level":2,"def_vi":"Tấm mỏng có chiều dày chính xác, chèn vào giữa các chi tiết để bù khe hở hoặc chỉnh vị trí.","def_en":"A thin piece of precise thickness inserted between parts to take up a gap or adjust position.","def_ja":"部品の間に挟み、すき間の調整や位置合わせに使う、厚さが正確な薄板。","usage_en":"Danh từ đếm được và cũng là động từ: shim the motor base, add / remove shims, shim pack.","usage_ja":"Hay đi với シムを入れる, シム調整, シム厚. Văn bản đôi khi viết 調整板 hoặc ライナー.","context_vi":"Dùng khi lắp ổ trục, căn chỉnh động cơ với bơm, chỉnh khe hở bánh răng côn.","ex_en":"Add a 0.10 mm shim under the motor foot to correct the height.","ex_ja":"高さを修正するため、モータの足の下に0.10 mmのシムを入れる。","ex_vi":"Chèn một miếng căn đệm 0,10 mm dưới chân động cơ để chỉnh chiều cao.","syn_en":["spacer (gần nghĩa)","packing (khẩu ngữ)"],"syn_ja":["調整板","ライナー"]},{"en":"press-fitting","pos":"noun","ipa":"/ˈpres ˌfɪtɪŋ/","ja":"圧入","kana":"あつにゅう","romaji":"atsunyuu","vi":"ép lắp (lắp ép)","level":2,"def_vi":"Lắp hai chi tiết có độ dôi bằng cách dùng lực ép đẩy trục vào lỗ ở nhiệt độ thường.","def_en":"Joining parts with an interference fit by forcing the shaft into the hole at room temperature.","def_ja":"しめしろのある部品同士を、常温で軸を穴に押し込んで結合すること。","usage_en":"Danh từ không đếm được; động từ là press-fit hoặc press in. Hay đi với: press-fitting force, press-fitting a bearing onto a shaft.","usage_ja":"Động từ 圧入する; hay gặp 圧入荷重, 圧入機, ベアリングを圧入する.","context_vi":"Dùng khi lắp ổ bi, bạc lót, chốt, bánh răng lên trục trong lắp ráp động cơ, hộp số.","ex_en":"Press-fitting the bearing onto the shaft by pushing the outer ring will damage the raceways.","ex_ja":"外輪を押して玉軸受を軸に圧入すると、軌道面を傷める。","ex_vi":"Ép lắp ổ bi lên trục bằng cách đẩy vào vòng ngoài sẽ làm hỏng rãnh lăn.","syn_en":["press fit","pressing in"],"syn_ja":["押込み","プレスフィット"]},{"en":"shrink fitting","pos":"noun phrase","ipa":"/ˈʃrɪŋk ˌfɪtɪŋ/","ja":"焼きばめ","kana":"やきばめ","romaji":"yakibame","vi":"lắp nóng (lắp ghép bằng nung nóng)","level":2,"def_vi":"Nung nóng chi tiết có lỗ cho giãn nở rồi lồng vào trục; khi nguội lỗ co lại tạo mối ghép chặt.","def_en":"Heating the outer part so its bore expands, fitting it over the shaft, and letting it cool to grip tightly.","def_ja":"穴側部品を加熱して膨張させて軸にはめ、冷えて縮むことで強く固定する方法。","usage_en":"Danh từ không đếm được; động từ shrink-fit. Hay đi với: shrink fitting a gear onto a shaft, induction heater for shrink fitting.","usage_ja":"Động từ 焼きばめする; viết 焼嵌め cũng gặp. Đối lập 冷やしばめ. Hay đi với 誘導加熱, 焼きばめ代.","context_vi":"Dùng lắp bánh răng lớn, moay ơ khớp nối, vành bánh xe lửa, đầu kẹp dao lắp nóng.","ex_en":"The coupling hub was heated to 180 °C for shrink fitting.","ex_ja":"焼きばめのため、カップリングのハブを180 °Cまで加熱した。","ex_vi":"Moay ơ khớp nối được nung đến 180 °C để lắp nóng.","syn_en":["shrink fit","heat fitting"],"syn_ja":["焼嵌め","加熱ばめ"]},{"en":"alignment","pos":"noun","ipa":"/əˈlaɪnmənt/","ja":"芯出し","kana":"しんだし","romaji":"shindashi","vi":"căn chỉnh đồng tâm (căn tâm)","level":2,"def_vi":"Điều chỉnh vị trí các trục hoặc chi tiết sao cho đường tâm của chúng trùng nhau trong giới hạn cho phép.","def_en":"Adjusting shafts or parts so that their centrelines coincide within the permitted tolerance.","def_ja":"軸や部品の中心線が許容範囲内で一致するように位置を調整すること。","usage_en":"Danh từ không đếm được. Hay đi với: shaft alignment, laser alignment, check / correct alignment; lệch tâm là misalignment.","usage_ja":"Động từ 芯出しする; viết 心出し cũng đúng. Hay gặp 芯出し作業, レーザー芯出し, 芯ずれ (lệch tâm).","context_vi":"Dùng khi lắp động cơ với bơm, quạt, hộp số qua khớp nối và khi lắp các cụm chính xác.","ex_en":"Laser alignment of the pump and motor reduced bearing vibration by half.","ex_ja":"ポンプとモータのレーザー芯出しで、軸受の振動が半分になった。","ex_vi":"Căn tâm bằng laser giữa bơm và động cơ đã giảm rung ổ trục xuống một nửa.","syn_en":["centring","shaft alignment"],"syn_ja":["心出し","アライメント"]},{"en":"tightening sequence","pos":"noun phrase","ipa":"/ˈtaɪtnɪŋ ˌsiːkwəns/","ja":"締付け順序","kana":"しめつけじゅんじょ","romaji":"shimetsukejunjo","vi":"trình tự siết","level":2,"def_vi":"Thứ tự quy định khi siết một nhóm bu lông, thường theo hình chéo hoặc hình sao, để lực kẹp phân bố đều.","def_en":"The specified order for tightening a group of bolts, often criss-cross, so that clamping force is even.","def_ja":"締付け力が均一になるよう、複数のボルトを対角などの決められた順で締める順番。","usage_en":"Danh từ đếm được. Hay đi với: follow the tightening sequence, star / criss-cross tightening sequence; gần nghĩa 'tightening pattern'.","usage_ja":"Hay đi với 締付け順序を守る, 対角締め, 仮締めから本締めへ.","context_vi":"Dùng khi lắp mặt bích, nắp quy lát, nắp hộp số có gioăng.","ex_en":"Follow the tightening sequence shown on the drawing to avoid flange distortion.","ex_ja":"フランジのひずみを防ぐため、図面に示す締付け順序を守ること。","ex_vi":"Tuân theo trình tự siết ghi trên bản vẽ để tránh cong vênh mặt bích.","syn_en":["tightening pattern","bolt-up sequence"],"syn_ja":["締付け手順","対角締め (liên quan)"]},{"en":"match mark","pos":"noun phrase","ipa":"/ˈmætʃ mɑːk/","ja":"合いマーク","kana":"あいマーク","romaji":"aimaaku","vi":"dấu khớp (dấu định vị, dấu siết)","level":2,"def_vi":"Vạch sơn hoặc dấu đột vắt qua hai chi tiết, dùng để lắp lại đúng vị trí hoặc phát hiện bu lông bị xoay lỏng.","def_en":"A paint line or punch mark across two parts, used to restore their position or show whether a fastener has turned.","def_ja":"二つの部品にまたがって付ける線や刻印で、再組立の位置合わせやねじの緩み確認に使う。","usage_en":"Danh từ đếm được. Hay đi với: apply / align match marks; vạch sơn sau khi siết đủ lực còn gọi 'torque mark' hoặc 'torque stripe'.","usage_ja":"Hay đi với 合いマークを付ける, 合いマークがずれる; vạch sau khi siết lực gọi マーキング hoặc トルクマーク.","context_vi":"Dùng sau khi siết bu lông quan trọng để kiểm tra bằng mắt, và trước khi tháo để lắp lại đúng chiều.","ex_en":"The inspector found a nut whose match mark had shifted by 15 degrees.","ex_ja":"検査員は合いマークが15度ずれたナットを見つけた。","ex_vi":"Nhân viên kiểm tra phát hiện một đai ốc có dấu khớp bị lệch 15 độ.","syn_en":["torque mark","witness mark"],"syn_ja":["マーキング","トルクマーク"]},{"en":"snap fit","pos":"noun phrase","ipa":"/ˈsnæp fɪt/","ja":"スナップフィット","kana":"スナップフィット","romaji":"sunappufitto","vi":"khớp gài (ngàm bấm)","level":2,"def_vi":"Kiểu ghép trong đó móc đàn hồi trên chi tiết nhựa uốn cong rồi bật vào rãnh, giữ chi tiết mà không cần vít.","def_en":"A joint in which a flexible hook deflects and springs into a recess, holding parts together without screws.","def_ja":"弾性のある爪がたわんで相手の穴や段に掛かり、ねじなしで部品を固定する結合。","usage_en":"Danh từ đếm được; khi làm tính từ viết snap-fit (snap-fit cover). Hay đi với: design / engage a snap fit, cantilever snap fit.","usage_ja":"Ngoài xưởng hay gọi ツメ (cái móc), パチンとはめる; văn bản dùng スナップフィット構造.","context_vi":"Dùng trong vỏ nhựa đồ điện tử, chi tiết nội thất ô tô, đồ gia dụng để lắp nhanh và giảm số vít.","ex_en":"Replacing four screws with a snap fit cut assembly time by 12 seconds.","ex_ja":"ねじ4本をスナップフィットに置き換え、組立時間を12秒短縮した。","ex_vi":"Thay bốn con vít bằng khớp gài đã giảm 12 giây thời gian lắp.","syn_en":["snap joint","clip fit"],"syn_ja":["ツメ (khẩu ngữ)","スナップ結合"]},{"en":"staking","pos":"noun","ipa":"/ˈsteɪkɪŋ/","ja":"かしめ","kana":"かしめ","romaji":"kashime","vi":"tán dập (ghép bằng biến dạng dẻo)","level":2,"def_vi":"Ghép cố định bằng cách làm biến dạng dẻo một phần chi tiết (gờ, chốt) để giữ chặt chi tiết kia.","def_en":"Fixing parts by plastically deforming a feature such as a lip or pin so that it locks the mating part.","def_ja":"部品の一部（縁やピン）を塑性変形させ、相手部品を固定する結合方法。","usage_en":"Danh từ không đếm được; động từ stake. Hay đi với: heat staking (cho nhựa), orbital staking, stake a bearing into a housing.","usage_ja":"Động từ かしめる; kanji 加締め ít dùng. Hay gặp かしめ加工, 熱かしめ, 揺動かしめ.","context_vi":"Dùng giữ ổ bi trong vỏ, ghép cực điện, cố định chốt nhựa vào bảng mạch, lắp chi tiết ô tô.","ex_en":"Orbital staking holds the bearing in the housing without a circlip.","ex_ja":"揺動かしめにより、止め輪なしで軸受をハウジングに固定している。","ex_vi":"Phương pháp tán dập xoay giữ ổ bi trong vỏ mà không cần phanh hãm.","syn_en":["swaging (gần nghĩa)","clinching (gần nghĩa)"],"syn_ja":["加締め","かしめ加工"]},{"en":"nutrunner","pos":"noun","ipa":"/ˈnʌtˌrʌnə/","ja":"ナットランナ","kana":"ナットランナ","romaji":"nattoranna","vi":"máy siết bu lông (nutrunner)","level":2,"def_vi":"Dụng cụ siết chạy điện hoặc khí nén có điều khiển và ghi lại mô-men, góc siết, dùng trên dây chuyền lắp ráp.","def_en":"A powered tightening tool that controls and records torque and angle on an assembly line.","def_ja":"締付けトルクや角度を制御・記録できる、組立ライン用の電動または空圧の締付け機。","usage_en":"Danh từ đếm được, thường viết liền. Hay đi với: DC nutrunner, multi-spindle nutrunner, nutrunner controller.","usage_ja":"Viết ナットランナー cũng phổ biến. Hay đi với 多軸ナットランナ, 締付けデータ, NG判定.","context_vi":"Dùng ở dây chuyền ô tô, xe máy để siết bu lông quan trọng và lưu dữ liệu phục vụ truy xuất.","ex_en":"A five-spindle nutrunner tightens all the hub bolts at once.","ex_ja":"5軸ナットランナでハブボルトを一度に締め付ける。","ex_vi":"Máy siết 5 đầu siết đồng thời toàn bộ bu lông moay ơ.","syn_en":["power tightening tool","DC tool (khẩu ngữ)"],"syn_ja":["ナットランナー","締付け機"]},{"en":"parts feeder","pos":"noun phrase","ipa":"/ˈpɑːts ˌfiːdə/","ja":"パーツフィーダ","kana":"パーツフィーダ","romaji":"paatsufiida","vi":"máy cấp linh kiện tự động","level":2,"def_vi":"Thiết bị rung hoặc cơ khí sắp xếp và cấp từng chi tiết nhỏ đúng hướng cho máy lắp ráp hoặc robot.","def_en":"A vibratory or mechanical device that orients small parts and feeds them one by one to an assembly machine.","def_ja":"小物部品を振動などで整列させ、一つずつ組立機やロボットへ供給する装置。","usage_en":"Danh từ đếm được. Hay đi với: vibratory bowl feeder, parts feeder jam, tooling of a parts feeder.","usage_ja":"Viết パーツフィーダー cũng gặp; loại bát rung gọi ボウルフィーダ. Hay đi với 詰まり, 整列.","context_vi":"Dùng cấp vít, đai ốc, chốt, linh kiện nhựa cho máy lắp tự động và robot.","ex_en":"The parts feeder jams when burrs are left on the pins.","ex_ja":"ピンにバリが残っていると、パーツフィーダが詰まる。","ex_vi":"Máy cấp linh kiện bị kẹt khi chốt còn ba via.","syn_en":["bowl feeder","vibratory feeder"],"syn_ja":["ボウルフィーダ","部品供給機"]},{"en":"mating surface","pos":"noun phrase","ipa":"/ˈmeɪtɪŋ ˌsɜːfɪs/","ja":"合わせ面","kana":"あわせめん","romaji":"awasemen","vi":"bề mặt lắp ghép (mặt tiếp xúc)","level":2,"def_vi":"Bề mặt của chi tiết tiếp xúc trực tiếp với bề mặt chi tiết khác sau khi lắp ráp.","def_en":"The surface of a part that is in direct contact with another part after assembly.","def_ja":"組立後に他の部品と直接接触する部品の面。","usage_en":"Danh từ đếm được. Hay đi với: clean / inspect the mating surfaces, mating surface flatness; chi tiết đối tiếp là 'mating part'.","usage_ja":"Hay đi với 合わせ面の清掃, 合わせ面に液状ガスケットを塗る; chi tiết đối tiếp gọi 相手部品.","context_vi":"Dùng khi lắp nắp, mặt bích, vỏ hộp số, nơi bề mặt phải sạch, phẳng và kín.","ex_en":"Clean the mating surfaces before applying liquid gasket.","ex_ja":"液状ガスケットを塗る前に、合わせ面を清掃する。","ex_vi":"Làm sạch bề mặt lắp ghép trước khi bôi gioăng lỏng.","syn_en":["mating face","contact surface"],"syn_ja":["合せ面","接触面"]},{"en":"foreign matter","pos":"noun phrase","ipa":"/ˌfɒrən ˈmætə/","ja":"異物","kana":"いぶつ","romaji":"ibutsu","vi":"dị vật","level":2,"def_vi":"Vật lạ như phoi, bụi, sợi vải lọt vào sản phẩm trong lúc lắp ráp, có thể gây hỏng hoặc lỗi chức năng.","def_en":"Unwanted material such as chips, dust or fibres that enters a product during assembly and may cause failure.","def_ja":"組立中に製品へ入り込み、故障や機能不良の原因となる切粉・ほこり・繊維などの物。","usage_en":"Danh từ không đếm được. Hay đi với: foreign matter contamination, remove foreign matter; dạng đếm được là 'foreign object' (FOD trong hàng không).","usage_ja":"Hay gặp 異物混入, 異物噛み込み, 異物除去; là từ rất hay dùng trong báo cáo lỗi ở nhà máy Nhật.","context_vi":"Dùng trong lắp ráp hệ thủy lực, hộp số, linh kiện điện tử và trong báo cáo khiếu nại khách hàng.","ex_en":"Foreign matter in the valve body caused the spool to stick.","ex_ja":"バルブボディ内の異物により、スプールが固着した。","ex_vi":"Dị vật trong thân van đã làm con trượt bị kẹt.","syn_en":["foreign object","contamination (gần nghĩa)"],"syn_ja":["コンタミ (khẩu ngữ)","異物混入 (liên quan)"]},{"en":"automatic assembly","pos":"noun phrase","ipa":"/ˌɔːtəˈmætɪk əˈsembli/","ja":"自動組立","kana":"じどうくみたて","romaji":"jidoukumitate","vi":"lắp ráp tự động","level":2,"def_vi":"Lắp ráp bằng máy chuyên dùng hoặc robot, tự cấp chi tiết, ghép và kiểm tra mà ít cần người thao tác.","def_en":"Assembly performed by dedicated machines or robots that feed, join and check parts with little human input.","def_ja":"専用機やロボットが部品の供給・組付け・検査を行い、人手をほとんど要しない組立。","usage_en":"Danh từ không đếm được. Hay đi với: automatic assembly machine / line; cũng nói 'automated assembly'.","usage_ja":"Hay gặp 自動組立機, 自動組立ライン; ngoài xưởng gọi máy lắp tự động là 自動機.","context_vi":"Dùng khi sản lượng lớn, chi tiết nhỏ và đồng đều như ổ bi, van, công tắc, linh kiện điện tử.","ex_en":"The switch housings move to automatic assembly once volume exceeds 50,000 units per month.","ex_ja":"月産5万個を超えたら、スイッチケースは自動組立に切り替える。","ex_vi":"Khi sản lượng vượt 50.000 chiếc mỗi tháng, vỏ công tắc sẽ chuyển sang lắp ráp tự động.","syn_en":["automated assembly"],"syn_ja":["自動機組立","ロボット組立 (liên quan)"]},{"en":"selective assembly","pos":"noun phrase","ipa":"/sɪˌlektɪv əˈsembli/","ja":"選択組立","kana":"せんたくくみたて","romaji":"sentakukumitate","vi":"lắp chọn (lắp ráp chọn lọc)","level":3,"def_vi":"Phân nhóm chi tiết theo kích thước thực rồi lắp các nhóm tương ứng với nhau để đạt khe hở chính xác hơn dung sai gia công.","def_en":"Sorting parts by measured size into groups and pairing matching groups to achieve tighter fits than machining allows.","def_ja":"部品を実寸で層別し、対応する群同士を組み合わせて加工公差より精密なはめあいを得る方法。","usage_en":"Danh từ không đếm được. Hay đi với: use selective assembly, selective assembly groups / classes; đối lập 'interchangeable assembly'.","usage_ja":"Còn gọi 選択組合せ; ngoài xưởng nói ランク分けして組む, 層別して組む.","context_vi":"Dùng cho cặp piston – xi lanh, ổ bi, bơm cao áp, nơi khe hở yêu cầu rất nhỏ.","ex_en":"Selective assembly is used to pair pistons and bores in three size classes.","ex_ja":"ピストンとシリンダ穴は、3ランクに分けた選択組立で組み合わせている。","ex_vi":"Phương pháp lắp chọn được dùng để ghép piston và lỗ xi lanh theo ba nhóm kích thước.","syn_en":["matched assembly","grade matching (gần nghĩa)"],"syn_ja":["選択組合せ","ランク組み (khẩu ngữ)"]},{"en":"interchangeability","pos":"noun","ipa":"/ˌɪntəˌtʃeɪndʒəˈbɪləti/","ja":"互換性","kana":"ごかんせい","romaji":"gokansei","vi":"tính lắp lẫn","level":3,"def_vi":"Tính chất cho phép bất kỳ chi tiết cùng loại nào cũng lắp được vào vị trí mà không cần chọn lựa hay sửa nguội.","def_en":"The property that any part of a given type fits its place in an assembly without selection or rework.","def_ja":"同じ種類のどの部品でも、選別や手直しなしに組み付けられる性質。","usage_en":"Danh từ không đếm được. Hay đi với: full / partial interchangeability, ensure interchangeability; tính từ là interchangeable.","usage_ja":"Hay đi với 互換性がある, 互換性を確保する, 完全互換性. Phương pháp lắp tương ứng gọi 互換性組立.","context_vi":"Là nền tảng của sản xuất hàng loạt và phụ tùng thay thế; dùng khi đặt dung sai và lập tiêu chuẩn.","ex_en":"Tighter tolerances were set to guarantee interchangeability of spare parts.","ex_ja":"補修部品の互換性を保証するため、公差を厳しくした。","ex_vi":"Dung sai được siết chặt hơn để bảo đảm tính lắp lẫn của phụ tùng thay thế.","syn_en":["interchangeable manufacture (liên quan)"],"syn_ja":["互換性組立 (liên quan)"]},{"en":"design for assembly","pos":"noun phrase","ipa":"/dɪˌzaɪn fər əˈsembli/","ja":"組立容易性設計","kana":"くみたてよういせいせっけい","romaji":"kumitateyouiseisekkei","vi":"thiết kế hướng lắp ráp (DFA)","level":3,"def_vi":"Phương pháp thiết kế nhằm giảm số chi tiết và làm thao tác lắp dễ, nhanh, khó nhầm lẫn.","def_en":"A design approach that reduces part count and makes assembly operations easy, fast and error-resistant.","def_ja":"部品点数を減らし、組立作業を容易・迅速で間違えにくくする設計手法。","usage_en":"Viết tắt DFA; dùng như danh từ không đếm được: apply design for assembly, DFA review, DFA analysis.","usage_ja":"Ngoài xưởng hay nói 組立性 (組立性が良い / 悪い) hoặc DFA; trong review thiết kế: 組立性検討.","context_vi":"Dùng trong giai đoạn thiết kế sản phẩm và review thiết kế, phối hợp giữa kỹ sư thiết kế và kỹ sư sản xuất.","ex_en":"Design for assembly cut the bracket from seven parts to two.","ex_ja":"組立容易性設計により、ブラケットの部品点数を7点から2点に減らした。","ex_vi":"Thiết kế hướng lắp ráp đã giảm giá đỡ từ bảy chi tiết xuống còn hai.","syn_en":["DFA","DFMA (nghĩa rộng hơn)"],"syn_ja":["DFA","組立性設計"]},{"en":"expansion fitting","pos":"noun phrase","ipa":"/ɪkˈspænʃn ˌfɪtɪŋ/","ja":"冷やしばめ","kana":"ひやしばめ","romaji":"hiyashibame","vi":"lắp lạnh (lắp ghép bằng làm lạnh)","level":3,"def_vi":"Làm lạnh chi tiết trục bằng nitơ lỏng hoặc đá khô cho co lại, lồng vào lỗ; khi ấm lên trục nở ra tạo độ dôi.","def_en":"Cooling the inner part, e.g. with liquid nitrogen, so that it shrinks to enter the bore and grips as it warms.","def_ja":"液体窒素などで軸側を冷やして縮ませ、穴にはめて常温に戻ると締まる結合法。","usage_en":"Danh từ không đếm được; còn gọi 'freeze fitting'. Hay đi với: expansion fitting with liquid nitrogen; đối lập shrink fitting.","usage_ja":"Viết 冷し嵌め cũng gặp; đối lập 焼きばめ. Hay đi với 液体窒素, ドライアイス, 冷却.","context_vi":"Dùng khi chi tiết ngoài lớn hoặc không được nung (như vỏ đã lắp ổ bi), trong chế tạo máy nặng.","ex_en":"Expansion fitting with liquid nitrogen was chosen because the housing could not be heated.","ex_ja":"ハウジングを加熱できないため、液体窒素による冷やしばめを採用した。","ex_vi":"Phương pháp lắp lạnh bằng nitơ lỏng được chọn vì vỏ không thể nung nóng.","syn_en":["freeze fitting","cryogenic fitting"],"syn_ja":["冷し嵌め","焼きばめ (liên quan)"]},{"en":"component cleanliness","pos":"noun phrase","ipa":"/kəmˈpəʊnənt ˈklenlinəs/","ja":"部品清浄度","kana":"ぶひんせいじょうど","romaji":"buhinseijoudo","vi":"độ sạch chi tiết","level":3,"def_vi":"Mức độ nhiễm bẩn hạt còn lại trên chi tiết, đánh giá bằng khối lượng và kích thước hạt sau khi rửa chiết.","def_en":"The level of residual particle contamination on a part, measured by the amount and size of extracted particles.","def_ja":"部品に残留する粒子汚染の程度で、抽出した粒子の量と大きさで評価する。","usage_en":"Danh từ không đếm được. Hay đi với: component cleanliness requirement / analysis, cleanliness testing to ISO 16232 or VDA 19.","usage_ja":"Hay gặp 清浄度管理, 清浄度測定, コンタミ量; tiêu chuẩn tham chiếu ISO 16232, VDA 19.","context_vi":"Dùng trong ngành ô tô, thủy lực, hệ thống nhiên liệu, nơi hạt bẩn nhỏ có thể gây kẹt van hoặc mòn.","ex_en":"The customer specifies component cleanliness of less than 2 mg per part.","ex_ja":"顧客は部品清浄度として1個あたり2 mg未満を要求している。","ex_vi":"Khách hàng yêu cầu độ sạch chi tiết dưới 2 mg cho mỗi chi tiết.","syn_en":["technical cleanliness","particle contamination level"],"syn_ja":["清浄度","コンタミ管理 (liên quan)"]},{"en":"assembly accuracy","pos":"noun phrase","ipa":"/əˈsembli ˈækjərəsi/","ja":"組立精度","kana":"くみたてせいど","romaji":"kumitateseido","vi":"độ chính xác lắp ráp","level":3,"def_vi":"Mức độ vị trí, độ song song, độ đồng tâm giữa các chi tiết sau khi lắp đạt yêu cầu thiết kế.","def_en":"How closely the position, parallelism and concentricity of parts after assembly meet the design requirements.","def_ja":"組立後の部品の位置・平行度・同軸度などが設計要求をどれだけ満たしているかの度合い。","usage_en":"Danh từ không đếm được. Hay đi với: improve / verify assembly accuracy, high assembly accuracy; phân biệt với 'machining accuracy'.","usage_ja":"Hay đi với 組立精度を出す, 組立精度が悪い; đối chiếu với 加工精度.","context_vi":"Dùng khi lắp máy công cụ, robot, khuôn, thiết bị quang học yêu cầu căn chỉnh chính xác.","ex_en":"Scraping the slideways improved the assembly accuracy of the machine.","ex_ja":"摺動面のきさげ加工で、機械の組立精度が向上した。","ex_vi":"Việc cạo rà mặt trượt đã nâng cao độ chính xác lắp ráp của máy.","syn_en":["build accuracy","alignment accuracy (gần nghĩa)"],"syn_ja":["組付け精度","加工精度 (liên quan)"]}]},{"id":47,"words":[{"en":"production control","pos":"noun phrase","ipa":"/prəˈdʌkʃn kənˈtrəʊl/","ja":"生産管理","kana":"せいさんかんり","romaji":"seisankanri","vi":"quản lý sản xuất","level":1,"def_vi":"Hoạt động lập kế hoạch, điều phối và theo dõi sản xuất để làm ra đúng sản phẩm, đúng số lượng, đúng hạn với chi phí hợp lý.","def_en":"Planning, coordinating and monitoring production so the right products are made in the right quantity, on time and at reasonable cost.","def_ja":"必要な製品を必要な量だけ、納期どおり適正な費用で作るため、生産を計画・調整・監視する活動。","usage_en":"Danh từ không đếm được. Hay đi với: production control department, production planning and control (PPC); không thêm 's'.","usage_ja":"Vừa chỉ hoạt động vừa chỉ phòng ban: 生産管理課, 生産管理部. Hay đi với 生産管理システム, 生産管理担当.","context_vi":"Dùng ở mọi nhà máy, chỉ bộ phận lập kế hoạch, điều độ, theo dõi tiến độ và vật tư.","ex_en":"Production control releases the weekly plan to each section every Friday.","ex_ja":"生産管理は毎週金曜日に各課へ週間計画を出す。","ex_vi":"Bộ phận quản lý sản xuất phát hành kế hoạch tuần cho từng tổ vào mỗi thứ Sáu.","syn_en":["production planning and control (PPC)","production management"],"syn_ja":["工程管理 (gần nghĩa)","生産計画 (liên quan)"]},{"en":"production plan","pos":"noun phrase","ipa":"/prəˈdʌkʃn plæn/","ja":"生産計画","kana":"せいさんけいかく","romaji":"seisankeikaku","vi":"kế hoạch sản xuất","level":1,"def_vi":"Bản xác định sẽ sản xuất sản phẩm nào, số lượng bao nhiêu và trong khoảng thời gian nào.","def_en":"A statement of which products will be made, in what quantities, and over what period.","def_ja":"どの製品を、いくつ、いつまでに作るかを定めた計画。","usage_en":"Danh từ đếm được. Hay đi với: monthly / weekly production plan, draw up / revise / release a production plan.","usage_ja":"Hay đi với 生産計画を立てる, 生産計画を変更する; theo cấp độ: 大日程, 中日程, 小日程計画.","context_vi":"Dùng trong cuộc họp sản xuất, bảng kế hoạch tháng, tuần và khi phối hợp với kinh doanh, mua hàng.","ex_en":"The production plan was revised after the customer doubled its order.","ex_ja":"顧客が注文を倍にしたため、生産計画を見直した。","ex_vi":"Kế hoạch sản xuất đã được điều chỉnh sau khi khách hàng tăng gấp đôi đơn hàng.","syn_en":["production schedule (gần nghĩa)","build plan"],"syn_ja":["生産予定","製造計画"]},{"en":"due date","pos":"noun phrase","ipa":"/ˈdjuː deɪt/","ja":"納期","kana":"のうき","romaji":"nouki","vi":"hạn giao hàng","level":1,"def_vi":"Ngày mà sản phẩm hoặc hàng hóa phải được hoàn thành và giao cho khách hàng hoặc công đoạn sau.","def_en":"The date by which products must be completed and delivered to the customer or next process.","def_ja":"製品を完成させ、顧客や後工程に引き渡さなければならない期日。","usage_en":"Danh từ đếm được. Hay đi với: meet / miss a due date, delivery due date; gần nghĩa 'delivery date', 'deadline'.","usage_ja":"Từ cực kỳ phổ biến: 納期を守る, 納期遅れ, 納期回答, 短納期. Không dùng katakana.","context_vi":"Dùng khi nhận đơn hàng, lập kế hoạch, đàm phán với khách hàng và nhà cung cấp.","ex_en":"We will miss the due date unless the second shift runs on Saturday.","ex_ja":"土曜日に2直を稼働させないと納期に間に合わない。","ex_vi":"Chúng ta sẽ trễ hạn giao hàng nếu ca hai không chạy vào thứ Bảy.","syn_en":["delivery date","deadline (nghĩa rộng hơn)"],"syn_ja":["納入期日","デリバリー (liên quan)"]},{"en":"lead time","pos":"noun phrase","ipa":"/ˈliːd taɪm/","ja":"リードタイム","kana":"リードタイム","romaji":"riidotaimu","vi":"thời gian sản xuất (lead time)","level":1,"def_vi":"Khoảng thời gian từ khi nhận đơn hoặc bắt đầu công việc đến khi sản phẩm hoàn thành hoặc được giao.","def_en":"The time from receiving an order or starting work until the product is finished or delivered.","def_ja":"受注または着手から、製品の完成または納入までにかかる時間。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: reduce / shorten lead time, manufacturing lead time, supplier lead time.","usage_ja":"Hay đi với リードタイム短縮, 製造リードタイム, 調達リードタイム; viết tắt LT trên bảng biểu.","context_vi":"Dùng khi báo giá, cam kết hạn giao, đặt mua vật tư và cải tiến dòng chảy sản xuất.","ex_en":"The lead time for cast housings is six weeks.","ex_ja":"鋳物ハウジングのリードタイムは6週間である。","ex_vi":"Thời gian sản xuất vỏ đúc là sáu tuần.","syn_en":["throughput time (gần nghĩa)","turnaround time"],"syn_ja":["LT","所要期間"]},{"en":"lot","pos":"noun","ipa":"/lɒt/","ja":"ロット","kana":"ロット","romaji":"rotto","vi":"lô sản xuất","level":1,"def_vi":"Một nhóm sản phẩm cùng loại được sản xuất liên tục trong cùng điều kiện và quản lý chung một mã số.","def_en":"A quantity of identical products made together under the same conditions and tracked under one number.","def_ja":"同じ条件でまとめて生産され、一つの番号で管理される同一製品の集まり。","usage_en":"Danh từ đếm được. Hay đi với: lot number, lot size, production lot, in lots of 500; gần nghĩa 'batch'.","usage_ja":"Hay đi với ロット番号, ロットサイズ, ロットアウト (lô bị loại), 小ロット化.","context_vi":"Dùng khi lập kế hoạch, truy xuất nguồn gốc, kiểm tra chất lượng và ghi nhãn sản phẩm.","ex_en":"Every box is labelled with its lot number for traceability.","ex_ja":"トレーサビリティのため、すべての箱にロット番号を表示している。","ex_vi":"Mỗi thùng đều được dán nhãn số lô để truy xuất nguồn gốc.","syn_en":["batch"],"syn_ja":["バッチ","生産単位 (gần nghĩa)"]},{"en":"inventory","pos":"noun","ipa":"/ˈɪnvəntri/","ja":"在庫","kana":"ざいこ","romaji":"zaiko","vi":"tồn kho","level":1,"def_vi":"Lượng nguyên vật liệu, bán thành phẩm và thành phẩm đang được giữ trong kho hoặc trên dây chuyền.","def_en":"The materials, work-in-process and finished products held in stock or on the line.","def_ja":"倉庫やラインに保有している原材料・仕掛品・製品の量。","usage_en":"Danh từ không đếm được (Mỹ dùng nhiều). Hay đi với: reduce inventory, inventory level, take inventory; Anh hay nói 'stock'.","usage_ja":"Hay đi với 在庫を持つ, 在庫削減, 在庫切れ, 在庫数; kiểm kê gọi 棚卸し.","context_vi":"Dùng trong quản lý kho, họp sản xuất, báo cáo tài chính và cải tiến tinh gọn.","ex_en":"Raw material inventory was cut from three weeks to one.","ex_ja":"原材料の在庫を3週間分から1週間分に減らした。","ex_vi":"Tồn kho nguyên vật liệu đã giảm từ ba tuần xuống một tuần.","syn_en":["stock (Anh)"],"syn_ja":["ストック","在庫品"]},{"en":"work-in-process","pos":"noun","ipa":"/ˌwɜːk ɪn ˈprəʊses/","ja":"仕掛品","kana":"しかかりひん","romaji":"shikakarihin","vi":"bán thành phẩm (sản phẩm dở dang)","level":1,"def_vi":"Sản phẩm đã bắt đầu gia công nhưng chưa hoàn thành, đang nằm giữa các công đoạn.","def_en":"Products that have started processing but are not yet finished and sit between operations.","def_ja":"加工に着手したが未完成で、工程間に滞留している品物。","usage_en":"Danh từ không đếm được, viết tắt WIP; Anh hay nói 'work-in-progress'. Hay đi với: reduce WIP, WIP level, WIP between stations.","usage_ja":"Hay đi với 仕掛品を減らす, 工程間仕掛, 仕掛在庫; ngoài xưởng nói gọn 仕掛 (しかかり).","context_vi":"Dùng khi đánh giá dòng chảy sản xuất, kiểm kê và tính giá thành dở dang.","ex_en":"Too much work-in-process was piling up in front of the heat treatment furnace.","ex_ja":"熱処理炉の前に仕掛品が溜まりすぎていた。","ex_vi":"Quá nhiều bán thành phẩm đang ùn lại trước lò nhiệt luyện.","syn_en":["WIP","work-in-progress (Anh)"],"syn_ja":["仕掛在庫","仕掛 (khẩu ngữ)"]},{"en":"finished goods","pos":"noun phrase","ipa":"/ˌfɪnɪʃt ˈɡʊdz/","ja":"完成品","kana":"かんせいひん","romaji":"kanseihin","vi":"thành phẩm","level":1,"def_vi":"Sản phẩm đã qua mọi công đoạn và kiểm tra, sẵn sàng nhập kho hoặc giao cho khách hàng.","def_en":"Products that have passed all operations and inspection and are ready to store or ship.","def_ja":"すべての工程と検査を終え、入庫または出荷できる状態の製品。","usage_en":"Danh từ số nhiều, không đếm được theo từng cái. Hay đi với: finished goods inventory / warehouse, ship finished goods.","usage_ja":"Trong kế toán, kho gọi 製品 hoặc 製品在庫; 完成品 dùng nhiều ở xưởng. Hay đi với 完成品検査, 完成品倉庫.","context_vi":"Dùng trong quản lý kho, giao hàng và báo cáo tồn kho thành phẩm.","ex_en":"Finished goods are shipped within 24 hours of final inspection.","ex_ja":"完成品は最終検査から24時間以内に出荷される。","ex_vi":"Thành phẩm được xuất hàng trong vòng 24 giờ sau khi kiểm tra cuối.","syn_en":["end products","finished products"],"syn_ja":["製品","製品在庫 (liên quan)"]},{"en":"mass production","pos":"noun phrase","ipa":"/ˌmæs prəˈdʌkʃn/","ja":"量産","kana":"りょうさん","romaji":"ryousan","vi":"sản xuất hàng loạt","level":1,"def_vi":"Sản xuất liên tục một sản phẩm với số lượng lớn theo quy trình đã ổn định.","def_en":"Continuous production of a product in large quantities using a stable, established process.","def_ja":"確立した工程で、同じ製品を継続的に大量に生産すること。","usage_en":"Danh từ không đếm được. Hay đi với: start of mass production (SOP), go into mass production; tính từ mass-produced.","usage_ja":"量産 là từ hằng ngày ở xưởng: 量産開始, 量産移行, 量産品, 量産試作. 大量生産 dùng trong văn viết chung.","context_vi":"Dùng khi chuyển từ mẫu thử sang sản xuất chính thức, trong ô tô, điện tử, đồ gia dụng.","ex_en":"The new bracket goes into mass production in April.","ex_ja":"新しいブラケットは4月から量産に入る。","ex_vi":"Giá đỡ mới sẽ bắt đầu sản xuất hàng loạt từ tháng Tư.","syn_en":["volume production","series production"],"syn_ja":["大量生産","量産化 (liên quan)"]},{"en":"work order","pos":"noun phrase","ipa":"/ˈwɜːk ˌɔːdə/","ja":"製造指図書","kana":"せいぞうさしずしょ","romaji":"seizousashizusho","vi":"lệnh sản xuất","level":1,"def_vi":"Chứng từ chỉ thị sản xuất một sản phẩm cụ thể với số lượng, vật tư, công đoạn và thời hạn xác định.","def_en":"A document authorizing production of a specific item, stating quantity, materials, operations and dates.","def_ja":"特定の品目について、数量・材料・工程・期日を示して製造を指示する書類。","usage_en":"Danh từ đếm được. Hay đi với: issue / release / close a work order, work order number; còn gọi 'production order', 'job order'.","usage_ja":"Ngoài xưởng hay gọi 指示書, 作業指示書, 製造指示書; số lệnh gọi 製番 (せいばん) ở nhiều công ty.","context_vi":"Dùng khi phát lệnh xuống xưởng, xuất vật tư, theo dõi tiến độ và tính giá thành từng lệnh.","ex_en":"Material is issued from the warehouse only against a released work order.","ex_ja":"材料は、発行済みの製造指図書に基づいてのみ倉庫から出庫される。","ex_vi":"Vật tư chỉ được xuất kho khi có lệnh sản xuất đã phát hành.","syn_en":["production order","job order"],"syn_ja":["製造指示書","作業指示書"]},{"en":"man-hour","pos":"noun","ipa":"/ˈmæn aʊə/","ja":"工数","kana":"こうすう","romaji":"kousuu","vi":"giờ công","level":2,"def_vi":"Đơn vị khối lượng công việc bằng lượng việc một người làm trong một giờ, dùng để tính nhân lực và chi phí.","def_en":"A unit of work equal to one person working for one hour, used to estimate labour and cost.","def_ja":"一人が1時間に行う作業量を単位とした仕事量で、人員や原価の算定に使う。","usage_en":"Danh từ đếm được, hay dùng số nhiều: 120 man-hours, man-hours per unit; cách nói trung tính giới tính là 'labour hour' hoặc 'person-hour'.","usage_ja":"工数 rất thông dụng: 工数削減, 工数がかかる, 工数見積もり; đơn vị 人時, 人日, 人月.","context_vi":"Dùng khi báo giá, lập kế hoạch nhân lực, đánh giá hiệu quả cải tiến.","ex_en":"The new fixture saves 40 man-hours a month.","ex_ja":"新しい治具で月40時間の工数を削減できる。","ex_vi":"Đồ gá mới tiết kiệm 40 giờ công mỗi tháng.","syn_en":["labour hour","person-hour"],"syn_ja":["人時 (にんじ)","作業工数"]},{"en":"production capacity","pos":"noun phrase","ipa":"/prəˈdʌkʃn kəˈpæsəti/","ja":"生産能力","kana":"せいさんのうりょく","romaji":"seisannouryoku","vi":"năng lực sản xuất","level":2,"def_vi":"Sản lượng tối đa mà dây chuyền, máy hoặc nhà máy có thể làm ra trong một khoảng thời gian.","def_en":"The maximum output that a line, machine or plant can produce in a given period.","def_ja":"ライン・機械・工場が一定期間に生産できる最大の量。","usage_en":"Danh từ không đếm được. Hay đi với: increase / expand production capacity, run at full capacity, capacity of 10,000 units per month.","usage_ja":"Hay đi với 生産能力を増強する, 能力不足, 能力オーバー; ngoài xưởng nói gọn 能力 hoặc キャパ.","context_vi":"Dùng khi nhận đơn hàng mới, đầu tư thiết bị, lập kế hoạch tháng và cân đối tải.","ex_en":"The press line has a production capacity of 3,000 panels per shift.","ex_ja":"プレスラインの生産能力は1直あたり3,000枚である。","ex_vi":"Dây chuyền dập có năng lực sản xuất 3.000 tấm mỗi ca.","syn_en":["capacity","output capacity"],"syn_ja":["キャパ (khẩu ngữ)","能力"]},{"en":"workload","pos":"noun","ipa":"/ˈwɜːkləʊd/","ja":"負荷","kana":"ふか","romaji":"fuka","vi":"phụ tải (khối lượng công việc giao cho máy, tổ)","level":2,"def_vi":"Lượng công việc được giao cho một máy, tổ hoặc người trong một kỳ, so sánh với năng lực để cân đối.","def_en":"The amount of work assigned to a machine, team or person in a period, compared with capacity.","def_ja":"一定期間に機械・班・人に割り当てられた仕事量で、能力と比較して調整する。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: balance the workload, heavy workload, workload versus capacity.","usage_ja":"Trong quản lý sản xuất hay gặp 負荷工数, 負荷計画, 負荷山積み (biểu đồ chồng tải), 負荷平準化.","context_vi":"Dùng khi lập biểu đồ chồng tải, quyết định tăng ca, thuê ngoài hoặc dời đơn hàng.","ex_en":"Next week's workload on the grinding machines exceeds capacity by 15%.","ex_ja":"来週の研削盤の負荷は能力を15%上回っている。","ex_vi":"Phụ tải tuần sau của các máy mài vượt năng lực 15%.","syn_en":["load","capacity requirement"],"syn_ja":["負荷工数","仕事量"]},{"en":"utilization rate","pos":"noun phrase","ipa":"/ˌjuːtəlaɪˈzeɪʃn reɪt/","ja":"稼働率","kana":"かどうりつ","romaji":"kadouritsu","vi":"tỷ lệ vận hành (hệ số sử dụng thiết bị)","level":2,"def_vi":"Tỷ lệ giữa thời gian máy thực sự sản xuất và thời gian có thể sử dụng trong một kỳ.","def_en":"The ratio of time a machine actually produces to the time available in a period.","def_ja":"一定期間の利用可能な時間に対し、設備が実際に生産した時間の割合。","usage_en":"Danh từ đếm được. Hay đi với: machine utilization rate, raise the utilization rate, run at 85% utilization.","usage_ja":"Phân biệt 稼働率 (tỷ lệ chạy so với kế hoạch / nhu cầu) và 可動率 (べきどうりつ, khả năng sẵn sàng chạy khi cần). Hay đi với 稼働率を上げる.","context_vi":"Dùng trong báo cáo sản xuất hằng ngày, đánh giá đầu tư máy và quyết định chạy thêm ca.","ex_en":"The utilization rate of the new machining center is only 55%.","ex_ja":"新しいマシニングセンタの稼働率はわずか55%だ。","ex_vi":"Tỷ lệ vận hành của trung tâm gia công mới chỉ đạt 55%.","syn_en":["operating rate","capacity utilization"],"syn_ja":["設備稼働率","可動率 (liên quan)"]},{"en":"bottleneck","pos":"noun","ipa":"/ˈbɒtlnek/","ja":"ボトルネック","kana":"ボトルネック","romaji":"botorunekku","vi":"điểm nghẽn (nút cổ chai)","level":2,"def_vi":"Công đoạn hoặc thiết bị có năng lực thấp nhất, quyết định sản lượng của cả dây chuyền.","def_en":"The operation or resource with the lowest capacity, which limits the output of the whole line.","def_ja":"能力が最も低く、ライン全体の生産量を制約している工程や設備。","usage_en":"Danh từ đếm được. Hay đi với: bottleneck process / machine, remove / relieve a bottleneck, the bottleneck shifts.","usage_ja":"Hay đi với ボトルネック工程, ボトルネックを解消する; văn viết đôi khi dùng 隘路 (あいろ) hoặc 制約工程.","context_vi":"Dùng khi phân tích dây chuyền, cân bằng chuyền, quyết định đầu tư hoặc lập lịch theo lý thuyết ràng buộc (TOC).","ex_en":"The heat treatment furnace is the bottleneck of the gear line.","ex_ja":"熱処理炉が歯車ラインのボトルネックになっている。","ex_vi":"Lò nhiệt luyện là điểm nghẽn của dây chuyền bánh răng.","syn_en":["constraint (TOC)","pinch point (khẩu ngữ)"],"syn_ja":["制約工程","隘路"]},{"en":"scheduling","pos":"noun","ipa":"/ˈʃedjuːlɪŋ/","ja":"日程計画","kana":"にっていけいかく","romaji":"nitteikeikaku","vi":"lập lịch sản xuất (điều độ)","level":2,"def_vi":"Việc xác định thời điểm bắt đầu, kết thúc của từng công việc trên từng máy hoặc tổ để đáp ứng hạn giao.","def_en":"Setting the start and finish times of each job on each machine or team to meet due dates.","def_ja":"納期を守るため、各仕事を各機械・班でいつ始めいつ終えるかを決めること。","usage_en":"Danh từ không đếm được. Hay đi với: production scheduling, scheduling software, forward / backward scheduling.","usage_ja":"Theo tầm thời gian chia 大日程計画, 中日程計画, 小日程計画; ngoài xưởng hay nói スケジューリング.","context_vi":"Dùng hằng ngày ở phòng kế hoạch, đặc biệt trong xưởng gia công nhiều mã hàng, nhiều máy.","ex_en":"Scheduling becomes difficult when rush orders arrive every day.","ex_ja":"特急品が毎日入ると、日程計画が難しくなる。","ex_vi":"Việc lập lịch sản xuất trở nên khó khăn khi đơn hàng gấp đến mỗi ngày.","syn_en":["production scheduling","schedule planning"],"syn_ja":["スケジューリング","日程管理 (liên quan)"]},{"en":"Gantt chart","pos":"noun phrase","ipa":"/ˈɡænt tʃɑːt/","ja":"ガントチャート","kana":"ガントチャート","romaji":"gantochaato","vi":"biểu đồ Gantt","level":2,"def_vi":"Biểu đồ thanh ngang thể hiện các công việc theo trục thời gian, cho thấy thời điểm bắt đầu, kết thúc và tiến độ.","def_en":"A horizontal bar chart showing jobs against a time axis, with their start, finish and progress.","def_ja":"作業を横棒で時間軸上に表し、開始・終了と進捗を示す図表。","usage_en":"Danh từ đếm được, viết hoa 'Gantt' (tên người). Hay đi với: draw / update a Gantt chart, show on a Gantt chart.","usage_ja":"Hay đi với ガントチャートで管理する, 線表 (cách gọi khác ở xưởng Nhật cho bảng tiến độ dạng thanh).","context_vi":"Dùng để lập lịch máy, theo dõi tiến độ đơn hàng và quản lý dự án.","ex_en":"The planner moved two jobs on the Gantt chart to free up the lathe.","ex_ja":"計画担当者は旋盤を空けるため、ガントチャート上で2件の仕事を移動した。","ex_vi":"Người lập kế hoạch đã dời hai công việc trên biểu đồ Gantt để giải phóng máy tiện.","syn_en":["bar chart (gần nghĩa)","schedule chart"],"syn_ja":["線表","工程表 (gần nghĩa)"]},{"en":"progress control","pos":"noun phrase","ipa":"/ˈprəʊɡres kənˌtrəʊl/","ja":"進捗管理","kana":"しんちょくかんり","romaji":"shinchokukanri","vi":"quản lý tiến độ","level":2,"def_vi":"Theo dõi tiến độ thực tế so với kế hoạch và có biện pháp khi bị chậm để giữ đúng hạn giao.","def_en":"Tracking actual progress against the plan and acting on delays so that due dates are kept.","def_ja":"計画に対する実際の進み具合を把握し、遅れに対策して納期を守ること。","usage_en":"Danh từ không đếm được. Hay đi với: progress control board, progress control of orders; gần nghĩa 'progress tracking', 'expediting'.","usage_ja":"JIS dùng 進度管理; nơi làm việc hay nói 進捗管理, 進捗確認, 進捗が遅れている.","context_vi":"Dùng trong họp giao ban, bảng theo dõi đơn hàng và quản lý dự án chế tạo.","ex_en":"Progress control showed the welded frames were two days behind schedule.","ex_ja":"進捗管理により、溶接フレームが計画より2日遅れていることが分かった。","ex_vi":"Quản lý tiến độ cho thấy khung hàn đang chậm hai ngày so với kế hoạch.","syn_en":["progress tracking","expediting (gần nghĩa)"],"syn_ja":["進度管理","工程管理 (nghĩa rộng hơn)"]},{"en":"safety stock","pos":"noun phrase","ipa":"/ˈseɪfti stɒk/","ja":"安全在庫","kana":"あんぜんざいこ","romaji":"anzenzaiko","vi":"tồn kho an toàn","level":2,"def_vi":"Lượng tồn kho dự phòng giữ thêm để chống thiếu hàng khi nhu cầu tăng đột biến hoặc giao hàng bị trễ.","def_en":"Extra stock kept as a buffer against stock-outs caused by demand peaks or late deliveries.","def_ja":"需要の変動や納入遅れによる欠品を防ぐため、余分に持つ在庫。","usage_en":"Danh từ không đếm được. Hay đi với: hold / set / calculate safety stock, safety stock level; gần nghĩa 'buffer stock'.","usage_ja":"Hay đi với 安全在庫を持つ, 安全在庫数, 安全在庫を割る (xuống dưới mức an toàn).","context_vi":"Dùng trong quản lý kho, mua hàng và hoạch định vật tư, đặc biệt với hàng nhập khẩu thời gian dài.","ex_en":"We keep two weeks of safety stock for imported bearings.","ex_ja":"輸入軸受は2週間分の安全在庫を持っている。","ex_vi":"Chúng tôi giữ tồn kho an toàn hai tuần cho ổ bi nhập khẩu.","syn_en":["buffer stock"],"syn_ja":["バッファ在庫","最低在庫 (gần nghĩa)"]},{"en":"stock-out","pos":"noun","ipa":"/ˈstɒk aʊt/","ja":"欠品","kana":"けっぴん","romaji":"keppin","vi":"thiếu hàng (hết hàng)","level":2,"def_vi":"Tình trạng không còn hàng hoặc vật tư trong kho khi cần dùng, gây dừng sản xuất hoặc chậm giao.","def_en":"A situation in which an item is not in stock when needed, stopping production or delaying delivery.","def_ja":"必要なときに品物や部品が在庫になく、生産停止や納入遅れを招く状態。","usage_en":"Danh từ đếm được; cũng viết 'stockout'. Hay đi với: cause / avoid a stock-out, stock-out risk; cụm động từ 'run out of stock'.","usage_ja":"Hay đi với 欠品が発生する, 欠品でライン停止, 欠品防止; gần nghĩa 在庫切れ.","context_vi":"Dùng trong họp sản xuất, báo cáo mua hàng, khi dây chuyền dừng vì thiếu linh kiện.","ex_en":"A stock-out of M8 nuts stopped the line for an hour.","ex_ja":"M8ナットの欠品でラインが1時間止まった。","ex_vi":"Việc thiếu hàng đai ốc M8 đã làm dây chuyền dừng một giờ.","syn_en":["stockout","shortage"],"syn_ja":["在庫切れ","部品切れ"]},{"en":"high-mix low-volume production","pos":"noun phrase","ipa":"/ˌhaɪ ˈmɪks ˌləʊ ˈvɒljuːm prəˈdʌkʃn/","ja":"多品種少量生産","kana":"たひんしゅしょうりょうせいさん","romaji":"tahinshushouryouseisan","vi":"sản xuất nhiều chủng loại, số lượng nhỏ","level":2,"def_vi":"Kiểu sản xuất nhiều mã sản phẩm khác nhau, mỗi mã với số lượng ít, cần chuyển đổi thường xuyên.","def_en":"Production of many different products, each in small quantities, requiring frequent changeovers.","def_ja":"多くの種類の製品をそれぞれ少ない数量で生産する方式で、段取り替えが多い。","usage_en":"Danh từ không đếm được; viết tắt HMLV. Đối lập 'low-mix high-volume'. Dùng làm bổ ngữ: high-mix low-volume manufacturing.","usage_ja":"Cụm từ rất phổ biến ở Nhật; đối lập 少品種大量生産. Hay đi với 多品種少量生産に対応する.","context_vi":"Dùng cho xưởng gia công cơ khí, chế tạo máy theo đơn, thiết bị công nghiệp, linh kiện thay thế.","ex_en":"High-mix low-volume production needs short setup times and flexible scheduling.","ex_ja":"多品種少量生産では、短い段取り時間と柔軟な日程計画が必要だ。","ex_vi":"Sản xuất nhiều chủng loại số lượng nhỏ đòi hỏi thời gian chuẩn bị ngắn và lập lịch linh hoạt.","syn_en":["HMLV","job-shop production (gần nghĩa)"],"syn_ja":["多品種小ロット生産","少品種大量生産 (trái nghĩa)"]},{"en":"make-to-order","pos":"noun phrase","ipa":"/ˌmeɪk tu ˈɔːdə/","ja":"受注生産","kana":"じゅちゅうせいさん","romaji":"juchuuseisan","vi":"sản xuất theo đơn hàng","level":2,"def_vi":"Phương thức chỉ bắt đầu sản xuất sau khi nhận được đơn đặt hàng cụ thể của khách hàng.","def_en":"A strategy in which production starts only after a specific customer order is received.","def_ja":"顧客から具体的な注文を受けてから生産を始める方式。","usage_en":"Thường làm tính từ hoặc danh từ không đếm được, viết tắt MTO: make-to-order production, a make-to-order business.","usage_ja":"Đối lập 見込み生産. Thiết kế riêng theo đơn gọi 個別受注生産 hoặc 受注設計生産 (ETO).","context_vi":"Dùng cho máy chuyên dùng, khuôn mẫu, thiết bị công nghiệp, sản phẩm theo yêu cầu riêng.","ex_en":"Special conveyors are built on a make-to-order basis.","ex_ja":"特殊コンベヤは受注生産で製作している。","ex_vi":"Băng tải đặc biệt được chế tạo theo hình thức sản xuất theo đơn hàng.","syn_en":["MTO","build-to-order"],"syn_ja":["受注製作","オーダーメイド (khẩu ngữ)"]},{"en":"make-to-stock","pos":"noun phrase","ipa":"/ˌmeɪk tə ˈstɒk/","ja":"見込み生産","kana":"みこみせいさん","romaji":"mikomiseisan","vi":"sản xuất để tồn kho (theo dự báo)","level":2,"def_vi":"Phương thức sản xuất trước dựa trên dự báo nhu cầu, sau đó bán từ kho thành phẩm.","def_en":"A strategy in which products are made in advance from a demand forecast and sold from stock.","def_ja":"需要予測に基づいて前もって生産し、製品在庫から販売する方式。","usage_en":"Thường làm tính từ hoặc danh từ không đếm được, viết tắt MTS: make-to-stock items, switch from make-to-stock to make-to-order.","usage_ja":"Đối lập 受注生産; hay đi với 見込み生産品, 見込み生産方式.","context_vi":"Dùng cho hàng tiêu chuẩn, phụ tùng thông dụng, hàng tiêu dùng có nhu cầu ổn định.","ex_en":"Standard pumps are make-to-stock, while large pumps are built to order.","ex_ja":"標準ポンプは見込み生産、大型ポンプは受注生産である。","ex_vi":"Bơm tiêu chuẩn được sản xuất để tồn kho, còn bơm cỡ lớn được làm theo đơn.","syn_en":["MTS","build-to-stock"],"syn_ja":["計画生産 (gần nghĩa)","受注生産 (trái nghĩa)"]},{"en":"demand forecast","pos":"noun phrase","ipa":"/dɪˈmɑːnd ˈfɔːkɑːst/","ja":"需要予測","kana":"じゅようよそく","romaji":"juyouyosoku","vi":"dự báo nhu cầu","level":2,"def_vi":"Ước tính lượng sản phẩm khách hàng sẽ cần trong tương lai, làm cơ sở cho kế hoạch sản xuất và mua hàng.","def_en":"An estimate of future customer demand, used as the basis for production and purchasing plans.","def_ja":"将来の顧客需要を見積もったもので、生産計画や購買計画の基礎となる。","usage_en":"Danh từ đếm được. Hay đi với: prepare / update a demand forecast, forecast accuracy, rolling forecast.","usage_ja":"Hay đi với 需要予測を立てる, 予測精度, 内示 (lượng đặt hàng dự kiến của khách hàng Nhật).","context_vi":"Dùng khi lập kế hoạch dài hạn, đặt vật tư thời gian dài và xây dựng kế hoạch năng lực.","ex_en":"The demand forecast for the second quarter was raised by 10%.","ex_ja":"第2四半期の需要予測を10%上方修正した。","ex_vi":"Dự báo nhu cầu quý hai đã được nâng lên 10%.","syn_en":["sales forecast (gần nghĩa)","demand projection"],"syn_ja":["販売予測","内示 (liên quan)"]},{"en":"material requirements planning","pos":"noun phrase","ipa":"/məˈtɪəriəl rɪˈkwaɪəmənts ˈplænɪŋ/","ja":"資材所要量計画","kana":"しざいしょようりょうけいかく","romaji":"shizaishoyouryoukeikaku","vi":"hoạch định nhu cầu vật tư (MRP)","level":3,"def_vi":"Phương pháp dùng kế hoạch sản xuất, định mức vật tư và tồn kho để tính lượng và thời điểm cần đặt hoặc sản xuất từng vật tư.","def_en":"A method that uses the production schedule, bill of materials and stock to calculate what to order or make and when.","def_ja":"生産計画・部品表・在庫から、各品目をいつ何個手配すべきかを計算する手法。","usage_en":"Danh từ không đếm được, gần như luôn nói tắt MRP. Hay đi với: run MRP, MRP system, MRP explosion.","usage_ja":"Ở xưởng gần như chỉ nói MRP; hay đi với MRPを回す, 所要量展開, 正味所要量.","context_vi":"Dùng trong phần mềm ERP và phòng kế hoạch vật tư của nhà máy lắp ráp nhiều linh kiện.","ex_en":"Material requirements planning is run every night to update purchase orders.","ex_ja":"発注を更新するため、資材所要量計画を毎晩実行している。","ex_vi":"Hoạch định nhu cầu vật tư được chạy mỗi đêm để cập nhật đơn đặt hàng.","syn_en":["MRP"],"syn_ja":["MRP","所要量計画"]},{"en":"master production schedule","pos":"noun phrase","ipa":"/ˌmɑːstə prəˈdʌkʃn ˈʃedjuːl/","ja":"基準生産計画","kana":"きじゅんせいさんけいかく","romaji":"kijunseisankeikaku","vi":"lịch sản xuất tổng thể (MPS)","level":3,"def_vi":"Kế hoạch xác định số lượng từng sản phẩm cuối cần sản xuất theo từng tuần, làm đầu vào cho MRP.","def_en":"A plan stating how many of each end product will be made in each period, used as the input to MRP.","def_ja":"最終製品ごとに各期間の生産数量を定めた計画で、MRPの入力となる。","usage_en":"Danh từ đếm được, viết tắt MPS. Hay đi với: freeze / update the master production schedule, MPS time fence.","usage_ja":"Hay nói MPS hoặc 基準日程計画; đi với 確定期間 (time fence), MPSを確定する.","context_vi":"Dùng trong hệ thống ERP/MRP và cuộc họp cân đối cung cầu (S&OP).","ex_en":"The first two weeks of the master production schedule are frozen.","ex_ja":"基準生産計画の最初の2週間は確定扱いとしている。","ex_vi":"Hai tuần đầu của lịch sản xuất tổng thể được giữ cố định.","syn_en":["MPS"],"syn_ja":["MPS","基準日程計画"]},{"en":"reorder point","pos":"noun phrase","ipa":"/riˈɔːdə pɔɪnt/","ja":"発注点","kana":"はっちゅうてん","romaji":"hacchuuten","vi":"điểm đặt hàng lại","level":3,"def_vi":"Mức tồn kho mà khi xuống tới đó thì phải đặt hàng bổ sung, bằng nhu cầu trong thời gian chờ cộng tồn kho an toàn.","def_en":"The stock level at which a replenishment order is placed, equal to lead-time demand plus safety stock.","def_ja":"補充発注を行う在庫水準で、調達期間中の需要に安全在庫を加えた量。","usage_en":"Danh từ đếm được, viết tắt ROP. Hay đi với: set / reach the reorder point, reorder point system.","usage_ja":"Hay đi với 発注点方式, 発注点を下回る, 定量発注方式.","context_vi":"Dùng để quản lý vật tư tiêu hao, bu lông đai ốc, phụ tùng có nhu cầu đều.","ex_en":"The system raises a purchase request when stock falls below the reorder point.","ex_ja":"在庫が発注点を下回ると、システムが購買依頼を出す。","ex_vi":"Hệ thống tạo yêu cầu mua hàng khi tồn kho xuống dưới điểm đặt hàng lại.","syn_en":["ROP","order point"],"syn_ja":["定量発注方式 (liên quan)","オーダーポイント"]},{"en":"dispatching","pos":"noun","ipa":"/dɪˈspætʃɪŋ/","ja":"差立て","kana":"さしたて","romaji":"sashitate","vi":"phân việc (điều độ tại xưởng)","level":3,"def_vi":"Quyết định và giao công việc nào sẽ làm tiếp theo trên từng máy hoặc cho từng công nhân theo thứ tự ưu tiên.","def_en":"Deciding and assigning which job is processed next on each machine or by each worker, by priority.","def_ja":"各機械や作業者に、次にどの仕事をどの順で行うかを決めて割り当てること。","usage_en":"Danh từ không đếm được. Hay đi với: dispatching rule, dispatch list; động từ dispatch a job to a machine.","usage_ja":"Thuật ngữ JIS trong quản lý sản xuất; hay gặp 差立て板 (bảng phân việc), 差立てルール.","context_vi":"Dùng ở cấp tổ, xưởng gia công nhiều máy, khi quản đốc quyết định thứ tự công việc trong ca.","ex_en":"The foreman uses an earliest-due-date rule for dispatching.","ex_ja":"職長は差立てに納期優先ルールを使っている。","ex_vi":"Tổ trưởng áp dụng quy tắc hạn giao sớm nhất trước khi phân việc.","syn_en":["job dispatching","shop-floor dispatching"],"syn_ja":["作業割当","差立て板 (liên quan)"]},{"en":"manufacturing execution system","pos":"noun phrase","ipa":"/ˌmænjuˈfæktʃərɪŋ ˌeksɪˈkjuːʃn ˈsɪstəm/","ja":"製造実行システム","kana":"せいぞうじっこうシステム","romaji":"seizoujikkoushisutemu","vi":"hệ thống điều hành sản xuất (MES)","level":3,"def_vi":"Phần mềm quản lý và ghi nhận hoạt động sản xuất tại xưởng theo thời gian thực, kết nối giữa ERP và máy móc.","def_en":"Software that manages and records shop-floor production in real time, linking ERP with machines.","def_ja":"工場の生産活動をリアルタイムで管理・記録し、ERPと設備をつなぐシステム。","usage_en":"Danh từ đếm được, gần như luôn nói MES. Hay đi với: implement an MES, MES data, MES-ERP integration.","usage_ja":"Ở Nhật hay nói MES; đi với 実績収集, 製造実績, トレーサビリティ.","context_vi":"Dùng ở nhà máy ô tô, điện tử, dược để theo dõi lệnh sản xuất, sản lượng, truy xuất.","ex_en":"The manufacturing execution system collects cycle times from every machine.","ex_ja":"製造実行システムは各設備からサイクルタイムを収集する。","ex_vi":"Hệ thống điều hành sản xuất thu thập thời gian chu kỳ từ mọi máy.","syn_en":["MES"],"syn_ja":["MES","生産実績管理システム (gần nghĩa)"]},{"en":"inventory turnover","pos":"noun phrase","ipa":"/ˈɪnvəntri ˈtɜːnəʊvə/","ja":"在庫回転率","kana":"ざいこかいてんりつ","romaji":"zaikokaitenritsu","vi":"vòng quay hàng tồn kho","level":3,"def_vi":"Số lần tồn kho được tiêu thụ và bổ sung trong một kỳ, tính bằng giá vốn hàng bán chia tồn kho bình quân.","def_en":"The number of times inventory is used and replaced in a period: cost of goods sold divided by average stock.","def_ja":"一定期間に在庫が何回入れ替わったかを示す指標で、売上原価を平均在庫で割って求める。","usage_en":"Danh từ không đếm được. Hay đi với: improve inventory turnover, inventory turns of 12 per year; nghịch đảo là 'days of inventory'.","usage_ja":"Hay đi với 在庫回転率を上げる, 在庫回転日数 (số ngày tồn kho).","context_vi":"Dùng trong báo cáo quản trị, đánh giá hiệu quả kho và chuỗi cung ứng.","ex_en":"Inventory turnover rose from 6 to 10 after kanban was introduced.","ex_ja":"かんばん導入後、在庫回転率は6回から10回に上がった。","ex_vi":"Vòng quay hàng tồn kho tăng từ 6 lên 10 sau khi áp dụng kanban.","syn_en":["inventory turns","stock turnover"],"syn_ja":["在庫回転数","在庫回転日数 (liên quan)"]}]},{"id":48,"words":[{"en":"lean manufacturing","pos":"noun phrase","ipa":"/ˌliːn ˌmænjuˈfæktʃərɪŋ/","ja":"リーン生産方式","kana":"リーンせいさんほうしき","romaji":"riinseisanhoushiki","vi":"sản xuất tinh gọn (Lean)","level":1,"def_vi":"Triết lý và phương pháp sản xuất tập trung loại bỏ lãng phí, chỉ làm những gì tạo giá trị cho khách hàng.","def_en":"A production philosophy and method that eliminates waste and does only what creates value for the customer.","def_ja":"ムダを排除し、顧客にとって価値を生む活動だけを行う生産の考え方と手法。","usage_en":"Danh từ không đếm được; hay nói gọn 'lean'. Hay đi với: implement lean manufacturing, lean tools, go lean, lean transformation.","usage_ja":"Ở Nhật thường nói トヨタ生産方式 hoặc TPS hơn là リーン; リーン生産 dùng trong tài liệu dịch hoặc công ty Âu Mỹ.","context_vi":"Dùng trong chương trình cải tiến nhà máy, đào tạo quản lý, tư vấn năng suất.","ex_en":"The plant adopted lean manufacturing to cut lead time and inventory.","ex_ja":"工場はリードタイムと在庫を減らすため、リーン生産方式を導入した。","ex_vi":"Nhà máy đã áp dụng sản xuất tinh gọn để giảm thời gian sản xuất và tồn kho.","syn_en":["lean production","lean (khẩu ngữ)"],"syn_ja":["リーン生産","トヨタ生産方式 (gần nghĩa)"]},{"en":"waste","pos":"noun","ipa":"/weɪst/","ja":"ムダ","kana":"ムダ","romaji":"muda","vi":"lãng phí","level":1,"def_vi":"Mọi hoạt động tiêu tốn thời gian, vật tư hoặc công sức nhưng không làm tăng giá trị cho sản phẩm.","def_en":"Any activity that consumes time, material or effort without adding value to the product.","def_ja":"時間・材料・労力を使うが、製品の価値を高めない活動。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: eliminate / reduce waste, the seven wastes; trong lean còn giữ từ Nhật 'muda'.","usage_ja":"Trong lean thường viết katakana ムダ để nhấn mạnh thuật ngữ; hay đi với ムダを省く, ムダ取り, 7つのムダ.","context_vi":"Dùng hằng ngày trong hoạt động cải tiến, đi hiện trường và đào tạo lean.","ex_en":"Walking to fetch parts is waste that the customer does not pay for.","ex_ja":"部品を取りに歩くことは、顧客が対価を払わないムダである。","ex_vi":"Việc đi lại lấy linh kiện là lãng phí mà khách hàng không trả tiền.","syn_en":["muda","non-value-added activity"],"syn_ja":["無駄","付加価値のない作業"]},{"en":"kaizen","pos":"noun","ipa":"/ˈkaɪzen/","ja":"改善","kana":"かいぜん","romaji":"kaizen","vi":"cải tiến (kaizen)","level":1,"def_vi":"Hoạt động cải tiến liên tục từng bước nhỏ do chính người làm việc tại hiện trường đề xuất và thực hiện.","def_en":"Continuous improvement in small steps, proposed and carried out by the people doing the work.","def_ja":"現場で働く人自身が提案・実行する、小さな改良の継続的な積み重ね。","usage_en":"Danh từ không đếm được, mượn từ tiếng Nhật. Hay đi với: kaizen activity, kaizen event / workshop, kaizen proposal.","usage_ja":"Hay đi với 改善活動, 改善提案, 改善する, カイゼン (katakana khi nhấn thuật ngữ quốc tế).","context_vi":"Dùng trong các phong trào cải tiến, hộp ý kiến, báo cáo cải tiến của nhà máy Nhật và Việt Nam.","ex_en":"A small kaizen moved the parts rack closer and saved 6 seconds per cycle.","ex_ja":"部品棚を近づける小さな改善で、1サイクル6秒短縮できた。","ex_vi":"Một cải tiến nhỏ đưa giá linh kiện lại gần đã tiết kiệm 6 giây mỗi chu kỳ.","syn_en":["continuous improvement"],"syn_ja":["カイゼン","改善活動"]},{"en":"5S","pos":"abbreviation","ipa":"/ˌfaɪv ˈes/","ja":"5S","kana":"ごエス","romaji":"goesu","vi":"5S (Sàng lọc, Sắp xếp, Sạch sẽ, Săn sóc, Sẵn sàng)","level":1,"def_vi":"Phương pháp tổ chức nơi làm việc gồm năm bước: sàng lọc, sắp xếp, sạch sẽ, săn sóc và sẵn sàng.","def_en":"A workplace organization method of five steps: sort, set in order, shine, standardize and sustain.","def_ja":"整理・整頓・清掃・清潔・しつけの五つで職場を整える活動。","usage_en":"Dùng như danh từ không đếm được: practise 5S, 5S audit, 5S activities; năm bước tiếng Anh: sort, set in order, shine, standardize, sustain.","usage_ja":"Năm chữ: 整理, 整頓, 清掃, 清潔, しつけ. Hay đi với 5S活動, 5Sパトロール, 5Sを徹底する.","context_vi":"Là nền tảng của mọi chương trình cải tiến, áp dụng ở xưởng, kho, văn phòng.","ex_en":"The 5S audit found unlabelled tools on three workbenches.","ex_ja":"5Sパトロールで、3台の作業台に表示のない工具が見つかった。","ex_vi":"Đợt đánh giá 5S phát hiện dụng cụ không dán nhãn trên ba bàn thao tác.","syn_en":["workplace organization"],"syn_ja":["整理・整頓","5S活動"]},{"en":"kanban","pos":"noun","ipa":"/ˈkɑːnbɑːn/","ja":"かんばん","kana":"かんばん","romaji":"kanban","vi":"thẻ kanban","level":1,"def_vi":"Thẻ hoặc tín hiệu ghi mã hàng và số lượng, dùng để ra lệnh sản xuất hoặc vận chuyển khi công đoạn sau đã sử dụng hàng.","def_en":"A card or signal showing part number and quantity that authorizes production or withdrawal after downstream use.","def_ja":"品番と数量を示し、後工程が使った分だけ生産や引取りを指示する札や信号。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: kanban card, kanban system, withdrawal / production kanban.","usage_ja":"Ở Toyota viết hiragana かんばん; nơi khác cũng viết カンバン hoặc 看板. Hay đi với 引取りかんばん, 生産指示かんばん, かんばんを外す.","context_vi":"Dùng ở dây chuyền lắp ráp, giữa xưởng và nhà cung cấp để kéo hàng theo nhu cầu.","ex_en":"Each box carries a kanban that returns to the press shop when emptied.","ex_ja":"各箱にはかんばんが付いており、空になるとプレス工場へ戻る。","ex_vi":"Mỗi thùng có một thẻ kanban, khi hết hàng thẻ được gửi trả về xưởng dập.","syn_en":["kanban card","pull signal"],"syn_ja":["カンバン","看板"]},{"en":"just-in-time","pos":"noun phrase","ipa":"/ˌdʒʌst ɪn ˈtaɪm/","ja":"ジャストインタイム","kana":"ジャストインタイム","romaji":"jasutointaimu","vi":"đúng thời điểm (JIT)","level":1,"def_vi":"Nguyên tắc sản xuất và cung cấp đúng thứ cần, đúng lúc cần, đúng số lượng cần.","def_en":"The principle of making and delivering only what is needed, when it is needed, in the amount needed.","def_ja":"必要なものを、必要なときに、必要な量だけ作り運ぶという考え方。","usage_en":"Viết tắt JIT; dùng như danh từ hoặc tính từ: just-in-time delivery, JIT supply; khi đứng sau động từ không cần gạch nối (arrive just in time).","usage_ja":"Hay viết JIT; là một trong hai trụ cột của トヨタ生産方式 cùng với 自働化.","context_vi":"Dùng trong lắp ráp ô tô, chuỗi cung ứng linh kiện, quản lý tồn kho tối thiểu.","ex_en":"Seats are delivered just-in-time in the same order as the cars on the line.","ex_ja":"シートはライン上の車と同じ順序でジャストインタイムに納入される。","ex_vi":"Ghế được giao theo nguyên tắc đúng thời điểm, đúng thứ tự xe trên dây chuyền.","syn_en":["JIT"],"syn_ja":["JIT","必要なものを必要なときに (giải thích)"]},{"en":"takt time","pos":"noun phrase","ipa":"/ˈtɑːkt taɪm/","ja":"タクトタイム","kana":"タクトタイム","romaji":"takutotaimu","vi":"nhịp sản xuất (takt time)","level":1,"def_vi":"Thời gian cần để làm ra một sản phẩm theo nhu cầu khách hàng, bằng thời gian làm việc chia số lượng cần.","def_en":"The time per unit set by customer demand: available working time divided by required quantity.","def_ja":"稼働時間を必要数で割った、顧客需要に合わせた1個あたりの生産時間。","usage_en":"Danh từ đếm được và không đếm được; 'takt' gốc tiếng Đức. Hay đi với: calculate takt time, a takt time of 60 seconds; không nhầm với cycle time.","usage_ja":"Hay đi với タクトタイムを決める, タクトに合わせる; ngoài xưởng nói gọn タクト.","context_vi":"Dùng khi thiết kế dây chuyền, cân bằng chuyền và điều chỉnh nhân lực theo sản lượng.","ex_en":"With 450 minutes and 900 units a day, the takt time is 30 seconds.","ex_ja":"1日450分で900台なら、タクトタイムは30秒になる。","ex_vi":"Với 450 phút và 900 sản phẩm mỗi ngày, nhịp sản xuất là 30 giây.","syn_en":["takt"],"syn_ja":["タクト (khẩu ngữ)","サイクルタイム (liên quan)"]},{"en":"cycle time","pos":"noun phrase","ipa":"/ˈsaɪkl taɪm/","ja":"サイクルタイム","kana":"サイクルタイム","romaji":"saikurutaimu","vi":"thời gian chu kỳ","level":1,"def_vi":"Thời gian thực tế để một công nhân hoặc máy hoàn thành một chu kỳ công việc cho một sản phẩm.","def_en":"The actual time for an operator or machine to complete one work cycle for one unit.","def_ja":"作業者や設備が1個分の作業を一巡するのに実際にかかる時間。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: reduce / measure cycle time, cycle time of 45 seconds; viết tắt CT.","usage_ja":"Viết tắt CT; hay đi với サイクルタイムを測る, サイクルタイム短縮, CTがタクトを超える.","context_vi":"Dùng trong đo thời gian thao tác, cân bằng chuyền, đánh giá năng suất máy.","ex_en":"Station 4 has a cycle time of 34 seconds, above the 30-second takt.","ex_ja":"4番工程のサイクルタイムは34秒で、タクト30秒を超えている。","ex_vi":"Trạm 4 có thời gian chu kỳ 34 giây, vượt nhịp sản xuất 30 giây.","syn_en":["CT","operation time (gần nghĩa)"],"syn_ja":["CT","加工時間 (gần nghĩa)"]},{"en":"standardized work","pos":"noun phrase","ipa":"/ˈstændədaɪzd wɜːk/","ja":"標準作業","kana":"ひょうじゅんさぎょう","romaji":"hyoujunsagyou","vi":"thao tác tiêu chuẩn","level":1,"def_vi":"Cách làm tốt nhất hiện tại được quy định rõ về trình tự thao tác, thời gian và lượng hàng chờ, làm cơ sở cho cải tiến.","def_en":"The current best method, defined by work sequence, timing and in-process stock, used as the baseline for improvement.","def_ja":"作業順序・タクト・標準手持ちを定めた現時点で最良の作業方法で、改善の基準となる。","usage_en":"Danh từ không đếm được. Hay đi với: follow / update standardized work, standardized work sheet; Anh viết standardised.","usage_ja":"Ba yếu tố của 標準作業: タクトタイム, 作業順序, 標準手持ち. Tài liệu đi kèm: 標準作業票, 作業要領書.","context_vi":"Dùng ở dây chuyền lắp ráp, đào tạo công nhân mới và khi kiểm tra tuân thủ quy trình.","ex_en":"New operators are trained using the standardized work sheet posted at each station.","ex_ja":"新人作業者は、各工程に掲示した標準作業票で教育を受ける。","ex_vi":"Công nhân mới được đào tạo theo bảng thao tác tiêu chuẩn dán ở mỗi trạm.","syn_en":["standard work","standard operating procedure (gần nghĩa)"],"syn_ja":["作業標準 (gần nghĩa)","標準作業票 (liên quan)"]},{"en":"gemba","pos":"noun","ipa":"/ˈɡembə/","ja":"現場","kana":"げんば","romaji":"genba","vi":"hiện trường (nơi sản xuất)","level":1,"def_vi":"Nơi công việc tạo giá trị thực sự diễn ra, như xưởng sản xuất, nơi cần đến tận nơi để quan sát sự thật.","def_en":"The place where value-adding work actually happens, such as the shop floor, where facts are observed first-hand.","def_ja":"実際に価値を生む仕事が行われる場所で、事実を自分の目で確かめる所。","usage_en":"Danh từ không đếm được, mượn tiếng Nhật (cũng viết 'genba'). Hay đi với: go to the gemba, gemba walk; thông thường nói 'shop floor'.","usage_ja":"Hay đi với 現場に行く, 現場主義, 三現主義 (現場・現物・現実), 現場の声.","context_vi":"Dùng khi quản lý đi xuống xưởng quan sát, giải quyết vấn đề tại chỗ.","ex_en":"The manager does a gemba walk every morning before the production meeting.","ex_ja":"マネージャーは毎朝、生産会議の前に現場を回る。","ex_vi":"Quản lý đi hiện trường mỗi sáng trước cuộc họp sản xuất.","syn_en":["genba","shop floor"],"syn_ja":["生産現場","三現主義 (liên quan)"]},{"en":"Toyota Production System","pos":"noun phrase","ipa":"/tɔɪˌəʊtə prəˈdʌkʃn ˌsɪstəm/","ja":"トヨタ生産方式","kana":"トヨタせいさんほうしき","romaji":"toyotaseisanhoushiki","vi":"Hệ thống sản xuất Toyota (TPS)","level":2,"def_vi":"Hệ thống sản xuất do Toyota xây dựng, dựa trên hai trụ cột đúng thời điểm và tự động hóa có trí tuệ, là gốc của Lean.","def_en":"Toyota's production system built on the two pillars of just-in-time and jidoka; the origin of lean.","def_ja":"ジャストインタイムと自働化を二本柱とするトヨタの生産方式で、リーンの原型。","usage_en":"Danh từ riêng, viết hoa, viết tắt TPS. Hay đi với: principles of the Toyota Production System, learn TPS.","usage_ja":"Viết tắt TPS; hay gặp trong sách 大野耐一 và tài liệu đào tạo của các công ty Nhật.","context_vi":"Dùng trong đào tạo lean, nhà máy ô tô và nhà cung cấp linh kiện cho các hãng Nhật.","ex_en":"Our supplier development team teaches the Toyota Production System to partner plants.","ex_ja":"当社の仕入先指導チームは、協力工場にトヨタ生産方式を教えている。","ex_vi":"Nhóm phát triển nhà cung cấp của chúng tôi đào tạo Hệ thống sản xuất Toyota cho các nhà máy đối tác.","syn_en":["TPS","lean manufacturing (gần nghĩa)"],"syn_ja":["TPS","リーン生産方式 (gần nghĩa)"]},{"en":"jidoka","pos":"noun","ipa":"/dʒɪˈdəʊkə/","ja":"自働化","kana":"じどうか","romaji":"jidouka","vi":"tự động hóa có trí tuệ (jidoka)","level":2,"def_vi":"Nguyên tắc máy hoặc người tự dừng ngay khi phát hiện bất thường để không sinh ra hàng lỗi.","def_en":"The principle that a machine or operator stops immediately when an abnormality occurs, so no defects are made.","def_ja":"異常が起きたら設備や人がすぐに止まり、不良を作らないようにする考え方。","usage_en":"Danh từ không đếm được, mượn tiếng Nhật; tiếng Anh giải thích là 'autonomation' hoặc 'automation with a human touch'.","usage_ja":"Chú ý viết 自働化 (chữ 働 có bộ nhân) để phân biệt với 自動化 thông thường; là trụ cột thứ hai của TPS.","context_vi":"Dùng khi thiết kế máy tự dừng, hệ thống andon và nguyên tắc dừng chuyền khi có lỗi.","ex_en":"Jidoka means the press stops itself if a double sheet is detected.","ex_ja":"自働化とは、二枚送りを検出したらプレスが自ら止まることだ。","ex_vi":"Jidoka nghĩa là máy dập tự dừng nếu phát hiện hai tấm bị nạp chồng.","syn_en":["autonomation","automation with a human touch"],"syn_ja":["ニンベンのついた自動化","自動化 (khác nghĩa, liên quan)"]},{"en":"andon","pos":"noun","ipa":"/ˈændɒn/","ja":"アンドン","kana":"アンドン","romaji":"andon","vi":"đèn báo andon","level":2,"def_vi":"Bảng đèn hoặc tín hiệu hiển thị trạng thái dây chuyền, cho công nhân báo bất thường và gọi hỗ trợ.","def_en":"A light or display board showing line status, used by operators to signal problems and call for help.","def_ja":"ラインの状態を表示し、作業者が異常を知らせて応援を呼ぶための表示灯や表示盤。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: andon cord, andon board, pull the andon.","usage_ja":"Hay đi với アンドンを点ける, 呼出しアンドン, ひもスイッチ (dây kéo andon); có khi viết 行灯.","context_vi":"Dùng ở dây chuyền lắp ráp ô tô, điện tử để dừng chuyền hoặc gọi tổ trưởng khi có sự cố.","ex_en":"The operator pulled the andon cord when a bolt would not seat.","ex_ja":"ボルトが着座しなかったので、作業者はアンドンのひもを引いた。","ex_vi":"Công nhân kéo dây andon khi một bu lông không vào hết.","syn_en":["andon board","andon cord (liên quan)"],"syn_ja":["行灯","表示灯 (gần nghĩa)"]},{"en":"poka-yoke","pos":"noun","ipa":"/ˌpəʊkə ˈjəʊkeɪ/","ja":"ポカヨケ","kana":"ポカヨケ","romaji":"pokayoke","vi":"chống sai lỗi (poka-yoke)","level":2,"def_vi":"Cơ cấu hoặc thiết bị đơn giản ngăn thao tác sai hoặc phát hiện ngay lỗi để hàng lỗi không đi tiếp.","def_en":"A simple device or design that prevents mistakes or detects them immediately so defects do not pass on.","def_ja":"作業ミスを防いだり、すぐに検出したりして不良を流さないための簡単な仕組み。","usage_en":"Danh từ đếm được và không đếm được, mượn tiếng Nhật. Hay đi với: install a poka-yoke, poka-yoke device; tiếng Anh: mistake-proofing, error-proofing.","usage_ja":"Hay đi với ポカヨケを付ける, ポカヨケ治具; văn bản dùng ミス防止, フールプルーフ.","context_vi":"Dùng trong lắp ráp, gia công, khi thiết kế đồ gá, chi tiết chỉ lắp được một chiều.","ex_en":"A poka-yoke pin stops the bracket from being loaded upside down.","ex_ja":"ポカヨケのピンで、ブラケットが逆向きにセットされるのを防いでいる。","ex_vi":"Một chốt chống sai lỗi ngăn giá đỡ bị đặt ngược.","syn_en":["mistake-proofing","error-proofing"],"syn_ja":["フールプルーフ","ミス防止"]},{"en":"pull production","pos":"noun phrase","ipa":"/ˈpʊl prəˌdʌkʃn/","ja":"後工程引取り","kana":"あとこうていひきとり","romaji":"atokouteihikitori","vi":"sản xuất kéo","level":2,"def_vi":"Cách tổ chức trong đó công đoạn sau lấy hàng từ công đoạn trước khi cần, và công đoạn trước chỉ làm bù đúng phần đã lấy.","def_en":"A system in which the downstream process withdraws what it needs and the upstream process makes only what was taken.","def_ja":"後工程が必要な分だけ前工程から引き取り、前工程は引き取られた分だけ作る仕組み。","usage_en":"Danh từ không đếm được. Hay đi với: pull system, switch from push to pull production; đối lập 'push production'.","usage_ja":"Thuật ngữ TPS; tài liệu chung nói プル生産方式 hoặc 引取り方式. Đối lập 押し込み生産 (プッシュ).","context_vi":"Dùng khi thiết kế dòng chảy với kanban giữa các công đoạn và nhà cung cấp.","ex_en":"Pull production stopped the machining area from building parts nobody needed.","ex_ja":"後工程引取りにより、加工課が不要な部品を作ることがなくなった。","ex_vi":"Sản xuất kéo đã giúp khu gia công thôi làm ra chi tiết không ai cần.","syn_en":["pull system"],"syn_ja":["プル生産方式","引取り方式"]},{"en":"one-piece flow","pos":"noun phrase","ipa":"/ˌwʌn piːs ˈfləʊ/","ja":"一個流し","kana":"いっこながし","romaji":"ikkonagashi","vi":"dòng chảy một sản phẩm","level":2,"def_vi":"Cách sản xuất trong đó từng sản phẩm một được chuyển ngay sang công đoạn kế tiếp thay vì chờ cả lô.","def_en":"Moving parts one at a time directly to the next operation instead of waiting for a whole batch.","def_ja":"ロットでまとめず、1個ずつ次の工程へ流して加工・組立する方式。","usage_en":"Danh từ không đếm được. Hay đi với: achieve one-piece flow, one-piece flow cell; còn gọi 'single-piece flow', 'continuous flow'.","usage_ja":"Hay đi với 一個流し生産, 一個流しにする; đối lập ロット生産, まとめ生産.","context_vi":"Dùng khi bố trí lại dây chuyền, lập cell sản xuất để giảm hàng chờ và thời gian sản xuất.","ex_en":"Changing to one-piece flow cut work-in-process from 200 parts to 8.","ex_ja":"一個流しに変えたことで、仕掛品が200個から8個になった。","ex_vi":"Chuyển sang dòng chảy một sản phẩm đã giảm bán thành phẩm từ 200 xuống 8 chiếc.","syn_en":["single-piece flow","continuous flow"],"syn_ja":["1個流し","連続フロー"]},{"en":"cell production","pos":"noun phrase","ipa":"/ˈsel prəˌdʌkʃn/","ja":"セル生産方式","kana":"セルせいさんほうしき","romaji":"seruseisanhoushiki","vi":"sản xuất theo cụm (cell)","level":2,"def_vi":"Cách bố trí máy và người thành cụm nhỏ, thường hình chữ U, để một hoặc vài người làm trọn sản phẩm.","def_en":"Arranging machines and people in small cells, often U-shaped, where one or a few workers complete a product.","def_ja":"設備と作業者を小さな単位（U字型など）にまとめ、少人数で製品を完成させる方式。","usage_en":"Danh từ không đếm được; cũng nói 'cellular manufacturing'. Hay đi với: U-shaped cell, set up a cell, cell layout.","usage_ja":"Hay nói セル生産, U字ライン, 一人屋台 (một người làm trọn sản phẩm).","context_vi":"Dùng ở nhà máy lắp ráp điện tử, máy móc nhiều chủng loại, khi chuyển từ dây chuyền dài sang tổ nhỏ.","ex_en":"Cell production let three operators build the whole pump in a U-shaped layout.","ex_ja":"セル生産方式により、U字型配置で3人がポンプ全体を組み立てられるようになった。","ex_vi":"Sản xuất theo cụm cho phép ba công nhân lắp trọn chiếc bơm trong bố trí hình chữ U.","syn_en":["cellular manufacturing","cell layout (liên quan)"],"syn_ja":["セル生産","U字ライン"]},{"en":"changeover","pos":"noun","ipa":"/ˈtʃeɪndʒəʊvə/","ja":"段取り替え","kana":"だんどりがえ","romaji":"dandorigae","vi":"chuyển đổi mã hàng (thay khuôn, thay đồ gá)","level":2,"def_vi":"Toàn bộ công việc dừng máy để chuyển từ sản xuất mã hàng này sang mã hàng khác, như thay khuôn, dao, đồ gá.","def_en":"All the work done to switch a machine or line from one product to another, such as changing dies or tools.","def_ja":"金型・工具・治具の交換など、ある品種から別の品種へ生産を切り替える作業。","usage_en":"Danh từ đếm được. Hay đi với: changeover time, reduce changeover, quick changeover; 'setup' là từ gần nghĩa.","usage_ja":"Viết 段取替え, 段取り替え đều gặp; hay đi với 段取り替え時間, 外段取り, 内段取り.","context_vi":"Dùng ở máy dập, máy ép nhựa, máy CNC khi sản xuất nhiều mã hàng.","ex_en":"Changeover on press 3 takes 40 minutes, so we run large batches.","ex_ja":"3号プレスの段取り替えに40分かかるので、大ロットで生産している。","ex_vi":"Việc chuyển đổi mã hàng ở máy dập số 3 mất 40 phút nên chúng tôi chạy lô lớn.","syn_en":["setup change","product changeover"],"syn_ja":["段取替え","品種切替え"]},{"en":"line balancing","pos":"noun phrase","ipa":"/ˈlaɪn ˌbælənsɪŋ/","ja":"ラインバランシング","kana":"ラインバランシング","romaji":"rainbaranshingu","vi":"cân bằng chuyền","level":2,"def_vi":"Phân bổ lại các thao tác giữa các trạm sao cho thời gian mỗi trạm gần bằng nhau và không vượt nhịp sản xuất.","def_en":"Redistributing tasks between stations so that each has nearly equal time not exceeding takt time.","def_ja":"各工程の作業時間がほぼ等しく、タクトタイムを超えないよう作業を配分し直すこと。","usage_en":"Danh từ không đếm được. Hay đi với: line balancing chart, perform line balancing; kết quả đo bằng 'line balance efficiency'.","usage_ja":"Hay đi với ラインバランスを取る, ラインバランス効率, 山積み表 (biểu đồ chồng thời gian).","context_vi":"Dùng khi thiết kế hoặc cải tiến dây chuyền lắp ráp, thay đổi sản lượng hoặc số người.","ex_en":"Line balancing moved two tasks from station 4 to station 5.","ex_ja":"ラインバランシングで、4番工程の作業2つを5番工程に移した。","ex_vi":"Việc cân bằng chuyền đã chuyển hai thao tác từ trạm 4 sang trạm 5.","syn_en":["line balance","work balancing"],"syn_ja":["ラインバランス","工程編成 (gần nghĩa)"]},{"en":"overproduction","pos":"noun","ipa":"/ˌəʊvəprəˈdʌkʃn/","ja":"作りすぎのムダ","kana":"つくりすぎのムダ","romaji":"tsukurisuginomuda","vi":"lãng phí sản xuất thừa","level":2,"def_vi":"Làm ra nhiều hơn hoặc sớm hơn mức công đoạn sau và khách hàng cần; được xem là lãng phí nghiêm trọng nhất.","def_en":"Making more, or earlier, than the next process or customer needs; regarded as the worst type of waste.","def_ja":"後工程や顧客が必要とする以上に、または早く作ること。最も悪いムダとされる。","usage_en":"Danh từ không đếm được. Hay đi với: waste of overproduction, avoid overproduction; động từ overproduce.","usage_ja":"Đứng đầu trong 7つのムダ; hay đi với 作りすぎを防ぐ, 作りすぎは在庫を生む.","context_vi":"Dùng khi phân tích lãng phí, đánh giá tồn kho tăng và trong đào tạo lean.","ex_en":"Running the press to keep it busy only led to overproduction.","ex_ja":"プレスを遊ばせないために動かした結果、作りすぎのムダが生じた。","ex_vi":"Chạy máy dập chỉ để máy không nghỉ đã dẫn đến lãng phí sản xuất thừa.","syn_en":["waste of overproduction"],"syn_ja":["作りすぎ","つくりすぎのムダ"]},{"en":"seven wastes","pos":"noun phrase","ipa":"/ˌsevn ˈweɪsts/","ja":"7つのムダ","kana":"ななつのムダ","romaji":"nanatsunomuda","vi":"7 loại lãng phí","level":2,"def_vi":"Bảy loại lãng phí trong TPS: sản xuất thừa, chờ đợi, vận chuyển, gia công thừa, tồn kho, thao tác thừa và hàng lỗi.","def_en":"TPS's seven wastes: overproduction, waiting, transport, over-processing, inventory, motion and defects.","def_ja":"作りすぎ・手待ち・運搬・加工そのもの・在庫・動作・不良をつくるムダの七つ。","usage_en":"Dùng với 'the': the seven wastes; ghi nhớ bằng TIMWOOD. Hay đi với: identify the seven wastes.","usage_ja":"Viết 七つのムダ hoặc 7つのムダ; nhiều nơi thêm loại thứ tám là 人の能力のムダ.","context_vi":"Dùng trong đào tạo lean, đi hiện trường tìm lãng phí và phiếu đề xuất cải tiến.","ex_en":"The team walked the line and listed examples of the seven wastes.","ex_ja":"チームはラインを回り、7つのムダの例を書き出した。","ex_vi":"Nhóm đi dọc dây chuyền và liệt kê các ví dụ về 7 loại lãng phí.","syn_en":["seven types of waste","TIMWOOD (cách nhớ)"],"syn_ja":["七つのムダ","ムダ (nghĩa rộng hơn)"]},{"en":"production leveling","pos":"noun phrase","ipa":"/prəˈdʌkʃn ˈlevəlɪŋ/","ja":"平準化","kana":"へいじゅんか","romaji":"heijunka","vi":"san bằng sản xuất (heijunka)","level":2,"def_vi":"Phân bổ đều số lượng và chủng loại sản phẩm theo thời gian để tải sản xuất không lên xuống thất thường.","def_en":"Spreading product volume and mix evenly over time so that the production load does not fluctuate.","def_ja":"生産の量と種類を時間的に均等にならし、負荷の変動をなくすこと。","usage_en":"Danh từ không đếm được; Anh viết levelling. Còn giữ từ Nhật 'heijunka': heijunka box, level the schedule.","usage_ja":"Hay đi với 生産の平準化, 平準化生産, 平準化ポスト (hộp heijunka), 混流生産.","context_vi":"Dùng khi lập lịch dây chuyền lắp ráp nhiều mẫu xe và trong hệ thống kanban.","ex_en":"Production leveling mixes models A, B and C every hour instead of one per day.","ex_ja":"平準化により、A・B・Cの各機種を1日1機種ではなく毎時間混ぜて流す。","ex_vi":"San bằng sản xuất trộn các mẫu A, B, C mỗi giờ thay vì mỗi ngày một mẫu.","syn_en":["heijunka","level scheduling"],"syn_ja":["平準化生産","混流生産 (liên quan)"]},{"en":"visual management","pos":"noun phrase","ipa":"/ˌvɪʒuəl ˈmænɪdʒmənt/","ja":"目で見る管理","kana":"めでみるかんり","romaji":"medemirukanri","vi":"quản lý trực quan","level":2,"def_vi":"Dùng bảng biểu, màu sắc, vạch kẻ, đèn để ai nhìn vào cũng thấy ngay tình trạng bình thường hay bất thường.","def_en":"Using boards, colours, floor markings and lights so anyone can see at a glance whether things are normal.","def_ja":"表示板・色・床の線・ランプなどで、正常か異常かを誰が見ても分かるようにする管理。","usage_en":"Danh từ không đếm được. Hay đi với: visual management board, visual controls; động từ 'make visible'.","usage_ja":"Hay đi với 見える化 (làm cho thấy được), 目で見る管理板, 見える化する.","context_vi":"Dùng ở xưởng, kho, văn phòng: bảng tiến độ, vạch sơn sàn, nhãn mức tồn tối thiểu.","ex_en":"Visual management boards show hourly output against the target.","ex_ja":"目で見る管理の掲示板に、目標に対する毎時の出来高を表示している。","ex_vi":"Bảng quản lý trực quan hiển thị sản lượng từng giờ so với mục tiêu.","syn_en":["visual control","visual factory"],"syn_ja":["見える化","目で見る管理板 (liên quan)"]},{"en":"value-added activity","pos":"noun phrase","ipa":"/ˌvæljuː ˈædɪd ækˈtɪvəti/","ja":"付加価値作業","kana":"ふかかちさぎょう","romaji":"fukakachisagyou","vi":"hoạt động tạo giá trị gia tăng","level":2,"def_vi":"Hoạt động làm thay đổi hình dạng, tính chất hoặc lắp ráp sản phẩm theo cách khách hàng sẵn sàng trả tiền.","def_en":"Work that changes the shape, properties or assembly of a product in a way the customer will pay for.","def_ja":"製品の形・性質・組付け状態を変え、顧客が対価を払う価値を生む作業。","usage_en":"Danh từ đếm được. Đối lập 'non-value-added activity'. Hay đi với: ratio of value-added time to lead time.","usage_ja":"Hay đi với 正味作業 (thao tác thực), 付随作業, 付加価値を生まない作業 (đối lập).","context_vi":"Dùng khi phân tích thao tác, vẽ sơ đồ chuỗi giá trị và tính tỷ lệ thời gian tạo giá trị.","ex_en":"Only 5% of the lead time was value-added activity; the rest was waiting.","ex_ja":"リードタイムのうち付加価値作業はわずか5%で、残りは待ちだった。","ex_vi":"Chỉ 5% thời gian sản xuất là hoạt động tạo giá trị gia tăng, phần còn lại là chờ.","syn_en":["value-adding work","VA activity"],"syn_ja":["正味作業","付加価値時間 (liên quan)"]},{"en":"value stream mapping","pos":"noun phrase","ipa":"/ˈvæljuː striːm ˈmæpɪŋ/","ja":"バリューストリームマッピング","kana":"バリューストリームマッピング","romaji":"baryuusutoriimumappingu","vi":"sơ đồ chuỗi giá trị (VSM)","level":3,"def_vi":"Kỹ thuật vẽ sơ đồ toàn bộ dòng vật tư và thông tin từ nhà cung cấp đến khách hàng để tìm lãng phí và thiết kế trạng thái tương lai.","def_en":"A technique that maps the whole material and information flow from supplier to customer to find waste and design a future state.","def_ja":"仕入先から顧客までのモノと情報の流れ全体を図にし、ムダを見つけ将来像を描く手法。","usage_en":"Danh từ không đếm được, viết tắt VSM. Hay đi với: current-state / future-state map, run a value stream mapping workshop.","usage_ja":"Ở Nhật gốc là モノと情報の流れ図; hay nói VSM, 現状マップ, 将来マップ.","context_vi":"Dùng khi khởi động dự án lean cấp nhà máy hoặc dòng sản phẩm.","ex_en":"Value stream mapping showed parts waited nine days in the warehouse.","ex_ja":"バリューストリームマッピングにより、部品が倉庫で9日間待っていることが分かった。","ex_vi":"Sơ đồ chuỗi giá trị cho thấy chi tiết nằm chờ trong kho chín ngày.","syn_en":["VSM","material and information flow mapping"],"syn_ja":["VSM","モノと情報の流れ図"]},{"en":"single-minute exchange of die","pos":"noun phrase","ipa":"/ˈsɪŋɡl ˈmɪnɪt ɪksˈtʃeɪndʒ əv daɪ/","ja":"シングル段取り","kana":"シングルだんどり","romaji":"shingurudandori","vi":"chuyển đổi khuôn dưới 10 phút (SMED)","level":3,"def_vi":"Phương pháp rút ngắn thời gian chuyển đổi xuống dưới 10 phút bằng cách tách và chuyển việc trong lúc dừng máy ra làm trước.","def_en":"A method of cutting changeover time below ten minutes by converting internal setup into external setup.","def_ja":"内段取りを外段取りに移すなどして、段取り時間を10分未満に短縮する手法。","usage_en":"Gần như luôn nói tắt SMED; 'single-minute' nghĩa là số phút một chữ số. Hay đi với: apply SMED, SMED workshop.","usage_ja":"Hay đi với 内段取り (việc làm khi máy dừng), 外段取り (việc làm khi máy chạy), ワンタッチ段取り.","context_vi":"Dùng ở máy dập, máy ép nhựa, máy CNC khi cần giảm cỡ lô và tăng linh hoạt.","ex_en":"Single-minute exchange of die reduced the die change from 90 to 8 minutes.","ex_ja":"シングル段取りの取り組みで、金型交換が90分から8分になった。","ex_vi":"Áp dụng SMED đã giảm thời gian thay khuôn từ 90 xuống 8 phút.","syn_en":["SMED","quick changeover"],"syn_ja":["SMED","段取り時間短縮 (liên quan)"]},{"en":"milk run","pos":"noun phrase","ipa":"/ˈmɪlk rʌn/","ja":"ミルクラン","kana":"ミルクラン","romaji":"mirukuran","vi":"vận chuyển theo tuyến cố định (milk run)","level":3,"def_vi":"Phương thức một xe chạy theo tuyến và giờ cố định để gom hàng từ nhiều nhà cung cấp hoặc cấp hàng cho nhiều trạm.","def_en":"A delivery method in which one vehicle follows a fixed route and timetable to collect from or supply many points.","def_ja":"一台の車両が決まった経路と時刻で複数の仕入先や工程を巡回し、集荷・供給する方式。","usage_en":"Danh từ đếm được. Hay đi với: milk run delivery, in-plant milk run, run a milk run every hour.","usage_ja":"Hay đi với ミルクラン方式, 巡回集荷, 定時巡回.","context_vi":"Dùng trong logistics đầu vào của nhà máy lắp ráp và cấp linh kiện nội bộ bằng xe kéo.","ex_en":"A milk run collects parts from six local suppliers twice a day.","ex_ja":"ミルクランで、近隣の仕入先6社から1日2回部品を集荷している。","ex_vi":"Xe chạy tuyến cố định gom linh kiện từ sáu nhà cung cấp địa phương hai lần mỗi ngày.","syn_en":["milk-run delivery","cyclic pickup"],"syn_ja":["巡回集荷","混載便 (gần nghĩa)"]},{"en":"water spider","pos":"noun phrase","ipa":"/ˈwɔːtə ˌspaɪdə/","ja":"水すまし","kana":"みずすまし","romaji":"mizusumashi","vi":"người cấp hàng định kỳ (water spider)","level":3,"def_vi":"Công nhân chuyên đi vòng theo chu kỳ cố định để cấp linh kiện và thu kanban, giúp công nhân chuyền không phải rời vị trí.","def_en":"A worker who circulates on a fixed cycle to supply parts and collect kanban so line operators never leave their stations.","def_ja":"一定周期でラインを巡回し部品供給とかんばん回収を行い、作業者が持ち場を離れずに済むようにする人。","usage_en":"Danh từ đếm được. Hay đi với: water spider route, assign a water spider; cũng gọi 'material handler', 'mizusumashi'.","usage_ja":"Tên lấy từ con bọ nước bơi vòng; hay đi với 水すまし作業, 水すましが巡回する.","context_vi":"Dùng ở dây chuyền lắp ráp áp dụng kanban và cấp hàng theo bộ.","ex_en":"The water spider refills each station every 20 minutes.","ex_ja":"水すましは20分ごとに各工程へ部品を補充する。","ex_vi":"Người cấp hàng định kỳ bổ sung linh kiện cho mỗi trạm 20 phút một lần.","syn_en":["mizusumashi","material handler"],"syn_ja":["ミズスマシ","部品供給係"]},{"en":"standard in-process stock","pos":"noun phrase","ipa":"/ˈstændəd ɪn ˈprəʊses stɒk/","ja":"標準手持ち","kana":"ひょうじゅんてもち","romaji":"hyoujuntemochi","vi":"lượng hàng chờ tiêu chuẩn","level":3,"def_vi":"Số lượng tối thiểu bán thành phẩm cần có trong dây chuyền, kể cả trong máy, để thao tác tiêu chuẩn diễn ra liên tục.","def_en":"The minimum work-in-process, including parts in machines, needed for standardized work to proceed smoothly.","def_ja":"標準作業を滞りなく行うために必要な、設備内を含む最小限の工程内仕掛品。","usage_en":"Danh từ không đếm được, viết tắt SWIP. Hay đi với: set the standard in-process stock, standard WIP.","usage_ja":"Là một trong ba yếu tố của 標準作業; hay đi với 標準手持ち数, 手持ち (khẩu ngữ).","context_vi":"Dùng khi lập bảng thao tác tiêu chuẩn và thiết kế cell sản xuất.","ex_en":"The standard in-process stock for this cell is one part in each machine.","ex_ja":"このセルの標準手持ちは各機械に1個である。","ex_vi":"Lượng hàng chờ tiêu chuẩn của cell này là một chi tiết trong mỗi máy.","syn_en":["standard WIP","SWIP"],"syn_ja":["標準仕掛","手持ち (khẩu ngữ)"]},{"en":"multi-process handling","pos":"noun phrase","ipa":"/ˌmʌlti ˈprəʊses ˈhændlɪŋ/","ja":"多工程持ち","kana":"たこうていもち","romaji":"takouteimochi","vi":"một người đứng nhiều công đoạn","level":3,"def_vi":"Cách bố trí để một công nhân lần lượt vận hành nhiều máy thuộc các công đoạn khác nhau theo trình tự gia công.","def_en":"An arrangement in which one operator runs several machines of different processes in processing order.","def_ja":"一人の作業者が、加工順に並んだ異なる工程の複数の設備を受け持つこと。","usage_en":"Danh từ không đếm được. Phân biệt với 'multi-machine handling' (nhiều máy cùng loại). Đi với multi-skilled operator.","usage_ja":"Phân biệt 多工程持ち với 多台持ち (nhiều máy cùng loại); cần 多能工 (công nhân đa năng).","context_vi":"Dùng trong cell sản xuất, xưởng gia công cơ khí áp dụng TPS để tăng năng suất lao động.","ex_en":"Multi-process handling lets one operator run the lathe, mill and washer in sequence.","ex_ja":"多工程持ちにより、一人で旋盤・フライス盤・洗浄機を順に担当できる。","ex_vi":"Nhờ một người đứng nhiều công đoạn, một công nhân vận hành lần lượt máy tiện, máy phay và máy rửa.","syn_en":["multi-process operation"],"syn_ja":["多台持ち (gần nghĩa)","多能工化 (liên quan)"]}]},{"id":49,"words":[{"en":"industrial robot","pos":"noun phrase","ipa":"/ɪnˌdʌstriəl ˈrəʊbɒt/","ja":"産業用ロボット","kana":"さんぎょうようロボット","romaji":"sangyouyourobotto","vi":"robot công nghiệp","level":1,"def_vi":"Tay máy điều khiển tự động, lập trình lại được, có từ ba trục trở lên, dùng trong sản xuất công nghiệp.","def_en":"An automatically controlled, reprogrammable manipulator with three or more axes, used in industrial production.","def_ja":"自動制御され再プログラム可能な3軸以上のマニピュレータで、産業の生産に使うもの。","usage_en":"Danh từ đếm được. Hay đi với: install / program / operate an industrial robot, industrial robot arm; thường nói gọn 'robot'.","usage_ja":"Ngoài xưởng nói gọn ロボット; trong luật an toàn Nhật (安衛則) dùng 産業用ロボット, cần 特別教育 để vận hành.","context_vi":"Dùng trong nhà máy ô tô, điện tử, kim loại, thực phẩm cho hàn, sơn, lắp ráp, bốc xếp.","ex_en":"The plant installed 40 industrial robots in the body shop.","ex_ja":"工場は車体工場に産業用ロボットを40台導入した。","ex_vi":"Nhà máy đã lắp đặt 40 robot công nghiệp ở xưởng thân xe.","syn_en":["robot","manipulator (gần nghĩa)"],"syn_ja":["ロボット","マニピュレータ (gần nghĩa)"]},{"en":"robot arm","pos":"noun phrase","ipa":"/ˈrəʊbɒt ɑːm/","ja":"ロボットアーム","kana":"ロボットアーム","romaji":"robottoaamu","vi":"cánh tay robot","level":1,"def_vi":"Phần cơ khí gồm các khâu nối với nhau bằng khớp, mang dụng cụ đến vị trí và hướng cần thiết.","def_en":"The mechanical structure of links and joints that moves the tool to the required position and orientation.","def_ja":"関節でつながったリンクからなり、ツールを必要な位置と姿勢へ運ぶ機械部分。","usage_en":"Danh từ đếm được; cũng viết 'robotic arm'. Hay đi với: robot arm reach, mount a gripper on the robot arm.","usage_ja":"Hay dùng trong ngôn ngữ chung; tài liệu kỹ thuật gọi アーム, 機構部, マニピュレータ.","context_vi":"Dùng khi mô tả cấu tạo robot, lắp dụng cụ, bố trí cell robot.","ex_en":"The robot arm reaches 1,400 mm from the base.","ex_ja":"このロボットアームはベースから1,400 mmまで届く。","ex_vi":"Cánh tay robot này với tới 1.400 mm tính từ đế.","syn_en":["robotic arm","manipulator"],"syn_ja":["アーム","マニピュレータ"]},{"en":"end effector","pos":"noun phrase","ipa":"/ˈend ɪˌfektə/","ja":"エンドエフェクタ","kana":"エンドエフェクタ","romaji":"endoefekuta","vi":"cơ cấu tác động cuối (dụng cụ đầu robot)","level":1,"def_vi":"Dụng cụ gắn ở mặt bích cuối cánh tay robot để thực hiện công việc, như tay kẹp, mỏ hàn, súng sơn.","def_en":"The tool fitted to the robot's wrist flange to do the work, such as a gripper, welding torch or spray gun.","def_ja":"ロボット手首のフランジに取り付け、作業を行うハンド・溶接トーチ・塗装ガンなどの装置。","usage_en":"Danh từ đếm được, viết tắt EOAT ('end-of-arm tooling'). Hay đi với: design / change the end effector.","usage_ja":"JIS gọi エンドエフェクタ; ngoài xưởng nói ハンド hoặc ツール. Hay đi với エンドエフェクタを交換する.","context_vi":"Dùng khi thiết kế cell robot, chọn dụng cụ phù hợp với chi tiết và công việc.","ex_en":"A new end effector was designed to pick two parts at once.","ex_ja":"2個同時に把持できる新しいエンドエフェクタを設計した。","ex_vi":"Một dụng cụ đầu robot mới được thiết kế để gắp hai chi tiết cùng lúc.","syn_en":["end-of-arm tooling (EOAT)","robot tool"],"syn_ja":["ハンド (khẩu ngữ)","ツール"]},{"en":"gripper","pos":"noun","ipa":"/ˈɡrɪpə/","ja":"グリッパ","kana":"グリッパ","romaji":"gurippa","vi":"tay kẹp (ngón kẹp robot)","level":1,"def_vi":"Dụng cụ đầu robot dùng các ngón kẹp đóng mở để nắm giữ và di chuyển chi tiết.","def_en":"An end effector with fingers or jaws that open and close to grasp and move parts.","def_ja":"指やつめを開閉して部品をつかみ、移動させるエンドエフェクタ。","usage_en":"Danh từ đếm được. Hay đi với: pneumatic / electric gripper, two-finger gripper, gripper fingers, open / close the gripper.","usage_ja":"Viết グリッパー cũng phổ biến; ngoài xưởng gọi ハンド, チャック. Ngón kẹp gọi つめ hoặc フィンガ.","context_vi":"Dùng khi robot gắp chi tiết vào máy CNC, lắp ráp, đóng gói.","ex_en":"The pneumatic gripper closes in 0.1 seconds.","ex_ja":"空圧式グリッパは0.1秒で閉じる。","ex_vi":"Tay kẹp khí nén đóng trong 0,1 giây.","syn_en":["robot hand","gripping device"],"syn_ja":["ロボットハンド","グリッパー"]},{"en":"teach pendant","pos":"noun phrase","ipa":"/ˈtiːtʃ ˌpendənt/","ja":"ティーチングペンダント","kana":"ティーチングペンダント","romaji":"tiichingupendanto","vi":"bảng dạy robot (teach pendant)","level":1,"def_vi":"Thiết bị cầm tay nối với bộ điều khiển, dùng để di chuyển robot, dạy điểm và chỉnh sửa chương trình.","def_en":"A handheld unit connected to the controller, used to jog the robot, teach points and edit programs.","def_ja":"制御装置につながる手持ち装置で、ロボットの手動操作・教示・プログラム編集に使う。","usage_en":"Danh từ đếm được, nói gọn 'pendant' hoặc 'TP'. Hay đi với: jog the robot with the teach pendant, enabling switch on the teach pendant.","usage_ja":"Ngoài xưởng gọi ペンダント hoặc TP; JIS gọi 教示ペンダント. Có イネーブルスイッチ (công tắc cho phép 3 vị trí).","context_vi":"Dùng khi dạy điểm, chạy thử, khắc phục lỗi robot ngay tại cell.","ex_en":"Hold the enabling switch on the teach pendant while jogging the robot.","ex_ja":"ロボットを手動で動かす間は、ティーチングペンダントのイネーブルスイッチを握っておく。","ex_vi":"Giữ công tắc cho phép trên bảng dạy robot trong khi di chuyển robot bằng tay.","syn_en":["pendant","TP"],"syn_ja":["教示ペンダント","ペンダント (khẩu ngữ)"]},{"en":"teaching","pos":"noun","ipa":"/ˈtiːtʃɪŋ/","ja":"ティーチング","kana":"ティーチング","romaji":"tiichingu","vi":"dạy robot (dạy điểm)","level":1,"def_vi":"Việc di chuyển robot đến các vị trí mong muốn và lưu lại để tạo chương trình chuyển động.","def_en":"Moving the robot to the desired positions and storing them to create a motion program.","def_ja":"ロボットを目的の位置へ動かして記憶させ、動作プログラムを作ること。","usage_en":"Danh từ không đếm được; động từ teach (teach a point, teach the robot). Hay đi với: online teaching, teaching mode.","usage_ja":"JIS dùng 教示; ngoài xưởng nói ティーチング, ティーチする. Hay đi với ティーチング作業, 教示点 (điểm dạy).","context_vi":"Dùng khi lập trình robot tại chỗ, sửa điểm khi đổi đồ gá hoặc mã hàng.","ex_en":"Teaching the new welding path took a whole shift.","ex_ja":"新しい溶接経路のティーチングに丸1直かかった。","ex_vi":"Việc dạy robot đường hàn mới mất trọn một ca.","syn_en":["robot teaching","online programming"],"syn_ja":["教示","ティーチ (khẩu ngữ)"]},{"en":"automation","pos":"noun","ipa":"/ˌɔːtəˈmeɪʃn/","ja":"自動化","kana":"じどうか","romaji":"jidouka","vi":"tự động hóa","level":1,"def_vi":"Việc dùng máy móc, robot và hệ thống điều khiển để thực hiện công việc thay con người.","def_en":"The use of machines, robots and control systems to perform tasks in place of people.","def_ja":"機械・ロボット・制御システムを使って、人に代わり作業を行わせること。","usage_en":"Danh từ không đếm được; tính từ automated, động từ automate. Hay đi với: factory automation (FA), level of automation, automation project.","usage_ja":"Hay đi với 自動化する, 自動化ライン, 省人化 (giảm người), FA (ファクトリーオートメーション).","context_vi":"Dùng khi đầu tư thiết bị, cải tiến năng suất, giảm thao tác nặng nhọc trong nhà máy.","ex_en":"Automation of the loading process freed two operators per shift.","ex_ja":"ローディング工程の自動化で、1直あたり作業者2名を削減できた。","ex_vi":"Tự động hóa công đoạn nạp phôi đã giải phóng hai công nhân mỗi ca.","syn_en":["factory automation (FA)","mechanization (gần nghĩa)"],"syn_ja":["オートメーション","省人化 (liên quan)"]},{"en":"safety fence","pos":"noun phrase","ipa":"/ˈseɪfti fens/","ja":"安全柵","kana":"あんぜんさく","romaji":"anzensaku","vi":"hàng rào an toàn","level":1,"def_vi":"Hàng rào bao quanh vùng làm việc của robot để ngăn người đi vào khi robot đang chạy tự động.","def_en":"A guard fence around the robot's working area that keeps people out while it runs automatically.","def_ja":"ロボットの動作範囲を囲い、自動運転中に人が入らないようにする柵。","usage_en":"Danh từ đếm được. Hay đi với: safety fence door, interlocked gate, inside / outside the safety fence; cũng gọi 'perimeter guarding'.","usage_ja":"Hay đi với 安全柵の扉, 安全柵内に入る, インターロック付き扉; còn gọi 安全フェンス.","context_vi":"Dùng khi thiết kế cell robot và đánh giá an toàn theo tiêu chuẩn ISO 10218.","ex_en":"Opening the safety fence door stops the robot immediately.","ex_ja":"安全柵の扉を開けると、ロボットは直ちに停止する。","ex_vi":"Mở cửa hàng rào an toàn thì robot dừng ngay lập tức.","syn_en":["perimeter guard","safety guard"],"syn_ja":["安全フェンス","防護柵"]},{"en":"robot controller","pos":"noun phrase","ipa":"/ˈrəʊbɒt kənˌtrəʊlə/","ja":"ロボットコントローラ","kana":"ロボットコントローラ","romaji":"robottokontoroora","vi":"tủ điều khiển robot","level":1,"def_vi":"Tủ chứa máy tính, bộ khuếch đại servo và mạch an toàn, điều khiển chuyển động và giao tiếp của robot.","def_en":"The cabinet containing the computer, servo amplifiers and safety circuits that control the robot's motion and I/O.","def_ja":"コンピュータ・サーボアンプ・安全回路を収め、ロボットの動作と入出力を制御する装置。","usage_en":"Danh từ đếm được. Hay đi với: robot controller cabinet, connect the PLC to the robot controller.","usage_ja":"JIS gọi ロボット制御装置; ngoài xưởng nói コントローラ, 制御盤. Viết コントローラー cũng gặp.","context_vi":"Dùng khi lắp đặt, đấu nối, bảo trì và cài đặt phần mềm cho robot.","ex_en":"The robot controller exchanges signals with the PLC over EtherNet/IP.","ex_ja":"ロボットコントローラはEtherNet/IPでPLCと信号をやり取りする。","ex_vi":"Tủ điều khiển robot trao đổi tín hiệu với PLC qua EtherNet/IP.","syn_en":["robot control unit","controller"],"syn_ja":["ロボット制御装置","コントローラ"]},{"en":"payload","pos":"noun","ipa":"/ˈpeɪləʊd/","ja":"可搬質量","kana":"かはんしつりょう","romaji":"kahanshitsuryou","vi":"tải trọng mang (tải trọng tay robot)","level":1,"def_vi":"Khối lượng lớn nhất robot có thể mang ở cổ tay, bao gồm cả dụng cụ và chi tiết.","def_en":"The maximum mass the robot can carry at its wrist, including the tool and the workpiece.","def_ja":"ロボットが手首部で運べる最大の質量で、ツールとワークの質量を含む。","usage_en":"Danh từ không đếm được. Hay đi với: a payload of 20 kg, rated payload, exceed the payload.","usage_ja":"Hay đi với 可搬質量20 kg, 可搬重量 (cách nói cũ); cũng nói ペイロード.","context_vi":"Dùng khi chọn model robot, kiểm tra tải gồm tay kẹp và chi tiết.","ex_en":"With the new gripper, the total load is close to the robot's 12 kg payload.","ex_ja":"新しいグリッパを付けると、総重量がロボットの可搬質量12 kgに近くなる。","ex_vi":"Khi lắp tay kẹp mới, tổng tải gần chạm tải trọng mang 12 kg của robot.","syn_en":["payload capacity","rated load"],"syn_ja":["可搬重量","ペイロード"]},{"en":"articulated robot","pos":"noun phrase","ipa":"/ɑːˌtɪkjuleɪtɪd ˈrəʊbɒt/","ja":"垂直多関節ロボット","kana":"すいちょくたかんせつロボット","romaji":"suichokutakansetsurobotto","vi":"robot khớp nối (robot nhiều khớp đứng)","level":2,"def_vi":"Robot có các khớp quay nối tiếp nhau, thường sáu trục, mô phỏng cánh tay người, linh hoạt nhất trong các loại.","def_en":"A robot with serial rotary joints, usually six axes, resembling a human arm and offering the greatest flexibility.","def_ja":"回転関節を直列につないだ、人の腕に似た通常6軸のロボットで、最も自由度が高い。","usage_en":"Danh từ đếm được. Hay đi với: six-axis articulated robot, vertical articulated robot.","usage_ja":"Ngoài xưởng hay gọi 6軸ロボット, 垂直多関節; đối chiếu với 水平多関節 (SCARA).","context_vi":"Dùng phổ biến cho hàn, sơn, bốc xếp máy CNC, lắp ráp chi tiết lớn.","ex_en":"A six-axis articulated robot loads the lathe and the milling machine.","ex_ja":"6軸の垂直多関節ロボットが旋盤とフライス盤にワークを供給する。","ex_vi":"Một robot khớp nối sáu trục cấp phôi cho máy tiện và máy phay.","syn_en":["six-axis robot","vertical articulated robot"],"syn_ja":["6軸ロボット","多関節ロボット"]},{"en":"SCARA robot","pos":"noun phrase","ipa":"/ˈskɑːrə ˌrəʊbɒt/","ja":"スカラロボット","kana":"スカラロボット","romaji":"sukararobotto","vi":"robot SCARA","level":2,"def_vi":"Robot có hai khớp quay theo phương ngang và một trục thẳng đứng, nhanh và chính xác cho thao tác lắp ráp trên mặt phẳng.","def_en":"A robot with two horizontal rotary joints and a vertical axis, fast and precise for planar assembly tasks.","def_ja":"水平方向の回転関節2つと上下軸を持ち、平面上の組立を高速・高精度に行うロボット。","usage_en":"Danh từ đếm được; SCARA = Selective Compliance Assembly Robot Arm. Hay đi với: four-axis SCARA robot, SCARA for pick and place.","usage_ja":"Còn gọi 水平多関節ロボット; ngoài xưởng nói スカラ. Hay đi với 4軸スカラ.","context_vi":"Dùng trong lắp ráp điện tử, gắp đặt linh kiện nhỏ, vặn vít tự động.","ex_en":"The SCARA robot inserts 60 connectors per minute.","ex_ja":"スカラロボットは毎分60個のコネクタを挿入する。","ex_vi":"Robot SCARA cắm 60 đầu nối mỗi phút.","syn_en":["horizontal articulated robot","SCARA"],"syn_ja":["水平多関節ロボット","スカラ"]},{"en":"Cartesian robot","pos":"noun phrase","ipa":"/kɑːˈtiːziən ˈrəʊbɒt/","ja":"直交ロボット","kana":"ちょっこうロボット","romaji":"chokkourobotto","vi":"robot tọa độ Descartes (robot trục thẳng)","level":2,"def_vi":"Robot có các trục chuyển động thẳng vuông góc X, Y, Z, cấu tạo đơn giản, dễ mở rộng hành trình.","def_en":"A robot whose axes move linearly along perpendicular X, Y and Z directions; simple and easy to extend.","def_ja":"X・Y・Zの直交する直線軸で動くロボットで、構造が簡単でストロークを伸ばしやすい。","usage_en":"Danh từ đếm được, viết hoa 'Cartesian'. Hay đi với: three-axis Cartesian robot; loại lớn treo trên cao gọi 'gantry robot'.","usage_ja":"Còn gọi 直交座標ロボット; loại treo trên khung gọi ガントリーローダ hoặc ガントリロボット.","context_vi":"Dùng cho bốc xếp, phân phối keo, cấp phôi máy ép, kiểm tra tự động.","ex_en":"A Cartesian robot removes parts from the injection molding machine.","ex_ja":"直交ロボットが射出成形機から成形品を取り出す。","ex_vi":"Một robot tọa độ Descartes lấy sản phẩm ra khỏi máy ép phun.","syn_en":["gantry robot (gần nghĩa)","linear robot"],"syn_ja":["直交座標ロボット","取出し機 (liên quan)"]},{"en":"collaborative robot","pos":"noun phrase","ipa":"/kəˈlæbərətɪv ˈrəʊbɒt/","ja":"協働ロボット","kana":"きょうどうロボット","romaji":"kyoudourobotto","vi":"robot cộng tác (cobot)","level":2,"def_vi":"Robot được thiết kế để làm việc gần hoặc cùng con người mà không cần hàng rào, nhờ giới hạn lực và tốc độ.","def_en":"A robot designed to work near or with people without fencing, thanks to force and speed limits.","def_ja":"力や速度を制限し、安全柵なしで人の近くや人と一緒に作業できるよう設計されたロボット。","usage_en":"Danh từ đếm được, khẩu ngữ 'cobot'. Hay đi với: deploy a collaborative robot, collaborative operation, cobot application.","usage_ja":"Chú ý chữ 協働 (きょうどう) khác 共同; hay đi với 協働ロボットを導入する, 人協働.","context_vi":"Dùng ở dây chuyền lắp ráp, đóng gói, kiểm tra nơi không gian hẹp và cần người cùng làm.","ex_en":"The collaborative robot tightens screws while the operator fits the cover.","ex_ja":"作業者がカバーを取り付ける間、協働ロボットがねじを締める。","ex_vi":"Robot cộng tác vặn vít trong khi công nhân lắp nắp.","syn_en":["cobot"],"syn_ja":["コボット","人協働ロボット"]},{"en":"work envelope","pos":"noun phrase","ipa":"/ˈwɜːk ˌenvələʊp/","ja":"動作範囲","kana":"どうさはんい","romaji":"dousahan'i","vi":"vùng làm việc (không gian hoạt động)","level":2,"def_vi":"Toàn bộ không gian mà cổ tay hoặc dụng cụ của robot có thể với tới khi các trục chuyển động hết hành trình.","def_en":"The whole space that the robot's wrist or tool can reach when all axes move through their ranges.","def_ja":"全軸が可動範囲いっぱいに動いたとき、ロボットの手首やツールが届く空間全体。","usage_en":"Danh từ đếm được. Hay đi với: within the work envelope, robot work envelope drawing; còn gọi 'working range', 'work space'.","usage_ja":"Hay đi với 動作範囲図, 動作範囲内に立ち入る, 最大動作範囲; cũng nói 可動範囲.","context_vi":"Dùng khi bố trí cell robot, tính khoảng cách an toàn và chọn model robot.","ex_en":"The conveyor must be placed inside the robot's work envelope.","ex_ja":"コンベヤはロボットの動作範囲内に配置しなければならない。","ex_vi":"Băng tải phải được đặt trong vùng làm việc của robot.","syn_en":["working range","work space"],"syn_ja":["可動範囲","作業領域"]},{"en":"tool center point","pos":"noun phrase","ipa":"/ˈtuːl ˌsentə pɔɪnt/","ja":"ツール先端点","kana":"ツールせんたんてん","romaji":"tsuurusentanten","vi":"điểm tâm dụng cụ (TCP)","level":2,"def_vi":"Điểm làm việc được định nghĩa trên dụng cụ, như đầu mỏ hàn, mà robot điều khiển vị trí và hướng của nó.","def_en":"The defined working point on the tool, such as a torch tip, whose position and orientation the robot controls.","def_ja":"溶接トーチの先端など、ロボットが位置と姿勢を制御するツール上の作業点。","usage_en":"Danh từ đếm được, viết tắt TCP; Anh viết 'centre'. Hay đi với: set / calibrate the TCP, TCP speed.","usage_ja":"Ngoài xưởng nói TCP; JIS gọi ツール中心点. Hay đi với TCP設定, TCPがずれる.","context_vi":"Dùng khi cài đặt dụng cụ mới, hiệu chỉnh mỏ hàn sau va chạm, lập trình đường chạy.","ex_en":"After the torch crash, the tool center point had to be re-taught.","ex_ja":"トーチの衝突後、ツール先端点を設定し直す必要があった。","ex_vi":"Sau khi mỏ hàn bị va chạm, phải dạy lại điểm tâm dụng cụ.","syn_en":["TCP","tool centre point (Anh)"],"syn_ja":["TCP","ツール中心点"]},{"en":"vacuum gripper","pos":"noun phrase","ipa":"/ˈvækjuːm ˌɡrɪpə/","ja":"真空吸着ハンド","kana":"しんくうきゅうちゃくハンド","romaji":"shinkuukyuuchakuhando","vi":"tay hút chân không","level":2,"def_vi":"Dụng cụ đầu robot dùng các giác hút và chân không để giữ chi tiết có bề mặt phẳng, nhẵn.","def_en":"An end effector that uses suction cups and vacuum to hold parts with flat, smooth surfaces.","def_ja":"吸着パッドと真空を利用し、平らで滑らかな面を持つ部品を保持するハンド。","usage_en":"Danh từ đếm được. Hay đi với: suction cup, vacuum generator / ejector, vacuum gripper for sheet metal.","usage_ja":"Ngoài xưởng nói 吸着ハンド, バキュームハンド; giác hút gọi 吸着パッド, tạo chân không bằng エジェクタ.","context_vi":"Dùng để gắp tấm thép, kính, thùng carton, bao bì trong dập, đóng gói, xếp hàng.","ex_en":"The vacuum gripper lost a panel because a suction cup was torn.","ex_ja":"吸着パッドが破れていたため、真空吸着ハンドがパネルを落とした。","ex_vi":"Tay hút chân không làm rơi tấm vì một giác hút bị rách.","syn_en":["suction gripper","vacuum cup gripper"],"syn_ja":["吸着ハンド","バキュームハンド"]},{"en":"palletizing","pos":"noun","ipa":"/ˈpælətaɪzɪŋ/","ja":"パレタイジング","kana":"パレタイジング","romaji":"paretaijingu","vi":"xếp hàng lên pallet","level":2,"def_vi":"Việc xếp thùng, bao hoặc sản phẩm lên pallet theo mẫu xếp lớp định sẵn, thường do robot thực hiện.","def_en":"Stacking boxes, bags or products onto a pallet in a set layer pattern, often done by a robot.","def_ja":"箱や袋、製品を決められた積付けパターンでパレットに積むこと。ロボットで行うことが多い。","usage_en":"Danh từ không đếm được; Anh viết palletising; ngược lại là depalletizing. Hay đi với: palletizing robot, palletizing pattern.","usage_ja":"Hay đi với パレタイジングロボット, 積付けパターン; ngược lại デパレタイジング. Văn bản cũng dùng パレット積み.","context_vi":"Dùng ở cuối dây chuyền đóng gói thực phẩm, đồ uống, xi măng, hóa chất.","ex_en":"Palletizing at the end of the line is done by a four-axis robot.","ex_ja":"ライン末端のパレタイジングは4軸ロボットで行っている。","ex_vi":"Việc xếp hàng lên pallet ở cuối dây chuyền do một robot bốn trục thực hiện.","syn_en":["pallet stacking","palletising (Anh)"],"syn_ja":["パレット積み","積付け"]},{"en":"pick and place","pos":"noun phrase","ipa":"/ˌpɪk ən ˈpleɪs/","ja":"ピックアンドプレース","kana":"ピックアンドプレース","romaji":"pikkuandopureesu","vi":"gắp và đặt","level":2,"def_vi":"Thao tác tự động lấy chi tiết từ một vị trí và đặt chính xác vào vị trí khác.","def_en":"The automatic operation of picking a part from one location and placing it accurately at another.","def_ja":"部品をある場所から取り出し、別の場所へ正確に置く自動動作。","usage_en":"Khi làm tính từ viết có gạch nối: pick-and-place robot / machine / application.","usage_ja":"Hay đi với ピックアンドプレース動作, ピック＆プレース; tiếng Nhật thuần: 取出し・移載.","context_vi":"Dùng trong lắp ráp điện tử, đóng gói, chuyển chi tiết giữa băng tải và máy.","ex_en":"A delta robot handles pick and place of chocolates at 150 picks per minute.","ex_ja":"パラレルリンクロボットが毎分150回でチョコレートのピックアンドプレースを行う。","ex_vi":"Một robot delta thực hiện gắp và đặt kẹo sô-cô-la với tốc độ 150 lần mỗi phút.","syn_en":["pick-and-place operation","transfer (gần nghĩa)"],"syn_ja":["移載","ピック＆プレース"]},{"en":"robot cell","pos":"noun phrase","ipa":"/ˈrəʊbɒt sel/","ja":"ロボットセル","kana":"ロボットセル","romaji":"robottoseru","vi":"trạm robot (cell robot)","level":2,"def_vi":"Khu vực làm việc gồm một hoặc nhiều robot cùng đồ gá, băng tải, thiết bị an toàn, thực hiện một công đoạn hoàn chỉnh.","def_en":"A work area of one or more robots with fixtures, conveyors and safety devices performing a complete operation.","def_ja":"1台以上のロボットと治具・コンベヤ・安全装置で構成され、一つの工程を完結する作業区画。","usage_en":"Danh từ đếm được. Hay đi với: welding robot cell, robot cell layout, turnkey robot cell.","usage_ja":"Hay đi với ロボットセルを構築する, 溶接セル; nhà tích hợp gọi システムインテグレータ (SIer).","context_vi":"Dùng khi thiết kế, báo giá và lắp đặt hệ thống robot cho nhà máy.","ex_en":"The welding robot cell has two turntables so loading and welding overlap.","ex_ja":"溶接のロボットセルにはターンテーブルが2台あり、段取りと溶接を並行できる。","ex_vi":"Trạm robot hàn có hai bàn xoay để việc gá phôi và hàn diễn ra song song.","syn_en":["robotic work cell","robot station"],"syn_ja":["ロボットシステム (nghĩa rộng hơn)","セル"]},{"en":"offline programming","pos":"noun phrase","ipa":"/ˌɒflaɪn ˈprəʊɡræmɪŋ/","ja":"オフラインティーチング","kana":"オフラインティーチング","romaji":"ofuraintiichingu","vi":"lập trình ngoại tuyến (offline)","level":2,"def_vi":"Lập trình robot trên máy tính bằng mô hình 3D và mô phỏng, không cần dừng robot thật.","def_en":"Programming a robot on a computer using 3D models and simulation, without stopping the real robot.","def_ja":"実機を止めずに、パソコン上で3Dモデルとシミュレーションを使ってロボットのプログラムを作ること。","usage_en":"Danh từ không đếm được, viết tắt OLP. Hay đi với: offline programming software, generate paths by offline programming.","usage_ja":"Viết tắt OLT hoặc OLP; còn gọi オフラインプログラミング. Đối lập với オンラインティーチング (dạy bằng pendant).","context_vi":"Dùng khi chuẩn bị chương trình cho dây chuyền mới, chi tiết phức tạp, giảm thời gian dừng máy.","ex_en":"Offline programming cut the robot downtime for the model change to two hours.","ex_ja":"オフラインティーチングにより、機種切替え時のロボット停止時間が2時間になった。","ex_vi":"Lập trình ngoại tuyến đã rút thời gian dừng robot khi đổi mẫu xuống hai giờ.","syn_en":["OLP","robot simulation (liên quan)"],"syn_ja":["オフラインプログラミング","OLP"]},{"en":"machine vision","pos":"noun phrase","ipa":"/məˈʃiːn ˈvɪʒn/","ja":"マシンビジョン","kana":"マシンビジョン","romaji":"mashinbijon","vi":"thị giác máy","level":2,"def_vi":"Hệ thống camera và phần mềm xử lý ảnh giúp máy hoặc robot nhận dạng, định vị và kiểm tra chi tiết.","def_en":"Camera and image-processing systems that let machines or robots identify, locate and inspect parts.","def_ja":"カメラと画像処理により、機械やロボットが部品の識別・位置決め・検査を行う技術。","usage_en":"Danh từ không đếm được. Hay đi với: machine vision system / camera, vision-guided robot.","usage_ja":"Ngoài xưởng hay nói 画像処理, ビジョン, カメラ; hay đi với 画像処理装置, ビジョンセンサ.","context_vi":"Dùng để robot xác định vị trí chi tiết, kiểm tra ngoại quan, đọc mã vạch, đếm sản phẩm.","ex_en":"Machine vision corrects the robot path for each part's position on the conveyor.","ex_ja":"マシンビジョンで、コンベヤ上の各ワークの位置に合わせてロボットの経路を補正する。","ex_vi":"Thị giác máy hiệu chỉnh đường đi của robot theo vị trí từng chi tiết trên băng tải.","syn_en":["vision system","robot vision"],"syn_ja":["画像処理","ビジョンセンサ (liên quan)"]},{"en":"welding robot","pos":"noun phrase","ipa":"/ˈweldɪŋ ˌrəʊbɒt/","ja":"溶接ロボット","kana":"ようせつロボット","romaji":"yousetsurobotto","vi":"robot hàn","level":2,"def_vi":"Robot mang mỏ hàn hoặc kìm hàn để thực hiện hàn hồ quang hoặc hàn điểm tự động.","def_en":"A robot carrying a welding torch or spot-welding gun to perform automatic arc or spot welding.","def_ja":"溶接トーチやスポット溶接ガンを持ち、アーク溶接やスポット溶接を自動で行うロボット。","usage_en":"Danh từ đếm được. Hay đi với: arc welding robot, spot welding robot, welding robot cell, program a welding robot.","usage_ja":"Hay phân loại アーク溶接ロボット, スポット溶接ロボット; đi với ポジショナ (bàn định vị), 溶接線.","context_vi":"Dùng ở xưởng thân xe ô tô, khung xe máy, kết cấu thép, máy nông nghiệp.","ex_en":"Each welding robot makes 35 spot welds on the floor panel.","ex_ja":"各溶接ロボットはフロアパネルに35点のスポット溶接を行う。","ex_vi":"Mỗi robot hàn thực hiện 35 điểm hàn trên tấm sàn.","syn_en":["robotic welder","arc welding robot (nghĩa hẹp hơn)"],"syn_ja":["アーク溶接ロボット (nghĩa hẹp hơn)","スポット溶接ロボット (nghĩa hẹp hơn)"]},{"en":"inverse kinematics","pos":"noun phrase","ipa":"/ˌɪnvɜːs ˌkɪnɪˈmætɪks/","ja":"逆運動学","kana":"ぎゃくうんどうがく","romaji":"gyakuundougaku","vi":"động học ngược","level":3,"def_vi":"Bài toán tính các góc khớp của robot từ vị trí và hướng mong muốn của dụng cụ.","def_en":"Calculating the robot's joint angles from the desired position and orientation of the tool.","def_ja":"ツールの目標位置・姿勢から、ロボットの各関節角度を求める計算。","usage_en":"Danh từ không đếm được, động từ đi theo số ít, viết tắt IK. Đối lập 'forward kinematics'. Hay đi với: solve the inverse kinematics.","usage_ja":"Hay đi với 逆運動学を解く, 逆運動学解, 順運動学 (động học thuận).","context_vi":"Dùng trong thiết kế bộ điều khiển robot, phần mềm mô phỏng và nghiên cứu robot.","ex_en":"The controller solves the inverse kinematics every 4 ms.","ex_ja":"コントローラは4 msごとに逆運動学を解いている。","ex_vi":"Bộ điều khiển giải bài toán động học ngược mỗi 4 ms.","syn_en":["IK","forward kinematics (trái nghĩa)"],"syn_ja":["逆キネマティクス","順運動学 (trái nghĩa)"]},{"en":"singularity","pos":"noun","ipa":"/ˌsɪŋɡjuˈlærəti/","ja":"特異点","kana":"とくいてん","romaji":"tokuiten","vi":"điểm kỳ dị","level":3,"def_vi":"Tư thế robot mất một bậc tự do, khiến một số khớp phải quay rất nhanh hoặc không xác định được nghiệm.","def_en":"A robot posture where a degree of freedom is lost, so some joints must rotate extremely fast or have no unique solution.","def_ja":"自由度が失われ、一部の関節が極端に速く回るか解が定まらなくなるロボットの姿勢。","usage_en":"Danh từ đếm được. Hay đi với: wrist singularity, pass through / avoid a singularity, singularity alarm.","usage_ja":"Hay đi với 特異点付近, 特異点を回避する, 特異点エラー; với robot 6 trục hay gặp 手首特異点.","context_vi":"Dùng khi lập trình đường chạy thẳng, gặp báo lỗi robot dừng hoặc khớp quay bất thường.","ex_en":"The linear move failed because the path passed through a wrist singularity.","ex_ja":"経路が手首の特異点を通るため、直線動作がエラーになった。","ex_vi":"Lệnh chạy thẳng bị lỗi vì đường đi đi qua điểm kỳ dị ở cổ tay.","syn_en":["singular configuration"],"syn_ja":["特異姿勢","シンギュラリティ"]},{"en":"tool coordinate system","pos":"noun phrase","ipa":"/ˈtuːl kəʊˈɔːdɪnət ˌsɪstəm/","ja":"ツール座標系","kana":"ツールざひょうけい","romaji":"tsuuruzahyoukei","vi":"hệ tọa độ dụng cụ","level":3,"def_vi":"Hệ tọa độ gắn với dụng cụ, gốc tại điểm tâm dụng cụ, dùng để di chuyển và lập trình theo hướng của dụng cụ.","def_en":"A coordinate system attached to the tool, with its origin at the TCP, used to move and program along the tool's axes.","def_ja":"ツールに固定され原点をTCPに置く座標系で、ツールの向きに沿った動作や教示に使う。","usage_en":"Danh từ đếm được; khẩu ngữ 'tool frame'. Đi cùng: base / world / user coordinate system; jog in the tool coordinate system.","usage_ja":"Hay đi với ツール座標系で動かす, ツール座標の設定; các hệ khác: ワールド座標系, ユーザ座標系.","context_vi":"Dùng khi cài dụng cụ mới, chạy tay robot theo hướng mỏ hàn, lập trình nghiêng dụng cụ.","ex_en":"Jog in the tool coordinate system to move straight along the torch axis.","ex_ja":"トーチの軸方向にまっすぐ動かすには、ツール座標系で手動送りする。","ex_vi":"Chạy tay trong hệ tọa độ dụng cụ để di chuyển thẳng theo trục mỏ hàn.","syn_en":["tool frame"],"syn_ja":["ツールフレーム","ユーザ座標系 (liên quan)"]},{"en":"force control","pos":"noun phrase","ipa":"/ˈfɔːs kənˌtrəʊl/","ja":"力制御","kana":"ちからせいぎょ","romaji":"chikaraseigyo","vi":"điều khiển lực","level":3,"def_vi":"Điều khiển robot dựa trên lực tiếp xúc đo bằng cảm biến lực, để lắp khít, mài, đánh bóng với lực ổn định.","def_en":"Controlling a robot from contact forces measured by a force sensor, for fitting, grinding or polishing at steady force.","def_ja":"力覚センサで測った接触力に基づきロボットを制御し、はめ込みや研磨を一定の力で行うこと。","usage_en":"Danh từ không đếm được. Hay đi với: force control function, force-controlled insertion, six-axis force sensor.","usage_ja":"Hay đi với 力覚センサ, 力制御による嵌合, 倣い動作 (bám theo bề mặt).","context_vi":"Dùng trong lắp ráp khe hở nhỏ, mài ba via, đánh bóng, kiểm tra lực lắp.","ex_en":"Force control lets the robot insert a shaft into a bore with 10 μm clearance.","ex_ja":"力制御により、ロボットはすき間10 μmの穴に軸を挿入できる。","ex_vi":"Điều khiển lực giúp robot lắp trục vào lỗ có khe hở 10 μm.","syn_en":["force-controlled motion","compliance control (gần nghĩa)"],"syn_ja":["力覚制御","インピーダンス制御 (gần nghĩa)"]},{"en":"hand-eye calibration","pos":"noun phrase","ipa":"/ˌhænd ˈaɪ ˌkælɪˈbreɪʃn/","ja":"ハンドアイキャリブレーション","kana":"ハンドアイキャリブレーション","romaji":"handoaikyaribureeshon","vi":"hiệu chuẩn tay–mắt","level":3,"def_vi":"Xác định quan hệ vị trí giữa camera và robot để chuyển tọa độ trong ảnh thành tọa độ robot.","def_en":"Finding the geometric relationship between camera and robot so image coordinates convert into robot coordinates.","def_ja":"カメラとロボットの位置関係を求め、画像上の座標をロボット座標に変換できるようにすること。","usage_en":"Danh từ không đếm được. Hay đi với: perform hand-eye calibration, eye-in-hand / eye-to-hand setup, calibration plate.","usage_ja":"Ngoài xưởng nói gọn キャリブレーション; hay đi với キャリブレーションプレート, カメラ座標, ロボット座標.","context_vi":"Dùng khi lắp đặt robot có camera để gắp chi tiết, sau khi camera bị dịch chuyển.","ex_en":"Hand-eye calibration must be repeated whenever the camera bracket is moved.","ex_ja":"カメラのブラケットを動かしたら、ハンドアイキャリブレーションをやり直す必要がある。","ex_vi":"Phải hiệu chuẩn tay–mắt lại mỗi khi giá đỡ camera bị dịch chuyển.","syn_en":["camera-robot calibration","vision calibration"],"syn_ja":["カメラキャリブレーション (gần nghĩa)","座標合わせ"]},{"en":"bin picking","pos":"noun phrase","ipa":"/ˈbɪn ˌpɪkɪŋ/","ja":"バラ積みピッキング","kana":"バラづみピッキング","romaji":"barazumipikkingu","vi":"gắp chi tiết xếp lộn xộn trong thùng","level":3,"def_vi":"Việc robot dùng thị giác 3D nhận dạng và gắp từng chi tiết nằm ngẫu nhiên, chồng chéo trong thùng.","def_en":"A robot using 3D vision to recognize and pick individual parts lying randomly piled in a bin.","def_ja":"3次元ビジョンでコンテナ内に無秩序に積まれた部品を認識し、ロボットが一つずつ取り出すこと。","usage_en":"Danh từ không đếm được; đầy đủ 'random bin picking'. Hay đi với: bin picking system, 3D vision for bin picking.","usage_ja":"Hay đi với バラ積み取出し, 3Dビジョン, 干渉チェック; viết ばら積み cũng gặp.","context_vi":"Dùng ở khâu cấp phôi rèn, đúc, chi tiết dập cho máy gia công mà không cần sắp xếp trước.","ex_en":"Bin picking removed the need to arrange forgings on trays by hand.","ex_ja":"バラ積みピッキングにより、鍛造品を手でトレイに並べる作業が不要になった。","ex_vi":"Nhờ robot gắp chi tiết lộn xộn trong thùng, không còn phải xếp phôi rèn lên khay bằng tay.","syn_en":["random bin picking"],"syn_ja":["バラ積み取出し","ばら積みピッキング"]},{"en":"power and force limiting","pos":"noun phrase","ipa":"/ˌpaʊər ən ˈfɔːs ˈlɪmɪtɪŋ/","ja":"動力及び力の制限","kana":"どうりょくおよびちからのせいげん","romaji":"douryokuoyobichikaranoseigen","vi":"giới hạn công suất và lực (PFL)","level":3,"def_vi":"Chế độ cộng tác an toàn trong đó robot giới hạn công suất và lực tiếp xúc để va chạm với người không gây thương tích.","def_en":"A collaborative safety mode in which the robot limits power and contact force so that contact with a person causes no injury.","def_ja":"ロボットの動力と接触力を制限し、人と接触してもけがをさせないようにする協働運転方式。","usage_en":"Danh từ không đếm được, viết tắt PFL; là một trong bốn chế độ cộng tác theo ISO 10218 / ISO/TS 15066.","usage_ja":"Thuật ngữ trong JIS B 8433 (ISO 10218); ngoài xưởng nói 力制限, 接触停止. Hay đi với 許容接触力.","context_vi":"Dùng khi đánh giá rủi ro và thiết kế ứng dụng robot cộng tác không có hàng rào.","ex_en":"The cobot application relies on power and force limiting, so the contact force must be measured.","ex_ja":"この協働用途は動力及び力の制限に依存しているため、接触力を測定しなければならない。","ex_vi":"Ứng dụng cobot này dựa vào giới hạn công suất và lực nên phải đo lực tiếp xúc.","syn_en":["PFL","speed and separation monitoring (liên quan)"],"syn_ja":["力制限","協働運転 (nghĩa rộng hơn)"]}]},{"id":50,"words":[{"en":"maintenance","pos":"noun","ipa":"/ˈmeɪntənəns/","ja":"保全","kana":"ほぜん","romaji":"hozen","vi":"bảo trì","level":1,"def_vi":"Mọi hoạt động kiểm tra, chăm sóc, sửa chữa nhằm giữ thiết bị ở trạng thái làm việc tốt hoặc khôi phục khi hỏng.","def_en":"All activities of inspecting, servicing and repairing equipment to keep it in, or restore it to, working condition.","def_ja":"設備を使用可能な状態に保ち、または故障から回復させるための点検・手入れ・修理の活動。","usage_en":"Danh từ không đếm được (không nói 'a maintenance'). Hay đi với: carry out / perform maintenance, maintenance department, under maintenance.","usage_ja":"Văn bản và tên phòng dùng 保全 (保全課, 設備保全); khẩu ngữ hay nói メンテ, メンテナンス. Hay đi với 保全する, 保全作業.","context_vi":"Dùng hằng ngày ở mọi nhà máy, chỉ cả hoạt động lẫn bộ phận bảo trì thiết bị.","ex_en":"The press is shut down every Sunday for maintenance.","ex_ja":"プレス機は毎週日曜日に保全のため停止する。","ex_vi":"Máy dập được dừng vào mỗi Chủ nhật để bảo trì.","syn_en":["upkeep","servicing (gần nghĩa)"],"syn_ja":["メンテナンス","メンテ (khẩu ngữ)"]},{"en":"inspection","pos":"noun","ipa":"/ɪnˈspekʃn/","ja":"点検","kana":"てんけん","romaji":"tenken","vi":"kiểm tra (thiết bị)","level":1,"def_vi":"Việc xem xét, nghe, đo thiết bị theo hạng mục định sẵn để phát hiện sớm bất thường và hư hỏng.","def_en":"Checking equipment by looking, listening and measuring against set items to find abnormalities early.","def_ja":"決められた項目に従い、見る・聞く・測るなどして設備の異常を早期に見つけること。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: carry out an inspection, inspection checklist, routine inspection.","usage_ja":"Phân biệt 点検 (kiểm tra thiết bị trong bảo trì) với 検査 (kiểm tra sản phẩm). Hay đi với 点検する, 点検表, 点検項目.","context_vi":"Dùng trong lịch bảo trì, phiếu kiểm tra thiết bị, quy định an toàn máy nâng, nồi hơi.","ex_en":"The inspection found a cracked hose on the hydraulic unit.","ex_ja":"点検で油圧ユニットのホースに亀裂が見つかった。","ex_vi":"Đợt kiểm tra phát hiện một ống mềm bị nứt trên bộ nguồn thủy lực.","syn_en":["check","examination"],"syn_ja":["チェック","検査 (khác nghĩa, liên quan)"]},{"en":"daily inspection","pos":"noun phrase","ipa":"/ˌdeɪli ɪnˈspekʃn/","ja":"日常点検","kana":"にちじょうてんけん","romaji":"nichijoutenken","vi":"kiểm tra hằng ngày","level":1,"def_vi":"Kiểm tra đơn giản do người vận hành thực hiện trước hoặc trong ca, như mức dầu, áp suất, tiếng ồn, rò rỉ.","def_en":"Simple checks done by the operator before or during each shift, such as oil level, pressure, noise and leaks.","def_ja":"作業者が始業前や稼働中に行う、油量・圧力・音・漏れなどの簡単な点検。","usage_en":"Danh từ đếm được. Hay đi với: daily inspection sheet / checklist, pre-shift check; gần nghĩa 'start-up check'.","usage_ja":"Hay đi với 日常点検表, 始業点検 (kiểm tra đầu ca); là một phần của 自主保全.","context_vi":"Dùng ở máy công cụ, xe nâng, máy nén khí, cầu trục; phiếu kiểm tra dán cạnh máy.","ex_en":"The daily inspection sheet must be signed before the machine is started.","ex_ja":"機械を起動する前に、日常点検表に署名しなければならない。","ex_vi":"Phải ký phiếu kiểm tra hằng ngày trước khi khởi động máy.","syn_en":["pre-shift check","start-up check"],"syn_ja":["始業点検","日々点検"]},{"en":"repair","pos":"noun","ipa":"/rɪˈpeə/","ja":"修理","kana":"しゅうり","romaji":"shuuri","vi":"sửa chữa","level":1,"def_vi":"Việc khắc phục hư hỏng để thiết bị hoặc chi tiết hoạt động trở lại bình thường.","def_en":"Work done to fix a fault so that equipment or a part works normally again.","def_ja":"故障や損傷を直し、設備や部品を再び正常に使えるようにすること。","usage_en":"Danh từ đếm được và cũng là động từ: carry out repairs, repair a leak, under repair, beyond repair.","usage_ja":"Động từ 修理する; trong JIS bảo trì còn gặp 修復. Khẩu ngữ: 直す.","context_vi":"Dùng khi máy hỏng, trong phiếu yêu cầu sửa chữa và báo cáo bảo trì.","ex_en":"The repair of the spindle took three days because a bearing had to be ordered.","ex_ja":"軸受を手配する必要があったため、主軸の修理に3日かかった。","ex_vi":"Việc sửa chữa trục chính mất ba ngày vì phải đặt mua ổ bi.","syn_en":["fix (khẩu ngữ)","restoration"],"syn_ja":["修復","補修 (gần nghĩa)"]},{"en":"spare part","pos":"noun phrase","ipa":"/ˌspeə ˈpɑːt/","ja":"予備品","kana":"よびひん","romaji":"yobihin","vi":"phụ tùng thay thế (phụ tùng dự phòng)","level":1,"def_vi":"Chi tiết được giữ sẵn trong kho để thay thế nhanh khi chi tiết tương ứng trên máy bị hỏng hoặc mòn.","def_en":"A part kept in stock to replace a failed or worn part on a machine quickly.","def_ja":"設備の部品が故障・摩耗したときにすぐ交換できるよう、在庫しておく部品。","usage_en":"Danh từ đếm được, hay dùng số nhiều 'spare parts' hoặc nói gọn 'spares'. Hay đi với: critical spare parts, spare parts list.","usage_ja":"Hay đi với 予備品管理, 予備品リスト; cũng nói スペアパーツ, 補修部品 (phụ tùng cho khách hàng).","context_vi":"Dùng trong quản lý kho bảo trì, lập danh mục phụ tùng quan trọng cho từng máy.","ex_en":"Keep at least one spare part for every critical motor.","ex_ja":"重要なモータには最低1台の予備品を持っておくこと。","ex_vi":"Hãy giữ ít nhất một phụ tùng dự phòng cho mỗi động cơ quan trọng.","syn_en":["spares","replacement part"],"syn_ja":["スペアパーツ","補修部品"]},{"en":"downtime","pos":"noun","ipa":"/ˈdaʊntaɪm/","ja":"ダウンタイム","kana":"ダウンタイム","romaji":"dauntaimu","vi":"thời gian dừng máy","level":1,"def_vi":"Khoảng thời gian thiết bị không thể sản xuất do hỏng, sửa chữa, bảo trì hoặc chờ phụ tùng.","def_en":"The time during which equipment cannot produce because of failure, repair, maintenance or waiting for parts.","def_ja":"故障・修理・保全・部品待ちなどにより、設備が生産できない時間。","usage_en":"Danh từ không đếm được. Hay đi với: reduce downtime, unplanned / planned downtime, two hours of downtime.","usage_ja":"Tiếng Nhật thuần: 停止時間, 故障停止時間. Hay đi với ダウンタイム削減, 計画停止.","context_vi":"Dùng trong báo cáo bảo trì, tính hiệu suất thiết bị và đánh giá chi phí hỏng hóc.","ex_en":"Unplanned downtime on the line fell by 30% after the new PM program.","ex_ja":"新しい予防保全計画の後、ラインの計画外のダウンタイムが30%減った。","ex_vi":"Thời gian dừng máy ngoài kế hoạch của dây chuyền giảm 30% sau chương trình bảo trì phòng ngừa mới.","syn_en":["outage","stoppage time"],"syn_ja":["停止時間","故障停止時間"]},{"en":"greasing","pos":"noun","ipa":"/ˈɡriːsɪŋ/","ja":"給脂","kana":"きゅうし","romaji":"kyuushi","vi":"tra mỡ (bơm mỡ)","level":1,"def_vi":"Việc bơm hoặc bôi mỡ bôi trơn vào ổ trục, khớp, ray trượt theo chu kỳ quy định.","def_en":"Applying or pumping grease into bearings, joints and slides at specified intervals.","def_ja":"決められた周期で、軸受・関節・しゅう動部にグリースを注入または塗布すること。","usage_en":"Danh từ không đếm được; động từ grease. Hay đi với: grease gun, grease nipple, greasing interval, over-greasing.","usage_ja":"Ngoài xưởng hay nói グリースアップ, グリスを入れる; dụng cụ グリースガン, vú mỡ グリースニップル. Tra dầu gọi 給油.","context_vi":"Dùng trong lịch bảo trì định kỳ của quạt, bơm, băng tải, cầu trục, máy xây dựng.","ex_en":"Greasing the fan bearings every 500 hours is part of the PM checklist.","ex_ja":"500時間ごとのファン軸受への給脂は予防保全チェックリストに入っている。","ex_vi":"Tra mỡ ổ trục quạt mỗi 500 giờ là một mục trong danh sách bảo trì phòng ngừa.","syn_en":["grease lubrication","grease-up (khẩu ngữ)"],"syn_ja":["グリースアップ","給油 (liên quan, cho dầu)"]},{"en":"overhaul","pos":"noun","ipa":"/ˈəʊvəhɔːl/","ja":"オーバーホール","kana":"オーバーホール","romaji":"oobaahooru","vi":"đại tu","level":1,"def_vi":"Tháo rời toàn bộ thiết bị, kiểm tra, thay chi tiết mòn rồi lắp lại để khôi phục gần như mới.","def_en":"Completely dismantling equipment, inspecting it, replacing worn parts and reassembling it to near-new condition.","def_ja":"設備を全分解して点検し、摩耗部品を交換して再組立し、新品に近い状態に戻すこと。","usage_en":"Danh từ đếm được và động từ (overhaul an engine; nhấn âm khác nhau). Hay đi với: major overhaul, overhaul interval.","usage_ja":"Viết tắt OH; hay đi với オーバーホールする, 定期オーバーホール; văn bản dùng 分解整備.","context_vi":"Dùng cho động cơ, hộp số, máy nén, bơm, tua bin theo chu kỳ vài năm một lần.","ex_en":"The compressor overhaul is scheduled during the summer shutdown.","ex_ja":"コンプレッサのオーバーホールは夏季休業中に予定している。","ex_vi":"Việc đại tu máy nén được lên lịch trong đợt nghỉ hè.","syn_en":["major service","rebuild (gần nghĩa)"],"syn_ja":["分解整備","OH"]},{"en":"maintenance record","pos":"noun phrase","ipa":"/ˈmeɪntənəns ˌrekɔːd/","ja":"保全記録","kana":"ほぜんきろく","romaji":"hozenkiroku","vi":"hồ sơ bảo trì (nhật ký bảo trì)","level":1,"def_vi":"Tài liệu ghi lại các lần kiểm tra, sửa chữa, thay thế, nguyên nhân hỏng và thời gian dừng của từng thiết bị.","def_en":"A document recording each inspection, repair, replacement, cause of failure and downtime for a machine.","def_ja":"設備ごとの点検・修理・交換・故障原因・停止時間などを記録したもの。","usage_en":"Danh từ đếm được, hay dùng số nhiều. Hay đi với: keep / update maintenance records, maintenance log, equipment history.","usage_ja":"Hay đi với 保全記録を残す, 設備履歴, 故障記録; nhiều nơi quản lý trên hệ thống CMMS.","context_vi":"Dùng để phân tích hỏng lặp lại, lập kế hoạch bảo trì và khi đánh giá ISO, khách hàng.","ex_en":"The maintenance record showed the same valve had been replaced four times.","ex_ja":"保全記録から、同じバルブが4回交換されていたことが分かった。","ex_vi":"Hồ sơ bảo trì cho thấy cùng một van đã bị thay bốn lần.","syn_en":["maintenance log","equipment history"],"syn_ja":["設備履歴","保全履歴"]},{"en":"consumable","pos":"noun","ipa":"/kənˈsjuːməbl/","ja":"消耗品","kana":"しょうもうひん","romaji":"shoumouhin","vi":"vật tư tiêu hao","level":1,"def_vi":"Vật tư hoặc chi tiết bị mòn, hết theo thời gian sử dụng và phải thay định kỳ, như lọc, dây đai, gioăng.","def_en":"A material or part that wears out or is used up in service and is replaced regularly, such as filters or belts.","def_ja":"使用により摩耗・消費され、定期的に交換するフィルタ・ベルト・パッキンなどの品。","usage_en":"Danh từ đếm được, thường dùng số nhiều 'consumables'. Hay đi với: replace consumables, consumable parts, wear parts.","usage_ja":"Hay đi với 消耗品の交換, 消耗部品, 定期交換部品.","context_vi":"Dùng khi lập danh mục vật tư bảo trì, ngân sách và kế hoạch thay thế định kỳ.","ex_en":"Filters and V-belts are treated as a consumable and replaced every six months.","ex_ja":"フィルタとVベルトは消耗品として6か月ごとに交換する。","ex_vi":"Lọc và dây đai thang được coi là vật tư tiêu hao và thay mỗi sáu tháng.","syn_en":["wear part","expendable"],"syn_ja":["消耗部品","定期交換部品"]},{"en":"preventive maintenance","pos":"noun phrase","ipa":"/prɪˌventɪv ˈmeɪntənəns/","ja":"予防保全","kana":"よぼうほぜん","romaji":"yobouhozen","vi":"bảo trì phòng ngừa","level":2,"def_vi":"Bảo trì có kế hoạch trước khi hỏng, như kiểm tra, thay thế định kỳ, để giảm xác suất xảy ra hỏng hóc.","def_en":"Planned maintenance done before failure, such as scheduled inspection and replacement, to reduce the chance of breakdown.","def_ja":"故障が起きる前に、計画的な点検や定期交換を行って故障の発生を防ぐ保全。","usage_en":"Danh từ không đếm được, viết tắt PM. Hay đi với: preventive maintenance schedule / program; Mỹ cũng nói 'preventative maintenance'.","usage_ja":"Viết tắt PM; gồm 時間基準保全 và 状態基準保全. Hay đi với 予防保全計画, 予防保全を実施する.","context_vi":"Dùng khi lập kế hoạch bảo trì năm, tháng cho thiết bị quan trọng.","ex_en":"Preventive maintenance on the conveyor drives is done every quarter.","ex_ja":"コンベヤ駆動部の予防保全は四半期ごとに行う。","ex_vi":"Bảo trì phòng ngừa bộ truyền động băng tải được thực hiện mỗi quý.","syn_en":["PM","preventative maintenance"],"syn_ja":["PM","計画保全 (gần nghĩa)"]},{"en":"breakdown maintenance","pos":"noun phrase","ipa":"/ˈbreɪkdaʊn ˌmeɪntənəns/","ja":"事後保全","kana":"じごほぜん","romaji":"jigohozen","vi":"bảo trì sự cố (sửa khi hỏng)","level":2,"def_vi":"Cách bảo trì chỉ sửa chữa sau khi thiết bị đã hỏng, phù hợp với thiết bị rẻ, ít ảnh hưởng đến sản xuất.","def_en":"Maintenance carried out only after equipment has failed; suited to cheap or non-critical equipment.","def_ja":"設備が故障してから修理する保全方式で、安価で生産への影響が小さい設備に適する。","usage_en":"Danh từ không đếm được, viết tắt BM. Hay đi với: rely on breakdown maintenance, run-to-failure; đối lập preventive maintenance.","usage_ja":"Viết tắt BM; đối lập 予防保全. Khi chọn có chủ đích gọi là 事後保全方式.","context_vi":"Dùng khi phân loại chiến lược bảo trì cho từng thiết bị theo mức độ quan trọng.","ex_en":"Breakdown maintenance is acceptable for the office fans but not for the main press.","ex_ja":"事務所の扇風機は事後保全でよいが、主力プレスはそうはいかない。","ex_vi":"Bảo trì sự cố chấp nhận được với quạt văn phòng nhưng không được với máy dập chính.","syn_en":["BM","run-to-failure"],"syn_ja":["BM","故障修理 (gần nghĩa)"]},{"en":"periodic inspection","pos":"noun phrase","ipa":"/ˌpɪəriɒdɪk ɪnˈspekʃn/","ja":"定期点検","kana":"ていきてんけん","romaji":"teikitenken","vi":"kiểm tra định kỳ","level":2,"def_vi":"Kiểm tra chi tiết theo chu kỳ cố định như hằng tháng, hằng năm, thường do bộ phận bảo trì hoặc theo luật quy định.","def_en":"Detailed inspection at fixed intervals, such as monthly or yearly, by maintenance staff or as required by law.","def_ja":"月次・年次など一定周期で、保全担当や法令に基づいて行う詳しい点検。","usage_en":"Danh từ đếm được. Hay đi với: annual periodic inspection, statutory inspection, carry out a periodic inspection.","usage_ja":"Hay đi với 年次点検, 月次点検, 特定自主検査 (kiểm tra bắt buộc theo luật cho xe nâng, máy dập).","context_vi":"Dùng cho cầu trục, xe nâng, nồi hơi, bình áp lực, máy dập theo quy định an toàn.","ex_en":"The overhead crane failed its periodic inspection because of a worn hook.","ex_ja":"天井クレーンはフックの摩耗で定期点検に不合格となった。","ex_vi":"Cầu trục không đạt kiểm tra định kỳ vì móc bị mòn.","syn_en":["scheduled inspection","statutory inspection (theo luật)"],"syn_ja":["定期検査","年次点検 (nghĩa hẹp hơn)"]},{"en":"maintenance interval","pos":"noun phrase","ipa":"/ˈmeɪntənəns ˌɪntəvl/","ja":"保全周期","kana":"ほぜんしゅうき","romaji":"hozenshuuki","vi":"chu kỳ bảo trì","level":2,"def_vi":"Khoảng thời gian hoặc số giờ chạy giữa hai lần thực hiện cùng một công việc bảo trì.","def_en":"The time or operating hours between two performances of the same maintenance task.","def_ja":"同じ保全作業を行ってから次に行うまでの時間または稼働時間。","usage_en":"Danh từ đếm được. Hay đi với: extend / shorten the maintenance interval, service interval of 2,000 hours.","usage_ja":"Ngoài xưởng hay nói 点検周期, 交換周期; hay đi với 周期を延ばす, 周期を見直す.","context_vi":"Dùng khi lập kế hoạch bảo trì phòng ngừa và tối ưu chi phí bảo trì.","ex_en":"Oil analysis allowed us to extend the maintenance interval of the gearbox.","ex_ja":"油分析の結果、減速機の保全周期を延ばすことができた。","ex_vi":"Phân tích dầu cho phép kéo dài chu kỳ bảo trì của hộp giảm tốc.","syn_en":["service interval","inspection interval"],"syn_ja":["点検周期","交換周期"]},{"en":"time-based maintenance","pos":"noun phrase","ipa":"/ˌtaɪm beɪst ˈmeɪntənəns/","ja":"時間基準保全","kana":"じかんきじゅんほぜん","romaji":"jikankijunhozen","vi":"bảo trì theo thời gian","level":2,"def_vi":"Bảo trì phòng ngừa thực hiện theo chu kỳ thời gian hoặc giờ chạy cố định, bất kể tình trạng thực tế của thiết bị.","def_en":"Preventive maintenance done at fixed time or operating-hour intervals, regardless of actual condition.","def_ja":"設備の実際の状態にかかわらず、一定の時間や稼働時間ごとに行う予防保全。","usage_en":"Danh từ không đếm được, viết tắt TBM. Đối lập 'condition-based maintenance'. Hay đi với: TBM schedule.","usage_ja":"Viết tắt TBM; hay gặp 定期保全 cùng nghĩa. Đối lập 状態基準保全 (CBM).","context_vi":"Dùng cho chi tiết có tuổi thọ dễ dự đoán như lọc, dầu, dây đai, hoặc khi luật yêu cầu.","ex_en":"Time-based maintenance replaces the hydraulic oil every 4,000 hours.","ex_ja":"時間基準保全として、作動油を4,000時間ごとに交換している。","ex_vi":"Theo bảo trì theo thời gian, dầu thủy lực được thay mỗi 4.000 giờ.","syn_en":["TBM","periodic maintenance"],"syn_ja":["TBM","定期保全"]},{"en":"corrective maintenance","pos":"noun phrase","ipa":"/kəˌrektɪv ˈmeɪntənəns/","ja":"改良保全","kana":"かいりょうほぜん","romaji":"kairyouhozen","vi":"bảo trì cải tiến","level":2,"def_vi":"Cải tạo thiết bị để loại bỏ nguyên nhân hỏng lặp lại, kéo dài tuổi thọ hoặc làm cho việc bảo trì dễ hơn.","def_en":"Modifying equipment to remove the cause of repeated failures, extend life or make maintenance easier.","def_ja":"繰り返す故障の原因をなくし、寿命を延ばしたり保全をしやすくしたりするための設備の改良。","usage_en":"Danh từ không đếm được, viết tắt CM. Lưu ý: trong tiêu chuẩn EN 13306, 'corrective maintenance' còn có nghĩa là sửa sau khi hỏng; theo TPM nó là cải tiến.","usage_ja":"Viết tắt CM theo phân loại TPM (BM, PM, CM, MP). Hay đi với 改良保全を行う, 再発防止.","context_vi":"Dùng khi phân tích hỏng lặp lại và quyết định cải tạo thiết bị thay vì chỉ sửa.","ex_en":"Corrective maintenance replaced the plastic gear with a steel one after five failures.","ex_ja":"5回の故障を受けて、改良保全で樹脂歯車を鋼製に変更した。","ex_vi":"Sau năm lần hỏng, bảo trì cải tiến đã thay bánh răng nhựa bằng bánh răng thép.","syn_en":["CM","improvement maintenance"],"syn_ja":["CM","改善保全"]},{"en":"autonomous maintenance","pos":"noun phrase","ipa":"/ɔːˈtɒnəməs ˈmeɪntənəns/","ja":"自主保全","kana":"じしゅほぜん","romaji":"jishuhozen","vi":"bảo trì tự quản","level":2,"def_vi":"Hoạt động trong TPM, người vận hành tự làm vệ sinh, kiểm tra, tra dầu, siết chặt và phát hiện bất thường trên máy của mình.","def_en":"A TPM activity in which operators clean, inspect, lubricate and tighten their own machines and spot abnormalities.","def_ja":"TPMの柱の一つで、作業者が自分の設備の清掃・点検・給油・増締めを行い異常を見つける活動。","usage_en":"Danh từ không đếm được, viết tắt AM; cũng giữ từ Nhật 'jishu hozen'. Hay đi với: autonomous maintenance step, AM board.","usage_ja":"Hay đi với 自主保全活動, 自主保全7ステップ, 初期清掃, 増締め; phân biệt với 専門保全 (bảo trì chuyên môn).","context_vi":"Dùng ở nhà máy triển khai TPM, nơi công nhân vận hành tham gia bảo trì cơ bản.","ex_en":"Autonomous maintenance starts with a thorough initial cleaning of the machine.","ex_ja":"自主保全は設備の徹底した初期清掃から始める。","ex_vi":"Bảo trì tự quản bắt đầu bằng việc vệ sinh ban đầu kỹ lưỡng cho máy.","syn_en":["AM","jishu hozen"],"syn_ja":["AM","専門保全 (liên quan)"]},{"en":"total productive maintenance","pos":"noun phrase","ipa":"/ˌtəʊtl prəˌdʌktɪv ˈmeɪntənəns/","ja":"TPM","kana":"ティーピーエム","romaji":"tiipiiemu","vi":"bảo trì năng suất toàn diện (TPM)","level":2,"def_vi":"Hệ thống quản lý thiết bị với sự tham gia của mọi người, từ lãnh đạo đến công nhân, nhằm đạt không hỏng, không lỗi, không tai nạn.","def_en":"A company-wide equipment management system involving everyone, aiming for zero breakdowns, defects and accidents.","def_ja":"経営者から作業者まで全員参加で設備を管理し、故障・不良・災害ゼロを目指す活動。","usage_en":"Danh từ không đếm được, gần như luôn nói TPM. Hay đi với: implement TPM, TPM pillars, TPM award.","usage_ja":"Tên đầy đủ 全員参加の生産保全 (JIPM). Hay đi với TPM活動, TPMの8本柱, TPM賞.","context_vi":"Dùng ở nhà máy Nhật, ô tô, hóa chất, thực phẩm khi xây dựng hệ thống quản lý thiết bị.","ex_en":"Since starting total productive maintenance, breakdowns have dropped by 60%.","ex_ja":"TPMを始めてから、故障件数が60%減った。","ex_vi":"Từ khi triển khai bảo trì năng suất toàn diện, số lần hỏng đã giảm 60%.","syn_en":["TPM"],"syn_ja":["全員参加の生産保全","生産保全 (nghĩa rộng hơn)"]},{"en":"minor stoppage","pos":"noun phrase","ipa":"/ˌmaɪnə ˈstɒpɪdʒ/","ja":"チョコ停","kana":"チョコてい","romaji":"chokotei","vi":"dừng máy vặt (dừng ngắn)","level":2,"def_vi":"Dừng máy ngắn, thường vài giây đến vài phút, do kẹt chi tiết, cảm biến báo sai, xử lý nhanh mà không cần sửa chữa.","def_en":"A short stop of seconds to minutes, caused by jams or false sensor signals, cleared quickly without repair.","def_ja":"部品の詰まりやセンサの誤検出などで起こる数秒〜数分の短い停止で、修理なしに復帰できるもの。","usage_en":"Danh từ đếm được. Hay đi với: reduce minor stoppages, minor stops and idling (một trong sáu tổn thất lớn).","usage_ja":"Khẩu ngữ rất phổ biến ở xưởng Nhật; văn bản dùng 小停止. Đối chiếu ドカ停 (dừng lớn do hỏng nặng).","context_vi":"Dùng ở dây chuyền tự động, máy lắp ráp, máy đóng gói, nơi dừng ngắn lặp lại làm giảm năng suất.","ex_en":"The feeder causes about 40 minor stoppages per shift.","ex_ja":"フィーダが原因のチョコ停が1直あたり約40回ある。","ex_vi":"Máy cấp gây ra khoảng 40 lần dừng máy vặt mỗi ca.","syn_en":["minor stop","short stop"],"syn_ja":["小停止","ドカ停 (liên quan)"]},{"en":"troubleshooting","pos":"noun","ipa":"/ˈtrʌblʃuːtɪŋ/","ja":"トラブルシューティング","kana":"トラブルシューティング","romaji":"toraburushuutingu","vi":"chẩn đoán và khắc phục sự cố","level":2,"def_vi":"Quá trình tìm nguyên nhân sự cố của thiết bị một cách có hệ thống và khắc phục để máy chạy lại.","def_en":"The systematic process of locating the cause of an equipment problem and fixing it to restore operation.","def_ja":"設備の不具合の原因を系統的に突き止め、対処して運転を回復させること。","usage_en":"Danh từ không đếm được; động từ troubleshoot. Hay đi với: troubleshooting guide / chart, troubleshoot a fault.","usage_ja":"Ngoài xưởng hay nói トラブル対応, 故障探求; sách hướng dẫn máy có mục トラブルシューティング.","context_vi":"Dùng khi máy báo lỗi, trong sổ tay hướng dẫn và đào tạo kỹ thuật viên bảo trì.","ex_en":"Troubleshooting showed that the alarm came from a broken sensor cable.","ex_ja":"トラブルシューティングの結果、アラームはセンサケーブルの断線が原因だった。","ex_vi":"Quá trình chẩn đoán sự cố cho thấy báo động do cáp cảm biến bị đứt.","syn_en":["fault finding","fault diagnosis"],"syn_ja":["故障探求","トラブル対応 (khẩu ngữ)"]},{"en":"deterioration","pos":"noun","ipa":"/dɪˌtɪəriəˈreɪʃn/","ja":"劣化","kana":"れっか","romaji":"rekka","vi":"sự xuống cấp (lão hóa)","level":2,"def_vi":"Sự suy giảm dần tính năng hoặc tình trạng của thiết bị, vật liệu theo thời gian do mòn, ăn mòn, lão hóa.","def_en":"The gradual loss of performance or condition of equipment or material over time through wear, corrosion or ageing.","def_ja":"摩耗・腐食・老化などにより、設備や材料の性能・状態が時間とともに低下すること。","usage_en":"Danh từ không đếm được; động từ deteriorate. Hay đi với: signs of deterioration, accelerated deterioration, deterioration of seals.","usage_ja":"Hay đi với 劣化する, 経年劣化, 強制劣化 (xuống cấp do vận hành sai, thuật ngữ TPM), 劣化診断.","context_vi":"Dùng khi đánh giá tình trạng thiết bị, ống mềm, gioăng cao su, dầu bôi trơn, cáp điện.","ex_en":"Rubber hoses must be replaced before deterioration causes a leak.","ex_ja":"劣化によって漏れが起きる前に、ゴムホースを交換しなければならない。","ex_vi":"Phải thay ống cao su trước khi sự xuống cấp gây rò rỉ.","syn_en":["degradation","ageing"],"syn_ja":["経年劣化","老朽化 (gần nghĩa)"]},{"en":"abnormal noise","pos":"noun phrase","ipa":"/æbˌnɔːml ˈnɔɪz/","ja":"異音","kana":"いおん","romaji":"ion","vi":"tiếng kêu lạ (tiếng ồn bất thường)","level":2,"def_vi":"Âm thanh khác với tiếng chạy bình thường của máy, thường là dấu hiệu sớm của hư hỏng ổ trục, bánh răng.","def_en":"A sound different from the machine's normal running noise, often an early sign of bearing or gear damage.","def_ja":"設備の通常の運転音と異なる音で、軸受や歯車の損傷の初期兆候であることが多い。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: hear / detect an abnormal noise, abnormal noise from the gearbox; cũng nói 'unusual noise'.","usage_ja":"Rất hay dùng trong báo cáo: 異音がする, 異音発生, 異音点検; mô tả âm: ゴロゴロ, キーキー.","context_vi":"Dùng trong kiểm tra hằng ngày, báo cáo bất thường và khi khách hàng khiếu nại sản phẩm.","ex_en":"The operator reported an abnormal noise from the spindle at high speed.","ex_ja":"作業者は高速回転時に主軸から異音がすると報告した。","ex_vi":"Công nhân báo trục chính phát ra tiếng kêu lạ khi chạy tốc độ cao.","syn_en":["unusual noise","strange noise (khẩu ngữ)"],"syn_ja":["異常音","騒音 (nghĩa rộng hơn)"]},{"en":"malfunction","pos":"noun","ipa":"/ˌmælˈfʌŋkʃn/","ja":"不具合","kana":"ふぐあい","romaji":"fuguai","vi":"trục trặc (sự cố, lỗi chức năng)","level":2,"def_vi":"Tình trạng thiết bị hoặc sản phẩm hoạt động không đúng như mong muốn, dù chưa hỏng hoàn toàn.","def_en":"A condition in which equipment or a product does not work as intended, even if it has not completely failed.","def_ja":"設備や製品が完全に故障していなくても、期待どおりに機能しない状態。","usage_en":"Danh từ đếm được và động từ (the valve malfunctioned). Hay đi với: equipment malfunction, cause a malfunction, malfunction alarm.","usage_ja":"Từ rất thông dụng ở công ty Nhật: 不具合が発生する, 不具合報告, 不具合対策; nghĩa rộng hơn 故障.","context_vi":"Dùng trong báo cáo sự cố, phiếu yêu cầu bảo trì và trao đổi với nhà cung cấp thiết bị.","ex_en":"A malfunction of the level switch caused the tank to overflow.","ex_ja":"レベルスイッチの不具合でタンクがあふれた。","ex_vi":"Trục trặc của công tắc mức đã làm bồn bị tràn.","syn_en":["fault","trouble (khẩu ngữ)"],"syn_ja":["トラブル","故障 (gần nghĩa)"]},{"en":"overall equipment effectiveness","pos":"noun phrase","ipa":"/ˌəʊvərɔːl ɪˈkwɪpmənt ɪˌfektɪvnəs/","ja":"設備総合効率","kana":"せつびそうごうこうりつ","romaji":"setsubisougoukouritsu","vi":"hiệu suất thiết bị tổng thể (OEE)","level":2,"def_vi":"Chỉ số bằng tích của tỷ lệ khả dụng, hiệu suất tốc độ và tỷ lệ chất lượng, cho biết thiết bị được dùng hiệu quả đến đâu.","def_en":"A measure equal to availability × performance × quality rate, showing how effectively equipment is used.","def_ja":"時間稼働率×性能稼働率×良品率で求め、設備がどれだけ有効に使われているかを示す指標。","usage_en":"Danh từ không đếm được, gần như luôn nói OEE. Hay đi với: improve OEE, OEE of 85%, calculate OEE.","usage_ja":"Hay nói OEE; công thức 時間稼働率 × 性能稼働率 × 良品率. Hay đi với 設備総合効率を上げる.","context_vi":"Dùng trong TPM, báo cáo sản xuất, so sánh hiệu quả các máy và dây chuyền.","ex_en":"Overall equipment effectiveness of the bottling line rose from 62% to 78%.","ex_ja":"ボトリングラインの設備総合効率は62%から78%に向上した。","ex_vi":"Hiệu suất thiết bị tổng thể của dây chuyền chiết chai tăng từ 62% lên 78%.","syn_en":["OEE"],"syn_ja":["OEE","総合効率"]},{"en":"predictive maintenance","pos":"noun phrase","ipa":"/prɪˌdɪktɪv ˈmeɪntənəns/","ja":"予知保全","kana":"よちほぜん","romaji":"yochihozen","vi":"bảo trì dự đoán","level":3,"def_vi":"Bảo trì dựa trên theo dõi tình trạng thiết bị để dự đoán thời điểm sắp hỏng và can thiệp vừa kịp lúc.","def_en":"Maintenance that monitors equipment condition to predict when failure will occur and intervene just in time.","def_ja":"設備の状態を監視して故障時期を予測し、適切な時期に処置する保全。","usage_en":"Danh từ không đếm được, viết tắt PdM. Hay đi với: predictive maintenance program, IoT-based predictive maintenance.","usage_ja":"Thường coi gần nghĩa 状態基準保全 (CBM); hay đi với 予知保全システム, AIによる予知保全.","context_vi":"Dùng cho máy quan trọng như máy nén, quạt lớn, trục chính CNC, kết hợp cảm biến IoT.","ex_en":"Predictive maintenance warned us two weeks before the fan bearing failed.","ex_ja":"予知保全により、ファンの軸受が壊れる2週間前に警告が出た。","ex_vi":"Bảo trì dự đoán đã cảnh báo hai tuần trước khi ổ trục quạt hỏng.","syn_en":["PdM","condition-based maintenance (gần nghĩa)"],"syn_ja":["状態基準保全 (gần nghĩa)","CBM"]},{"en":"condition monitoring","pos":"noun phrase","ipa":"/kənˈdɪʃn ˌmɒnɪtərɪŋ/","ja":"状態監視","kana":"じょうたいかんし","romaji":"joutaikanshi","vi":"giám sát tình trạng thiết bị","level":3,"def_vi":"Đo và theo dõi liên tục hoặc định kỳ các thông số như rung, nhiệt độ, dầu để đánh giá tình trạng thiết bị.","def_en":"Continuous or periodic measurement of parameters such as vibration, temperature and oil to assess equipment condition.","def_ja":"振動・温度・油などを連続または定期的に測定し、設備の状態を評価すること。","usage_en":"Danh từ không đếm được, viết tắt CM. Hay đi với: online condition monitoring, condition monitoring system / sensor.","usage_ja":"Hay đi với 状態監視システム, オンライン監視; liên quan 設備診断 (chẩn đoán thiết bị).","context_vi":"Dùng cho động cơ, bơm, hộp số, tuabin trong nhà máy điện, hóa chất, xi măng.","ex_en":"Condition monitoring of the pumps uses wireless vibration sensors.","ex_ja":"ポンプの状態監視には無線式の振動センサを使っている。","ex_vi":"Việc giám sát tình trạng các bơm sử dụng cảm biến rung không dây.","syn_en":["machine condition monitoring","equipment diagnosis (gần nghĩa)"],"syn_ja":["設備診断","コンディションモニタリング"]},{"en":"oil analysis","pos":"noun phrase","ipa":"/ˈɔɪl əˌnæləsɪs/","ja":"潤滑油分析","kana":"じゅんかつゆぶんせき","romaji":"junkatsuyubunseki","vi":"phân tích dầu bôi trơn","level":3,"def_vi":"Lấy mẫu dầu đang sử dụng để phân tích độ nhớt, nước, hạt mài mòn, nhằm đánh giá tình trạng dầu và máy.","def_en":"Sampling in-service oil to analyse viscosity, water and wear particles, assessing the condition of oil and machine.","def_ja":"使用中の油を採取し、粘度・水分・摩耗粉などを分析して油と設備の状態を評価すること。","usage_en":"Danh từ không đếm được. Hay đi với: oil analysis report, take an oil sample, wear debris analysis, ferrography.","usage_ja":"Ngoài xưởng hay nói オイル分析, 油分析; liên quan フェログラフィ (phân tích hạt mài mòn), 汚染度測定.","context_vi":"Dùng cho hộp số lớn, hệ thủy lực, động cơ diesel, máy nén trong bảo trì dự đoán.","ex_en":"Oil analysis found high iron content, indicating gear wear.","ex_ja":"潤滑油分析で鉄分が多く検出され、歯車の摩耗が疑われた。","ex_vi":"Phân tích dầu bôi trơn phát hiện hàm lượng sắt cao, cho thấy bánh răng bị mòn.","syn_en":["lubricant analysis","wear debris analysis (gần nghĩa)"],"syn_ja":["オイル分析","油分析"]},{"en":"infrared thermography","pos":"noun phrase","ipa":"/ˌɪnfrəred θɜːˈmɒɡrəfi/","ja":"赤外線サーモグラフィ","kana":"せきがいせんサーモグラフィ","romaji":"sekigaisensaamogurafi","vi":"chụp ảnh nhiệt hồng ngoại","level":3,"def_vi":"Dùng camera hồng ngoại đo phân bố nhiệt độ bề mặt để phát hiện điểm quá nhiệt ở ổ trục, mối nối điện.","def_en":"Using an infrared camera to map surface temperature and find hot spots in bearings or electrical joints.","def_ja":"赤外線カメラで表面温度分布を測り、軸受や電気接続部の過熱箇所を見つける方法。","usage_en":"Danh từ không đếm được. Hay đi với: thermographic survey, thermal camera / thermal imager, hot spot.","usage_ja":"Ngoài xưởng nói サーモ, サーモカメラ; hay đi với 熱画像, ホットスポット, 温度分布.","context_vi":"Dùng kiểm tra tủ điện, động cơ, ổ trục, lò, đường ống cách nhiệt mà không cần dừng máy.","ex_en":"Infrared thermography revealed a loose terminal running at 95 °C.","ex_ja":"赤外線サーモグラフィで、95 °Cに過熱した緩んだ端子が見つかった。","ex_vi":"Chụp ảnh nhiệt hồng ngoại đã phát hiện một đầu cốt lỏng nóng tới 95 °C.","syn_en":["thermal imaging","IR thermography"],"syn_ja":["サーモグラフィ","サーモカメラ (khẩu ngữ)"]},{"en":"six big losses","pos":"noun phrase","ipa":"/ˌsɪks bɪɡ ˈlɒsɪz/","ja":"6大ロス","kana":"ろくだいロス","romaji":"rokudairosu","vi":"6 tổn thất lớn","level":3,"def_vi":"Sáu nhóm tổn thất làm giảm hiệu suất thiết bị trong TPM: hỏng, chuyển đổi, dừng vặt, giảm tốc, phế phẩm, tổn thất khởi động.","def_en":"TPM's six losses reducing equipment effectiveness: breakdowns, setup, minor stops, speed loss, defects and start-up loss.","def_ja":"故障・段取り調整・チョコ停・速度低下・不良手直し・立上りの、設備効率を下げる六つのロス。","usage_en":"Dùng với 'the': the six big losses; mỗi loại gắn với một thành phần của OEE. Hay đi với: analyse the six big losses.","usage_ja":"Viết 六大ロス cũng gặp; trong TPM mở rộng thành 16大ロス. Hay đi với ロス分析, ロス構造.","context_vi":"Dùng khi phân tích nguyên nhân OEE thấp và chọn chủ đề cải tiến thiết bị.","ex_en":"The six big losses analysis showed minor stops were the largest loss.","ex_ja":"6大ロスの分析から、チョコ停が最大のロスであることが分かった。","ex_vi":"Phân tích 6 tổn thất lớn cho thấy dừng máy vặt là tổn thất lớn nhất.","syn_en":["six major losses"],"syn_ja":["六大ロス","16大ロス (nghĩa rộng hơn)"]},{"en":"maintenance prevention","pos":"noun phrase","ipa":"/ˈmeɪntənəns prɪˌvenʃn/","ja":"保全予防","kana":"ほぜんよぼう","romaji":"hozenyobou","vi":"phòng ngừa bảo trì (thiết kế không cần bảo trì)","level":3,"def_vi":"Đưa kinh nghiệm bảo trì vào thiết kế thiết bị mới để thiết bị ít hỏng và ít cần bảo trì ngay từ đầu.","def_en":"Feeding maintenance experience into new equipment design so that it fails less and needs little maintenance.","def_ja":"保全の経験を新設備の設計に反映し、故障が少なく保全をほとんど要しない設備にすること。","usage_en":"Danh từ không đếm được, viết tắt MP; dễ nhầm với 'preventive maintenance'. Hay đi với: MP design, MP information sheet.","usage_ja":"Viết tắt MP; chú ý thứ tự chữ 保全予防 (MP) khác 予防保全 (PM). Hay đi với MP設計, MP情報.","context_vi":"Dùng khi đặt mua hoặc thiết kế máy mới, phối hợp giữa bảo trì và kỹ thuật thiết bị.","ex_en":"Maintenance prevention data led us to move all grease points to one side of the new machine.","ex_ja":"保全予防の情報を基に、新設備の給脂箇所をすべて片側に集めた。","ex_vi":"Dữ liệu phòng ngừa bảo trì giúp chúng tôi dồn mọi điểm tra mỡ của máy mới về một phía.","syn_en":["MP","design for maintainability (gần nghĩa)"],"syn_ja":["MP","MP設計 (liên quan)"]}]}]};
